    fn record_writer_fault(&self, context: &'static str, error: &Error) {
        {
            let mut fault = self.writer_fault.lock();
            if fault.is_none() {
                *fault = Some(format!("{context}: {error}"));
            }
        }
        if let Some(telemetry) = self.telemetry.get() {
            telemetry.inc_storage_budget_exceeded("kura_writer_fault");
        }
    }

    fn poison_canonical_storage(&self, context: &'static str, error: &Error) {
        // Publish the process-local fail-stop latch before looking for consensus.
        // The handshake lock then serializes this lookup with guard publication:
        // either poison nonblockingly closes admission on an already-bound
        // guard, or a later bind observes the latch and closes admission on the
        // newly published guard before returning. In-flight output is drained
        // by the consensus guard's ordinary fail-stop finalization paths.
        self.canonical_storage_poisoned
            .store(true, Ordering::Release);
        #[cfg(test)]
        self.maybe_pause_canonical_poison_after_latch_for_tests();
        let binding_guard = self.canonical_poison_binding_lock.lock();
        if let Some(output_guard) = self.consensus_output_guard.get() {
            output_guard.close_admission_for_restart();
        }
        drop(binding_guard);
        self.record_writer_fault(context, error);
    }

    /// Bind canonical-storage fail-stop handling to the authoritative consensus guard.
    ///
    /// Rebinding the same guard is idempotent. A different guard would create
    /// an admission window in which Kura poison closes only one of two
    /// consensus runtimes, so it is rejected. Binding and poison inspection
    /// share one handshake lock, so this method never returns with an open
    /// bound guard after canonical poison has been published.
    pub(crate) fn bind_consensus_output_guard(
        &self,
        output_guard: Arc<ConsensusOutputGuard>,
    ) -> Result<()> {
        let _binding_guard = self.canonical_poison_binding_lock.lock();
        let candidate = Arc::clone(&output_guard);
        let bound = self.consensus_output_guard.get_or_init(|| output_guard);
        if self.canonical_storage_poisoned.load(Ordering::Acquire) {
            bound.close_admission_for_restart();
        }
        if Arc::ptr_eq(bound, &candidate) {
            Ok(())
        } else {
            Err(Error::ConsensusOutputGuardAlreadyBound)
        }
    }

    fn committed_recovery_failure(&self, context: &'static str, error: &Error) -> Error {
        let recovery_error = Error::CanonicalBlockCommittedRecoveryRequired {
            detail: format!("{context}: {error}"),
        };
        self.poison_canonical_storage(context, &recovery_error);
        recovery_error
    }

    fn record_or_poison_fsync_fault(&self, context: &'static str, error: &Error) {
        if self.store_root.as_os_str().is_empty() {
            self.record_writer_fault(context, error);
            return;
        }
        let unresolved_stage = {
            let store = self.block_store.lock();
            [
                store.da_block_rewrite_stage_path(),
                store.eviction_compaction_stage_path(),
            ]
            .into_iter()
            .any(|path| match std::fs::symlink_metadata(path) {
                Ok(_) => true,
                Err(error) => error.kind() != ErrorKind::NotFound,
            })
        };
        if unresolved_stage
            || matches!(
                error,
                Error::DaBlockRewriteCommitStateUnknown { .. } | Error::CanonicalStoragePoisoned
            )
        {
            self.poison_canonical_storage(context, error);
        } else {
            self.record_writer_fault(context, error);
        }
    }

    fn ensure_canonical_storage_not_poisoned(&self) -> Result<()> {
        if self.canonical_storage_poisoned.load(Ordering::Acquire) {
            return Err(Error::CanonicalStoragePoisoned);
        }
        Ok(())
    }

    fn resolve_canonical_storage_before_mutation(&self) -> Result<()> {
        self.durable_mutation_authorized()?;
        if self.store_root.as_os_str().is_empty() {
            return Ok(());
        }
        let write_guard = self.block_store_write_lock.lock();
        let mut store = self.block_store.lock();
        if let Err(error) = store.recover_canonical_storage_stages() {
            drop(store);
            self.poison_canonical_storage("unresolved canonical storage stage", &error);
            return Err(Error::CanonicalStoragePoisoned);
        }
        let deferred_da_recovery_fault = store.take_deferred_da_recovery_fault();
        let da_rewrite_stage_path = store.da_block_rewrite_stage_path();
        drop(store);
        drop(write_guard);
        if let Some(message) = deferred_da_recovery_fault {
            let recovered = Error::IO(std::io::Error::other(message), da_rewrite_stage_path);
            return Err(
                self.committed_recovery_failure("recovered committed DA block rewrite", &recovered)
            );
        }
        // A stale association stage may describe an append whose marker never committed. Its
        // cleanup is an exact-retry precondition, not evidence that this invocation crossed a
        // canonical commit point.
        self.recover_canonical_association_stage()
    }

    fn canonical_association_stage_path(&self) -> PathBuf {
        self.active_blocks_dir
            .lock()
            .join(CANONICAL_ASSOCIATION_STAGE_FILE_NAME)
    }

    fn validate_canonical_association_stage(
        &self,
        stage: &CanonicalAssociationStageV1,
    ) -> Result<SignedBlock> {
        if stage.format_version != CANONICAL_ASSOCIATION_STAGE_VERSION
            || stage.height == 0
            || u64::try_from(stage.block_wire.len())? > STRICT_INIT_MAX_BLOCK_BYTES
            || Hash::new(&stage.block_wire) != stage.canonical_wire_hash
        {
            return Err(Error::IO(
                std::io::Error::new(
                    ErrorKind::InvalidData,
                    "canonical association stage envelope is invalid",
                ),
                self.canonical_association_stage_path(),
            ));
        }
        let block = decode_framed_signed_block(&stage.block_wire)?;
        if block.header().height().get() != stage.height || block.hash() != stage.block_hash {
            return Err(Error::IO(
                std::io::Error::new(
                    ErrorKind::InvalidData,
                    "canonical association stage block mismatches its height or hash",
                ),
                self.canonical_association_stage_path(),
            ));
        }
        match (
            Self::block_merge_reference(&block),
            stage.merge_entry.as_ref(),
        ) {
            (Some(reference), Some(entry)) if reference.matches_entry(entry) => {}
            (None, None) => {}
            _ => {
                return Err(Error::IO(
                    std::io::Error::new(
                        ErrorKind::InvalidData,
                        "canonical association stage merge entry mismatches the block",
                    ),
                    self.canonical_association_stage_path(),
                ));
            }
        }
        Ok(block)
    }

    fn read_canonical_association_stage(&self) -> Result<Option<CanonicalAssociationStageV1>> {
        let path = self.canonical_association_stage_path();
        let metadata = match std::fs::symlink_metadata(&path) {
            Ok(metadata) => metadata,
            Err(error) if error.kind() == ErrorKind::NotFound => return Ok(None),
            Err(error) => return Err(Error::IO(error, path)),
        };
        if metadata.file_type().is_symlink()
            || !metadata.is_file()
            || metadata.len() > MAX_CANONICAL_ASSOCIATION_STAGE_BYTES
        {
            return Err(Error::IO(
                std::io::Error::new(
                    ErrorKind::InvalidData,
                    "canonical association stage is not a bounded regular file",
                ),
                path,
            ));
        }
        let bytes = std::fs::read(&path).map_err(|error| Error::IO(error, path.clone()))?;
        let stage = norito::decode_canonical::<CanonicalAssociationStageV1>(&bytes)
            .map_err(|error| Error::NoritoFrame(error.into()))?;
        let _ = self.validate_canonical_association_stage(&stage)?;
        Ok(Some(stage))
    }

    fn write_canonical_association_stage(
        &self,
        block: &SignedBlock,
        merge_entry: Option<&MergeLedgerEntry>,
    ) -> Result<()> {
        let block_wire = block.encode_wire()?;
        let stage = CanonicalAssociationStageV1 {
            format_version: CANONICAL_ASSOCIATION_STAGE_VERSION,
            height: block.header().height().get(),
            block_hash: block.hash(),
            canonical_wire_hash: Hash::new(&block_wire),
            block_wire,
            merge_entry: merge_entry.cloned(),
        };
        let _ = self.validate_canonical_association_stage(&stage)?;
        let bytes = norito::encode_canonical(&stage).map_err(Error::NoritoFrame)?;
        if u64::try_from(bytes.len())? > MAX_CANONICAL_ASSOCIATION_STAGE_BYTES {
            return Err(Error::IO(
                std::io::Error::new(
                    ErrorKind::InvalidData,
                    "canonical association stage exceeds its hard size limit",
                ),
                self.canonical_association_stage_path(),
            ));
        }
        let path = self.canonical_association_stage_path();
        if let Some(existing) = self.read_canonical_association_stage()? {
            if existing == stage {
                return Ok(());
            }
            return Err(Error::IO(
                std::io::Error::new(
                    ErrorKind::AlreadyExists,
                    "a conflicting canonical association stage already exists",
                ),
                path,
            ));
        }
        let accounting_mutation = self.begin_total_disk_usage_mutation();
        let before = Self::file_len_or_zero(&path)?;
        if !self.write_atomic_synced_noclobber(&path, &bytes)? {
            return Err(Error::IO(
                std::io::Error::new(
                    ErrorKind::AlreadyExists,
                    "canonical association stage publication raced",
                ),
                path,
            ));
        }
        let after = Self::file_len_or_zero(&path)?;
        self.update_disk_usage_delta(before, after);
        self.update_total_disk_usage_delta(before, after);
        accounting_mutation.finish();
        Ok(())
    }

    fn remove_canonical_association_stage(&self) -> Result<()> {
        let path = self.canonical_association_stage_path();
        let before = Self::file_len_or_zero(&path)?;
        if before == 0 {
            return Ok(());
        }
        let accounting_mutation = self.begin_total_disk_usage_mutation();
        std::fs::remove_file(&path).map_err(|error| Error::IO(error, path.clone()))?;
        if let Some(parent) = path.parent() {
            sync_dir(parent).map_err(|error| Error::IO(error, parent.to_path_buf()))?;
        }
        self.update_disk_usage_delta(before, 0);
        self.update_total_disk_usage_delta(before, 0);
        accounting_mutation.finish();
        Ok(())
    }

    fn durable_hash_ignoring_poison(&self, height: u64) -> Result<Option<HashOf<BlockHeader>>> {
        Self::read_durable_hash_at_height(&mut self.block_store.lock(), height)
    }

    fn recover_canonical_association_stage(&self) -> Result<()> {
        self.recover_canonical_association_stage_with_authority(None)
    }

    fn recover_canonical_association_stage_during_snapshot_finalization(
        &self,
        authority: &SnapshotFinalizationMutationAuthority<'_>,
    ) -> Result<()> {
        authority.validate_for(self)?;
        self.recover_canonical_association_stage_with_authority(Some(authority))
    }

    fn recover_canonical_association_stage_with_authority(
        &self,
        finalization_authority: Option<&SnapshotFinalizationMutationAuthority<'_>>,
    ) -> Result<()> {
        if let Some(authority) = finalization_authority {
            authority.validate_for(self)?;
        }
        let Some(stage) = self.read_canonical_association_stage()? else {
            return Ok(());
        };
        #[cfg(test)]
        if self
            .fail_next_canonical_association_recovery
            .swap(false, Ordering::AcqRel)
        {
            return Err(Error::IO(
                std::io::Error::other("injected canonical association recovery failure"),
                self.canonical_association_stage_path(),
            ));
        }
        let block = self.validate_canonical_association_stage(&stage)?;
        if self.durable_hash_ignoring_poison(stage.height)? != Some(stage.block_hash) {
            return self.remove_canonical_association_stage();
        }
        self.persist_lane_payload_ownership_artifacts_for_block(&block)?;
        if let Some(entry) = stage.merge_entry.as_ref() {
            let _ = self.append_committed_merge_entry_for_block_if_missing(&block, entry)?;
            if finalization_authority.is_some() {
                self.remove_pending_certified_merge_entry_after_authorization(
                    entry.canonical_hash(),
                )?;
            } else {
                self.remove_committed_pending_merge_entry_best_effort(entry.canonical_hash());
            }
        }
        self.remove_canonical_association_stage()
    }

    /// Evict persisted block bodies after enough remote replicas advertise the same height/hash.
    #[allow(clippy::too_many_lines)]
    pub(crate) fn evict_block_bodies(&self, bytes_needed: u64) -> Result<u64> {
        let _prune_guard = self.prune_lock.lock();
        self.ensure_prune_recovery_not_required()?;
        self.evict_block_bodies_unlocked(bytes_needed)
    }

    #[allow(clippy::too_many_lines)]
    fn evict_block_bodies_unlocked(&self, bytes_needed: u64) -> Result<u64> {
        if bytes_needed == 0 || self.store_root.as_os_str().is_empty() {
            return Ok(0);
        }

        let _canonical_chain_guard = self.canonical_chain_lock.lock();
        self.resolve_canonical_storage_before_mutation()?;
        let _write_guard = self.block_store_write_lock.lock();
        self.ensure_no_pending_rollback()?;
        let blocks_dir = self.active_blocks_dir.lock().clone();
        let canonical_count = self.block_data.lock().len();
        let (
            persisted,
            evict_limit,
            indices,
            hashes,
            evict_mask,
            freed,
            before_bytes,
            marker,
            marker_len,
            marker_digest,
            hashes_len,
            hashes_digest,
            data_path,
            data_tmp,
            index_tmp,
            da_blocks_dir,
        ) = {
            let mut block_store = self.block_store.lock();
            block_store.flush_pending_fsync(true)?;

            let persisted = usize::try_from(block_store.read_durable_index_count()?)?;
            if persisted <= 1 {
                return Ok(0);
            }
            let marker = block_store.read_commit_marker()?.ok_or_else(|| {
                Error::IO(
                    std::io::Error::new(
                        ErrorKind::InvalidData,
                        "body eviction requires an exact durable commit marker",
                    ),
                    block_store.commit_marker_path(),
                )
            })?;
            if marker.count != u64::try_from(persisted)? {
                return Err(Error::IO(
                    std::io::Error::new(
                        ErrorKind::InvalidData,
                        "body eviction marker count differs from the durable index",
                    ),
                    block_store.commit_marker_path(),
                ));
            }
            if persisted > canonical_count {
                return Err(Error::IO(
                    std::io::Error::new(
                        ErrorKind::InvalidData,
                        "durable eviction prefix exceeds the live canonical block count",
                    ),
                    block_store.commit_marker_path(),
                ));
            }
            let retain_tail = self.blocks_in_memory.get().max(1);
            let evict_limit = persisted.saturating_sub(retain_tail);
            if evict_limit <= 1 {
                return Ok(0);
            }

            let mut indices = vec![BlockIndex::default(); persisted];
            block_store.read_block_indices(0, &mut indices)?;
            let hashes = block_store.read_block_hashes(0, persisted)?;
            if hashes.len() != persisted {
                return Err(Error::HashesFileHeightMismatch);
            }
            let data_len = block_store.data_file_len()?;
            let verified_tail = block_store.validated_verified_snapshot_tail(
                u64::try_from(persisted)?,
                u64::try_from(persisted)?,
            )?;
            let hard_fork_hash_only_count = self
                .hard_fork_hash_only_block_count
                .load(Ordering::Acquire)
                .min(persisted);
            for (idx, entry) in indices.iter().copied().enumerate() {
                if entry.length > STRICT_INIT_MAX_BLOCK_BYTES {
                    return Err(Error::CorruptedBlockLength {
                        length: entry.length,
                        limit: STRICT_INIT_MAX_BLOCK_BYTES,
                    });
                }
                if entry.is_evicted() {
                    if entry.length == 0 {
                        let position = u64::try_from(idx)?;
                        let verified = verified_tail.as_ref().is_some_and(|marker| {
                            position >= marker.body_prefix_count
                                && position < marker.snapshot_height
                        });
                        if idx >= hard_fork_hash_only_count && !verified {
                            return Err(Error::IO(
                                std::io::Error::new(
                                    ErrorKind::InvalidData,
                                    "zero-length eviction index has no authenticated snapshot binding",
                                ),
                                block_store.path_to_blockchain.join(INDEX_FILE_NAME),
                            ));
                        }
                    }
                    continue;
                }
                if entry.length == 0 {
                    return Err(Error::CorruptedBlockLength {
                        length: 0,
                        limit: STRICT_INIT_MAX_BLOCK_BYTES,
                    });
                }
                if entry
                    .start
                    .checked_add(entry.length)
                    .is_none_or(|end| end > data_len)
                {
                    return Err(Error::CorruptedBlockRange {
                        start: entry.start,
                        length: entry.length,
                        data_len,
                    });
                }
            }

            let mut evict_mask = vec![false; persisted];
            let mut freed = 0u64;
            let mut selected = 0usize;
            for idx in 1..evict_limit {
                let entry = indices[idx];
                if entry.is_evicted() {
                    continue;
                }
                let height = idx.saturating_add(1) as u64;
                let hash = hashes[idx];
                if !self.has_required_remote_replicas(height, hash, entry.length) {
                    debug!(
                        height,
                        block = %hash,
                        required_replicas = self.eviction_required_replicas.get(),
                        payload_len = entry.length,
                        "skipping Kura body eviction without enough remote replicas"
                    );
                    continue;
                }
                if self
                    .verified_v2_finality_wire_hash_for_eviction(&blocks_dir, height, hash)?
                    .is_none()
                {
                    debug!(
                        height,
                        block = %hash,
                        "skipping Kura body eviction without signed complete-wire finality"
                    );
                    continue;
                }
                freed = freed.saturating_add(entry.length);
                evict_mask[idx] = true;
                selected = selected.saturating_add(1);
                if freed >= bytes_needed || selected >= MAX_EVICTION_COMPACTION_ENTRIES {
                    break;
                }
            }

            if freed == 0 {
                return Ok(0);
            }

            let before_bytes = Self::block_store_tracked_bytes(&mut block_store)?;
            block_store.ensure_da_blocks_dir()?;
            let data_path = block_store.path_to_blockchain.join(DATA_FILE_NAME);
            let data_tmp = block_store.eviction_compaction_data_path();
            let index_tmp = block_store.eviction_compaction_index_path();
            let da_blocks_dir = block_store.da_blocks_dir.clone();
            let marker_path = block_store.commit_marker_path();
            let (marker_len, marker_digest) = BlockStore::eviction_file_digest(&marker_path)?;
            let hashes_path = block_store.path_to_blockchain.join(HASHES_FILE_NAME);
            let (hashes_len, hashes_digest) = BlockStore::eviction_file_digest(&hashes_path)?;

            (
                persisted,
                evict_limit,
                indices,
                hashes,
                evict_mask,
                freed,
                before_bytes,
                marker,
                marker_len,
                marker_digest,
                hashes_len,
                hashes_digest,
                data_path,
                data_tmp,
                index_tmp,
                da_blocks_dir,
            )
        };

        #[cfg(test)]
        self.maybe_pause_eviction_after_snapshot_for_tests();

        let accounting_mutation = self.begin_total_disk_usage_mutation();
        let mut evicted =
            Vec::with_capacity(evict_mask.iter().filter(|selected| **selected).count());
        let mut data_source = FileWrap::open_with(data_path.clone(), |opts| {
            opts.read(true);
        })?;
        let mut buffer = Vec::new();
        for idx in 1..evict_limit {
            if !evict_mask[idx] {
                continue;
            }
            let entry = indices[idx];
            if entry.is_evicted() {
                continue;
            }
            let height = idx.saturating_add(1) as u64;
            let canonical_hash = hashes[idx];
            let finality_wire_hash = self
                .verified_v2_finality_wire_hash_for_eviction(&blocks_dir, height, canonical_hash)?
                .ok_or_else(|| {
                    Error::IO(
                        std::io::Error::new(
                            ErrorKind::InvalidData,
                            "signed complete-wire finality disappeared during body eviction",
                        ),
                        Self::v2_finality_artifact_path_for(&blocks_dir, height),
                    )
                })?;
            let path = da_blocks_dir.join(format!("{height:020}.norito"));
            let length: usize = entry.length.try_into()?;
            buffer.resize(length, 0);
            Self::read_block_data_from_file(&mut data_source, entry.start, &mut buffer)?;
            let block = decode_framed_signed_block(&buffer)?;
            if block.header().height().get() != height {
                return Err(Error::IO(
                    std::io::Error::new(
                        ErrorKind::InvalidData,
                        "block selected for eviction has a header height different from its durable index",
                    ),
                    data_path.clone(),
                ));
            }
            let actual_hash = block.hash();
            if actual_hash != canonical_hash {
                return Err(Error::BlockHeightConflict {
                    height,
                    expected: canonical_hash,
                    actual: actual_hash,
                });
            }
            if Hash::new(&buffer) != finality_wire_hash {
                return Err(Error::V2FinalityPayloadHashMismatch { height });
            }
            self.persist_retained_block_record(&blocks_dir, canonical_hash, &block)?;

            let da_before = Self::file_len_or_zero(&path)?;
            self.write_atomic_synced_replace(&path, &buffer)?;
            let durable_wire =
                std::fs::read(&path).map_err(|error| Error::IO(error, path.clone()))?;
            if durable_wire != buffer {
                return Err(Error::IO(
                    std::io::Error::new(
                        ErrorKind::InvalidData,
                        "eviction DA-sidecar readback differs from the canonical block wire",
                    ),
                    path,
                ));
            }
            let da_after = Self::file_len_or_zero(&path)?;
            self.update_total_disk_usage_delta(da_before, da_after);
            evicted.push(EvictionCompactionEntryV1 {
                height,
                block_hash: canonical_hash,
                canonical_wire_hash: Hash::new(&buffer),
                wire_len: entry.length,
            });
        }

        if evicted.is_empty() {
            self.invalidate_durable_budget_snapshot();
            return Ok(0);
        }

        let mut new_indices = indices.clone();
        let mut cursor = 0u64;
        let mut data_tmp_file = FileWrap::open_with(data_tmp.clone(), |opts| {
            opts.write(true).create_new(true);
        })?;
        for (idx, entry) in indices.iter().enumerate() {
            if entry.is_evicted() || evict_mask[idx] {
                new_indices[idx].start = EVICTED_BLOCK_START;
                continue;
            }
            let length: usize = entry.length.try_into()?;
            buffer.resize(length, 0);
            Self::read_block_data_from_file(&mut data_source, entry.start, &mut buffer)?;
            let block = decode_framed_signed_block(&buffer)?;
            let height = u64::try_from(idx.saturating_add(1))?;
            if block.header().height().get() != height || block.hash() != hashes[idx] {
                return Err(Error::IO(
                    std::io::Error::new(
                        ErrorKind::InvalidData,
                        "inline block selected for compaction mismatches its durable height or hash",
                    ),
                    data_path.clone(),
                ));
            }
            data_tmp_file.try_io(|file| {
                file.seek(SeekFrom::Start(cursor))?;
                file.write_all(&buffer)
            })?;
            new_indices[idx].start = cursor;
            cursor = cursor.saturating_add(entry.length);
        }
        data_tmp_file.try_io(|file| {
            file.flush()?;
            file.set_len(cursor)?;
            file.sync_all()
        })?;

        let mut index_tmp_file = FileWrap::open_with(index_tmp.clone(), |opts| {
            opts.write(true).create_new(true);
        })?;
        let index_len = u64::try_from(persisted)?
            .checked_mul(BlockIndex::SIZE)
            .ok_or_else(|| {
                Error::IO(
                    std::io::Error::new(
                        ErrorKind::InvalidData,
                        "eviction replacement index length overflowed",
                    ),
                    index_tmp.clone(),
                )
            })?;
        index_tmp_file.try_io(|file| {
            for entry in &new_indices {
                let bytes = (*entry).encode();
                file.write_all(&bytes)?;
            }
            file.flush()?;
            file.set_len(index_len)?;
            file.sync_all()
        })?;
        drop(index_tmp_file);
        drop(data_tmp_file);
        drop(data_source);
        sync_dir(data_tmp.parent().ok_or_else(|| {
            Error::IO(
                std::io::Error::new(
                    ErrorKind::InvalidInput,
                    "eviction replacement data path has no parent",
                ),
                data_tmp.clone(),
            )
        })?)
        .map_err(|error| {
            Error::IO(
                error,
                data_tmp
                    .parent()
                    .expect("eviction replacement parent checked")
                    .to_path_buf(),
            )
        })?;

        let (data_len, data_digest) = BlockStore::eviction_file_digest(&data_tmp)?;
        let (actual_index_len, index_digest) = BlockStore::eviction_file_digest(&index_tmp)?;
        if actual_index_len != index_len {
            return Err(Error::IO(
                std::io::Error::new(
                    ErrorKind::InvalidData,
                    "synced eviction replacement index has an unexpected length",
                ),
                index_tmp,
            ));
        }

        {
            let mut block_store = self.block_store.lock();
            let current_persisted = usize::try_from(block_store.read_durable_index_count()?)?;
            let current_marker = block_store.read_commit_marker()?;
            let marker_path = block_store.commit_marker_path();
            let current_marker_digest = BlockStore::eviction_file_digest(&marker_path)?;
            let hashes_path = block_store.path_to_blockchain.join(HASHES_FILE_NAME);
            let current_hashes_digest = BlockStore::eviction_file_digest(&hashes_path)?;
            if current_persisted != persisted
                || current_marker.as_ref() != Some(&marker)
                || current_marker_digest != (marker_len, marker_digest)
                || current_hashes_digest != (hashes_len, hashes_digest)
            {
                warn!(
                    current_persisted,
                    persisted,
                    "Kura block store changed during eviction compaction; discarding temp files"
                );
                block_store.cleanup_unpublished_eviction_compaction_files()?;
                self.invalidate_durable_budget_snapshot();
                return Ok(0);
            }

            let stage = EvictionCompactionStageV1 {
                format_version: EVICTION_COMPACTION_STAGE_VERSION,
                marker,
                marker_len,
                marker_digest,
                hashes_len,
                hashes_digest,
                data_temp_name: EVICTION_COMPACTION_DATA_FILE_NAME.to_owned(),
                data_len,
                data_digest,
                index_temp_name: EVICTION_COMPACTION_INDEX_FILE_NAME.to_owned(),
                index_len,
                index_digest,
                evicted,
            };
            if let Err(publication_error) = block_store.write_eviction_compaction_stage(&stage) {
                match block_store.read_eviction_compaction_stage() {
                    Ok(Some(published)) if published == stage => {
                        if let Err(retry_error) = block_store.sync_eviction_compaction_stage(&stage)
                        {
                            drop(block_store);
                            self.invalidate_durable_budget_snapshot();
                            let ambiguous = Error::IO(
                                std::io::Error::other(format!(
                                    "eviction stage publication failed ({publication_error}); durability retry failed ({retry_error})"
                                )),
                                data_tmp
                                    .parent()
                                    .expect("eviction replacement parent checked")
                                    .join(EVICTION_COMPACTION_STAGE_FILE_NAME),
                            );
                            self.poison_canonical_storage(
                                "ambiguous eviction compaction stage durability",
                                &ambiguous,
                            );
                            return Err(Error::CanonicalStoragePoisoned);
                        }
                        warn!(
                            ?publication_error,
                            "eviction compaction stage durability succeeded on explicit retry"
                        );
                    }
                    Ok(None) => {
                        block_store.cleanup_unpublished_eviction_compaction_files()?;
                        return Err(publication_error);
                    }
                    Ok(Some(_)) | Err(_) => {
                        drop(block_store);
                        self.invalidate_durable_budget_snapshot();
                        self.poison_canonical_storage(
                            "ambiguous eviction compaction stage publication",
                            &publication_error,
                        );
                        return Err(Error::CanonicalStoragePoisoned);
                    }
                }
            }
            if let Err(error) = block_store.recover_eviction_compaction_stage() {
                drop(block_store);
                self.invalidate_durable_budget_snapshot();
                self.poison_canonical_storage("eviction compaction roll-forward", &error);
                return Err(Error::CanonicalStoragePoisoned);
            }
            // Keep the durable-store guard through cache invalidation. Readers now always consult
            // the index before honoring an Arc copied from this cache, so one that raced ahead of
            // this lock observes the evicted index and discards its stale copy.
            {
                let mut block_data = self.block_data.lock();
                for (idx, selected) in evict_mask.iter().copied().enumerate() {
                    if selected && let Some((_, cached_body)) = block_data.get_mut(idx) {
                        *cached_body = None;
                    }
                }
            }

            block_store.fsync.clear();
            block_store.drop_cached_handles();
            let after_bytes = Self::block_store_tracked_bytes(&mut block_store)?;
            self.update_disk_usage_delta(before_bytes, after_bytes);
            self.publish_durable_budget_snapshot(persisted, 0);
        }

        if freed > 0 {
            if let Some(telemetry) = self.telemetry.get() {
                telemetry.add_storage_da_churn_bytes("kura", "evicted", freed);
            }
        }

        accounting_mutation.finish();
        Ok(freed)
    }

    /// Retention window for commit-roster snapshots.
    #[must_use]
    pub fn block_sync_roster_retention(&self) -> NonZeroUsize {
        self.block_sync_roster_retention
    }

    /// Return the single shared owner of the structurally validated legacy archival journal.
    ///
    /// State and Kura pruning must never retain independent clean snapshots of the same durable
    /// tree: a stale clone could otherwise resurrect rows removed by rollback. This journal is not
    /// finality authority; live recovery uses Kura's verified Sumeragi-v2 finality artifacts.
    pub(crate) fn commit_roster_journal_handle(&self) -> Arc<RwLock<CommitRosterJournal>> {
        Arc::clone(&self.roster_log)
    }

    /// Retention window for roster sidecars stored alongside blocks.
    #[must_use]
    pub fn roster_sidecar_retention(&self) -> NonZeroUsize {
        self.roster_sidecar_retention
    }

    /// Shared bounded-history budget for durable per-route Native AMX evidence.
    ///
    /// Native manifests and receipts use the existing operator-configured Kura
    /// sidecar retention rather than introducing an environment-only or
    /// consensus-divergent limit. One extra entry may exist transiently while
    /// a strict append is being compacted or recovered.
    fn native_amx_participant_evidence_retention(&self) -> NonZeroUsize {
        self.roster_sidecar_retention
    }

    fn native_amx_evidence_prune_intent_max_entries(retention: NonZeroUsize) -> Result<usize> {
        retention
            .get()
            .checked_add(1)
            .and_then(|count| count.checked_mul(2))
            .ok_or_else(|| {
                Error::PruneIntentConflict(
                    "configured Native AMX evidence prune-intent entry bound overflowed".to_owned(),
                )
            })
    }

    fn native_amx_evidence_prune_intent_max_bytes_for_retention(
        retention: NonZeroUsize,
    ) -> Result<usize> {
        let max_entries = Self::native_amx_evidence_prune_intent_max_entries(retention)?;
        let shared_budget = usize::try_from(MAX_NATIVE_AMX_PARTICIPANT_EVIDENCE_FILE_BYTES)?;
        let allocation_bytes = max_entries
            .checked_mul(std::mem::size_of::<NativeAmxEvidencePruneEntryV1>())
            .ok_or_else(|| {
                Error::PruneIntentConflict(
                    "configured Native AMX evidence prune-intent allocation overflowed".to_owned(),
                )
            })?;
        if allocation_bytes > shared_budget {
            return Err(Error::PruneIntentConflict(
                "configured Native AMX evidence retention requires a prune journal larger than the shared sidecar budget"
                    .to_owned(),
            ));
        }

        let maximum_entry = NativeAmxEvidencePruneEntryV1 {
            kind: NativeAmxEvidencePruneIntentV1::RECEIPT_KIND,
            participant_height: u64::MAX,
            artifact_hash: Hash::prehashed([u8::MAX; Hash::LENGTH]),
        };
        let mut entries = Vec::new();
        entries.try_reserve_exact(max_entries)?;
        entries.resize(max_entries, maximum_entry);
        let maximum_intent = NativeAmxEvidencePruneIntentV1 {
            version: NativeAmxEvidencePruneIntentV1::VERSION,
            lane_id: LaneId::new(u32::MAX),
            dataspace_id: DataSpaceId::new(u64::MAX),
            lane_incarnation: Hash::prehashed([u8::MAX; Hash::LENGTH]),
            entries,
        };
        let encoded_len = norito::encode_canonical(&maximum_intent)?.len();
        if encoded_len == 0 || encoded_len > shared_budget {
            return Err(Error::PruneIntentConflict(
                "configured Native AMX evidence retention encodes a prune journal larger than the shared sidecar budget"
                    .to_owned(),
            ));
        }
        Ok(encoded_len)
    }

    fn native_amx_evidence_prune_intent_max_bytes(&self) -> usize {
        self.native_amx_evidence_prune_intent_max_bytes
    }

    fn lane_storage_entries_from_config(
        lane_config: &LaneConfig,
    ) -> BTreeMap<LaneId, LaneConfigEntry> {
        lane_config
            .entries()
            .iter()
            .cloned()
            .map(|entry| (entry.lane_id, entry))
            .collect()
    }

    #[cfg(test)]
    fn set_lane_storage_entry(&self, entry: &LaneConfigEntry) {
        self.lane_storage_entries
            .lock()
            .insert(entry.lane_id, entry.clone());
    }

    #[cfg(test)]
    fn remove_lane_storage_entry(&self, lane_id: LaneId) {
        self.lane_storage_entries.lock().remove(&lane_id);
    }

    fn lane_storage_entry(&self, lane_id: LaneId) -> Result<LaneConfigEntry> {
        self.lane_storage_entries
            .lock()
            .get(&lane_id)
            .cloned()
            .ok_or_else(|| {
                Error::IO(
                    std::io::Error::new(
                        ErrorKind::NotFound,
                        format!("no Kura storage segment configured for lane {lane_id:?}"),
                    ),
                    self.store_root
                        .join("blocks")
                        .join(format!("lane_{:03}", lane_id.as_u32())),
                )
            })
    }

    fn roster_log_path(store_root: &Path) -> PathBuf {
        CommitRosterJournal::journal_path(store_root)
    }

    fn ensure_lane_directories(
        store_dir: &Path,
        lane_config: &LaneConfig,
        active_blocks_dir: &Path,
        active_merge_path: &Path,
    ) -> Result<()> {
        let primary_lane = lane_config.primary().lane_id;
        for entry in lane_config.entries() {
            // The primary binding was already resolved from the durable geometry journal and
            // opened above. Recreating its configured alias here would resurrect the stale side
            // of an interrupted relabel and make the next recovery ambiguous.
            let is_primary = entry.lane_id == primary_lane;
            let blocks_dir = if is_primary {
                active_blocks_dir.to_path_buf()
            } else {
                entry.blocks_dir(store_dir)
            };
            if !is_primary && blocks_dir.as_path() != active_blocks_dir {
                std::fs::create_dir_all(&blocks_dir)
                    .map_err(|err| Error::MkDir(err, blocks_dir.clone()))?;
            }
            let lane_artifacts_dir = Self::lane_artifact_dir(&blocks_dir);
            std::fs::create_dir_all(&lane_artifacts_dir)
                .map_err(|err| Error::MkDir(err, lane_artifacts_dir))?;

            if is_primary {
                continue;
            }

            let merge_path = entry.merge_log_path(store_dir);
            if merge_path.as_path() != active_merge_path {
                if let Some(parent) = merge_path.parent() {
                    std::fs::create_dir_all(parent)
                        .map_err(|err| Error::MkDir(err, parent.to_path_buf()))?;
                }
                if !merge_path.exists() {
                    FileWrap::open_with(merge_path.clone(), |opts| {
                        opts.read(true).write(true).create(true).append(true);
                    })?;
                }
            }
        }

        Ok(())
    }

    /// Provision an unauthenticated lane-storage fixture for unit tests.
    ///
    /// Production topology changes must use the authenticated geometry journal.
    /// This helper is absent from release builds and exists only for consensus
    /// tests whose subject is unrelated to storage lifecycle authentication.
    ///
    /// # Errors
    /// Returns an [`Error`] if preparing or retiring storage directories fails for any entry.
    #[cfg(test)]
    pub(crate) fn reconcile_lane_segments_for_testing(
        &self,
        added: &[&LaneConfigEntry],
        retired: &[&LaneConfigEntry],
        replacements: &[(&LaneConfigEntry, &LaneConfigEntry)],
    ) -> Result<()> {
        let _prune_guard = self.prune_lock.lock();
        self.ensure_prune_recovery_not_required()?;
        if self.store_root.as_os_str().is_empty() {
            return Ok(());
        }
        let _canonical_chain_guard = self.canonical_chain_lock.lock();
        self.resolve_canonical_storage_before_mutation()?;
        let mut changed = false;

        for (previous, _) in replacements {
            self.retire_lane_storage(previous)?;
            self.remove_lane_storage_entry(previous.lane_id);
            changed = true;
        }
        for entry in added {
            self.prepare_lane_storage_resolved(entry)?;
            self.set_lane_storage_entry(entry);
            changed = true;
        }
        for (_, current) in replacements {
            self.prepare_lane_storage_resolved(current)?;
            self.set_lane_storage_entry(current);
            changed = true;
        }
        for entry in retired {
            self.retire_lane_storage(entry)?;
            self.remove_lane_storage_entry(entry.lane_id);
            changed = true;
        }

        if changed {
            if let Err(err) = self.refresh_disk_usage_bytes() {
                warn!(
                    ?err,
                    "failed to refresh disk usage after lane reconciliation"
                );
            }
        }

        Ok(())
    }

    /// Restore the effective lane catalog recorded in a trusted WSV snapshot.
    ///
    /// Kura is opened before the WSV snapshot is decoded, so its in-memory lane
    /// map initially reflects static configuration. This operation provisions all
    /// snapshot lanes and atomically replaces that map without archiving inactive
    /// static-config directories; those directories may contain data needed for an
    /// operator-directed rollback. The primary lane must retain the active block
    /// and merge-log paths selected when Kura was opened.
    ///
    /// # Errors
    /// Returns an [`Error`] if the snapshot changes the active primary storage
    /// paths or any restored lane storage cannot be validated or provisioned.
    pub fn restore_lane_segments(&self, lane_config: &LaneConfig) -> Result<()> {
        let _prune_guard = self.prune_lock.lock();
        self.ensure_prune_recovery_not_required()?;
        let restored_entries = Self::lane_storage_entries_from_config(lane_config);
        if self.store_root.as_os_str().is_empty() {
            *self.lane_storage_entries.lock() = restored_entries;
            return Ok(());
        }
        let _canonical_chain_guard = self.canonical_chain_lock.lock();
        self.resolve_canonical_storage_before_mutation()?;

        let primary = lane_config.primary();
        let primary_blocks_dir = primary.blocks_dir(&self.store_root);
        let active_blocks_dir = self.active_blocks_dir.lock().clone();
        if primary_blocks_dir != active_blocks_dir {
            return Err(Error::IO(
                std::io::Error::new(
                    ErrorKind::InvalidInput,
                    "snapshot primary lane block path differs from the active Kura path",
                ),
                primary_blocks_dir,
            ));
        }
        let primary_merge_path = primary.merge_log_path(&self.store_root);
        let active_merge_path = self.active_merge_path.lock().clone();
        if primary_merge_path != active_merge_path {
            return Err(Error::IO(
                std::io::Error::new(
                    ErrorKind::InvalidInput,
                    "snapshot primary lane merge path differs from the active Kura path",
                ),
                primary_merge_path,
            ));
        }

        for entry in lane_config.entries() {
            self.preflight_prepare_lane_storage(entry)?;
        }
        for entry in lane_config.entries() {
            self.prepare_lane_storage_resolved(entry)?;
        }
        *self.lane_storage_entries.lock() = restored_entries;
        drop(_canonical_chain_guard);
        drop(_prune_guard);
        self.rebuild_autonomous_lane_route_latest_attempt_indexes_on_startup()?;
        self.rebuild_native_amx_participant_receipt_latest_indexes_on_startup()?;
        if let Err(err) = self.refresh_disk_usage_bytes() {
            warn!(
                ?err,
                "failed to refresh disk usage after snapshot lane restore"
            );
        }
        Ok(())
    }

    /// Reject legacy snapshot lane restore without retained-lineage evidence.
    ///
    /// This entry point is retained for source compatibility, but its arguments
    /// identify only active lanes. They cannot authenticate retired incarnation
    /// history, so production recovery must use the exact-lineage restore path.
    ///
    /// # Errors
    /// Always returns an [`Error`] because the exact retained-lineage commitment
    /// is absent from this legacy signature.
    pub fn restore_lane_segments_with_geometry(
        &self,
        lane_config: &LaneConfig,
        incarnations: &BTreeMap<LaneId, Hash>,
        activation_heights: &BTreeMap<LaneId, u64>,
    ) -> Result<()> {
        let _ = (lane_config, incarnations, activation_heights);
        Err(Error::IO(
            std::io::Error::new(
                ErrorKind::InvalidInput,
                "exact retained lane-incarnation lineage is required for geometry restore",
            ),
            self.lane_geometry_journal_path(),
        ))
    }

    /// Restore snapshot lane storage at an exact committed transition height
    /// and retained-lineage commitment.
    pub(crate) fn restore_lane_segments_with_geometry_at_height_and_lineage_root(
        &self,
        lane_config: &LaneConfig,
        incarnations: &BTreeMap<LaneId, Hash>,
        activation_heights: &BTreeMap<LaneId, u64>,
        authoritative_height: u64,
        lineage_root: Hash,
    ) -> Result<()> {
        self.recover_lane_geometry_journal_at_height_with_lineage_root(
            lane_config,
            incarnations,
            activation_heights,
            authoritative_height,
            lineage_root,
        )?;
        self.finish_restored_lane_segments_with_geometry(lane_config)
    }

    /// Restore lane storage to the cursor before every transition at one committed height.
    ///
    /// Startup replay uses this for the genesis/configuration height, where more than one
    /// transition can legitimately share the same height and must be retried in journal order.
    pub(crate) fn restore_lane_segments_with_geometry_before_first_transition_at_height(
        &self,
        lane_config: &LaneConfig,
        incarnations: &BTreeMap<LaneId, Hash>,
        activation_heights: &BTreeMap<LaneId, u64>,
        lineage_root: Hash,
        transition_height: u64,
    ) -> Result<()> {
        self.recover_lane_geometry_journal_before_first_transition_at_height_with_lineage_root(
            lane_config,
            incarnations,
            activation_heights,
            lineage_root,
            transition_height,
        )?;
        self.finish_restored_lane_segments_with_geometry(lane_config)
    }

    fn finish_restored_lane_segments_with_geometry(&self, lane_config: &LaneConfig) -> Result<()> {
        if self.store_root.as_os_str().is_empty() {
            return Ok(());
        }
        let primary = lane_config.primary();
        let primary_blocks_dir = primary.blocks_dir(&self.store_root);
        if primary_blocks_dir != *self.active_blocks_dir.lock() {
            return Err(Error::IO(
                std::io::Error::new(
                    ErrorKind::InvalidInput,
                    "recovered primary lane block path differs from the active Kura path",
                ),
                primary_blocks_dir,
            ));
        }
        let primary_merge_path = primary.merge_log_path(&self.store_root);
        if primary_merge_path != *self.active_merge_path.lock() {
            return Err(Error::IO(
                std::io::Error::new(
                    ErrorKind::InvalidInput,
                    "recovered primary lane merge path differs from the active Kura path",
                ),
                primary_merge_path,
            ));
        }
        self.rebuild_autonomous_lane_route_latest_attempt_indexes_on_startup()?;
        self.rebuild_native_amx_participant_receipt_latest_indexes_on_startup()?;
        if let Err(err) = self.refresh_disk_usage_bytes() {
            warn!(
                ?err,
                "failed to refresh disk usage after journaled snapshot lane restore"
            );
        }
        Ok(())
    }

    /// Validate lane storage topology changes that can fail without mutating Kura state.
    ///
    /// This catches deterministic path-shape conflicts before callers reconcile
    /// other lane-scoped storage backends.
    ///
    /// # Errors
    /// Returns an [`Error`] if an existing file or directory would make lane
    /// storage provisioning, retirement, or relabeling fail.
    pub fn preflight_lane_segments(
        &self,
        added: &[&LaneConfigEntry],
        retired: &[&LaneConfigEntry],
        replacements: &[(&LaneConfigEntry, &LaneConfigEntry)],
        relabelled: &[(&LaneConfigEntry, &LaneConfigEntry)],
    ) -> Result<()> {
        if self.store_root.as_os_str().is_empty() {
            return Ok(());
        }

        for (previous, current) in replacements {
            self.preflight_replace_lane_storage(previous, current)?;
        }

        for entry in added {
            self.preflight_prepare_lane_storage(entry)?;
        }
        for entry in retired {
            self.preflight_retire_lane_storage(entry)?;
        }
        for (previous, current) in relabelled {
            self.preflight_relabel_lane_storage(previous, current)?;
        }

        Ok(())
    }

    fn preflight_replace_lane_storage(
        &self,
        previous: &LaneConfigEntry,
        current: &LaneConfigEntry,
    ) -> Result<()> {
        self.preflight_retire_lane_storage(previous)?;

        let old_dir = previous.blocks_dir(&self.store_root);
        let new_dir = current.blocks_dir(&self.store_root);
        if old_dir != new_dir && new_dir.exists() {
            return Err(Error::MkDir(
                std::io::Error::new(
                    std::io::ErrorKind::AlreadyExists,
                    "lane storage replacement target already exists",
                ),
                new_dir,
            ));
        }

        let old_merge = previous.merge_log_path(&self.store_root);
        let new_merge = current.merge_log_path(&self.store_root);
        if old_merge != new_merge && new_merge.exists() {
            return Err(Error::IO(
                std::io::Error::new(
                    std::io::ErrorKind::AlreadyExists,
                    "lane merge-ledger replacement target already exists",
                ),
                new_merge,
            ));
        }

        self.preflight_prepare_lane_storage(current)
    }

    /// Test the low-level rollback mechanics for a direct lane-path move.
    ///
    /// Production relabels exclusively use the durable lane-geometry journal; this helper is not
    /// compiled into a node binary and cannot create an unjournaled first-release path.
    ///
    /// # Errors
    /// Returns an error if preparing lane storage, creating directories, renaming,
    /// or retargeting the block store fails.
    #[cfg(test)]
    fn relabel_lane_segments(
        &self,
        migrations: &[(&LaneConfigEntry, &LaneConfigEntry)],
    ) -> Result<()> {
        let _prune_guard = self.prune_lock.lock();
        self.ensure_prune_recovery_not_required()?;
        if self.store_root.as_os_str().is_empty() {
            return Ok(());
        }
        let _canonical_chain_guard = self.canonical_chain_lock.lock();
        self.resolve_canonical_storage_before_mutation()?;
        for (previous, current) in migrations {
            self.preflight_relabel_lane_storage(previous, current)?;
        }

        // Provisioning an entirely absent prior path is not a rename and can be
        // completed before taking the block-store writer lock. A lone prior merge
        // log is inconsistent and must not be silently orphaned.
        let mut moves = Vec::new();
        for (previous, current) in migrations {
            let old_dir = previous.blocks_dir(&self.store_root);
            let new_dir = current.blocks_dir(&self.store_root);
            let old_merge = previous.merge_log_path(&self.store_root);
            let new_merge = current.merge_log_path(&self.store_root);
            if old_dir == new_dir && old_merge == new_merge {
                self.set_lane_storage_entry(current);
                continue;
            }
            if !old_dir.exists() {
                if old_merge.exists() {
                    return Err(Error::IO(
                        std::io::Error::new(
                            ErrorKind::InvalidData,
                            "lane relabel found a merge log without its prior block directory",
                        ),
                        old_merge,
                    ));
                }
                self.prepare_lane_storage_resolved(current)?;
                self.set_lane_storage_entry(current);
                continue;
            }
            moves.push((*previous, *current));
        }

        let _write_guard = self.block_store_write_lock.lock();
        let mut merge_log = self.merge_log.lock();
        let accounting_mutation = self.begin_total_disk_usage_mutation();
        for (previous, current) in moves {
            let old_dir = previous.blocks_dir(&self.store_root);
            let new_dir = current.blocks_dir(&self.store_root);
            let old_merge = previous.merge_log_path(&self.store_root);
            let new_merge = current.merge_log_path(&self.store_root);
            if let Some(parent) = new_dir.parent() {
                create_dir_all_with_context(parent)?;
            }
            let active_blocks = *self.active_blocks_dir.lock() == old_dir;
            let active_merge = *self.active_merge_path.lock() == old_merge;
            let mut block_store = active_blocks.then(|| self.block_store.lock());
            if let Some(store) = block_store.as_mut() {
                store.drop_cached_handles();
            }

            let mut canonical_path_moved = false;
            let move_result: Result<()> = (|| {
                if old_dir != new_dir {
                    std::fs::rename(&old_dir, &new_dir)
                        .map_err(|err| Error::IO(err, old_dir.clone()))?;
                    canonical_path_moved = true;
                    let new_parent = new_dir.parent();
                    let old_parent = old_dir.parent();
                    if let Some(parent) = new_parent {
                        sync_dir(parent).map_err(|err| Error::IO(err, parent.to_path_buf()))?;
                    }
                    if let Some(parent) = old_parent
                        && Some(parent) != new_parent
                    {
                        sync_dir(parent).map_err(|err| Error::IO(err, parent.to_path_buf()))?;
                    }
                    #[cfg(test)]
                    if self
                        .fail_next_relabel_after_block_move
                        .swap(false, Ordering::AcqRel)
                    {
                        return Err(Error::IO(
                            std::io::Error::other(
                                "injected direct lane-relabel failure after block move",
                            ),
                            new_dir.clone(),
                        ));
                    }
                }
                if old_merge != new_merge {
                    canonical_path_moved |= old_merge.exists();
                    self.relabel_merge_log(previous, current)?;
                }
                Ok(())
            })();
            if let Err(error) = move_result {
                if canonical_path_moved {
                    let restoration = (|| {
                        if old_merge != new_merge {
                            match (old_merge.exists(), new_merge.exists()) {
                                (false, true) => std::fs::rename(&new_merge, &old_merge)
                                    .map_err(|restore| Error::IO(restore, new_merge.clone()))?,
                                (true, false) => {}
                                _ => {
                                    return Err(Error::IO(
                                        std::io::Error::new(
                                            ErrorKind::InvalidData,
                                            "lane merge-log rollback has an ambiguous path state",
                                        ),
                                        old_merge.clone(),
                                    ));
                                }
                            }
                        }
                        if old_dir != new_dir {
                            match (old_dir.exists(), new_dir.exists()) {
                                (false, true) => std::fs::rename(&new_dir, &old_dir)
                                    .map_err(|restore| Error::IO(restore, new_dir.clone()))?,
                                (true, false) => {}
                                _ => {
                                    return Err(Error::IO(
                                        std::io::Error::new(
                                            ErrorKind::InvalidData,
                                            "lane block-directory rollback has an ambiguous path state",
                                        ),
                                        old_dir.clone(),
                                    ));
                                }
                            }
                        }
                        for parent in [
                            old_dir.parent(),
                            new_dir.parent(),
                            old_merge.parent(),
                            new_merge.parent(),
                        ]
                        .into_iter()
                        .flatten()
                        {
                            sync_dir(parent)
                                .map_err(|restore| Error::IO(restore, parent.to_path_buf()))?;
                        }
                        Ok(())
                    })();
                    if let Err(restoration) = restoration {
                        let poison = Error::LaneGeometryPublicationRestoreFailed {
                            publication: error.to_string(),
                            restoration: restoration.to_string(),
                        };
                        drop(block_store);
                        drop(merge_log);
                        self.poison_canonical_storage("lane storage relabel rollback", &poison);
                        return Err(Error::CanonicalStoragePoisoned);
                    }
                }
                return Err(error);
            }

            if let Some(store) = block_store.as_mut() {
                store.retarget_existing_path(new_dir.clone());
                *self.active_blocks_dir.lock() = new_dir.clone();
                self.invalidate_durable_budget_snapshot();
            }
            if active_merge {
                if let Some(file) = merge_log.file.as_mut() {
                    file.path.clone_from(&new_merge);
                }
                *self.active_merge_path.lock() = new_merge.clone();
            }
            if old_dir != new_dir {
                let mut plain_text = self.block_plain_text_path.lock();
                if let Some(path) = plain_text.as_mut()
                    && let Ok(suffix) = path.strip_prefix(&old_dir)
                {
                    *path = new_dir.join(suffix);
                }
            }
            self.set_lane_storage_entry(current);

            iroha_logger::info!(
                lane = %current.lane_id.as_u32(),
                alias_before = previous.alias,
                alias_after = current.alias,
                source = %old_dir.display(),
                target = %new_dir.display(),
                "lane storage relabelled to match updated alias"
            );
        }

        accounting_mutation.finish();
        Ok(())
    }

    #[cfg(test)]
    fn relabel_merge_log(
        &self,
        previous: &LaneConfigEntry,
        current: &LaneConfigEntry,
    ) -> Result<()> {
        let old_path = previous.merge_log_path(&self.store_root);
        let new_path = current.merge_log_path(&self.store_root);
        if old_path == new_path {
            return Ok(());
        }

        if !old_path.exists() {
            if let Some(parent) = new_path.parent() {
                create_dir_all_with_context(parent)?;
            }
            if !new_path.exists() {
                FileWrap::open_with(new_path.clone(), |opts| {
                    opts.read(true).write(true).create(true).append(true);
                })?;
            }
            return Ok(());
        }

        if let Some(parent) = new_path.parent() {
            create_dir_all_with_context(parent)?;
        }
        if new_path.exists() {
            return Err(Error::IO(
                std::io::Error::new(
                    ErrorKind::AlreadyExists,
                    "lane merge-ledger relabel target already exists",
                ),
                new_path,
            ));
        }

        std::fs::rename(&old_path, &new_path).map_err(|err| Error::IO(err, old_path.clone()))?;
        let new_parent = new_path.parent();
        let old_parent = old_path.parent();
        if let Some(parent) = new_parent {
            sync_dir(parent).map_err(|err| Error::IO(err, parent.to_path_buf()))?;
        }
        if let Some(parent) = old_parent {
            if Some(parent) != new_parent {
                sync_dir(parent).map_err(|err| Error::IO(err, parent.to_path_buf()))?;
            }
        }

        iroha_logger::info!(
            lane = %current.lane_id.as_u32(),
            alias_before = previous.alias,
            alias_after = current.alias,
            source = %old_path.display(),
            target = %new_path.display(),
            "lane merge-ledger relabelled"
        );

        Ok(())
    }

    fn prepare_lane_storage_resolved(&self, entry: &LaneConfigEntry) -> Result<()> {
        let accounting_mutation = self.begin_total_disk_usage_mutation();
        let blocks_dir = entry.blocks_dir(&self.store_root);
        let active = {
            let active_dir = self.active_blocks_dir.lock();
            blocks_dir == *active_dir
        };
        if active {
            let _write_guard = self.block_store_write_lock.lock();
            self.block_store
                .lock()
                .create_files_if_they_do_not_exist()?;
        } else {
            let mut block_store = BlockStore::new(&blocks_dir);
            block_store.create_files_if_they_do_not_exist()?;
        }
        create_dir_all_with_context(&Self::lane_artifact_dir(&blocks_dir))?;

        let merge_path = entry.merge_log_path(&self.store_root);
        if let Some(parent) = merge_path.parent() {
            create_dir_all_with_context(parent)?;
        }
        if !merge_path.exists() {
            FileWrap::open_with(merge_path.clone(), |opts| {
                opts.read(true).write(true).create(true).append(true);
            })?;
        }

        iroha_logger::info!(
            lane = %entry.lane_id.as_u32(),
            alias = entry.alias,
            blocks = %blocks_dir.display(),
            merge = %merge_path.display(),
            "lane storage provisioned"
        );
        accounting_mutation.finish();
        Ok(())
    }

    fn preflight_prepare_lane_storage(&self, entry: &LaneConfigEntry) -> Result<()> {
        let blocks_dir = entry.blocks_dir(&self.store_root);
        Self::preflight_dir_path(&blocks_dir)?;
        Self::preflight_dir_path(&Self::lane_artifact_dir(&blocks_dir))?;
        for name in [INDEX_FILE_NAME, DATA_FILE_NAME, HASHES_FILE_NAME] {
            Self::preflight_file_path(&blocks_dir.join(name))?;
        }

        let merge_path = entry.merge_log_path(&self.store_root);
        if let Some(parent) = merge_path.parent() {
            Self::preflight_dir_path(parent)?;
        }
        Self::preflight_file_path(&merge_path)?;
        Ok(())
    }

    fn preflight_retire_lane_storage(&self, entry: &LaneConfigEntry) -> Result<()> {
        let blocks_dir = entry.blocks_dir(&self.store_root);
        if blocks_dir == *self.active_blocks_dir.lock() {
            return Ok(());
        }
        let merge_path = entry.merge_log_path(&self.store_root);
        if merge_path == *self.active_merge_path.lock() {
            return Ok(());
        }

        let retired_root = self.store_root.join("retired");
        Self::preflight_dir_path(&retired_root.join("blocks"))?;
        Self::preflight_dir_path(&retired_root.join("merge_ledger"))?;
        Ok(())
    }

    fn preflight_relabel_lane_storage(
        &self,
        previous: &LaneConfigEntry,
        current: &LaneConfigEntry,
    ) -> Result<()> {
        let old_dir = previous.blocks_dir(&self.store_root);
        let new_dir = current.blocks_dir(&self.store_root);
        let old_merge = previous.merge_log_path(&self.store_root);
        if old_dir == new_dir {
            return self.preflight_relabel_merge_log(previous, current);
        }
        if !old_dir.exists() {
            if old_merge.exists() {
                return Err(Error::IO(
                    std::io::Error::new(
                        ErrorKind::InvalidData,
                        "lane relabel found a merge log without its prior block directory",
                    ),
                    old_merge,
                ));
            }
            self.preflight_prepare_lane_storage(current)?;
            return Ok(());
        }

        if let Some(parent) = new_dir.parent() {
            Self::preflight_dir_path(parent)?;
        }
        if new_dir.exists() {
            return Err(Error::MkDir(
                std::io::Error::new(
                    std::io::ErrorKind::AlreadyExists,
                    "lane storage relabel target already exists",
                ),
                new_dir,
            ));
        }
        self.preflight_relabel_merge_log(previous, current)
    }

    fn preflight_relabel_merge_log(
        &self,
        previous: &LaneConfigEntry,
        current: &LaneConfigEntry,
    ) -> Result<()> {
        let old_path = previous.merge_log_path(&self.store_root);
        let new_path = current.merge_log_path(&self.store_root);
        if old_path == new_path {
            return Ok(());
        }
        if let Some(parent) = new_path.parent() {
            Self::preflight_dir_path(parent)?;
        }
        if !old_path.exists() {
            Self::preflight_file_path(&new_path)?;
            return Ok(());
        }
        if new_path.exists() {
            return Err(Error::IO(
                std::io::Error::new(
                    ErrorKind::AlreadyExists,
                    "lane merge-ledger relabel target already exists",
                ),
                new_path,
            ));
        }
        Ok(())
    }

    fn preflight_dir_path(path: &Path) -> Result<()> {
        if path.exists() && !path.is_dir() {
            return Err(Error::MkDir(
                std::io::Error::new(std::io::ErrorKind::AlreadyExists, "expected directory path"),
                path.to_path_buf(),
            ));
        }
        Ok(())
    }

    fn preflight_file_path(path: &Path) -> Result<()> {
        if path.exists() && !path.is_file() {
            return Err(Error::IO(
                std::io::Error::new(std::io::ErrorKind::AlreadyExists, "expected file path"),
                path.to_path_buf(),
            ));
        }
        Ok(())
    }

    #[cfg(test)]
    fn retire_lane_storage(&self, entry: &LaneConfigEntry) -> Result<()> {
        let blocks_dir = entry.blocks_dir(&self.store_root);
        {
            let active_dir = self.active_blocks_dir.lock();
            if blocks_dir == *active_dir {
                iroha_logger::warn!(
                    lane = %entry.lane_id.as_u32(),
                    alias = entry.alias,
                    "skipping retirement of active lane block directory"
                );
                return Ok(());
            }
        }
        let merge_path = entry.merge_log_path(&self.store_root);
        if merge_path == *self.active_merge_path.lock() {
            iroha_logger::warn!(
                lane = %entry.lane_id.as_u32(),
                alias = entry.alias,
                "skipping retirement of active lane merge log"
            );
            return Ok(());
        }

        let retired_root = self.store_root.join("retired");
        let retired_blocks_root = retired_root.join("blocks");
        let retired_merge_root = retired_root.join("merge_ledger");
        create_dir_all_with_context(&retired_blocks_root)?;
        create_dir_all_with_context(&retired_merge_root)?;
        let accounting_mutation = self.begin_total_disk_usage_mutation();

        if blocks_dir.exists() {
            let dest = unique_retired_path(&retired_blocks_root, &entry.kura_segment, None::<&str>);
            std::fs::rename(&blocks_dir, &dest)
                .map_err(|err| Error::IO(err, blocks_dir.clone()))?;
            let dest_parent = dest.parent();
            let blocks_parent = blocks_dir.parent();
            if let Some(parent) = dest_parent {
                sync_dir(parent).map_err(|err| Error::IO(err, parent.to_path_buf()))?;
            }
            if let Some(parent) = blocks_parent {
                if Some(parent) != dest_parent {
                    sync_dir(parent).map_err(|err| Error::IO(err, parent.to_path_buf()))?;
                }
            }
            iroha_logger::info!(
                lane = %entry.lane_id.as_u32(),
                alias = entry.alias,
                source = %blocks_dir.display(),
                target = %dest.display(),
                "retired lane block directory"
            );
        }

        if merge_path.exists() {
            let dest = unique_retired_path(&retired_merge_root, &entry.merge_segment, Some("log"));
            std::fs::rename(&merge_path, &dest)
                .map_err(|err| Error::IO(err, merge_path.clone()))?;
            let dest_parent = dest.parent();
            let merge_parent = merge_path.parent();
            if let Some(parent) = dest_parent {
                sync_dir(parent).map_err(|err| Error::IO(err, parent.to_path_buf()))?;
            }
            if let Some(parent) = merge_parent {
                if Some(parent) != dest_parent {
                    sync_dir(parent).map_err(|err| Error::IO(err, parent.to_path_buf()))?;
                }
            }
            iroha_logger::info!(
                lane = %entry.lane_id.as_u32(),
                alias = entry.alias,
                source = %merge_path.display(),
                target = %dest.display(),
                "retired lane merge log"
            );
        }

        accounting_mutation.finish();
        Ok(())
    }

    /// Append a merge-ledger entry to the persistent log and in-memory cache.
    ///
    /// # Errors
    /// Returns an error if the merge-ledger entry cannot be persisted.
    pub fn append_merge_entry(&self, entry: &MergeLedgerEntry) -> Result<()> {
        let _canonical_chain_guard = self.canonical_chain_lock.lock();
        self.resolve_canonical_storage_before_mutation()?;
        self.append_merge_entry_after_storage_resolution(entry)
    }

    fn append_merge_entry_after_storage_resolution(&self, entry: &MergeLedgerEntry) -> Result<()> {
        let accounting_mutation = self.begin_total_disk_usage_mutation();
        let appended = self.merge_log.lock().append(entry)?;
        if appended && !self.store_root.as_os_str().is_empty() {
            let bytes = Self::merge_entry_bytes(entry)?;
            self.add_disk_usage_bytes(bytes);
        }
        accounting_mutation.finish();
        Ok(())
    }

    fn merge_carrier_dir(&self) -> PathBuf {
        self.store_root.join(MERGE_CARRIERS_DIR)
    }

    fn merge_carrier_path(&self, block_height: u64) -> PathBuf {
        self.merge_carrier_dir()
            .join(format!("{block_height}.norito"))
    }

    #[cfg(unix)]
    fn sidecar_metadata_same_object(left: &std::fs::Metadata, right: &std::fs::Metadata) -> bool {
        use std::os::unix::fs::MetadataExt as _;

        left.dev() == right.dev() && left.ino() == right.ino()
    }

    #[cfg(windows)]
    fn sidecar_metadata_same_object(left: &std::fs::Metadata, right: &std::fs::Metadata) -> bool {
        use std::os::windows::fs::MetadataExt as _;

        left.volume_serial_number() == right.volume_serial_number()
            && left.file_index() == right.file_index()
            && left.volume_serial_number().is_some()
            && left.file_index().is_some()
    }

    #[cfg(all(not(unix), not(windows)))]
    fn sidecar_metadata_same_object(_left: &std::fs::Metadata, _right: &std::fs::Metadata) -> bool {
        false
    }

    #[cfg(unix)]
    fn sidecar_file_metadata_unchanged(
        left: &std::fs::Metadata,
        right: &std::fs::Metadata,
    ) -> bool {
        use std::os::unix::fs::MetadataExt as _;

        Self::sidecar_metadata_same_object(left, right)
            && left.nlink() == 1
            && right.nlink() == 1
            && left.len() == right.len()
            && left.mtime() == right.mtime()
            && left.mtime_nsec() == right.mtime_nsec()
            && left.ctime() == right.ctime()
            && left.ctime_nsec() == right.ctime_nsec()
    }

    #[cfg(unix)]
    fn sidecar_directory_metadata_unchanged(
        left: &std::fs::Metadata,
        right: &std::fs::Metadata,
    ) -> bool {
        use std::os::unix::fs::MetadataExt as _;

        Self::sidecar_metadata_same_object(left, right)
            && left.mtime() == right.mtime()
            && left.mtime_nsec() == right.mtime_nsec()
            && left.ctime() == right.ctime()
            && left.ctime_nsec() == right.ctime_nsec()
    }

    #[cfg(windows)]
    fn sidecar_directory_metadata_unchanged(
        left: &std::fs::Metadata,
        right: &std::fs::Metadata,
    ) -> bool {
        use std::os::windows::fs::MetadataExt as _;

        Self::sidecar_metadata_same_object(left, right)
            && left.last_write_time() == right.last_write_time()
            && left.creation_time() == right.creation_time()
    }

    #[cfg(all(not(unix), not(windows)))]
    fn sidecar_directory_metadata_unchanged(
        _left: &std::fs::Metadata,
        _right: &std::fs::Metadata,
    ) -> bool {
        false
    }

    #[cfg(windows)]
    fn sidecar_file_metadata_unchanged(
        left: &std::fs::Metadata,
        right: &std::fs::Metadata,
    ) -> bool {
        use std::os::windows::fs::MetadataExt as _;

        Self::sidecar_metadata_same_object(left, right)
            && left.number_of_links() == Some(1)
            && right.number_of_links() == Some(1)
            && left.file_size() == right.file_size()
            && left.last_write_time() == right.last_write_time()
            && left.creation_time() == right.creation_time()
    }

    #[cfg(all(not(unix), not(windows)))]
    fn sidecar_file_metadata_unchanged(
        left: &std::fs::Metadata,
        right: &std::fs::Metadata,
    ) -> bool {
        Self::sidecar_metadata_same_object(left, right)
            && left.len() == right.len()
            && left.modified().ok() == right.modified().ok()
    }

    fn stable_sidecar_metadata_unchanged(
        left: &StableSidecarMetadata,
        right: &StableSidecarMetadata,
    ) -> bool {
        left.canonical_path == right.canonical_path
            && Self::sidecar_file_metadata_unchanged(&left.file, &right.file)
            && Self::sidecar_directory_metadata_unchanged(&left.directory, &right.directory)
    }

    fn stable_sidecar_directory_metadata_unchanged(
        left: &StableSidecarDirectoryMetadata,
        right: &StableSidecarDirectoryMetadata,
    ) -> bool {
        if left.expected_path != right.expected_path || left.canonical_path != right.canonical_path
        {
            return false;
        }
        match (&left.metadata, &right.metadata) {
            (None, None) => true,
            (Some(left), Some(right)) => Self::sidecar_directory_metadata_unchanged(left, right),
            (None, Some(_)) | (Some(_), None) => false,
        }
    }

    #[cfg(unix)]
    fn sidecar_is_single_link(metadata: &std::fs::Metadata) -> bool {
        use std::os::unix::fs::MetadataExt as _;

        metadata.nlink() == 1
    }

    #[cfg(windows)]
    fn sidecar_is_single_link(metadata: &std::fs::Metadata) -> bool {
        use std::os::windows::fs::MetadataExt as _;

        metadata.number_of_links() == Some(1)
    }

    #[cfg(all(not(unix), not(windows)))]
    fn sidecar_is_single_link(_metadata: &std::fs::Metadata) -> bool {
        false
    }

    #[cfg(unix)]
    fn sidecar_has_link_count(metadata: &std::fs::Metadata, expected: u64) -> bool {
        use std::os::unix::fs::MetadataExt as _;

        metadata.nlink() == expected
    }

    #[cfg(windows)]
    fn sidecar_has_link_count(metadata: &std::fs::Metadata, expected: u64) -> bool {
        use std::os::windows::fs::MetadataExt as _;

        u32::try_from(expected)
            .ok()
            .is_some_and(|expected| metadata.number_of_links() == Some(expected))
    }

    #[cfg(all(not(unix), not(windows)))]
    fn sidecar_has_link_count(_metadata: &std::fs::Metadata, _expected: u64) -> bool {
        false
    }

    fn canonical_sidecar_directory_for(
        store_root: &Path,
        expected_directory: &Path,
    ) -> Result<Option<(PathBuf, std::fs::Metadata)>> {
        let before = match std::fs::symlink_metadata(expected_directory) {
            Ok(metadata) => metadata,
            Err(error) if error.kind() == ErrorKind::NotFound => return Ok(None),
            Err(error) => return Err(Error::IO(error, expected_directory.to_path_buf())),
        };
        if before.file_type().is_symlink() || !before.is_dir() {
            return Err(Error::IO(
                std::io::Error::new(
                    ErrorKind::InvalidData,
                    "sidecar directory is not a direct directory",
                ),
                expected_directory.to_path_buf(),
            ));
        }
        let relative = expected_directory.strip_prefix(store_root).map_err(|_| {
            Error::IO(
                std::io::Error::new(
                    ErrorKind::InvalidData,
                    "sidecar directory is outside the configured Kura root",
                ),
                expected_directory.to_path_buf(),
            )
        })?;
        let canonical_root = std::fs::canonicalize(store_root)
            .map_err(|error| Error::IO(error, store_root.to_path_buf()))?;
        let canonical_directory = std::fs::canonicalize(expected_directory)
            .map_err(|error| Error::IO(error, expected_directory.to_path_buf()))?;
        if canonical_directory != canonical_root.join(relative) {
            return Err(Error::IO(
                std::io::Error::new(
                    ErrorKind::InvalidData,
                    "sidecar directory contains a symlink or escapes the Kura root",
                ),
                expected_directory.to_path_buf(),
            ));
        }
        let after = std::fs::symlink_metadata(expected_directory)
            .map_err(|error| Error::IO(error, expected_directory.to_path_buf()))?;
        if after.file_type().is_symlink()
            || !after.is_dir()
            || !Self::sidecar_directory_metadata_unchanged(&before, &after)
        {
            return Err(Error::IO(
                std::io::Error::new(
                    ErrorKind::InvalidData,
                    "sidecar directory changed during canonical validation",
                ),
                expected_directory.to_path_buf(),
            ));
        }
        Ok(Some((canonical_directory, after)))
    }

    fn canonical_sidecar_directory(
        &self,
        expected_directory: &Path,
    ) -> Result<Option<(PathBuf, std::fs::Metadata)>> {
        Self::canonical_sidecar_directory_for(&self.store_root, expected_directory)
    }

    fn stable_sidecar_directory_metadata(
        &self,
        expected_directory: &Path,
    ) -> Result<StableSidecarDirectoryMetadata> {
        let current = self.canonical_sidecar_directory(expected_directory)?;
        Ok(StableSidecarDirectoryMetadata {
            expected_path: expected_directory.to_path_buf(),
            canonical_path: current.as_ref().map(|(path, _)| path.clone()),
            metadata: current.map(|(_, metadata)| metadata),
        })
    }

    fn stable_sidecar_directory_inventory(
        &self,
        expected_directory: &Path,
    ) -> Result<StableSidecarDirectoryInventory> {
        let before = self.stable_sidecar_directory_metadata(expected_directory)?;
        let mut files = BTreeMap::new();
        if before.metadata.is_some() {
            let entries = std::fs::read_dir(expected_directory)
                .map_err(|error| Error::IO(error, expected_directory.to_path_buf()))?;
            for entry in entries {
                let entry =
                    entry.map_err(|error| Error::IO(error, expected_directory.to_path_buf()))?;
                let path = entry.path();
                let metadata = self
                    .regular_sidecar_metadata(&path, expected_directory)?
                    .ok_or_else(|| {
                        Error::IO(
                            std::io::Error::new(
                                ErrorKind::InvalidData,
                                "startup replay sidecar disappeared during identity capture",
                            ),
                            path.clone(),
                        )
                    })?;
                files.insert(path, metadata);
            }
        }
        let after = self.stable_sidecar_directory_metadata(expected_directory)?;
        if !Self::stable_sidecar_directory_metadata_unchanged(&before, &after) {
            return Err(Error::IO(
                std::io::Error::new(
                    ErrorKind::InvalidData,
                    "startup replay sidecar directory changed during identity capture",
                ),
                expected_directory.to_path_buf(),
            ));
        }
        Ok(StableSidecarDirectoryInventory {
            directory: after,
            files,
        })
    }

    fn stable_sidecar_directory_inventory_unchanged(
        left: &StableSidecarDirectoryInventory,
        right: &StableSidecarDirectoryInventory,
    ) -> bool {
        Self::stable_sidecar_directory_metadata_unchanged(&left.directory, &right.directory)
            && left.files.len() == right.files.len()
            && left.files.iter().all(|(path, metadata)| {
                right.files.get(path).is_some_and(|current| {
                    Self::stable_sidecar_metadata_unchanged(metadata, current)
                })
            })
    }

    fn regular_sidecar_metadata_for(
        store_root: &Path,
        path: &Path,
        expected_directory: &Path,
    ) -> Result<Option<StableSidecarMetadata>> {
        if path.parent() != Some(expected_directory) {
            return Err(Error::IO(
                std::io::Error::new(
                    ErrorKind::InvalidData,
                    "sidecar path is not an immediate child of its expected directory",
                ),
                path.to_path_buf(),
            ));
        }
        let directory = Self::canonical_sidecar_directory_for(store_root, expected_directory)?;
        let metadata = match std::fs::symlink_metadata(path) {
            Ok(metadata) => metadata,
            Err(err) if err.kind() == ErrorKind::NotFound => return Ok(None),
            Err(err) => return Err(Error::IO(err, path.to_path_buf())),
        };
        let Some((canonical_directory, directory_metadata)) = directory else {
            return Err(Error::IO(
                std::io::Error::new(
                    ErrorKind::InvalidData,
                    "sidecar exists without its expected direct directory",
                ),
                path.to_path_buf(),
            ));
        };
        if !metadata.file_type().is_file()
            || metadata.file_type().is_symlink()
            || !Self::sidecar_is_single_link(&metadata)
        {
            return Err(Error::IO(
                std::io::Error::new(
                    ErrorKind::InvalidData,
                    "sidecar path is not a single-link regular file",
                ),
                path.to_path_buf(),
            ));
        }
        let canonical_path =
            std::fs::canonicalize(path).map_err(|err| Error::IO(err, path.to_path_buf()))?;
        if canonical_path.parent() != Some(canonical_directory.as_path()) {
            return Err(Error::IO(
                std::io::Error::new(
                    ErrorKind::InvalidData,
                    "sidecar path escapes its canonical Kura directory",
                ),
                path.to_path_buf(),
            ));
        }
        Ok(Some(StableSidecarMetadata {
            canonical_path,
            file: metadata,
            directory: directory_metadata,
        }))
    }

    fn regular_sidecar_metadata(
        &self,
        path: &Path,
        expected_directory: &Path,
    ) -> Result<Option<StableSidecarMetadata>> {
        Self::regular_sidecar_metadata_for(&self.store_root, path, expected_directory)
    }

    fn open_bound_progress_file(
        namespace: &BoundProgressNamespace,
        path: &Path,
        expected: &StableSidecarMetadata,
    ) -> Result<std::fs::File> {
        let immediate = namespace.directories.first().ok_or_else(|| {
            Error::IO(
                std::io::Error::new(
                    ErrorKind::InvalidData,
                    "bound progress namespace has no immediate directory",
                ),
                path.to_path_buf(),
            )
        })?;
        if path.parent() != Some(immediate.expected_path.as_path()) {
            return Err(Error::IO(
                std::io::Error::new(
                    ErrorKind::InvalidInput,
                    "progress sidecar file is outside its bound immediate directory",
                ),
                path.to_path_buf(),
            ));
        }
        let file_name = path.file_name().ok_or_else(|| {
            Error::IO(
                std::io::Error::new(
                    ErrorKind::InvalidInput,
                    "progress sidecar file has no entry name",
                ),
                path.to_path_buf(),
            )
        })?;

        #[cfg(unix)]
        let file = std::fs::File::from(
            rustix::fs::openat(
                &immediate.file,
                file_name,
                rustix::fs::OFlags::RDWR
                    | rustix::fs::OFlags::NOFOLLOW
                    | rustix::fs::OFlags::CLOEXEC,
                rustix::fs::Mode::empty(),
            )
            .map_err(std::io::Error::from)
            .map_err(|error| Error::IO(error, path.to_path_buf()))?,
        );

        #[cfg(not(unix))]
        let file = {
            let mut options = std::fs::OpenOptions::new();
            options.read(true).write(true);
            #[cfg(windows)]
            {
                use std::os::windows::fs::OpenOptionsExt as _;

                const FILE_FLAG_OPEN_REPARSE_POINT: u32 = 0x0020_0000;
                options.custom_flags(FILE_FLAG_OPEN_REPARSE_POINT);
            }
            options
                .open(path)
                .map_err(|error| Error::IO(error, path.to_path_buf()))?
        };
        let opened = file
            .metadata()
            .map_err(|error| Error::IO(error, path.to_path_buf()))?;
        if !opened.is_file() || !Self::sidecar_file_metadata_unchanged(&expected.file, &opened) {
            return Err(Error::IO(
                std::io::Error::new(
                    ErrorKind::InvalidData,
                    "progress sidecar file changed while opening",
                ),
                path.to_path_buf(),
            ));
        }
        Ok(file)
    }

    fn open_optional_bound_progress_file(
        &self,
        namespace: &BoundProgressNamespace,
        path: &Path,
    ) -> Result<Option<std::fs::File>> {
        let immediate = namespace.directories.first().ok_or_else(|| {
            Error::IO(
                std::io::Error::new(
                    ErrorKind::InvalidData,
                    "bound progress namespace has no immediate directory",
                ),
                path.to_path_buf(),
            )
        })?;
        if path.parent() != Some(immediate.expected_path.as_path()) {
            return Err(Error::IO(
                std::io::Error::new(
                    ErrorKind::InvalidInput,
                    "progress sidecar file is outside its bound immediate directory",
                ),
                path.to_path_buf(),
            ));
        }
        let Some(expected) =
            Self::regular_sidecar_metadata_for(&self.store_root, path, &immediate.expected_path)?
        else {
            if !Self::progress_mutation_namespace_unchanged(namespace) {
                return Err(Error::IO(
                    std::io::Error::new(
                        ErrorKind::InvalidData,
                        "progress sidecar namespace changed while proving an optional file absent",
                    ),
                    path.to_path_buf(),
                ));
            }
            return Ok(None);
        };
        if !Self::sidecar_metadata_same_object(&immediate.metadata, &expected.directory) {
            return Err(Error::IO(
                std::io::Error::new(
                    ErrorKind::InvalidData,
                    "progress sidecar directory changed while binding an optional file",
                ),
                path.to_path_buf(),
            ));
        }
        let file = Self::open_bound_progress_file(namespace, path, &expected)?;
        if !Self::progress_mutation_namespace_unchanged(namespace) {
            return Err(Error::IO(
                std::io::Error::new(
                    ErrorKind::InvalidData,
                    "progress sidecar namespace changed while binding an optional file",
                ),
                path.to_path_buf(),
            ));
        }
        Ok(Some(file))
    }

    fn open_direct_sidecar_file_in_namespace(
        path: &Path,
        create: bool,
        append: bool,
        namespace: Option<&BoundProgressNamespace>,
    ) -> std::io::Result<std::fs::File> {
        let before = match std::fs::symlink_metadata(path) {
            Ok(metadata) => Some(metadata),
            Err(error) if error.kind() == ErrorKind::NotFound && create => None,
            Err(error) => return Err(error),
        };
        if before.as_ref().is_some_and(|metadata| {
            metadata.file_type().is_symlink()
                || !metadata.is_file()
                || !Self::sidecar_is_single_link(metadata)
        }) {
            return Err(std::io::Error::new(
                ErrorKind::InvalidData,
                "sidecar path is not a direct single-link regular file",
            ));
        }

        #[cfg(unix)]
        {
            use std::os::unix::fs::{MetadataExt as _, OpenOptionsExt as _};

            let parent_path = path.parent().ok_or_else(|| {
                std::io::Error::new(ErrorKind::InvalidInput, "sidecar path has no parent")
            })?;
            let file_name = path.file_name().ok_or_else(|| {
                std::io::Error::new(ErrorKind::InvalidInput, "sidecar path has no file name")
            })?;
            let owned_parent;
            let parent = if let Some(namespace) = namespace {
                let immediate = namespace.directories.first().ok_or_else(|| {
                    std::io::Error::new(
                        ErrorKind::InvalidData,
                        "bound sidecar namespace has no immediate directory",
                    )
                })?;
                if parent_path != immediate.expected_path {
                    return Err(std::io::Error::new(
                        ErrorKind::InvalidData,
                        "sidecar path is outside its bound namespace",
                    ));
                }
                let opened = immediate.file.metadata()?;
                let current = std::fs::symlink_metadata(parent_path)?;
                if !opened.is_dir()
                    || current.file_type().is_symlink()
                    || !current.is_dir()
                    || !Self::sidecar_metadata_same_object(&immediate.metadata, &opened)
                    || !Self::sidecar_metadata_same_object(&immediate.metadata, &current)
                {
                    return Err(std::io::Error::new(
                        ErrorKind::InvalidData,
                        "bound sidecar namespace changed before mutation",
                    ));
                }
                &immediate.file
            } else {
                let parent_before = std::fs::symlink_metadata(parent_path)?;
                if parent_before.file_type().is_symlink() || !parent_before.is_dir() {
                    return Err(std::io::Error::new(
                        ErrorKind::InvalidData,
                        "sidecar parent is not a direct directory",
                    ));
                }
                let mut options = std::fs::OpenOptions::new();
                options.read(true).custom_flags(
                    (rustix::fs::OFlags::DIRECTORY
                        | rustix::fs::OFlags::NOFOLLOW
                        | rustix::fs::OFlags::CLOEXEC)
                        .bits() as i32,
                );
                owned_parent = options.open(parent_path)?;
                let parent_opened = owned_parent.metadata()?;
                let parent_after = std::fs::symlink_metadata(parent_path)?;
                if !parent_opened.is_dir()
                    || parent_after.file_type().is_symlink()
                    || !parent_after.is_dir()
                    || !Self::sidecar_metadata_same_object(&parent_before, &parent_opened)
                    || !Self::sidecar_metadata_same_object(&parent_before, &parent_after)
                {
                    return Err(std::io::Error::new(
                        ErrorKind::InvalidData,
                        "sidecar parent changed while binding it",
                    ));
                }
                &owned_parent
            };

            let mut flags = rustix::fs::OFlags::RDWR
                | rustix::fs::OFlags::NOFOLLOW
                | rustix::fs::OFlags::CLOEXEC;
            if create {
                flags |= rustix::fs::OFlags::CREATE;
            }
            if append {
                flags |= rustix::fs::OFlags::APPEND;
            }
            let file = std::fs::File::from(
                rustix::fs::openat(
                    parent,
                    file_name,
                    flags,
                    rustix::fs::Mode::RUSR | rustix::fs::Mode::WUSR,
                )
                .map_err(std::io::Error::from)?,
            );
            let opened = file.metadata()?;
            let after =
                rustix::fs::statat(parent, file_name, rustix::fs::AtFlags::SYMLINK_NOFOLLOW)
                    .map_err(std::io::Error::from)?;
            if !opened.is_file()
                || !Self::sidecar_is_single_link(&opened)
                || after.st_dev as u64 != opened.dev()
                || after.st_ino as u64 != opened.ino()
                || after.st_nlink as u64 != 1
                || before
                    .as_ref()
                    .is_some_and(|metadata| !Self::sidecar_metadata_same_object(metadata, &opened))
            {
                return Err(std::io::Error::new(
                    ErrorKind::InvalidData,
                    "sidecar path identity changed while opening",
                ));
            }
            return Ok(file);
        }

        #[cfg(not(unix))]
        {
            let mut options = std::fs::OpenOptions::new();
            options.read(true).write(true).create(create).append(append);
            #[cfg(windows)]
            {
                use std::os::windows::fs::OpenOptionsExt as _;

                const FILE_FLAG_OPEN_REPARSE_POINT: u32 = 0x0020_0000;
                options.custom_flags(FILE_FLAG_OPEN_REPARSE_POINT);
            }
            let file = options.open(path)?;
            let opened = file.metadata()?;
            let after = std::fs::symlink_metadata(path)?;
            if !opened.is_file()
                || after.file_type().is_symlink()
                || !after.is_file()
                || !Self::sidecar_is_single_link(&opened)
                || !Self::sidecar_is_single_link(&after)
                || !Self::sidecar_metadata_same_object(&opened, &after)
                || before
                    .as_ref()
                    .is_some_and(|metadata| !Self::sidecar_metadata_same_object(metadata, &opened))
            {
                return Err(std::io::Error::new(
                    ErrorKind::InvalidData,
                    "sidecar path identity changed while opening",
                ));
            }
            Ok(file)
        }
    }

    fn remove_bound_progress_temp_if_present(
        namespace: &BoundProgressNamespace,
        path: &Path,
    ) -> std::io::Result<()> {
        let immediate = namespace.directories.first().ok_or_else(|| {
            std::io::Error::new(
                ErrorKind::InvalidData,
                "bound progress namespace has no immediate directory",
            )
        })?;
        if path.parent() != Some(immediate.expected_path.as_path()) {
            return Err(std::io::Error::new(
                ErrorKind::InvalidInput,
                "progress temp is outside its bound namespace",
            ));
        }
        let name = path.file_name().ok_or_else(|| {
            std::io::Error::new(ErrorKind::InvalidInput, "progress temp has no entry name")
        })?;

        #[cfg(unix)]
        {
            let entry = match rustix::fs::statat(
                &immediate.file,
                name,
                rustix::fs::AtFlags::SYMLINK_NOFOLLOW,
            ) {
                Ok(entry) => entry,
                Err(rustix::io::Errno::NOENT) => return Ok(()),
                Err(error) => return Err(std::io::Error::from(error)),
            };
            if rustix::fs::FileType::from_raw_mode(entry.st_mode)
                != rustix::fs::FileType::RegularFile
                || entry.st_nlink as u64 != 1
            {
                return Err(std::io::Error::new(
                    ErrorKind::InvalidData,
                    "progress temp is not a direct single-link regular file",
                ));
            }
            rustix::fs::unlinkat(&immediate.file, name, rustix::fs::AtFlags::empty())
                .map_err(std::io::Error::from)?;
            return Ok(());
        }

        #[cfg(not(unix))]
        {
            match std::fs::symlink_metadata(path) {
                Ok(metadata)
                    if metadata.is_file()
                        && !metadata.file_type().is_symlink()
                        && Self::sidecar_is_single_link(&metadata) =>
                {
                    std::fs::remove_file(path)
                }
                Ok(_) => Err(std::io::Error::new(
                    ErrorKind::InvalidData,
                    "progress temp is not a direct single-link regular file",
                )),
                Err(error) if error.kind() == ErrorKind::NotFound => Ok(()),
                Err(error) => Err(error),
            }
        }
    }

    fn create_new_bound_progress_temp(
        namespace: &BoundProgressNamespace,
        path: &Path,
    ) -> std::io::Result<std::fs::File> {
        let immediate = namespace.directories.first().ok_or_else(|| {
            std::io::Error::new(
                ErrorKind::InvalidData,
                "bound progress namespace has no immediate directory",
            )
        })?;
        if path.parent() != Some(immediate.expected_path.as_path()) {
            return Err(std::io::Error::new(
                ErrorKind::InvalidInput,
                "progress temp is outside its bound namespace",
            ));
        }
        let name = path.file_name().ok_or_else(|| {
            std::io::Error::new(ErrorKind::InvalidInput, "progress temp has no entry name")
        })?;

        #[cfg(unix)]
        {
            let file = std::fs::File::from(
                rustix::fs::openat(
                    &immediate.file,
                    name,
                    rustix::fs::OFlags::RDWR
                        | rustix::fs::OFlags::CREATE
                        | rustix::fs::OFlags::EXCL
                        | rustix::fs::OFlags::NOFOLLOW
                        | rustix::fs::OFlags::CLOEXEC,
                    rustix::fs::Mode::RUSR | rustix::fs::Mode::WUSR,
                )
                .map_err(std::io::Error::from)?,
            );
            let metadata = file.metadata()?;
            let entry =
                rustix::fs::statat(&immediate.file, name, rustix::fs::AtFlags::SYMLINK_NOFOLLOW)
                    .map_err(std::io::Error::from)?;
            use std::os::unix::fs::MetadataExt as _;
            if !metadata.is_file()
                || metadata.nlink() != 1
                || entry.st_dev as u64 != metadata.dev()
                || entry.st_ino as u64 != metadata.ino()
                || entry.st_nlink as u64 != 1
            {
                return Err(std::io::Error::new(
                    ErrorKind::InvalidData,
                    "progress temp identity changed during exclusive creation",
                ));
            }
            return Ok(file);
        }

        #[cfg(not(unix))]
        {
            let mut options = std::fs::OpenOptions::new();
            options.read(true).write(true).create_new(true);
            #[cfg(windows)]
            {
                use std::os::windows::fs::OpenOptionsExt as _;

                const FILE_FLAG_OPEN_REPARSE_POINT: u32 = 0x0020_0000;
                options.custom_flags(FILE_FLAG_OPEN_REPARSE_POINT);
            }
            let file = options.open(path)?;
            let metadata = file.metadata()?;
            if !metadata.is_file() || !Self::sidecar_is_single_link(&metadata) {
                return Err(std::io::Error::new(
                    ErrorKind::InvalidData,
                    "progress temp is not a direct single-link regular file",
                ));
            }
            Ok(file)
        }
    }

    fn promote_bound_progress_temp(
        namespace: &BoundProgressNamespace,
        temp_path: &Path,
        main_path: &Path,
        temp: &std::fs::File,
    ) -> std::result::Result<(), BoundProgressPromotionError> {
        let unpublished = |source| BoundProgressPromotionError {
            published: false,
            source,
        };
        let published = |source| BoundProgressPromotionError {
            published: true,
            source,
        };
        let immediate = namespace
            .directories
            .first()
            .ok_or_else(|| {
                std::io::Error::new(
                    ErrorKind::InvalidData,
                    "bound progress namespace has no immediate directory",
                )
            })
            .map_err(unpublished)?;
        if temp_path.parent() != Some(immediate.expected_path.as_path())
            || main_path.parent() != Some(immediate.expected_path.as_path())
        {
            return Err(unpublished(std::io::Error::new(
                ErrorKind::InvalidInput,
                "progress promotion escapes its bound namespace",
            )));
        }
        let temp_name = temp_path
            .file_name()
            .ok_or_else(|| {
                std::io::Error::new(ErrorKind::InvalidInput, "progress temp has no entry name")
            })
            .map_err(unpublished)?;
        let main_name = main_path
            .file_name()
            .ok_or_else(|| {
                std::io::Error::new(ErrorKind::InvalidInput, "progress index has no entry name")
            })
            .map_err(unpublished)?;

        #[cfg(unix)]
        {
            use std::os::unix::fs::MetadataExt as _;

            let metadata = temp.metadata().map_err(unpublished)?;
            let before = rustix::fs::statat(
                &immediate.file,
                temp_name,
                rustix::fs::AtFlags::SYMLINK_NOFOLLOW,
            )
            .map_err(std::io::Error::from)
            .map_err(unpublished)?;
            if !metadata.is_file()
                || metadata.nlink() != 1
                || before.st_dev as u64 != metadata.dev()
                || before.st_ino as u64 != metadata.ino()
                || before.st_nlink as u64 != 1
            {
                return Err(unpublished(std::io::Error::new(
                    ErrorKind::InvalidData,
                    "progress temp changed before promotion",
                )));
            }
            rustix::fs::renameat(&immediate.file, temp_name, &immediate.file, main_name)
                .map_err(std::io::Error::from)
                .map_err(unpublished)?;
            let after = rustix::fs::statat(
                &immediate.file,
                main_name,
                rustix::fs::AtFlags::SYMLINK_NOFOLLOW,
            )
            .map_err(std::io::Error::from)
            .map_err(published)?;
            if after.st_dev as u64 != metadata.dev()
                || after.st_ino as u64 != metadata.ino()
                || after.st_nlink as u64 != 1
            {
                return Err(published(std::io::Error::new(
                    ErrorKind::InvalidData,
                    "promoted progress index has the wrong identity",
                )));
            }
            return Ok(());
        }

        #[cfg(not(unix))]
        {
            let _ = (namespace, temp_path, main_path, temp);
            Err(BoundProgressPromotionError {
                published: false,
                source: std::io::Error::new(
                    ErrorKind::Unsupported,
                    "descriptor-relative progress prepend promotion is unsupported on this platform",
                ),
            })
        }
    }

    fn bound_progress_append_build_path(index_path: &Path) -> PathBuf {
        index_path.with_extension("index.append.build.tmp")
    }

    fn bound_progress_append_intent_path(index_path: &Path) -> PathBuf {
        index_path.with_extension("index.append.intent.tmp")
    }

    fn sync_bound_progress_intent_directories(
        namespace: &BoundProgressNamespace,
    ) -> std::io::Result<()> {
        #[cfg(test)]
        let fail_at = FAIL_BOUND_PROGRESS_INTENT_DIRECTORY_SYNC.with(|slot| {
            let Some(mut fault) = slot.get() else {
                return None;
            };
            if fault.calls_before_failure > 0 {
                fault.calls_before_failure -= 1;
                slot.set(Some(fault));
                None
            } else {
                Some(fault.target_index)
            }
        });
        #[cfg(not(test))]
        let fail_at: Option<usize> = None;
        for (position, directory) in namespace.directories.iter().enumerate() {
            if fail_at == Some(position) {
                #[cfg(test)]
                FAIL_BOUND_PROGRESS_INTENT_DIRECTORY_SYNC.with(|slot| slot.set(None));
                return Err(std::io::Error::other(
                    "injected bound progress append-intent directory sync failure",
                ));
            }
            directory.file.sync_all()?;
        }
        Ok(())
    }

    fn promote_bound_progress_temp_noreplace(
        namespace: &BoundProgressNamespace,
        temp_path: &Path,
        intent_path: &Path,
        temp: &std::fs::File,
    ) -> std::result::Result<(), BoundProgressPromotionError> {
        let unpublished = |source| BoundProgressPromotionError {
            published: false,
            source,
        };
        let published = |source| BoundProgressPromotionError {
            published: true,
            source,
        };
        let immediate = namespace
            .directories
            .first()
            .ok_or_else(|| {
                std::io::Error::new(
                    ErrorKind::InvalidData,
                    "bound progress namespace has no immediate directory",
                )
            })
            .map_err(unpublished)?;
        if temp_path.parent() != Some(immediate.expected_path.as_path())
            || intent_path.parent() != Some(immediate.expected_path.as_path())
        {
            return Err(unpublished(std::io::Error::new(
                ErrorKind::InvalidInput,
                "progress append-intent promotion escapes its bound namespace",
            )));
        }
        let temp_name = temp_path
            .file_name()
            .ok_or_else(|| {
                std::io::Error::new(ErrorKind::InvalidInput, "progress build has no entry name")
            })
            .map_err(unpublished)?;
        let intent_name = intent_path
            .file_name()
            .ok_or_else(|| {
                std::io::Error::new(ErrorKind::InvalidInput, "progress intent has no entry name")
            })
            .map_err(unpublished)?;

        #[cfg(any(target_vendor = "apple", target_os = "linux", target_os = "android"))]
        {
            use std::os::unix::fs::MetadataExt as _;

            let metadata = temp.metadata().map_err(unpublished)?;
            let before = rustix::fs::statat(
                &immediate.file,
                temp_name,
                rustix::fs::AtFlags::SYMLINK_NOFOLLOW,
            )
            .map_err(std::io::Error::from)
            .map_err(unpublished)?;
            if !metadata.is_file()
                || metadata.nlink() != 1
                || before.st_dev as u64 != metadata.dev()
                || before.st_ino as u64 != metadata.ino()
                || before.st_nlink as u64 != 1
            {
                return Err(unpublished(std::io::Error::new(
                    ErrorKind::InvalidData,
                    "progress append-intent build changed before promotion",
                )));
            }
            rustix::fs::renameat_with(
                &immediate.file,
                temp_name,
                &immediate.file,
                intent_name,
                rustix::fs::RenameFlags::NOREPLACE,
            )
            .map_err(std::io::Error::from)
            .map_err(unpublished)?;
            let after = rustix::fs::statat(
                &immediate.file,
                intent_name,
                rustix::fs::AtFlags::SYMLINK_NOFOLLOW,
            )
            .map_err(std::io::Error::from)
            .map_err(published)?;
            if after.st_dev as u64 != metadata.dev()
                || after.st_ino as u64 != metadata.ino()
                || after.st_nlink as u64 != 1
            {
                return Err(published(std::io::Error::new(
                    ErrorKind::InvalidData,
                    "published progress append intent has the wrong identity",
                )));
            }
            return Ok(());
        }

        #[cfg(not(any(target_vendor = "apple", target_os = "linux", target_os = "android")))]
        {
            let _ = (namespace, temp_path, intent_path, temp);
            Err(BoundProgressPromotionError {
                published: false,
                source: std::io::Error::new(
                    ErrorKind::Unsupported,
                    "atomic descriptor-relative append-intent publication is unsupported on this platform",
                ),
            })
        }
    }

    fn publish_bound_progress_append_intent(
        namespace: &BoundProgressNamespace,
        index_path: &Path,
        intent: &BoundProgressAppendIntentV1,
        kind: &str,
    ) -> Option<std::fs::File> {
        let build_path = Self::bound_progress_append_build_path(index_path);
        let intent_path = Self::bound_progress_append_intent_path(index_path);
        let bytes = match norito::encode_canonical(intent) {
            Ok(bytes)
                if !bytes.is_empty() && bytes.len() <= BOUND_PROGRESS_APPEND_INTENT_MAX_BYTES =>
            {
                bytes
            }
            Ok(bytes) => {
                warn!(
                    len = bytes.len(),
                    ?intent_path,
                    kind,
                    "bound progress append intent exceeds its hard byte limit"
                );
                return None;
            }
            Err(error) => {
                warn!(
                    ?error,
                    ?intent_path,
                    kind,
                    "failed to encode progress append intent"
                );
                return None;
            }
        };
        let mut build = match Self::create_new_bound_progress_temp(namespace, &build_path) {
            Ok(build) => build,
            Err(error) => {
                warn!(
                    ?error,
                    ?build_path,
                    kind,
                    "failed to create progress append-intent build"
                );
                return None;
            }
        };
        if let Err(error) = build
            .write_all(&bytes)
            .and_then(|_| build.flush())
            .and_then(|_| sync_bound_progress_intent_file(&build))
        {
            warn!(
                ?error,
                ?build_path,
                kind,
                "failed to persist progress append-intent build"
            );
            drop(build);
            let _ = Self::remove_bound_progress_temp_if_present(namespace, &build_path);
            let _ = Self::sync_bound_progress_intent_directories(namespace);
            return None;
        }
        if let Err(error) = Self::promote_bound_progress_temp_noreplace(
            namespace,
            &build_path,
            &intent_path,
            &build,
        ) {
            warn!(
                source = ?error.source,
                published = error.published,
                ?build_path,
                ?intent_path,
                kind,
                "failed to publish progress append intent"
            );
            drop(build);
            if !error.published {
                let _ = Self::remove_bound_progress_temp_if_present(namespace, &build_path);
                let _ = Self::sync_bound_progress_intent_directories(namespace);
            }
            return None;
        }
        if let Err(error) = Self::sync_bound_progress_intent_directories(namespace) {
            warn!(
                ?error,
                ?intent_path,
                kind,
                "failed to sync progress append-intent publication"
            );
            return None;
        }
        Some(build)
    }

    fn open_bound_progress_directory(
        store_root: &Path,
        expected_path: &Path,
    ) -> Result<BoundProgressDirectory> {
        let (canonical_path, metadata) =
            Self::canonical_sidecar_directory_for(store_root, expected_path)?.ok_or_else(|| {
                Error::IO(
                    std::io::Error::new(
                        ErrorKind::NotFound,
                        "progress sidecar directory disappeared while binding it",
                    ),
                    expected_path.to_path_buf(),
                )
            })?;
        let mut options = std::fs::OpenOptions::new();
        options.read(true);
        #[cfg(unix)]
        {
            use std::os::unix::fs::OpenOptionsExt as _;

            options.custom_flags(
                (rustix::fs::OFlags::DIRECTORY | rustix::fs::OFlags::NOFOLLOW).bits() as i32,
            );
        }
        #[cfg(windows)]
        {
            use std::os::windows::fs::OpenOptionsExt as _;

            const FILE_FLAG_OPEN_REPARSE_POINT: u32 = 0x0020_0000;
            const FILE_FLAG_BACKUP_SEMANTICS: u32 = 0x0200_0000;
            options.custom_flags(FILE_FLAG_OPEN_REPARSE_POINT | FILE_FLAG_BACKUP_SEMANTICS);
        }
        let file = options
            .open(expected_path)
            .map_err(|error| Error::IO(error, expected_path.to_path_buf()))?;
        let opened = file
            .metadata()
            .map_err(|error| Error::IO(error, expected_path.to_path_buf()))?;
        let after = Self::canonical_sidecar_directory_for(store_root, expected_path)?;
        if !opened.is_dir()
            || !Self::sidecar_directory_metadata_unchanged(&metadata, &opened)
            || !after.as_ref().is_some_and(|(after_path, after_metadata)| {
                *after_path == canonical_path
                    && Self::sidecar_directory_metadata_unchanged(&metadata, after_metadata)
            })
        {
            return Err(Error::IO(
                std::io::Error::new(
                    ErrorKind::InvalidData,
                    "progress sidecar directory changed while opening",
                ),
                expected_path.to_path_buf(),
            ));
        }
        Ok(BoundProgressDirectory {
            expected_path: expected_path.to_path_buf(),
            canonical_path,
            entry_name: None,
            file,
            metadata,
        })
    }

    fn open_bound_progress_child_directory(
        store_root: &Path,
        parent: &BoundProgressDirectory,
        expected_path: &Path,
    ) -> Result<BoundProgressDirectory> {
        #[cfg(unix)]
        let _ = store_root;
        if expected_path.parent() != Some(parent.expected_path.as_path()) {
            return Err(Error::IO(
                std::io::Error::new(
                    ErrorKind::InvalidInput,
                    "progress sidecar directory is not a direct child of its bound parent",
                ),
                expected_path.to_path_buf(),
            ));
        }
        let name = expected_path.file_name().ok_or_else(|| {
            Error::IO(
                std::io::Error::new(
                    ErrorKind::InvalidInput,
                    "progress sidecar child directory has no entry name",
                ),
                expected_path.to_path_buf(),
            )
        })?;

        #[cfg(unix)]
        {
            use std::os::unix::fs::MetadataExt as _;

            let before =
                rustix::fs::statat(&parent.file, name, rustix::fs::AtFlags::SYMLINK_NOFOLLOW)
                    .map_err(std::io::Error::from)
                    .map_err(|error| Error::IO(error, expected_path.to_path_buf()))?;
            if rustix::fs::FileType::from_raw_mode(before.st_mode)
                != rustix::fs::FileType::Directory
            {
                return Err(Error::IO(
                    std::io::Error::new(
                        ErrorKind::InvalidData,
                        "progress sidecar path component is not a direct directory",
                    ),
                    expected_path.to_path_buf(),
                ));
            }
            let file = std::fs::File::from(
                rustix::fs::openat(
                    &parent.file,
                    name,
                    rustix::fs::OFlags::RDONLY
                        | rustix::fs::OFlags::DIRECTORY
                        | rustix::fs::OFlags::NOFOLLOW
                        | rustix::fs::OFlags::CLOEXEC,
                    rustix::fs::Mode::empty(),
                )
                .map_err(std::io::Error::from)
                .map_err(|error| Error::IO(error, expected_path.to_path_buf()))?,
            );
            let metadata = file
                .metadata()
                .map_err(|error| Error::IO(error, expected_path.to_path_buf()))?;
            let after =
                rustix::fs::statat(&parent.file, name, rustix::fs::AtFlags::SYMLINK_NOFOLLOW)
                    .map_err(std::io::Error::from)
                    .map_err(|error| Error::IO(error, expected_path.to_path_buf()))?;
            let canonical_path = parent.canonical_path.join(name);
            let canonical_after = std::fs::canonicalize(expected_path)
                .map_err(|error| Error::IO(error, expected_path.to_path_buf()))?;
            if !metadata.is_dir()
                || before.st_dev as u64 != metadata.dev()
                || before.st_ino as u64 != metadata.ino()
                || after.st_dev as u64 != metadata.dev()
                || after.st_ino as u64 != metadata.ino()
                || canonical_after != canonical_path
            {
                return Err(Error::IO(
                    std::io::Error::new(
                        ErrorKind::InvalidData,
                        "progress sidecar directory changed during descriptor-relative binding",
                    ),
                    expected_path.to_path_buf(),
                ));
            }
            return Ok(BoundProgressDirectory {
                expected_path: expected_path.to_path_buf(),
                canonical_path,
                entry_name: Some(name.to_os_string()),
                file,
                metadata,
            });
        }

        #[cfg(not(unix))]
        {
            let mut child = Self::open_bound_progress_directory(store_root, expected_path)?;
            child.entry_name = Some(name.to_os_string());
            Ok(child)
        }
    }

    fn open_bound_progress_namespace(
        &self,
        data_path: &Path,
        index_path: &Path,
    ) -> Result<BoundProgressNamespace> {
        let sidecar_dir = data_path.parent().ok_or_else(|| {
            Error::IO(
                std::io::Error::new(
                    ErrorKind::InvalidInput,
                    "progress sidecar data path has no parent",
                ),
                data_path.to_path_buf(),
            )
        })?;
        if index_path.parent() != Some(sidecar_dir) {
            return Err(Error::IO(
                std::io::Error::new(
                    ErrorKind::InvalidInput,
                    "progress sidecar files do not share one parent directory",
                ),
                index_path.to_path_buf(),
            ));
        }
        let mut directory_paths = vec![sidecar_dir.to_path_buf()];
        let mut ancestor = sidecar_dir;
        loop {
            if ancestor == self.store_root {
                break;
            }
            ancestor = ancestor.parent().ok_or_else(|| {
                Error::IO(
                    std::io::Error::new(
                        ErrorKind::InvalidData,
                        "progress sidecar durability chain did not reach the Kura root",
                    ),
                    ancestor.to_path_buf(),
                )
            })?;
            directory_paths.push(ancestor.to_path_buf());
        }
        directory_paths.reverse();
        let Some(root_path) = directory_paths.first() else {
            return Err(Error::IO(
                std::io::Error::new(
                    ErrorKind::InvalidData,
                    "progress sidecar durability chain is empty",
                ),
                sidecar_dir.to_path_buf(),
            ));
        };
        let root = Self::open_bound_progress_directory(&self.store_root, root_path)?;
        let mut directories = Vec::with_capacity(directory_paths.len());
        directories.push(root);
        for path in directory_paths.iter().skip(1) {
            let parent = directories
                .last()
                .expect("bound progress directory chain starts at Kura root");
            let child = Self::open_bound_progress_child_directory(&self.store_root, parent, path)?;
            directories.push(child);
        }
        directories.reverse();

        let namespace = BoundProgressNamespace {
            data_path: data_path.to_path_buf(),
            index_path: index_path.to_path_buf(),
            directories,
        };
        if !self.bound_progress_namespace_unchanged(&namespace) {
            return Err(Error::IO(
                std::io::Error::new(
                    ErrorKind::InvalidData,
                    "progress sidecar namespace changed while binding durability handles",
                ),
                sidecar_dir.to_path_buf(),
            ));
        }
        Ok(namespace)
    }

    fn open_bound_progress_pair(
        &self,
        data_path: &Path,
        index_path: &Path,
    ) -> Result<BoundProgressPair> {
        let namespace = self.open_bound_progress_namespace(data_path, index_path)?;
        let sidecar_dir = namespace
            .data_path
            .parent()
            .expect("bound progress namespace always has an immediate parent");

        let data_metadata =
            Self::regular_sidecar_metadata_for(&self.store_root, data_path, sidecar_dir)?;
        let index_metadata =
            Self::regular_sidecar_metadata_for(&self.store_root, index_path, sidecar_dir)?;
        let (data_metadata, index_metadata) = match (data_metadata, index_metadata) {
            (None, None) => {
                if !self.bound_progress_namespace_unchanged(&namespace) {
                    return Err(Error::IO(
                        std::io::Error::new(
                            ErrorKind::InvalidData,
                            "progress sidecar namespace changed while attesting absence",
                        ),
                        sidecar_dir.to_path_buf(),
                    ));
                }
                return Ok(BoundProgressPair::Absent(namespace));
            }
            (Some(data), Some(index)) => (data, index),
            _ => {
                return Err(Error::IO(
                    std::io::Error::new(
                        ErrorKind::InvalidData,
                        "progress sidecar data and index are only partially present",
                    ),
                    sidecar_dir.to_path_buf(),
                ));
            }
        };
        let data = Self::open_bound_progress_file(&namespace, data_path, &data_metadata)?;
        let index = Self::open_bound_progress_file(&namespace, index_path, &index_metadata)?;

        let bound = BoundProgressSidecar {
            namespace,
            data,
            index,
            data_metadata,
            index_metadata,
        };
        if !self.bound_progress_sidecar_unchanged(&bound) {
            return Err(Error::IO(
                std::io::Error::new(
                    ErrorKind::InvalidData,
                    "progress sidecar identity changed while binding its durability handles",
                ),
                data_path.to_path_buf(),
            ));
        }
        Ok(BoundProgressPair::Present(bound))
    }

    fn open_bound_progress_sidecar(
        &self,
        data_path: &Path,
        index_path: &Path,
    ) -> Result<BoundProgressSidecar> {
        match self.open_bound_progress_pair(data_path, index_path)? {
            BoundProgressPair::Present(bound) => Ok(bound),
            BoundProgressPair::Absent(namespace) => Err(Error::IO(
                std::io::Error::new(ErrorKind::NotFound, "progress sidecar pair is absent"),
                namespace.data_path,
            )),
        }
    }

    fn bound_progress_namespace_unchanged(&self, namespace: &BoundProgressNamespace) -> bool {
        namespace
            .directories
            .iter()
            .enumerate()
            .all(|(index, directory)| {
                let Ok(opened) = directory.file.metadata() else {
                    return false;
                };
                #[cfg(unix)]
                if let Some(name) = directory.entry_name.as_deref() {
                    use std::os::unix::fs::MetadataExt as _;

                    let Some(parent) = namespace.directories.get(index.saturating_add(1)) else {
                        return false;
                    };
                    let Ok(entry) = rustix::fs::statat(
                        &parent.file,
                        name,
                        rustix::fs::AtFlags::SYMLINK_NOFOLLOW,
                    ) else {
                        return false;
                    };
                    if rustix::fs::FileType::from_raw_mode(entry.st_mode)
                        != rustix::fs::FileType::Directory
                        || entry.st_dev as u64 != opened.dev()
                        || entry.st_ino as u64 != opened.ino()
                    {
                        return false;
                    }
                }
                let opened_matches = if index == 0 {
                    Self::sidecar_directory_metadata_unchanged(&directory.metadata, &opened)
                } else {
                    Self::sidecar_metadata_same_object(&directory.metadata, &opened)
                };
                if !opened.is_dir() || !opened_matches {
                    return false;
                }
                Self::canonical_sidecar_directory_for(&self.store_root, &directory.expected_path)
                    .ok()
                    .flatten()
                    .is_some_and(|(canonical_path, metadata)| {
                        let path_matches = if index == 0 {
                            Self::sidecar_directory_metadata_unchanged(
                                &directory.metadata,
                                &metadata,
                            )
                        } else {
                            Self::sidecar_metadata_same_object(&directory.metadata, &metadata)
                        };
                        canonical_path == directory.canonical_path && path_matches
                    })
            })
    }

    fn bound_progress_sidecar_unchanged(&self, bound: &BoundProgressSidecar) -> bool {
        let Some(sidecar_dir) = bound.namespace.data_path.parent() else {
            return false;
        };
        if bound.namespace.index_path.parent() != Some(sidecar_dir) {
            return false;
        }
        let Ok(data_opened) = bound.data.metadata() else {
            return false;
        };
        let Ok(index_opened) = bound.index.metadata() else {
            return false;
        };
        if !Self::sidecar_file_metadata_unchanged(&bound.data_metadata.file, &data_opened)
            || !Self::sidecar_file_metadata_unchanged(&bound.index_metadata.file, &index_opened)
        {
            return false;
        }
        let Ok(data_after) = Self::regular_sidecar_metadata_for(
            &self.store_root,
            &bound.namespace.data_path,
            sidecar_dir,
        ) else {
            return false;
        };
        let Ok(index_after) = Self::regular_sidecar_metadata_for(
            &self.store_root,
            &bound.namespace.index_path,
            sidecar_dir,
        ) else {
            return false;
        };
        if !data_after.as_ref().is_some_and(|after| {
            Self::stable_sidecar_metadata_unchanged(&bound.data_metadata, after)
        }) || !index_after.as_ref().is_some_and(|after| {
            Self::stable_sidecar_metadata_unchanged(&bound.index_metadata, after)
        }) {
            return false;
        }
        self.bound_progress_namespace_unchanged(&bound.namespace)
    }

    fn sync_bound_progress_namespace(
        &self,
        namespace: &BoundProgressNamespace,
        kind: &str,
    ) -> bool {
        for (index, directory) in namespace.directories.iter().enumerate() {
            let result = if index == 0 {
                sync_indexed_sidecar_dir_handle(&directory.file)
            } else {
                sync_progress_sidecar_ancestor_dir_handle(&directory.file)
            };
            if let Err(err) = result {
                iroha_logger::warn!(
                    ?err,
                    path = ?directory.expected_path,
                    kind,
                    "failed to sync bound progress sidecar namespace"
                );
                return false;
            }
        }
        self.bound_progress_namespace_unchanged(namespace)
    }

    fn sync_bound_progress_absence(&self, namespace: &BoundProgressNamespace, kind: &str) -> bool {
        if !self.sync_bound_progress_namespace(namespace, kind) {
            return false;
        }
        let Some(sidecar_dir) = namespace.data_path.parent() else {
            return false;
        };
        if namespace.index_path.parent() != Some(sidecar_dir) {
            return false;
        }
        matches!(
            Self::regular_sidecar_metadata_for(&self.store_root, &namespace.data_path, sidecar_dir,),
            Ok(None)
        ) && matches!(
            Self::regular_sidecar_metadata_for(
                &self.store_root,
                &namespace.index_path,
                sidecar_dir,
            ),
            Ok(None)
        ) && self.bound_progress_namespace_unchanged(namespace)
    }

    fn sync_bound_progress_sidecar(&self, bound: &BoundProgressSidecar, kind: &str) -> bool {
        if let Err(err) = sync_indexed_sidecar_data(&bound.data) {
            iroha_logger::warn!(?err, path = ?bound.namespace.data_path, kind, "failed to sync progress sidecar payload");
            return false;
        }
        if let Err(err) = sync_indexed_sidecar_index(&bound.index) {
            iroha_logger::warn!(?err, path = ?bound.namespace.index_path, kind, "failed to sync progress sidecar index");
            return false;
        }
        self.sync_bound_progress_namespace(&bound.namespace, kind)
            && self.bound_progress_sidecar_unchanged(bound)
    }

    fn bound_indexed_sidecar_payload_heights(
        &self,
        bound: &mut BoundProgressSidecar,
        kind: &str,
        limit: usize,
    ) -> Result<BTreeSet<u64>> {
        if !self.bound_progress_sidecar_unchanged(bound) {
            return Err(Error::IO(
                std::io::Error::new(
                    ErrorKind::InvalidData,
                    "progress sidecar identity changed before index enumeration",
                ),
                bound.namespace.index_path.clone(),
            ));
        }
        let index_len = bound
            .index
            .metadata()
            .map_err(|error| Error::IO(error, bound.namespace.index_path.clone()))?
            .len();
        let layout =
            SidecarIndexLayout::read_from(&mut bound.index, index_len).map_err(|reason| {
                Error::IO(
                    std::io::Error::new(
                        ErrorKind::InvalidData,
                        format!("{kind} index is malformed: {reason}"),
                    ),
                    bound.namespace.index_path.clone(),
                )
            })?;
        if layout.aligned_len != index_len
            || usize::try_from(layout.entry_count).unwrap_or(usize::MAX) > limit
        {
            return Err(Error::IO(
                std::io::Error::new(
                    ErrorKind::InvalidData,
                    format!("{kind} index is misaligned or exceeds its bounded entry count"),
                ),
                bound.namespace.index_path.clone(),
            ));
        }
        let data_len = bound
            .data
            .metadata()
            .map_err(|error| Error::IO(error, bound.namespace.data_path.clone()))?
            .len();
        bound
            .index
            .seek(SeekFrom::Start(layout.entries_offset))
            .map_err(|error| Error::IO(error, bound.namespace.index_path.clone()))?;
        let mut heights = BTreeSet::new();
        let mut indexed_end = 0_u64;
        let mut encoded = [0_u8; PIPELINE_INDEX_ENTRY_SIZE];
        for offset in 0..layout.entry_count {
            bound
                .index
                .read_exact(&mut encoded)
                .map_err(|error| Error::IO(error, bound.namespace.index_path.clone()))?;
            let entry = SidecarIndexEntry::from_bytes(encoded);
            if entry.len == 0 {
                continue;
            }
            if entry.len > STRICT_INIT_MAX_BLOCK_BYTES
                || entry
                    .offset
                    .checked_add(entry.len)
                    .is_none_or(|end| end > data_len)
            {
                return Err(Error::IO(
                    std::io::Error::new(
                        ErrorKind::InvalidData,
                        format!("{kind} index contains an invalid payload range"),
                    ),
                    bound.namespace.index_path.clone(),
                ));
            }
            indexed_end = indexed_end.max(
                entry
                    .offset
                    .checked_add(entry.len)
                    .expect("validated sidecar range cannot overflow"),
            );
            let height = layout.base_height.checked_add(offset).ok_or_else(|| {
                Error::IO(
                    std::io::Error::new(
                        ErrorKind::InvalidData,
                        format!("{kind} index height overflows"),
                    ),
                    bound.namespace.index_path.clone(),
                )
            })?;
            heights.insert(height);
        }
        if data_len != indexed_end {
            return Err(Error::IO(
                std::io::Error::new(
                    ErrorKind::InvalidData,
                    format!("{kind} data has an unindexed suffix and requires writer recovery"),
                ),
                bound.namespace.data_path.clone(),
            ));
        }
        if !self.bound_progress_sidecar_unchanged(bound) {
            return Err(Error::IO(
                std::io::Error::new(
                    ErrorKind::InvalidData,
                    "progress sidecar identity changed during index enumeration",
                ),
                bound.namespace.index_path.clone(),
            ));
        }
        Ok(heights)
    }

    fn bound_indexed_sidecar_height_range(
        &self,
        bound: &mut BoundProgressSidecar,
        kind: &str,
    ) -> Result<Option<core::ops::RangeInclusive<u64>>> {
        if !self.bound_progress_sidecar_unchanged(bound) {
            return Err(Error::IO(
                std::io::Error::new(
                    ErrorKind::InvalidData,
                    "progress sidecar identity changed before range enumeration",
                ),
                bound.namespace.index_path.clone(),
            ));
        }
        let index_len = bound
            .index
            .metadata()
            .map_err(|error| Error::IO(error, bound.namespace.index_path.clone()))?
            .len();
        let layout =
            SidecarIndexLayout::read_from(&mut bound.index, index_len).map_err(|reason| {
                Error::IO(
                    std::io::Error::new(
                        ErrorKind::InvalidData,
                        format!("{kind} index is malformed: {reason}"),
                    ),
                    bound.namespace.index_path.clone(),
                )
            })?;
        if layout.aligned_len != index_len {
            return Err(Error::IO(
                std::io::Error::new(
                    ErrorKind::InvalidData,
                    format!("{kind} index has trailing or partial bytes"),
                ),
                bound.namespace.index_path.clone(),
            ));
        }
        if !self.bound_progress_sidecar_unchanged(bound) {
            return Err(Error::IO(
                std::io::Error::new(
                    ErrorKind::InvalidData,
                    "progress sidecar identity changed during range enumeration",
                ),
                bound.namespace.index_path.clone(),
            ));
        }
        Ok(layout.height_range())
    }

    fn read_regular_sidecar_bytes_for(
        store_root: &Path,
        path: &Path,
        expected_directory: &Path,
        byte_limit: usize,
    ) -> Result<Option<Vec<u8>>> {
        Ok(Self::read_regular_sidecar_snapshot_for(
            store_root,
            path,
            expected_directory,
            byte_limit,
        )?
        .map(|snapshot| snapshot.bytes))
    }

    fn read_regular_sidecar_snapshot_for(
        store_root: &Path,
        path: &Path,
        expected_directory: &Path,
        byte_limit: usize,
    ) -> Result<Option<StableSidecarRead>> {
        let directory_before =
            Self::canonical_sidecar_directory_for(store_root, expected_directory)?;
        let Some(metadata) =
            Self::regular_sidecar_metadata_for(store_root, path, expected_directory)?
        else {
            return Ok(None);
        };
        let Some((_, directory_before)) = directory_before else {
            return Err(Error::IO(
                std::io::Error::new(
                    ErrorKind::InvalidData,
                    "sidecar exists without a stable direct directory",
                ),
                path.to_path_buf(),
            ));
        };
        if metadata.file.len() > u64::try_from(byte_limit)? {
            return Err(Error::IO(
                std::io::Error::new(
                    ErrorKind::InvalidData,
                    "sidecar exceeds its hard byte limit",
                ),
                path.to_path_buf(),
            ));
        }
        let mut file =
            std::fs::File::open(path).map_err(|err| Error::IO(err, path.to_path_buf()))?;
        let opened_metadata = file
            .metadata()
            .map_err(|err| Error::IO(err, path.to_path_buf()))?;
        if !opened_metadata.is_file()
            || !Self::sidecar_file_metadata_unchanged(&metadata.file, &opened_metadata)
        {
            return Err(Error::IO(
                std::io::Error::new(ErrorKind::InvalidData, "sidecar file changed while opening"),
                path.to_path_buf(),
            ));
        }
        let mut bytes = Vec::new();
        bytes.try_reserve_exact(usize::try_from(metadata.file.len())?)?;
        Read::by_ref(&mut file)
            .take(u64::try_from(byte_limit.saturating_add(1))?)
            .read_to_end(&mut bytes)
            .map_err(|err| Error::IO(err, path.to_path_buf()))?;
        let opened_after = file
            .metadata()
            .map_err(|err| Error::IO(err, path.to_path_buf()))?;
        let path_after = Self::regular_sidecar_metadata_for(store_root, path, expected_directory)?;
        if bytes.len() > byte_limit
            || u64::try_from(bytes.len())? != metadata.file.len()
            || !Self::sidecar_file_metadata_unchanged(&metadata.file, &opened_after)
            || !path_after.as_ref().is_some_and(|after| {
                Self::stable_sidecar_metadata_unchanged(&metadata, after)
                    && Self::sidecar_metadata_same_object(&directory_before, &after.directory)
            })
        {
            return Err(Error::IO(
                std::io::Error::new(
                    ErrorKind::InvalidData,
                    "sidecar changed or exceeded its hard byte limit while reading",
                ),
                path.to_path_buf(),
            ));
        }
        Ok(Some(StableSidecarRead {
            bytes_hash: Hash::new(&bytes),
            bytes,
            metadata: path_after.expect("validated stable sidecar metadata exists"),
        }))
    }

    fn read_regular_sidecar_snapshot(
        &self,
        path: &Path,
        expected_directory: &Path,
        byte_limit: usize,
    ) -> Result<Option<StableSidecarRead>> {
        Self::read_regular_sidecar_snapshot_for(
            &self.store_root,
            path,
            expected_directory,
            byte_limit,
        )
    }

    fn read_regular_sidecar_bytes(
        &self,
        path: &Path,
        expected_directory: &Path,
        byte_limit: usize,
    ) -> Result<Option<Vec<u8>>> {
        Self::read_regular_sidecar_bytes_for(&self.store_root, path, expected_directory, byte_limit)
    }

    fn block_merge_reference(
        block: &SignedBlock,
    ) -> Option<&iroha_data_model::block::CertifiedMergeLedgerReference> {
        block.execution_context()?.merge_entry.as_ref()
    }

    fn carrier_record_for_block_entry(
        block: &SignedBlock,
        entry: &MergeLedgerEntry,
    ) -> Result<MergeLedgerCarrierRecord> {
        let reference = Self::block_merge_reference(block).ok_or_else(|| {
            Error::MergeReferenceMismatch(
                "merge entry supplied for a block without a compact reference".to_owned(),
            )
        })?;
        if !reference.matches_entry(entry) {
            return Err(Error::MergeReferenceMismatch(
                "compact block reference does not match the resolved full entry".to_owned(),
            ));
        }
        if entry.merge_qc.carrier_height != block.header().height().get()
            || Some(entry.merge_qc.carrier_parent_hash) != block.header().prev_block_hash()
            || entry.merge_qc.view != block.header().view_change_index()
        {
            return Err(Error::MergeReferenceMismatch(
                "merge QC carrier height, parent, or view does not match the referencing block"
                    .to_owned(),
            ));
        }
        Ok(MergeLedgerCarrierRecord::new(entry, block))
    }

    fn read_merge_carrier_path(&self, path: &Path) -> Result<Option<MergeLedgerCarrierRecord>> {
        let Some(bytes) = self.read_regular_sidecar_bytes(
            path,
            &self.merge_carrier_dir(),
            MERGE_CARRIER_MAX_BYTES,
        )?
        else {
            return Ok(None);
        };
        self.decode_merge_carrier_record(path, path, &bytes)
            .map(Some)
    }

    fn decode_merge_carrier_record(
        &self,
        source_path: &Path,
        canonical_path: &Path,
        bytes: &[u8],
    ) -> Result<MergeLedgerCarrierRecord> {
        let record =
            norito::decode_canonical::<MergeLedgerCarrierRecord>(bytes).map_err(|err| {
                Error::MergeCarrierConflict(format!(
                    "carrier record {} is not exact framed Norito: {err}",
                    source_path.display()
                ))
            })?;
        if record.version != 1
            || record.block_height == 0
            || self.merge_carrier_path(record.block_height) != canonical_path
        {
            return Err(Error::MergeCarrierConflict(format!(
                "carrier record {} has a non-canonical identity",
                source_path.display()
            )));
        }
        Ok(record)
    }

    fn reconcile_merge_carrier_temp_files_unlocked(&self) -> Result<()> {
        let directory = self.merge_carrier_dir();
        let read_dir = match std::fs::read_dir(&directory) {
            Ok(read_dir) => read_dir,
            Err(err) if err.kind() == ErrorKind::NotFound => return Ok(()),
            Err(err) => return Err(Error::IO(err, directory)),
        };
        let durable_count = u64::try_from(self.exact_durable_blocks_count()?)?;
        let mut changed = false;
        for entry in read_dir {
            let entry = entry.map_err(|err| Error::IO(err, directory.clone()))?;
            let path = entry.path();
            let metadata =
                std::fs::symlink_metadata(&path).map_err(|err| Error::IO(err, path.clone()))?;
            if metadata.file_type().is_symlink() || !metadata.file_type().is_file() {
                return Err(Error::MergeCarrierConflict(format!(
                    "carrier directory entry {} is not a regular no-follow file",
                    path.display()
                )));
            }
            let Some(file_name) = entry.file_name().to_str().map(str::to_owned) else {
                return Err(Error::MergeCarrierConflict(
                    "carrier directory contains a non-UTF-8 entry".to_owned(),
                ));
            };
            if file_name.ends_with(".norito") {
                continue;
            }
            let Some(height_text) = file_name.strip_suffix(".norito.tmp") else {
                return Err(Error::MergeCarrierConflict(format!(
                    "carrier directory contains unexpected entry {}",
                    path.display()
                )));
            };
            let block_height = height_text.parse::<u64>().map_err(|_| {
                Error::MergeCarrierConflict(format!(
                    "carrier temporary {} has a non-numeric height",
                    path.display()
                ))
            })?;
            if block_height == 0 || block_height.to_string() != height_text {
                return Err(Error::MergeCarrierConflict(format!(
                    "carrier temporary {} has a non-canonical height",
                    path.display()
                )));
            }
            let canonical_path = self.merge_carrier_path(block_height);
            let bytes = self
                .read_regular_sidecar_bytes(&path, &directory, MERGE_CARRIER_MAX_BYTES)?
                .ok_or_else(|| {
                    Error::MergeCarrierConflict(format!(
                        "carrier temporary {} disappeared during recovery",
                        path.display()
                    ))
                })?;
            let record = self.decode_merge_carrier_record(&path, &canonical_path, &bytes)?;
            if let Some(existing) = self.read_merge_carrier_path(&canonical_path)? {
                if existing != record {
                    return Err(Error::MergeCarrierConflict(format!(
                        "carrier temporary {} conflicts with its published record",
                        path.display()
                    )));
                }
                std::fs::remove_file(&path).map_err(|err| Error::IO(err, path.clone()))?;
                changed = true;
                continue;
            }
            match self.get_durable_block_hash(
                NonZeroUsize::new(usize::try_from(block_height)?).ok_or_else(|| {
                    Error::MergeCarrierConflict("carrier temporary height is zero".to_owned())
                })?,
            ) {
                Some(block_hash) if block_hash == record.block_hash => {
                    std::fs::rename(&path, &canonical_path)
                        .map_err(|err| Error::IO(err, canonical_path.clone()))?;
                    changed = true;
                }
                None if block_height > durable_count => {
                    // The process stopped before publishing the matching block.
                    // The log suffix is reconciled separately below.
                    std::fs::remove_file(&path).map_err(|err| Error::IO(err, path.clone()))?;
                    changed = true;
                }
                Some(block_hash) => {
                    return Err(Error::MergeCarrierConflict(format!(
                        "carrier temporary {} names block {} but durable block {} has hash {}",
                        path.display(),
                        record.block_hash,
                        block_height,
                        block_hash
                    )));
                }
                None => {
                    return Err(Error::MergeCarrierConflict(format!(
                        "carrier temporary {} points into a gap in the durable block log",
                        path.display()
                    )));
                }
            }
        }
        if changed {
            sync_dir(&directory).map_err(|err| Error::IO(err, directory))?;
        }
        Ok(())
    }

    fn merge_carrier_records_from_disk_unlocked(&self) -> Result<Vec<MergeLedgerCarrierRecord>> {
        let directory = self.merge_carrier_dir();
        let read_dir = match std::fs::read_dir(&directory) {
            Ok(read_dir) => read_dir,
            Err(err) if err.kind() == ErrorKind::NotFound => return Ok(Vec::new()),
            Err(err) => return Err(Error::IO(err, directory)),
        };
        let max_records = self.exact_durable_blocks_count()?.saturating_add(1);
        let mut paths = Vec::new();
        for entry in read_dir {
            let entry = entry.map_err(|err| Error::IO(err, directory.clone()))?;
            let path = entry.path();
            let metadata =
                std::fs::symlink_metadata(&path).map_err(|err| Error::IO(err, path.clone()))?;
            if metadata.file_type().is_symlink() || !metadata.file_type().is_file() {
                return Err(Error::MergeCarrierConflict(format!(
                    "carrier directory entry {} is not a regular no-follow file",
                    path.display()
                )));
            }
            if path
                .extension()
                .is_some_and(|extension| extension == "norito")
            {
                paths.push(path);
                if paths.len() > max_records {
                    return Err(Error::MergeCarrierConflict(
                        "carrier record count exceeds the durable block count plus one staged publication"
                            .to_owned(),
                    ));
                }
            } else {
                return Err(Error::MergeCarrierConflict(format!(
                    "carrier directory contains unexpected entry {}",
                    path.display()
                )));
            }
        }
        paths.sort();
        let mut records = Vec::with_capacity(paths.len());
        let mut entry_hashes = BTreeSet::new();
        let mut block_heights = BTreeSet::new();
        for path in paths {
            let Some(record) = self.read_merge_carrier_path(&path)? else {
                continue;
            };
            if !entry_hashes.insert(record.entry_hash) || !block_heights.insert(record.block_height)
            {
                return Err(Error::MergeCarrierConflict(
                    "carrier index duplicates an entry hash or block height".to_owned(),
                ));
            }
            records.push(record);
        }
        records.sort_by_key(|record| record.block_height);
        Ok(records)
    }

    fn ensure_merge_carrier_index_initialized_unlocked(&self) -> Result<()> {
        {
            let index = self.merge_carrier_index.lock();
            if index.initialized {
                return Ok(());
            }
        }
        let records = self.merge_carrier_records_from_disk_unlocked()?;
        let mut index = self.merge_carrier_index.lock();
        #[cfg(test)]
        {
            index.directory_scans = index.directory_scans.saturating_add(1);
        }
        index.by_height = records
            .iter()
            .map(|record| (record.block_height, *record))
            .collect();
        index.by_entry = records
            .iter()
            .map(|record| (record.entry_hash, *record))
            .collect();
        index.initialized = true;
        index.generation = index.generation.saturating_add(1);
        Ok(())
    }

    fn merge_carrier_records_unlocked(&self) -> Result<Vec<MergeLedgerCarrierRecord>> {
        self.ensure_merge_carrier_index_initialized_unlocked()?;
        #[cfg(test)]
        let mut index = self.merge_carrier_index.lock();
        #[cfg(not(test))]
        let index = self.merge_carrier_index.lock();
        #[cfg(test)]
        {
            index.full_inventory_clones = index.full_inventory_clones.saturating_add(1);
        }
        Ok(index.by_height.values().copied().collect())
    }

    fn write_merge_carrier_record_unlocked(
        &self,
        record: MergeLedgerCarrierRecord,
    ) -> Result<bool> {
        let accounting_mutation = self.begin_total_disk_usage_mutation();
        let directory = self.merge_carrier_dir();
        std::fs::create_dir_all(&directory).map_err(|err| Error::MkDir(err, directory.clone()))?;
        self.ensure_merge_carrier_index_initialized_unlocked()?;
        let (existing_for_entry, existing_for_height) = {
            let index = self.merge_carrier_index.lock();
            (
                index.by_entry.get(&record.entry_hash).copied(),
                index.by_height.get(&record.block_height).copied(),
            )
        };
        if let Some(existing) = existing_for_entry {
            if existing == record {
                return match self
                    .read_merge_carrier_path(&self.merge_carrier_path(record.block_height))?
                {
                    Some(persisted) if persisted == record => Ok(false),
                    Some(_) => Err(Error::MergeCarrierConflict(
                        "cached carrier record differs from its canonical file".to_owned(),
                    )),
                    None => Err(Error::MergeCarrierConflict(
                        "cached carrier record is missing from its canonical file".to_owned(),
                    )),
                };
            }
            return Err(Error::MergeCarrierConflict(format!(
                "entry {} is already carried by block {} ({})",
                record.entry_hash, existing.block_height, existing.block_hash
            )));
        }
        if let Some(existing) = existing_for_height {
            return Err(Error::MergeCarrierConflict(format!(
                "block {} ({}) already carries merge entry {}",
                existing.block_height, existing.block_hash, existing.entry_hash
            )));
        }
        let path = self.merge_carrier_path(record.block_height);
        let bytes = norito::encode_canonical(&record).map_err(Error::NoritoFrame)?;
        if bytes.len() > MERGE_CARRIER_MAX_BYTES {
            return Err(Error::MergeCarrierConflict(
                "canonical carrier record exceeds its hard byte limit".to_owned(),
            ));
        }
        let temp_path = path.with_extension("norito.tmp");
        if let Err(err) = std::fs::remove_file(&temp_path)
            && err.kind() != ErrorKind::NotFound
        {
            panic!(
                "cannot clear stale carrier temporary {} before atomic publication: {err}",
                temp_path.display()
            );
        }
        let stage_result = (|| {
            let mut temp = std::fs::OpenOptions::new()
                .create_new(true)
                .write(true)
                .open(&temp_path)
                .map_err(|err| Error::IO(err, temp_path.clone()))?;
            temp.write_all(&bytes)
                .map_err(|err| Error::IO(err, temp_path.clone()))?;
            temp.sync_all()
                .map_err(|err| Error::IO(err, temp_path.clone()))?;
            Ok::<(), Error>(())
        })();
        if let Err(stage_err) = stage_result {
            if let Err(cleanup_err) = std::fs::remove_file(&temp_path)
                && cleanup_err.kind() != ErrorKind::NotFound
            {
                panic!(
                    "carrier staging failed ({stage_err}) and temporary cleanup failed ({cleanup_err})"
                );
            }
            if let Err(sync_err) = sync_dir(&directory) {
                panic!(
                    "carrier staging failed ({stage_err}) and temporary cleanup sync failed ({sync_err})"
                );
            }
            return Err(stage_err);
        }
        if let Err(rename_err) = std::fs::rename(&temp_path, &path) {
            if let Err(cleanup_err) = std::fs::remove_file(&temp_path)
                && cleanup_err.kind() != ErrorKind::NotFound
            {
                panic!(
                    "carrier rename failed ({rename_err}) and temporary cleanup failed ({cleanup_err})"
                );
            }
            if let Err(sync_err) = sync_dir(&directory) {
                panic!(
                    "carrier rename failed ({rename_err}) and temporary cleanup sync failed ({sync_err})"
                );
            }
            return Err(Error::IO(rename_err, path));
        }
        if let Err(sync_err) = sync_dir(&directory) {
            // The rename is already visible. Keep the merge-log frame and fail
            // stop so startup can validate/reconcile the complete pair instead
            // of letting the caller truncate only one half.
            panic!(
                "carrier record {} was renamed but its directory sync failed: {sync_err}",
                path.display()
            );
        }
        self.add_disk_usage_bytes(u64::try_from(bytes.len())?);
        let mut index = self.merge_carrier_index.lock();
        index.by_height.insert(record.block_height, record);
        index.by_entry.insert(record.entry_hash, record);
        index.initialized = true;
        index.generation = index.generation.saturating_add(1);
        drop(index);
        accounting_mutation.finish();
        Ok(true)
    }

    fn preflight_merge_carrier_record_unlocked(
        &self,
        record: MergeLedgerCarrierRecord,
    ) -> Result<bool> {
        self.ensure_merge_carrier_index_initialized_unlocked()?;
        let index = self.merge_carrier_index.lock();
        if let Some(existing) = index.by_entry.get(&record.entry_hash) {
            if *existing != record {
                return Err(Error::MergeCarrierConflict(format!(
                    "entry {} is already carried by block {} ({})",
                    record.entry_hash, existing.block_height, existing.block_hash
                )));
            }
            drop(index);
            return match self
                .read_merge_carrier_path(&self.merge_carrier_path(record.block_height))?
            {
                Some(persisted) if persisted == record => Ok(false),
                Some(_) => Err(Error::MergeCarrierConflict(
                    "cached carrier record differs from its canonical file".to_owned(),
                )),
                None => Err(Error::MergeCarrierConflict(
                    "cached carrier record is missing from its canonical file".to_owned(),
                )),
            };
        }
        if let Some(existing) = index.by_height.get(&record.block_height) {
            return Err(Error::MergeCarrierConflict(format!(
                "block {} ({}) already carries merge entry {}",
                existing.block_height, existing.block_hash, existing.entry_hash
            )));
        }
        Ok(true)
    }

    fn remove_merge_carrier_record_unlocked(&self, record: MergeLedgerCarrierRecord) -> Result<()> {
        let path = self.merge_carrier_path(record.block_height);
        let Some(existing) = self.read_merge_carrier_path(&path)? else {
            return Err(Error::MergeCarrierConflict(format!(
                "cannot remove missing carrier record for block {}",
                record.block_height
            )));
        };
        if existing != record {
            return Err(Error::MergeCarrierConflict(
                "refusing to remove a different merge carrier record".to_owned(),
            ));
        }
        let accounting_mutation = self.begin_total_disk_usage_mutation();
        let bytes = std::fs::metadata(&path).map_or(0, |metadata| metadata.len());
        std::fs::remove_file(&path).map_err(|err| Error::IO(err, path))?;
        let sync_result = sync_dir(&self.merge_carrier_dir())
            .map_err(|err| Error::IO(err, self.merge_carrier_dir()));
        self.sub_disk_usage_bytes(bytes);
        let mut index = self.merge_carrier_index.lock();
        index.by_height.remove(&record.block_height);
        index.by_entry.remove(&record.entry_hash);
        index.generation = index.generation.saturating_add(1);
        drop(index);
        sync_result?;
        accounting_mutation.finish();
        Ok(())
    }

    fn validate_merge_carrier_record_against_block(
        &self,
        record: MergeLedgerCarrierRecord,
        block: &SignedBlock,
    ) -> Result<MergeLedgerEntry> {
        let persisted = self
            .read_merge_carrier_path(&self.merge_carrier_path(record.block_height))?
            .ok_or_else(|| {
                Error::MergeCarrierConflict(format!(
                    "cached carrier record for block {} is missing",
                    record.block_height
                ))
            })?;
        if persisted != record {
            return Err(Error::MergeCarrierConflict(format!(
                "cached carrier record for block {} differs from disk",
                record.block_height
            )));
        }
        let height = NonZeroUsize::new(usize::try_from(record.block_height)?)
            .ok_or_else(|| Error::MergeCarrierConflict("carrier height is zero".to_owned()))?;
        if self.get_durable_block_hash(height) != Some(record.block_hash) {
            return Err(Error::MergeCarrierConflict(format!(
                "carrier for entry {} does not match canonical block {}",
                record.entry_hash, record.block_height
            )));
        }
        let reference = Self::block_merge_reference(block).ok_or_else(|| {
            Error::MergeCarrierConflict(format!(
                "carrier block {} no longer contains a compact merge reference",
                record.block_height
            ))
        })?;
        let entry = self
            .merge_log
            .lock()
            .entry_by_hash(record.entry_hash)?
            .ok_or_else(|| {
                Error::MergeCarrierConflict(format!(
                    "carrier for entry {} is absent from the committed merge log",
                    record.entry_hash
                ))
            })?;
        if entry.merge_qc.carrier_height != block.header().height().get()
            || Some(entry.merge_qc.carrier_parent_hash) != block.header().prev_block_hash()
            || entry.merge_qc.view != block.header().view_change_index()
        {
            return Err(Error::MergeCarrierConflict(format!(
                "carrier block {} merge QC height, parent, or view differs from its canonical block header",
                record.block_height
            )));
        }
        if block.hash() != record.block_hash
            || reference.entry_hash != record.entry_hash
            || reference.epoch_id != record.epoch_id
            || entry.epoch_id != record.epoch_id
            || entry.merge_qc.carrier_height != record.block_height
            || Some(entry.merge_qc.carrier_parent_hash) != block.header().prev_block_hash()
            || entry.merge_qc.view != block.header().view_change_index()
            || !reference.matches_entry(&entry)
        {
            return Err(Error::MergeCarrierConflict(format!(
                "carrier block {} compact reference differs from its record or full entry",
                record.block_height
            )));
        }
        Ok(entry)
    }

    fn validate_merge_carrier_record(
        &self,
        record: MergeLedgerCarrierRecord,
    ) -> Result<MergeLedgerEntry> {
        let height = NonZeroUsize::new(usize::try_from(record.block_height)?)
            .ok_or_else(|| Error::MergeCarrierConflict("carrier height is zero".to_owned()))?;
        let block = self.get_block(height).ok_or_else(|| {
            Error::MergeCarrierConflict(format!(
                "carrier block {} body is unavailable; compact merge reference cannot be revalidated",
                record.block_height
            ))
        })?;
        self.validate_merge_carrier_record_against_block(record, block.as_ref())
    }

    fn merge_carrier_record_for_block(
        &self,
        block_height: u64,
        block_hash: HashOf<BlockHeader>,
    ) -> Result<Option<MergeLedgerCarrierRecord>> {
        let record = {
            let _guard = self.merge_carrier_lock.lock();
            self.ensure_merge_carrier_index_initialized_unlocked()?;
            self.merge_carrier_index
                .lock()
                .by_height
                .get(&block_height)
                .copied()
        };
        match record {
            None => Ok(None),
            Some(record) if record.block_hash == block_hash => Ok(Some(record)),
            Some(record) => Err(Error::MergeCarrierConflict(format!(
                "carrier record for block {} binds hash {} instead of canonical hash {}",
                block_height, record.block_hash, block_hash
            ))),
        }
    }

    fn merge_entry_for_loaded_carrier(
        &self,
        block: &SignedBlock,
    ) -> Result<Option<MergeLedgerEntry>> {
        let Some(record) =
            self.merge_carrier_record_for_block(block.header().height().get(), block.hash())?
        else {
            return Ok(None);
        };
        self.validate_merge_carrier_record_against_block(record, block)
            .map(Some)
    }

    /// Resolve the exact canonical carrier for a committed merge entry hash.
    ///
    /// # Errors
    /// Returns an error if the sparse carrier index is malformed or the carrier
    /// no longer matches Kura's canonical block hash.
    pub(crate) fn merge_carrier_for_entry(
        &self,
        entry_hash: HashOf<MergeLedgerEntry>,
    ) -> Result<Option<MergeLedgerCarrierRecord>> {
        self.ensure_prune_recovery_not_required()?;
        let record = {
            let _guard = self.merge_carrier_lock.lock();
            self.ensure_merge_carrier_index_initialized_unlocked()?;
            self.merge_carrier_index
                .lock()
                .by_entry
                .get(&entry_hash)
                .copied()
        };
        if let Some(record) = record {
            let _ = self.validate_merge_carrier_record(record)?;
        }
        self.ensure_prune_recovery_not_required()?;
        Ok(record)
    }

    /// Resolve the complete committed merge entry carried by an exact global block.
    ///
    /// This reads the complete merge log rather than the capacity-truncated
    /// in-memory cache and revalidates the sparse carrier and compact reference.
    pub(crate) fn merge_entry_for_carrier(
        &self,
        block_height: u64,
        block_hash: HashOf<BlockHeader>,
    ) -> Result<Option<MergeLedgerEntry>> {
        self.ensure_prune_recovery_not_required()?;
        let Some(record) = self.merge_carrier_record_for_block(block_height, block_hash)? else {
            self.ensure_prune_recovery_not_required()?;
            return Ok(None);
        };
        let entry = self.validate_merge_carrier_record(record)?;
        self.ensure_prune_recovery_not_required()?;
        Ok(Some(entry))
    }

    /// Resolve the complete committed merge entry carried at a canonical block height.
    ///
    /// The lookup is index-backed and validates the sparse carrier record, canonical
    /// block hash, compact block reference, and full merge-log entry before returning.
    ///
    /// # Errors
    /// Returns an error when the canonical carrier metadata or full merge entry is
    /// unavailable, malformed, or inconsistent with the block log.
    pub fn get_merge_entry_by_carrier_height(
        &self,
        block_height: NonZeroUsize,
    ) -> Result<Option<MergeLedgerEntry>> {
        let Some(block_hash) = self.get_block_hash(block_height) else {
            return Ok(None);
        };
        self.merge_entry_for_carrier(u64::try_from(block_height.get())?, block_hash)
    }
    /// Return every globally carried execution entry in sparse carrier order.
    ///
    /// The result is complete regardless of merge-log cache capacity.
    pub(crate) fn committed_merge_execution_entries(
        &self,
    ) -> Result<Vec<(MergeLedgerCarrierRecord, MergeLedgerEntry)>> {
        self.ensure_prune_recovery_not_required()?;
        #[cfg(test)]
        {
            let mut merge_log = self.merge_log.lock();
            merge_log.complete_execution_scans =
                merge_log.complete_execution_scans.saturating_add(1);
        }
        for _ in 0..2 {
            let records = self.merge_carrier_records()?;
            let generation = self.merge_carrier_index.lock().generation;
            let mut committed = Vec::new();
            for record in records {
                let entry = self
                    .merge_log
                    .lock()
                    .entry_by_hash(record.entry_hash)?
                    .ok_or_else(|| {
                        Error::MergeCarrierConflict(format!(
                            "carrier block {} references a missing committed merge entry",
                            record.block_height
                        ))
                    })?;
                if entry.execution_batch.is_some() {
                    committed.push((record, entry));
                }
            }
            if self.merge_carrier_index.lock().generation == generation {
                self.ensure_prune_recovery_not_required()?;
                return Ok(committed);
            }
        }
        Err(Error::MergeCarrierConflict(
            "sparse merge carriers changed during complete query snapshot".to_owned(),
        ))
    }

    /// Snapshot every sparse merge carrier after validating each record against
    /// the canonical durable block hash. The result is ordered by block height.
    ///
    /// # Errors
    /// Returns an error if the carrier index is malformed or references a
    /// non-canonical block.
    pub(crate) fn merge_carrier_records(&self) -> Result<Vec<MergeLedgerCarrierRecord>> {
        self.ensure_prune_recovery_not_required()?;
        for _ in 0..2 {
            let (records, generation) = {
                let _guard = self.merge_carrier_lock.lock();
                let records = self.merge_carrier_records_unlocked()?;
                let generation = self.merge_carrier_index.lock().generation;
                (records, generation)
            };
            for record in records.iter().copied() {
                let _ = self.validate_merge_carrier_record(record)?;
            }
            if self.merge_carrier_index.lock().generation == generation {
                self.ensure_prune_recovery_not_required()?;
                return Ok(records);
            }
        }
        Err(Error::MergeCarrierConflict(
            "sparse merge carriers changed during validated snapshot".to_owned(),
        ))
    }

    fn reconcile_merge_carriers_from_durable_blocks(&self) -> Result<()> {
        self.reconcile_merge_carriers_from_durable_blocks_with_authority(None)
    }

    fn reconcile_merge_carriers_during_snapshot_finalization(
        &self,
        authority: &SnapshotFinalizationMutationAuthority<'_>,
    ) -> Result<()> {
        authority.validate_for(self)?;
        self.reconcile_merge_carriers_from_durable_blocks_with_authority(Some(authority))
    }

    fn reconcile_merge_carriers_from_durable_blocks_with_authority(
        &self,
        finalization_authority: Option<&SnapshotFinalizationMutationAuthority<'_>>,
    ) -> Result<()> {
        if let Some(authority) = finalization_authority {
            authority.validate_for(self)?;
        }
        self.validate_pending_merge_entries_on_startup()?;
        let block_count = self.exact_durable_blocks_count()?;
        let block_count_u64 = u64::try_from(block_count)?;

        // Recover the only intentionally non-atomic window in the publication
        // sequence: merge log -> carrier sidecar -> canonical block. Complete
        // carrier temporaries are published only when their exact block is
        // already durable. A suffix whose QC targets heights beyond the durable
        // block log is an uncommitted crash remnant and is rolled back as one
        // unit; records at committed heights are never silently discarded.
        {
            let _guard = self.merge_carrier_lock.lock();
            self.reconcile_merge_carrier_temp_files_unlocked()?;
            let records = self.merge_carrier_records_from_disk_unlocked()?;
            {
                let mut index = self.merge_carrier_index.lock();
                index.by_height = records
                    .iter()
                    .map(|record| (record.block_height, *record))
                    .collect();
                index.by_entry = records
                    .iter()
                    .map(|record| (record.entry_hash, *record))
                    .collect();
                index.initialized = true;
                index.generation = index.generation.saturating_add(1);
                #[cfg(test)]
                {
                    index.directory_scans = index.directory_scans.saturating_add(1);
                }
            }

            let future_records = records
                .iter()
                .copied()
                .filter(|record| record.block_height > block_count_u64)
                .collect::<Vec<_>>();
            let (staged_entries, retained_len) = {
                let mut merge_log = self.merge_log.lock();
                let frames = merge_log
                    .frames_by_epoch
                    .values()
                    .rev()
                    .copied()
                    .collect::<Vec<_>>();
                let mut staged = Vec::new();
                for frame in frames {
                    let entry = merge_log.entry_by_hash(frame.entry_hash)?.ok_or_else(|| {
                        Error::MergeCarrierConflict(
                            "merge suffix index references a missing frame".to_owned(),
                        )
                    })?;
                    if entry.merge_qc.carrier_height <= block_count_u64 {
                        break;
                    }
                    staged.push(entry);
                }
                let retained_len = merge_log.total_entries.saturating_sub(staged.len());
                (staged, retained_len)
            };
            let staged_by_hash = staged_entries
                .iter()
                .map(|entry| (entry.canonical_hash(), entry))
                .collect::<BTreeMap<_, _>>();
            for record in &future_records {
                let entry = staged_by_hash.get(&record.entry_hash).ok_or_else(|| {
                    Error::MergeCarrierConflict(format!(
                        "future carrier at block {} is not part of the uncommitted merge-log suffix",
                        record.block_height
                    ))
                })?;
                if entry.epoch_id != record.epoch_id
                    || entry.merge_qc.carrier_height != record.block_height
                {
                    return Err(Error::MergeCarrierConflict(format!(
                        "future carrier at block {} differs from its staged merge entry",
                        record.block_height
                    )));
                }
            }
            for record in future_records.iter().rev().copied() {
                self.remove_merge_carrier_record_unlocked(record)?;
            }
            if !staged_entries.is_empty() {
                self.truncate_merge_log_to_len(retained_len)?;
            }
        }

        // Existing carrier files must never silently migrate to a different
        // block after truncation or fork replacement.
        let _ = self.merge_carrier_records()?;
        for height in 1..=block_count {
            let height = NonZeroUsize::new(height).expect("durable block height is non-zero");
            let Some(block) = self.get_block(height) else {
                continue;
            };
            let Some(reference) = Self::block_merge_reference(&block) else {
                continue;
            };
            let entry = self.merge_entry_by_hash(reference.entry_hash)?.ok_or(
                Error::MissingCertifiedMergeSidecar {
                    entry_hash: reference.entry_hash,
                },
            )?;
            if !reference.matches_entry(&entry) {
                return Err(Error::MergeReferenceMismatch(format!(
                    "canonical block {} compact reference does not match its sidecar",
                    height.get()
                )));
            }
            self.append_committed_merge_entry_for_block_if_missing(&block, &entry)?;
            self.set_transaction_entrypoint_index_entry(
                height.get(),
                &block,
                block_count,
                Some(&entry),
            );
            if finalization_authority.is_some() {
                self.remove_pending_certified_merge_entry_after_authorization(
                    reference.entry_hash,
                )?;
            } else {
                self.remove_pending_certified_merge_entry(reference.entry_hash)?;
            }
        }
        Ok(())
    }

    fn pending_merge_entry_dir(&self) -> PathBuf {
        self.store_root.join(PENDING_MERGE_ENTRIES_DIR)
    }

    fn pending_merge_entry_path(&self, hash: HashOf<MergeLedgerEntry>) -> PathBuf {
        self.pending_merge_entry_dir()
            .join(format!("{}.norito", hex::encode(hash.as_ref())))
    }

    fn invalid_pending_merge_entry_error(path: PathBuf, message: impl Into<String>) -> Error {
        Error::IO(
            std::io::Error::new(ErrorKind::InvalidData, message.into()),
            path,
        )
    }

    fn validate_pending_merge_hash_text(path: &Path, hash_text: &str) -> Result<()> {
        let decoded_hash = hex::decode(hash_text).map_err(|_| {
            Self::invalid_pending_merge_entry_error(
                path.to_path_buf(),
                "pending merge filename is not a canonical hash",
            )
        })?;
        if decoded_hash.len() != Hash::LENGTH || hex::encode(&decoded_hash) != hash_text {
            return Err(Self::invalid_pending_merge_entry_error(
                path.to_path_buf(),
                "pending merge filename is not a canonical lowercase hash",
            ));
        }
        Ok(())
    }

    fn ensure_pending_merge_entry_dir_unlocked(&self) -> Result<()> {
        let directory = self.pending_merge_entry_dir();
        match std::fs::symlink_metadata(&directory) {
            Ok(_) => {
                self.canonical_sidecar_directory(&directory)?
                    .ok_or_else(|| {
                        Self::invalid_pending_merge_entry_error(
                            directory.clone(),
                            "pending merge directory disappeared",
                        )
                    })?;
            }
            Err(error) if error.kind() == ErrorKind::NotFound => {
                std::fs::create_dir(&directory)
                    .map_err(|error| Error::MkDir(error, directory.clone()))?;
                sync_dir(&self.store_root)
                    .map_err(|error| Error::IO(error, self.store_root.clone()))?;
                sync_dir(&directory).map_err(|error| Error::IO(error, directory.clone()))?;
                self.canonical_sidecar_directory(&directory)?
                    .ok_or_else(|| {
                        Self::invalid_pending_merge_entry_error(
                            directory.clone(),
                            "new pending merge directory disappeared",
                        )
                    })?;
            }
            Err(error) => return Err(Error::IO(error, directory)),
        }
        Ok(())
    }

    fn create_exclusive_pending_merge_temp(&self, path: &Path) -> Result<std::fs::File> {
        let directory = self.pending_merge_entry_dir();
        if path.parent() != Some(directory.as_path()) {
            return Err(Self::invalid_pending_merge_entry_error(
                path.to_path_buf(),
                "pending merge temporary is outside its direct directory",
            ));
        }
        let (_, directory_before) =
            self.canonical_sidecar_directory(&directory)?
                .ok_or_else(|| {
                    Self::invalid_pending_merge_entry_error(
                        directory.clone(),
                        "pending merge directory does not exist",
                    )
                })?;
        let file_name = path.file_name().ok_or_else(|| {
            Self::invalid_pending_merge_entry_error(
                path.to_path_buf(),
                "pending merge temporary has no filename",
            )
        })?;

        #[cfg(unix)]
        let file = {
            use std::os::unix::fs::OpenOptionsExt as _;

            let mut directory_options = std::fs::OpenOptions::new();
            directory_options.read(true).custom_flags(
                (rustix::fs::OFlags::DIRECTORY
                    | rustix::fs::OFlags::NOFOLLOW
                    | rustix::fs::OFlags::CLOEXEC)
                    .bits() as i32,
            );
            let opened_directory = directory_options
                .open(&directory)
                .map_err(|error| Error::IO(error, directory.clone()))?;
            let opened_directory_metadata = opened_directory
                .metadata()
                .map_err(|error| Error::IO(error, directory.clone()))?;
            if !opened_directory_metadata.is_dir()
                || !Self::sidecar_metadata_same_object(
                    &directory_before,
                    &opened_directory_metadata,
                )
            {
                return Err(Self::invalid_pending_merge_entry_error(
                    directory.clone(),
                    "pending merge directory changed while binding it",
                ));
            }
            std::fs::File::from(
                rustix::fs::openat(
                    &opened_directory,
                    file_name,
                    rustix::fs::OFlags::WRONLY
                        | rustix::fs::OFlags::CREATE
                        | rustix::fs::OFlags::EXCL
                        | rustix::fs::OFlags::NOFOLLOW
                        | rustix::fs::OFlags::CLOEXEC,
                    rustix::fs::Mode::RUSR | rustix::fs::Mode::WUSR,
                )
                .map_err(std::io::Error::from)
                .map_err(|error| Error::IO(error, path.to_path_buf()))?,
            )
        };

        #[cfg(not(unix))]
        let file = {
            let mut options = std::fs::OpenOptions::new();
            options.create_new(true).write(true);
            #[cfg(windows)]
            {
                use std::os::windows::fs::OpenOptionsExt as _;

                const FILE_FLAG_OPEN_REPARSE_POINT: u32 = 0x0020_0000;
                options.custom_flags(FILE_FLAG_OPEN_REPARSE_POINT);
            }
            options
                .open(path)
                .map_err(|error| Error::IO(error, path.to_path_buf()))?
        };

        let opened = file
            .metadata()
            .map_err(|error| Error::IO(error, path.to_path_buf()))?;
        let path_metadata = std::fs::symlink_metadata(path)
            .map_err(|error| Error::IO(error, path.to_path_buf()))?;
        let (_, directory_after) =
            self.canonical_sidecar_directory(&directory)?
                .ok_or_else(|| {
                    Self::invalid_pending_merge_entry_error(
                        directory.clone(),
                        "pending merge directory disappeared while creating a temporary",
                    )
                })?;
        if !opened.is_file()
            || path_metadata.file_type().is_symlink()
            || !path_metadata.file_type().is_file()
            || !Self::sidecar_is_single_link(&opened)
            || !Self::sidecar_is_single_link(&path_metadata)
            || !Self::sidecar_metadata_same_object(&opened, &path_metadata)
            || !Self::sidecar_metadata_same_object(&directory_before, &directory_after)
        {
            return Err(Self::invalid_pending_merge_entry_error(
                path.to_path_buf(),
                "pending merge temporary identity changed during creation",
            ));
        }
        Ok(file)
    }

    fn pending_queue_plan_admission_dir(&self) -> PathBuf {
        self.store_root.join(PENDING_QUEUE_PLAN_ADMISSIONS_DIR)
    }

    fn pending_queue_plan_admission_path(&self, hash: Hash) -> PathBuf {
        self.pending_queue_plan_admission_dir()
            .join(format!("{}.norito", hex::encode(hash.as_ref())))
    }

    fn invalid_pending_queue_plan_admission_error(
        path: PathBuf,
        message: impl Into<String>,
    ) -> Error {
        Error::IO(
            std::io::Error::new(ErrorKind::InvalidData, message.into()),
            path,
        )
    }

    fn validate_pending_queue_plan_admission_hash_text(path: &Path, hash_text: &str) -> Result<()> {
        let decoded_hash = hex::decode(hash_text).map_err(|_| {
            Self::invalid_pending_queue_plan_admission_error(
                path.to_path_buf(),
                "pending QueuePlan admission filename is not a canonical hash",
            )
        })?;
        if decoded_hash.len() != Hash::LENGTH || hex::encode(&decoded_hash) != hash_text {
            return Err(Self::invalid_pending_queue_plan_admission_error(
                path.to_path_buf(),
                "pending QueuePlan admission filename is not a canonical lowercase hash",
            ));
        }
        Ok(())
    }

    fn pending_queue_plan_admission_paths_unlocked(&self) -> Result<(Vec<PathBuf>, usize)> {
        let directory = self.pending_queue_plan_admission_dir();
        let read_dir = match std::fs::read_dir(&directory) {
            Ok(read_dir) => read_dir,
            Err(err) if err.kind() == ErrorKind::NotFound => return Ok((Vec::new(), 0)),
            Err(err) => return Err(Error::IO(err, directory)),
        };
        let mut paths = Vec::new();
        let mut total_bytes = 0usize;
        for entry in read_dir {
            if paths.len() == self.pending_control_sidecar_limits.queue_plan_admissions {
                return Err(Self::invalid_pending_queue_plan_admission_error(
                    directory,
                    "pending QueuePlan admission certificate count exceeds the hard limit",
                ));
            }
            let entry = entry.map_err(|err| Error::IO(err, directory.clone()))?;
            let path = entry.path();
            let Some(file_name) = entry.file_name().to_str().map(str::to_owned) else {
                return Err(Self::invalid_pending_queue_plan_admission_error(
                    path,
                    "pending QueuePlan admission directory contains a non-UTF-8 entry",
                ));
            };
            let Some(hash_text) = file_name.strip_suffix(".norito") else {
                return Err(Self::invalid_pending_queue_plan_admission_error(
                    path,
                    "pending QueuePlan admission directory contains an unexpected entry",
                ));
            };
            Self::validate_pending_queue_plan_admission_hash_text(&path, hash_text)?;
            let metadata =
                std::fs::symlink_metadata(&path).map_err(|err| Error::IO(err, path.clone()))?;
            if metadata.file_type().is_symlink()
                || !metadata.file_type().is_file()
                || !Self::sidecar_is_single_link(&metadata)
            {
                return Err(Self::invalid_pending_queue_plan_admission_error(
                    path,
                    "pending QueuePlan admission entry is not a single-link regular no-follow file",
                ));
            }
            let file_bytes = usize::try_from(metadata.len())?;
            if file_bytes == 0 || file_bytes > MAX_PENDING_QUEUE_PLAN_ADMISSION_CERTIFICATE_BYTES {
                return Err(Self::invalid_pending_queue_plan_admission_error(
                    path,
                    "pending QueuePlan admission certificate violates its hard byte limit",
                ));
            }
            total_bytes = total_bytes.checked_add(file_bytes).ok_or_else(|| {
                Self::invalid_pending_queue_plan_admission_error(
                    directory.clone(),
                    "pending QueuePlan admission certificate byte count overflow",
                )
            })?;
            if !self
                .pending_control_sidecar_limits
                .merge_bytes_within_limit(total_bytes)
            {
                return Err(Self::invalid_pending_queue_plan_admission_error(
                    directory,
                    "pending QueuePlan admission bytes exceed the aggregate hard limit",
                ));
            }
            paths.push(path);
        }
        paths.sort();
        Ok((paths, total_bytes))
    }

    fn ensure_pending_queue_plan_admission_dir_unlocked(&self) -> Result<()> {
        let directory = self.pending_queue_plan_admission_dir();
        match std::fs::symlink_metadata(&directory) {
            Ok(_) => {
                self.canonical_sidecar_directory(&directory)?
                    .ok_or_else(|| {
                        Self::invalid_pending_queue_plan_admission_error(
                            directory.clone(),
                            "pending QueuePlan admission directory disappeared",
                        )
                    })?;
            }
            Err(error) if error.kind() == ErrorKind::NotFound => {
                std::fs::create_dir(&directory)
                    .map_err(|error| Error::MkDir(error, directory.clone()))?;
                sync_dir(&self.store_root)
                    .map_err(|error| Error::IO(error, self.store_root.clone()))?;
                sync_dir(&directory).map_err(|error| Error::IO(error, directory.clone()))?;
                self.canonical_sidecar_directory(&directory)?
                    .ok_or_else(|| {
                        Self::invalid_pending_queue_plan_admission_error(
                            directory.clone(),
                            "new pending QueuePlan admission directory disappeared",
                        )
                    })?;
            }
            Err(error) => return Err(Error::IO(error, directory)),
        }
        Ok(())
    }

    fn create_exclusive_pending_queue_plan_admission_temp(
        &self,
        path: &Path,
    ) -> Result<std::fs::File> {
        let directory = self.pending_queue_plan_admission_dir();
        if path.parent() != Some(directory.as_path()) {
            return Err(Self::invalid_pending_queue_plan_admission_error(
                path.to_path_buf(),
                "pending QueuePlan admission temporary is outside its direct directory",
            ));
        }
        let (_, directory_before) =
            self.canonical_sidecar_directory(&directory)?
                .ok_or_else(|| {
                    Self::invalid_pending_queue_plan_admission_error(
                        directory.clone(),
                        "pending QueuePlan admission directory does not exist",
                    )
                })?;
        let file_name = path.file_name().ok_or_else(|| {
            Self::invalid_pending_queue_plan_admission_error(
                path.to_path_buf(),
                "pending QueuePlan admission temporary has no filename",
            )
        })?;

        #[cfg(unix)]
        let file = {
            use std::os::unix::fs::OpenOptionsExt as _;

            let mut directory_options = std::fs::OpenOptions::new();
            directory_options.read(true).custom_flags(
                (rustix::fs::OFlags::DIRECTORY
                    | rustix::fs::OFlags::NOFOLLOW
                    | rustix::fs::OFlags::CLOEXEC)
                    .bits() as i32,
            );
            let opened_directory = directory_options
                .open(&directory)
                .map_err(|error| Error::IO(error, directory.clone()))?;
            let opened_directory_metadata = opened_directory
                .metadata()
                .map_err(|error| Error::IO(error, directory.clone()))?;
            if !opened_directory_metadata.is_dir()
                || !Self::sidecar_metadata_same_object(
                    &directory_before,
                    &opened_directory_metadata,
                )
            {
                return Err(Self::invalid_pending_queue_plan_admission_error(
                    directory.clone(),
                    "pending QueuePlan admission directory changed while binding it",
                ));
            }
            std::fs::File::from(
                rustix::fs::openat(
                    &opened_directory,
                    file_name,
                    rustix::fs::OFlags::WRONLY
                        | rustix::fs::OFlags::CREATE
                        | rustix::fs::OFlags::EXCL
                        | rustix::fs::OFlags::NOFOLLOW
                        | rustix::fs::OFlags::CLOEXEC,
                    rustix::fs::Mode::RUSR | rustix::fs::Mode::WUSR,
                )
                .map_err(std::io::Error::from)
                .map_err(|error| Error::IO(error, path.to_path_buf()))?,
            )
        };

        #[cfg(not(unix))]
        let file = {
            let mut options = std::fs::OpenOptions::new();
            options.create_new(true).write(true);
            #[cfg(windows)]
            {
                use std::os::windows::fs::OpenOptionsExt as _;

                const FILE_FLAG_OPEN_REPARSE_POINT: u32 = 0x0020_0000;
                options.custom_flags(FILE_FLAG_OPEN_REPARSE_POINT);
            }
            options
                .open(path)
                .map_err(|error| Error::IO(error, path.to_path_buf()))?
        };

        let opened = file
            .metadata()
            .map_err(|error| Error::IO(error, path.to_path_buf()))?;
        let path_metadata = std::fs::symlink_metadata(path)
            .map_err(|error| Error::IO(error, path.to_path_buf()))?;
        let (_, directory_after) = self.canonical_sidecar_directory(&directory)?.ok_or_else(
            || {
                Self::invalid_pending_queue_plan_admission_error(
                    directory.clone(),
                    "pending QueuePlan admission directory disappeared while creating a temporary",
                )
            },
        )?;
        if !opened.is_file()
            || path_metadata.file_type().is_symlink()
            || !path_metadata.file_type().is_file()
            || !Self::sidecar_is_single_link(&opened)
            || !Self::sidecar_is_single_link(&path_metadata)
            || !Self::sidecar_metadata_same_object(&opened, &path_metadata)
            || !Self::sidecar_metadata_same_object(&directory_before, &directory_after)
        {
            return Err(Self::invalid_pending_queue_plan_admission_error(
                path.to_path_buf(),
                "pending QueuePlan admission temporary identity changed during creation",
            ));
        }
        Ok(file)
    }

    fn read_pending_queue_plan_admission_path(
        &self,
        path: &Path,
        expected_hash: Option<Hash>,
    ) -> Result<Option<(Hash, Vec<u8>)>> {
        let Some(bytes) = self.read_regular_sidecar_bytes(
            path,
            &self.pending_queue_plan_admission_dir(),
            MAX_PENDING_QUEUE_PLAN_ADMISSION_CERTIFICATE_BYTES,
        )?
        else {
            return Ok(None);
        };
        if bytes.is_empty() {
            return Err(Self::invalid_pending_queue_plan_admission_error(
                path.to_path_buf(),
                "pending QueuePlan admission certificate is empty",
            ));
        }
        let hash = Hash::new(&bytes);
        if expected_hash.is_some_and(|expected| expected != hash)
            || self.pending_queue_plan_admission_path(hash) != path
        {
            return Err(Self::invalid_pending_queue_plan_admission_error(
                path.to_path_buf(),
                "pending QueuePlan admission certificate path/hash mismatch",
            ));
        }
        Ok(Some((hash, bytes)))
    }

    fn validate_pending_queue_plan_admission_temp_bytes(
        &self,
        path: &Path,
        hash_text: &str,
        bytes: &[u8],
    ) -> Result<Hash> {
        if bytes.is_empty() || bytes.len() > MAX_PENDING_QUEUE_PLAN_ADMISSION_CERTIFICATE_BYTES {
            return Err(Self::invalid_pending_queue_plan_admission_error(
                path.to_path_buf(),
                "pending QueuePlan admission temporary violates its hard byte limit",
            ));
        }
        let hash = Hash::new(bytes);
        if hex::encode(hash.as_ref()) != hash_text {
            return Err(Self::invalid_pending_queue_plan_admission_error(
                path.to_path_buf(),
                "pending QueuePlan admission temporary bytes do not match their hash path",
            ));
        }
        Ok(hash)
    }

    fn pending_control_recovery_directory_bytes_unlocked(
        &self,
        directory: &Path,
        max_stable_count: usize,
        max_file_bytes: usize,
        queue_plan_admission: bool,
    ) -> Result<usize> {
        #[derive(Clone, Copy, Debug, Eq, Ord, PartialEq, PartialOrd)]
        enum RecoveryFileIdentity {
            #[cfg(unix)]
            Unix { device: u64, inode: u64 },
            #[cfg(windows)]
            Windows { volume: u32, index: u64 },
            #[cfg(not(unix))]
            Synthetic(usize),
        }

        struct RecoveryRecord {
            path: PathBuf,
            hash_text: String,
            is_temporary: bool,
            metadata: std::fs::Metadata,
            identity: RecoveryFileIdentity,
        }

        struct RecoveryAliases {
            first: usize,
            second: Option<usize>,
            count: usize,
        }

        let invalid = |path: PathBuf, message: String| {
            if queue_plan_admission {
                Self::invalid_pending_queue_plan_admission_error(path, message)
            } else {
                Self::invalid_pending_merge_entry_error(path, message)
            }
        };
        let (_, directory_before) =
            self.canonical_sidecar_directory(directory)?
                .ok_or_else(|| {
                    invalid(
                        directory.to_path_buf(),
                        "pending control recovery directory does not exist".to_owned(),
                    )
                })?;
        let read_dir = std::fs::read_dir(directory)
            .map_err(|error| Error::IO(error, directory.to_path_buf()))?;
        let mut records: Vec<RecoveryRecord> = Vec::new();
        let mut stable_count = 0usize;
        let mut temporary_count = 0usize;
        let mut unique_bytes = 0usize;
        let mut aliases_by_identity = BTreeMap::<RecoveryFileIdentity, RecoveryAliases>::new();
        for entry in read_dir {
            if records.len() == max_stable_count.saturating_add(1) {
                return Err(invalid(
                    directory.to_path_buf(),
                    "pending control recovery entry count exceeds its hard limit".to_owned(),
                ));
            }
            let entry = entry.map_err(|error| Error::IO(error, directory.to_path_buf()))?;
            let path = entry.path();
            let file_name = entry
                .file_name()
                .to_str()
                .map(str::to_owned)
                .ok_or_else(|| {
                    invalid(
                        path.clone(),
                        "pending control recovery directory contains a non-UTF-8 entry".to_owned(),
                    )
                })?;
            let (hash_text, is_temporary) = if let Some(hash_text) =
                file_name.strip_suffix(".norito.tmp")
            {
                temporary_count = temporary_count.saturating_add(1);
                if temporary_count > 1 {
                    return Err(invalid(
                        directory.to_path_buf(),
                        "pending control recovery directory contains multiple temporaries"
                            .to_owned(),
                    ));
                }
                (hash_text, true)
            } else if let Some(hash_text) = file_name.strip_suffix(".norito") {
                stable_count = stable_count.saturating_add(1);
                if stable_count > max_stable_count {
                    return Err(invalid(
                        directory.to_path_buf(),
                        "pending control recovery stable entry count exceeds its hard limit"
                            .to_owned(),
                    ));
                }
                (hash_text, false)
            } else {
                return Err(invalid(
                    path,
                    "pending control recovery directory contains an unexpected entry".to_owned(),
                ));
            };
            if queue_plan_admission {
                Self::validate_pending_queue_plan_admission_hash_text(&path, hash_text)?;
            } else {
                Self::validate_pending_merge_hash_text(&path, hash_text)?;
            }
            let metadata =
                std::fs::symlink_metadata(&path).map_err(|error| Error::IO(error, path.clone()))?;
            if metadata.file_type().is_symlink()
                || !metadata.file_type().is_file()
                || (!Self::sidecar_has_link_count(&metadata, 1)
                    && !Self::sidecar_has_link_count(&metadata, 2))
            {
                return Err(invalid(
                    path,
                    "pending control recovery entry is not a one- or two-link regular no-follow file"
                        .to_owned(),
                ));
            }
            let file_bytes = usize::try_from(metadata.len())?;
            if file_bytes == 0 || file_bytes > max_file_bytes {
                return Err(invalid(
                    path,
                    "pending control recovery entry violates its per-file byte limit".to_owned(),
                ));
            }
            #[cfg(unix)]
            let identity = {
                use std::os::unix::fs::MetadataExt as _;

                RecoveryFileIdentity::Unix {
                    device: metadata.dev(),
                    inode: metadata.ino(),
                }
            };
            #[cfg(windows)]
            let identity = {
                use std::os::windows::fs::MetadataExt as _;

                match (metadata.volume_serial_number(), metadata.file_index()) {
                    (Some(volume), Some(index)) => RecoveryFileIdentity::Windows { volume, index },
                    // Match `sidecar_metadata_same_object`: missing Windows identity
                    // components never establish aliasing, so a two-link record
                    // remains fail-closed during the pair check below.
                    _ => RecoveryFileIdentity::Synthetic(records.len()),
                }
            };
            #[cfg(all(not(unix), not(windows)))]
            let identity = RecoveryFileIdentity::Synthetic(records.len());
            let record_index = records.len();
            // The previous all-prior-record metadata scan made configured
            // maximum inventories quadratic. One ordered identity group keeps
            // byte de-duplication and exact alias validation O(n log n).
            match aliases_by_identity.entry(identity) {
                std::collections::btree_map::Entry::Vacant(slot) => {
                    unique_bytes = unique_bytes.checked_add(file_bytes).ok_or_else(|| {
                        invalid(
                            directory.to_path_buf(),
                            "pending control recovery byte count overflow".to_owned(),
                        )
                    })?;
                    if !self
                        .pending_control_sidecar_limits
                        .merge_bytes_within_limit(unique_bytes)
                    {
                        return Err(invalid(
                            directory.to_path_buf(),
                            "pending control recovery bytes exceed their aggregate hard limit"
                                .to_owned(),
                        ));
                    }
                    slot.insert(RecoveryAliases {
                        first: record_index,
                        second: None,
                        count: 1,
                    });
                }
                std::collections::btree_map::Entry::Occupied(mut slot) => {
                    let aliases = slot.get_mut();
                    aliases.count = aliases.count.saturating_add(1);
                    if aliases.second.is_none() {
                        aliases.second = Some(record_index);
                    }
                }
            }
            records.push(RecoveryRecord {
                path,
                hash_text: hash_text.to_owned(),
                is_temporary,
                metadata,
                identity,
            });
        }

        for record in &records {
            if !Self::sidecar_has_link_count(&record.metadata, 2) {
                continue;
            }
            let Some(aliases) = aliases_by_identity.get(&record.identity) else {
                return Err(invalid(
                    record.path.clone(),
                    "pending control recovery hard links are not one exact temporary/target pair"
                        .to_owned(),
                ));
            };
            let Some(second) = aliases.second.filter(|_| aliases.count == 2) else {
                return Err(invalid(
                    record.path.clone(),
                    "pending control recovery hard links are not one exact temporary/target pair"
                        .to_owned(),
                ));
            };
            let left = &records[aliases.first];
            let right = &records[second];
            if left.is_temporary == right.is_temporary || left.hash_text != right.hash_text {
                return Err(invalid(
                    record.path.clone(),
                    "pending control recovery hard links are not one exact temporary/target pair"
                        .to_owned(),
                ));
            }
        }
        let (_, directory_after) =
            self.canonical_sidecar_directory(directory)?
                .ok_or_else(|| {
                    invalid(
                        directory.to_path_buf(),
                        "pending control recovery directory disappeared during inventory"
                            .to_owned(),
                    )
                })?;
        if !Self::sidecar_directory_metadata_unchanged(&directory_before, &directory_after) {
            return Err(invalid(
                directory.to_path_buf(),
                "pending control recovery directory changed during inventory".to_owned(),
            ));
        }
        Ok(unique_bytes)
    }

    fn preflight_pending_control_recovery_unlocked(&self) -> Result<(usize, usize)> {
        self.ensure_pending_merge_entry_dir_unlocked()?;
        self.ensure_pending_queue_plan_admission_dir_unlocked()?;
        let merge_bytes = self.pending_control_recovery_directory_bytes_unlocked(
            &self.pending_merge_entry_dir(),
            self.pending_control_sidecar_limits.certified_merge_entries,
            MAX_MERGE_LEDGER_ENTRY_BYTES,
            false,
        )?;
        let admission_bytes = self.pending_control_recovery_directory_bytes_unlocked(
            &self.pending_queue_plan_admission_dir(),
            self.pending_control_sidecar_limits.queue_plan_admissions,
            MAX_PENDING_QUEUE_PLAN_ADMISSION_CERTIFICATE_BYTES,
            true,
        )?;
        if !self
            .pending_control_sidecar_limits
            .combined_bytes_within_limit(merge_bytes, admission_bytes)
        {
            return Err(Self::invalid_pending_merge_entry_error(
                self.store_root.clone(),
                "pending merge and QueuePlan admission recovery bytes exceed their shared hard limit",
            ));
        }
        Ok((merge_bytes, admission_bytes))
    }

    fn pending_merge_entry_paths_unlocked(&self) -> Result<(Vec<PathBuf>, usize)> {
        let directory = self.pending_merge_entry_dir();
        let read_dir = match std::fs::read_dir(&directory) {
            Ok(read_dir) => read_dir,
            Err(err) if err.kind() == ErrorKind::NotFound => return Ok((Vec::new(), 0)),
            Err(err) => return Err(Error::IO(err, directory)),
        };
        let mut paths = Vec::new();
        let mut total_bytes = 0usize;
        for entry in read_dir {
            if paths.len() == self.pending_control_sidecar_limits.certified_merge_entries {
                return Err(Self::invalid_pending_merge_entry_error(
                    directory,
                    "pending certified merge entry count exceeds the hard limit",
                ));
            }
            let entry = entry.map_err(|err| Error::IO(err, directory.clone()))?;
            let path = entry.path();
            let Some(file_name) = entry.file_name().to_str().map(str::to_owned) else {
                return Err(Self::invalid_pending_merge_entry_error(
                    path,
                    "pending merge directory contains a non-UTF-8 entry",
                ));
            };
            let Some(hash_text) = file_name.strip_suffix(".norito") else {
                return Err(Self::invalid_pending_merge_entry_error(
                    path,
                    "pending merge directory contains an unexpected non-Norito entry",
                ));
            };
            Self::validate_pending_merge_hash_text(&path, hash_text)?;
            let metadata =
                std::fs::symlink_metadata(&path).map_err(|err| Error::IO(err, path.clone()))?;
            if metadata.file_type().is_symlink()
                || !metadata.file_type().is_file()
                || !Self::sidecar_is_single_link(&metadata)
            {
                return Err(Self::invalid_pending_merge_entry_error(
                    path,
                    "pending merge directory entry is not a single-link regular no-follow file",
                ));
            }
            let file_bytes = usize::try_from(metadata.len())?;
            total_bytes = total_bytes.checked_add(file_bytes).ok_or_else(|| {
                Self::invalid_pending_merge_entry_error(
                    directory.clone(),
                    "pending certified merge byte count overflow",
                )
            })?;
            if !self
                .pending_control_sidecar_limits
                .merge_bytes_within_limit(total_bytes)
            {
                return Err(Self::invalid_pending_merge_entry_error(
                    directory,
                    "pending certified merge bytes exceed the aggregate hard limit",
                ));
            }
            paths.push(path);
        }
        paths.sort();
        Ok((paths, total_bytes))
    }

    fn validate_pending_merge_entries_on_startup(&self) -> Result<()> {
        let _guard = self.sidecar_lock.lock();
        self.reconcile_pending_merge_temp_files_unlocked()?;
        self.reconcile_pending_queue_plan_admission_temp_files_unlocked()?;
        let (merge_paths, merge_bytes) = self.pending_merge_entry_paths_unlocked()?;
        let (admission_paths, admission_bytes) =
            self.pending_queue_plan_admission_paths_unlocked()?;
        if !self
            .pending_control_sidecar_limits
            .combined_bytes_within_limit(merge_bytes, admission_bytes)
        {
            return Err(Self::invalid_pending_queue_plan_admission_error(
                self.store_root.clone(),
                "pending merge and QueuePlan admission sidecars exceed their shared hard byte limit",
            ));
        }
        for path in merge_paths {
            let _ = self
                .read_pending_merge_entry_path(&path, None)?
                .ok_or_else(|| {
                    Self::invalid_pending_merge_entry_error(
                        path,
                        "pending merge sidecar disappeared during startup validation",
                    )
                })?;
        }
        for path in admission_paths {
            let _ = self
                .read_pending_queue_plan_admission_path(&path, None)?
                .ok_or_else(|| {
                    Self::invalid_pending_queue_plan_admission_error(
                        path,
                        "pending QueuePlan admission sidecar disappeared during startup validation",
                    )
                })?;
        }
        Ok(())
    }

    fn reconcile_pending_merge_temp_files_unlocked(&self) -> Result<()> {
        let _ = self.preflight_pending_control_recovery_unlocked()?;
        let directory = self.pending_merge_entry_dir();
        let read_dir = match std::fs::read_dir(&directory) {
            Ok(read_dir) => read_dir,
            Err(err) => return Err(Error::IO(err, directory)),
        };
        let accounting_mutation = self.begin_total_disk_usage_mutation();
        let mut scanned = 0usize;
        let mut stable_count = 0usize;
        let mut total_bytes = 0usize;
        let mut path_bytes_before = 0u64;
        let mut temp_paths = Vec::new();
        #[cfg(unix)]
        let mut seen_inodes = BTreeSet::new();
        #[cfg(windows)]
        let mut seen_file_ids = BTreeSet::new();
        for entry in read_dir {
            scanned = scanned.saturating_add(1);
            if scanned
                > self
                    .pending_control_sidecar_limits
                    .certified_merge_entries
                    .saturating_add(1)
            {
                return Err(Self::invalid_pending_merge_entry_error(
                    directory,
                    "pending merge directory entry count exceeds the crash-recovery limit",
                ));
            }
            let entry = entry.map_err(|err| Error::IO(err, directory.clone()))?;
            let path = entry.path();
            let metadata =
                std::fs::symlink_metadata(&path).map_err(|err| Error::IO(err, path.clone()))?;
            if metadata.file_type().is_symlink()
                || !metadata.file_type().is_file()
                || (!Self::sidecar_has_link_count(&metadata, 1)
                    && !Self::sidecar_has_link_count(&metadata, 2))
            {
                return Err(Self::invalid_pending_merge_entry_error(
                    path,
                    "pending merge recovery entry is not a one- or two-link regular no-follow file",
                ));
            }
            path_bytes_before = path_bytes_before
                .checked_add(metadata.len())
                .ok_or_else(|| {
                    Self::invalid_pending_merge_entry_error(
                        directory.clone(),
                        "pending merge recovery path-byte count overflow",
                    )
                })?;
            #[cfg(unix)]
            let count_file_bytes = {
                use std::os::unix::fs::MetadataExt as _;
                seen_inodes.insert((metadata.dev(), metadata.ino()))
            };
            #[cfg(windows)]
            let count_file_bytes = {
                use std::os::windows::fs::MetadataExt as _;

                let volume = metadata.volume_serial_number().ok_or_else(|| {
                    Self::invalid_pending_merge_entry_error(
                        path.clone(),
                        "pending merge recovery entry has no volume identity",
                    )
                })?;
                let index = metadata.file_index().ok_or_else(|| {
                    Self::invalid_pending_merge_entry_error(
                        path.clone(),
                        "pending merge recovery entry has no file identity",
                    )
                })?;
                seen_file_ids.insert((volume, index))
            };
            #[cfg(all(not(unix), not(windows)))]
            let count_file_bytes = true;
            if count_file_bytes {
                total_bytes = total_bytes
                    .checked_add(usize::try_from(metadata.len())?)
                    .ok_or_else(|| {
                        Self::invalid_pending_merge_entry_error(
                            directory.clone(),
                            "pending merge directory byte count overflow",
                        )
                    })?;
            }
            if !self
                .pending_control_sidecar_limits
                .merge_bytes_within_limit(total_bytes)
            {
                return Err(Self::invalid_pending_merge_entry_error(
                    directory,
                    "pending merge directory bytes exceed the aggregate hard limit",
                ));
            }
            let Some(file_name) = entry.file_name().to_str().map(str::to_owned) else {
                return Err(Self::invalid_pending_merge_entry_error(
                    path,
                    "pending merge directory contains a non-UTF-8 entry",
                ));
            };
            if let Some(hash_text) = file_name.strip_suffix(".norito.tmp") {
                Self::validate_pending_merge_hash_text(&path, hash_text)?;
                temp_paths.push((path, hash_text.to_owned()));
                if temp_paths.len() > 1 {
                    return Err(Self::invalid_pending_merge_entry_error(
                        directory,
                        "pending merge directory contains multiple temporaries",
                    ));
                }
                continue;
            }
            let Some(hash_text) = file_name.strip_suffix(".norito") else {
                return Err(Self::invalid_pending_merge_entry_error(
                    path,
                    "pending merge directory contains an unexpected recovery entry",
                ));
            };
            Self::validate_pending_merge_hash_text(&path, hash_text)?;
            stable_count = stable_count.saturating_add(1);
            if stable_count > self.pending_control_sidecar_limits.certified_merge_entries {
                return Err(Self::invalid_pending_merge_entry_error(
                    directory,
                    "pending certified merge entry count exceeds the hard limit",
                ));
            }
            continue;
        }
        for (temp_path, hash_text) in temp_paths {
            let temp_metadata = std::fs::symlink_metadata(&temp_path)
                .map_err(|err| Error::IO(err, temp_path.clone()))?;
            let target_path = directory.join(format!("{hash_text}.norito"));
            let target_metadata = match std::fs::symlink_metadata(&target_path) {
                Ok(metadata) => Some(metadata),
                Err(err) if err.kind() == ErrorKind::NotFound => None,
                Err(err) => return Err(Error::IO(err, target_path.clone())),
            };
            if let Some(target_metadata) = target_metadata.as_ref() {
                if target_metadata.file_type().is_symlink()
                    || !target_metadata.file_type().is_file()
                {
                    return Err(Self::invalid_pending_merge_entry_error(
                        target_path,
                        "pending merge recovery target is not a regular no-follow file",
                    ));
                }
                if Self::sidecar_metadata_same_object(&temp_metadata, target_metadata) {
                    if !Self::sidecar_has_link_count(&temp_metadata, 2)
                        || !Self::sidecar_has_link_count(target_metadata, 2)
                    {
                        return Err(Self::invalid_pending_merge_entry_error(
                            temp_path,
                            "pending merge recovery pair has an unexpected hard-link count",
                        ));
                    }
                    // A crash after `hard_link` legitimately leaves both
                    // names attached to the same two-link inode. Remove the
                    // temporary first so the ordinary single-link reader can
                    // authenticate the stable path without weakening its
                    // invariant.
                    std::fs::remove_file(&temp_path)
                        .map_err(|err| Error::IO(err, temp_path.clone()))?;
                    sync_dir(&directory).map_err(|err| Error::IO(err, directory.clone()))?;
                    let _ = self
                        .read_pending_merge_entry_path(&target_path, None)?
                        .ok_or_else(|| {
                            Self::invalid_pending_merge_entry_error(
                                target_path,
                                "published pending merge target disappeared during recovery",
                            )
                        })?;
                    continue;
                } else if !Self::sidecar_is_single_link(&temp_metadata)
                    || !Self::sidecar_is_single_link(target_metadata)
                {
                    return Err(Self::invalid_pending_merge_entry_error(
                        temp_path,
                        "conflicting pending merge recovery paths are not single-link files",
                    ));
                }
            }
            let bytes = self
                .read_regular_sidecar_bytes(&temp_path, &directory, MAX_MERGE_LEDGER_ENTRY_BYTES)?
                .ok_or_else(|| {
                    Self::invalid_pending_merge_entry_error(
                        temp_path.clone(),
                        "pending merge temporary disappeared during recovery",
                    )
                })?;
            let entry = norito::decode_canonical::<MergeLedgerEntry>(&bytes).map_err(|err| {
                Self::invalid_pending_merge_entry_error(
                    temp_path.clone(),
                    format!("pending merge temporary is not exact framed Norito: {err}"),
                )
            })?;
            if !entry.has_current_version() {
                return Err(Self::invalid_pending_merge_entry_error(
                    temp_path,
                    format!(
                        "pending merge temporary has unsupported merge ledger entry version {}",
                        entry.version
                    ),
                ));
            }
            if hex::encode(entry.canonical_hash().as_ref()) != hash_text
                || self.pending_merge_entry_path(entry.canonical_hash()) != target_path
            {
                return Err(Self::invalid_pending_merge_entry_error(
                    temp_path,
                    "pending merge temporary bytes do not match their canonical hash path",
                ));
            }
            if let Some(existing) =
                self.read_pending_merge_entry_path(&target_path, Some(entry.canonical_hash()))?
            {
                if existing != entry {
                    return Err(Self::invalid_pending_merge_entry_error(
                        temp_path,
                        "pending merge temporary conflicts with its published target",
                    ));
                }
                std::fs::remove_file(&temp_path)
                    .map_err(|err| Error::IO(err, temp_path.clone()))?;
                sync_dir(&directory).map_err(|err| Error::IO(err, directory.clone()))?;
                continue;
            }
            if target_metadata.is_some() {
                return Err(Self::invalid_pending_merge_entry_error(
                    target_path,
                    "pending merge recovery target disappeared during validation",
                ));
            }
            if stable_count == self.pending_control_sidecar_limits.certified_merge_entries {
                return Err(Self::invalid_pending_merge_entry_error(
                    directory,
                    "unpublished pending merge temporary exceeds the entry-count hard limit",
                ));
            }
            if !Self::sidecar_is_single_link(&temp_metadata) {
                return Err(Self::invalid_pending_merge_entry_error(
                    temp_path,
                    "unpublished pending merge temporary is not a single-link file",
                ));
            }
            std::fs::File::open(&temp_path)
                .and_then(|file| file.sync_all())
                .map_err(|err| Error::IO(err, temp_path.clone()))?;
            sync_dir(&directory).map_err(|err| Error::IO(err, directory.clone()))?;
            std::fs::hard_link(&temp_path, &target_path)
                .map_err(|err| Error::IO(err, target_path.clone()))?;
            let target_metadata = std::fs::symlink_metadata(&target_path)
                .map_err(|err| Error::IO(err, target_path.clone()))?;
            if !Self::sidecar_metadata_same_object(&temp_metadata, &target_metadata)
                || !Self::sidecar_has_link_count(&target_metadata, 2)
            {
                return Err(Self::invalid_pending_merge_entry_error(
                    target_path,
                    "published pending merge target does not bind its durable temporary",
                ));
            }
            std::fs::File::open(&target_path)
                .and_then(|file| file.sync_all())
                .map_err(|err| Error::IO(err, target_path.clone()))?;
            sync_dir(&directory).map_err(|err| Error::IO(err, directory.clone()))?;
            std::fs::remove_file(&temp_path).map_err(|err| Error::IO(err, temp_path.clone()))?;
            sync_dir(&directory).map_err(|err| Error::IO(err, directory.clone()))?;
        }
        let (_, path_bytes_after) = self.pending_merge_entry_paths_unlocked()?;
        self.update_disk_usage_delta(path_bytes_before, u64::try_from(path_bytes_after)?);
        accounting_mutation.finish();
        Ok(())
    }

    fn reconcile_pending_queue_plan_admission_temp_files_unlocked(&self) -> Result<()> {
        let _ = self.preflight_pending_control_recovery_unlocked()?;
        let directory = self.pending_queue_plan_admission_dir();
        let read_dir = match std::fs::read_dir(&directory) {
            Ok(read_dir) => read_dir,
            Err(err) => return Err(Error::IO(err, directory)),
        };
        // Recovery may unlink a crash-staged temporary after its stable hard
        // link is already visible. The usage scanners account directory
        // entries, so that unlink removes one full path's byte contribution
        // even though the underlying inode remains. Publish the exact
        // before/after delta here: callers may otherwise complete an
        // idempotent retry without performing any later write whose accounting
        // could repair the stale cache.
        let accounting_mutation = self.begin_total_disk_usage_mutation();
        let mut scanned = 0usize;
        let mut stable_count = 0usize;
        let mut total_bytes = 0usize;
        let mut path_bytes_before = 0u64;
        let mut temp_paths = Vec::new();
        #[cfg(unix)]
        let mut seen_inodes = BTreeSet::new();
        #[cfg(windows)]
        let mut seen_file_ids = BTreeSet::new();
        for entry in read_dir {
            scanned = scanned.saturating_add(1);
            if scanned
                > self
                    .pending_control_sidecar_limits
                    .queue_plan_admissions
                    .saturating_add(1)
            {
                return Err(Self::invalid_pending_queue_plan_admission_error(
                    directory,
                    "pending QueuePlan admission directory entry count exceeds the crash-recovery limit",
                ));
            }
            let entry = entry.map_err(|err| Error::IO(err, directory.clone()))?;
            let path = entry.path();
            let metadata =
                std::fs::symlink_metadata(&path).map_err(|err| Error::IO(err, path.clone()))?;
            if metadata.file_type().is_symlink()
                || !metadata.file_type().is_file()
                || (!Self::sidecar_has_link_count(&metadata, 1)
                    && !Self::sidecar_has_link_count(&metadata, 2))
            {
                return Err(Self::invalid_pending_queue_plan_admission_error(
                    path,
                    "pending QueuePlan admission recovery entry is not a one- or two-link regular no-follow file",
                ));
            }
            let file_bytes = usize::try_from(metadata.len())?;
            path_bytes_before = path_bytes_before
                .checked_add(metadata.len())
                .ok_or_else(|| {
                    Self::invalid_pending_queue_plan_admission_error(
                        directory.clone(),
                        "pending QueuePlan admission recovery path-byte count overflow",
                    )
                })?;
            if file_bytes == 0 || file_bytes > MAX_PENDING_QUEUE_PLAN_ADMISSION_CERTIFICATE_BYTES {
                return Err(Self::invalid_pending_queue_plan_admission_error(
                    path,
                    "pending QueuePlan admission recovery entry violates its hard byte limit",
                ));
            }
            #[cfg(unix)]
            let count_file_bytes = {
                use std::os::unix::fs::MetadataExt as _;

                seen_inodes.insert((metadata.dev(), metadata.ino()))
            };
            #[cfg(windows)]
            let count_file_bytes = {
                use std::os::windows::fs::MetadataExt as _;

                let volume = metadata.volume_serial_number().ok_or_else(|| {
                    Self::invalid_pending_queue_plan_admission_error(
                        path.clone(),
                        "pending QueuePlan admission recovery entry has no volume identity",
                    )
                })?;
                let index = metadata.file_index().ok_or_else(|| {
                    Self::invalid_pending_queue_plan_admission_error(
                        path.clone(),
                        "pending QueuePlan admission recovery entry has no file identity",
                    )
                })?;
                seen_file_ids.insert((volume, index))
            };
            #[cfg(all(not(unix), not(windows)))]
            let count_file_bytes = true;
            if count_file_bytes {
                total_bytes = total_bytes.checked_add(file_bytes).ok_or_else(|| {
                    Self::invalid_pending_queue_plan_admission_error(
                        directory.clone(),
                        "pending QueuePlan admission recovery byte count overflow",
                    )
                })?;
            }
            if !self
                .pending_control_sidecar_limits
                .merge_bytes_within_limit(total_bytes)
            {
                return Err(Self::invalid_pending_queue_plan_admission_error(
                    directory,
                    "pending QueuePlan admission recovery bytes exceed the aggregate hard limit",
                ));
            }

            let Some(file_name) = entry.file_name().to_str().map(str::to_owned) else {
                return Err(Self::invalid_pending_queue_plan_admission_error(
                    path,
                    "pending QueuePlan admission directory contains a non-UTF-8 recovery entry",
                ));
            };
            if let Some(hash_text) = file_name.strip_suffix(".norito.tmp") {
                Self::validate_pending_queue_plan_admission_hash_text(&path, hash_text)?;
                temp_paths.push((path, hash_text.to_owned()));
                if temp_paths.len() > 1 {
                    return Err(Self::invalid_pending_queue_plan_admission_error(
                        directory,
                        "pending QueuePlan admission directory contains multiple temporaries",
                    ));
                }
                continue;
            }
            let Some(hash_text) = file_name.strip_suffix(".norito") else {
                return Err(Self::invalid_pending_queue_plan_admission_error(
                    path,
                    "pending QueuePlan admission directory contains an unexpected recovery entry",
                ));
            };
            Self::validate_pending_queue_plan_admission_hash_text(&path, hash_text)?;
            stable_count = stable_count.saturating_add(1);
            if stable_count > self.pending_control_sidecar_limits.queue_plan_admissions {
                return Err(Self::invalid_pending_queue_plan_admission_error(
                    directory,
                    "pending QueuePlan admission certificate count exceeds the hard limit",
                ));
            }
        }
        for (temp_path, hash_text) in temp_paths {
            let target_path = directory.join(format!("{hash_text}.norito"));
            let temp_metadata = std::fs::symlink_metadata(&temp_path)
                .map_err(|err| Error::IO(err, temp_path.clone()))?;
            let target_metadata = match std::fs::symlink_metadata(&target_path) {
                Ok(metadata) => Some(metadata),
                Err(err) if err.kind() == ErrorKind::NotFound => None,
                Err(err) => return Err(Error::IO(err, target_path.clone())),
            };

            if let Some(target_metadata) = target_metadata {
                if target_metadata.file_type().is_symlink()
                    || !target_metadata.file_type().is_file()
                {
                    return Err(Self::invalid_pending_queue_plan_admission_error(
                        target_path,
                        "pending QueuePlan admission recovery target is not a regular no-follow file",
                    ));
                }
                if Self::sidecar_metadata_same_object(&temp_metadata, &target_metadata) {
                    if !Self::sidecar_has_link_count(&temp_metadata, 2)
                        || !Self::sidecar_has_link_count(&target_metadata, 2)
                    {
                        return Err(Self::invalid_pending_queue_plan_admission_error(
                            temp_path,
                            "pending QueuePlan admission recovery pair has an unexpected hard-link count",
                        ));
                    }
                    std::fs::remove_file(&temp_path)
                        .map_err(|err| Error::IO(err, temp_path.clone()))?;
                    sync_dir(&directory).map_err(|err| Error::IO(err, directory.clone()))?;
                    let expected_hash = self
                        .read_pending_queue_plan_admission_path(&target_path, None)?
                        .ok_or_else(|| {
                            Self::invalid_pending_queue_plan_admission_error(
                                target_path.clone(),
                                "published QueuePlan admission target disappeared during recovery",
                            )
                        })?
                        .0;
                    if hex::encode(expected_hash.as_ref()) != hash_text {
                        return Err(Self::invalid_pending_queue_plan_admission_error(
                            target_path,
                            "published QueuePlan admission target bytes do not match their hash path",
                        ));
                    }
                    continue;
                }
                if !Self::sidecar_is_single_link(&temp_metadata)
                    || !Self::sidecar_is_single_link(&target_metadata)
                {
                    return Err(Self::invalid_pending_queue_plan_admission_error(
                        temp_path,
                        "conflicting QueuePlan admission recovery paths are not single-link files",
                    ));
                }
                let temp_bytes = self
                    .read_regular_sidecar_bytes(
                        &temp_path,
                        &directory,
                        MAX_PENDING_QUEUE_PLAN_ADMISSION_CERTIFICATE_BYTES,
                    )?
                    .ok_or_else(|| {
                        Self::invalid_pending_queue_plan_admission_error(
                            temp_path.clone(),
                            "pending QueuePlan admission temporary disappeared during recovery",
                        )
                    })?;
                let expected_hash = self.validate_pending_queue_plan_admission_temp_bytes(
                    &temp_path,
                    &hash_text,
                    &temp_bytes,
                )?;
                let (_, target_bytes) = self
                    .read_pending_queue_plan_admission_path(&target_path, Some(expected_hash))?
                    .ok_or_else(|| {
                        Self::invalid_pending_queue_plan_admission_error(
                            target_path.clone(),
                            "published QueuePlan admission target disappeared during recovery",
                        )
                    })?;
                if target_bytes != temp_bytes {
                    return Err(Self::invalid_pending_queue_plan_admission_error(
                        temp_path,
                        "pending QueuePlan admission temporary conflicts with its published target",
                    ));
                }
                std::fs::remove_file(&temp_path)
                    .map_err(|err| Error::IO(err, temp_path.clone()))?;
                sync_dir(&directory).map_err(|err| Error::IO(err, directory.clone()))?;
                continue;
            }

            if stable_count == self.pending_control_sidecar_limits.queue_plan_admissions {
                return Err(Self::invalid_pending_queue_plan_admission_error(
                    directory,
                    "unpublished pending QueuePlan admission temporary exceeds the certificate-count hard limit",
                ));
            }
            if !Self::sidecar_is_single_link(&temp_metadata) {
                return Err(Self::invalid_pending_queue_plan_admission_error(
                    temp_path,
                    "unpublished QueuePlan admission temporary is not a single-link file",
                ));
            }
            let temp_bytes = self
                .read_regular_sidecar_bytes(
                    &temp_path,
                    &directory,
                    MAX_PENDING_QUEUE_PLAN_ADMISSION_CERTIFICATE_BYTES,
                )?
                .ok_or_else(|| {
                    Self::invalid_pending_queue_plan_admission_error(
                        temp_path.clone(),
                        "pending QueuePlan admission temporary disappeared during recovery",
                    )
                })?;
            let expected_hash = self.validate_pending_queue_plan_admission_temp_bytes(
                &temp_path,
                &hash_text,
                &temp_bytes,
            )?;
            std::fs::File::open(&temp_path)
                .and_then(|file| file.sync_all())
                .map_err(|err| Error::IO(err, temp_path.clone()))?;
            sync_dir(&directory).map_err(|err| Error::IO(err, directory.clone()))?;
            std::fs::hard_link(&temp_path, &target_path)
                .map_err(|err| Error::IO(err, target_path.clone()))?;
            let target_metadata = std::fs::symlink_metadata(&target_path)
                .map_err(|err| Error::IO(err, target_path.clone()))?;
            if !Self::sidecar_metadata_same_object(&temp_metadata, &target_metadata)
                || !Self::sidecar_has_link_count(&target_metadata, 2)
            {
                return Err(Self::invalid_pending_queue_plan_admission_error(
                    target_path,
                    "published QueuePlan admission target does not bind its durable temporary",
                ));
            }
            std::fs::File::open(&target_path)
                .and_then(|file| file.sync_all())
                .map_err(|err| Error::IO(err, target_path.clone()))?;
            sync_dir(&directory).map_err(|err| Error::IO(err, directory.clone()))?;
            std::fs::remove_file(&temp_path).map_err(|err| Error::IO(err, temp_path.clone()))?;
            sync_dir(&directory).map_err(|err| Error::IO(err, directory.clone()))?;
            let _ = self
                .read_pending_queue_plan_admission_path(&target_path, Some(expected_hash))?
                .ok_or_else(|| {
                    Self::invalid_pending_queue_plan_admission_error(
                        target_path,
                        "published QueuePlan admission target disappeared after recovery",
                    )
                })?;
        }
        let (_, path_bytes_after) = self.pending_queue_plan_admission_paths_unlocked()?;
        self.update_disk_usage_delta(path_bytes_before, u64::try_from(path_bytes_after)?);
        accounting_mutation.finish();
        Ok(())
    }

    fn read_pending_merge_entry_path(
        &self,
        path: &Path,
        expected_hash: Option<HashOf<MergeLedgerEntry>>,
    ) -> Result<Option<MergeLedgerEntry>> {
        let Some(bytes) = self.read_regular_sidecar_bytes(
            path,
            &self.pending_merge_entry_dir(),
            MAX_MERGE_LEDGER_ENTRY_BYTES,
        )?
        else {
            return Ok(None);
        };
        let entry = norito::decode_canonical::<MergeLedgerEntry>(&bytes).map_err(|err| {
            Self::invalid_pending_merge_entry_error(
                path.to_path_buf(),
                format!("pending certified merge entry is not exact framed Norito: {err}"),
            )
        })?;
        if !entry.has_current_version() {
            return Err(Self::invalid_pending_merge_entry_error(
                path.to_path_buf(),
                format!(
                    "pending certified merge entry has unsupported merge ledger entry version {}",
                    entry.version
                ),
            ));
        }
        let actual_hash = crate::merge::merge_ledger_entry_hash(&entry);
        if expected_hash.is_some_and(|expected| expected != actual_hash)
            || self.pending_merge_entry_path(actual_hash) != path
        {
            return Err(Self::invalid_pending_merge_entry_error(
                path.to_path_buf(),
                "pending certified merge entry path/hash mismatch",
            ));
        }
        Ok(Some(entry))
    }

    fn retain_pending_certified_merge_entries_unlocked(
        &self,
        mut retain: impl FnMut(&MergeLedgerEntry) -> bool,
    ) -> Result<usize> {
        let accounting_mutation = self.begin_total_disk_usage_mutation();
        let directory = self.pending_merge_entry_dir();
        let (paths, _) = self.pending_merge_entry_paths_unlocked()?;
        let mut removed = 0usize;
        let mut removed_bytes = 0u64;
        for path in paths {
            let Some(entry) = self.read_pending_merge_entry_path(&path, None)? else {
                continue;
            };
            if retain(&entry) {
                continue;
            }
            removed_bytes = removed_bytes
                .saturating_add(std::fs::metadata(&path).map_or(0, |metadata| metadata.len()));
            std::fs::remove_file(&path).map_err(|err| Error::IO(err, path))?;
            removed = removed.saturating_add(1);
        }
        if removed > 0 {
            sync_dir(&directory).map_err(|err| Error::IO(err, directory))?;
            self.sub_disk_usage_bytes(removed_bytes);
        }
        accounting_mutation.finish();
        Ok(removed)
    }

    fn prune_pending_certified_merge_entries_not_bound_to_unlocked(
        &self,
        carrier_height: u64,
        carrier_parent_hash: HashOf<BlockHeader>,
        view: u64,
    ) -> Result<usize> {
        self.retain_pending_certified_merge_entries_unlocked(|entry| {
            entry.merge_qc.carrier_height == carrier_height
                && entry.merge_qc.carrier_parent_hash == carrier_parent_hash
                && entry.merge_qc.view == view
        })
    }

    /// Remove pending certificates that can no longer be carried by the exact current round.
    ///
    /// This cleanup runs before pending-count and aggregate-byte admission, so missed rounds
    /// cannot permanently consume the bounded pending store.
    pub(crate) fn prune_pending_certified_merge_entries_not_bound_to(
        &self,
        carrier_height: u64,
        carrier_parent_hash: HashOf<BlockHeader>,
        view: u64,
    ) -> Result<usize> {
        self.ensure_prune_recovery_not_required()?;
        self.durable_mutation_authorized()?;
        let _guard = self.sidecar_lock.lock();
        self.reconcile_pending_merge_temp_files_unlocked()?;
        self.prune_pending_certified_merge_entries_not_bound_to_unlocked(
            carrier_height,
            carrier_parent_hash,
            view,
        )
    }

    /// At a locked carrier, retain only the exact full entry referenced by the
    /// immutable body. With no reference, remove every losing sidecar for that
    /// carrier height while leaving other heights untouched.
    pub(crate) fn retain_pending_certified_merge_entry_for_locked_carrier(
        &self,
        carrier_height: u64,
        reference: Option<&iroha_data_model::block::CertifiedMergeLedgerReference>,
    ) -> Result<usize> {
        self.durable_mutation_authorized()?;
        let _guard = self.sidecar_lock.lock();
        self.reconcile_pending_merge_temp_files_unlocked()?;
        self.retain_pending_certified_merge_entries_unlocked(|entry| {
            entry.merge_qc.carrier_height != carrier_height
                || reference.is_some_and(|reference| reference.matches_entry(entry))
        })
    }

    /// Remove every pending merge sidecar whose carrier height is already
    /// finalized. No losing sidecar can become canonical after height rollover.
    pub(crate) fn prune_finalized_pending_certified_merge_entries(
        &self,
        finalized_height: u64,
    ) -> Result<usize> {
        self.durable_mutation_authorized()?;
        let _guard = self.sidecar_lock.lock();
        self.reconcile_pending_merge_temp_files_unlocked()?;
        self.retain_pending_certified_merge_entries_unlocked(|entry| {
            entry.merge_qc.carrier_height > finalized_height
        })
    }

    /// Persist a fully certified entry in the hash-addressed pending sidecar
    /// store without appending it to the globally committed merge log.
    ///
    /// # Errors
    /// Returns an error for an oversized or conflicting sidecar, or when the
    /// atomic file publication cannot be completed. This method never prunes
    /// other carrier rounds; callers that own the active round must invoke the
    /// explicit exact-round pruning API first.
    pub(crate) fn persist_pending_certified_merge_entry(
        &self,
        entry: &MergeLedgerEntry,
    ) -> Result<HashOf<MergeLedgerEntry>> {
        self.ensure_prune_recovery_not_required()?;
        self.durable_mutation_authorized()?;
        let bytes = crate::merge::canonical_merge_ledger_entry_bytes(entry);
        if bytes.len() > MAX_MERGE_LEDGER_ENTRY_BYTES {
            return Err(Self::invalid_pending_merge_entry_error(
                self.pending_merge_entry_dir(),
                "pending certified merge entry exceeds the hard byte limit",
            ));
        }
        let hash = crate::merge::merge_ledger_entry_hash(entry);
        let path = self.pending_merge_entry_path(hash);
        let directory = self.pending_merge_entry_dir();
        let _guard = self.sidecar_lock.lock();
        self.ensure_pending_merge_entry_dir_unlocked()?;
        let accounting_mutation = self.begin_total_disk_usage_mutation();
        self.reconcile_pending_merge_temp_files_unlocked()?;
        self.reconcile_pending_queue_plan_admission_temp_files_unlocked()?;
        let temp_path = path.with_extension("norito.tmp");
        let (paths, pending_bytes) = self.pending_merge_entry_paths_unlocked()?;
        if let Some(existing) = self.read_pending_merge_entry_path(&path, Some(hash))? {
            if existing == *entry {
                accounting_mutation.finish();
                return Ok(hash);
            }
            return Err(Self::invalid_pending_merge_entry_error(
                path,
                "hash-addressed pending merge sidecar conflicts with existing bytes",
            ));
        }
        if paths.len() == self.pending_control_sidecar_limits.certified_merge_entries {
            return Err(Self::invalid_pending_merge_entry_error(
                directory,
                "pending certified merge entry count exceeds the hard limit",
            ));
        }
        let (_, admission_bytes) = self.pending_queue_plan_admission_paths_unlocked()?;
        if pending_bytes.checked_add(bytes.len()).is_none_or(|total| {
            !self
                .pending_control_sidecar_limits
                .combined_bytes_within_limit(total, admission_bytes)
        }) {
            return Err(Self::invalid_pending_merge_entry_error(
                directory,
                "pending merge and QueuePlan admission bytes exceed their shared hard limit",
            ));
        }

        let mut temp = self.create_exclusive_pending_merge_temp(&temp_path)?;
        temp.write_all(&bytes)
            .map_err(|error| Error::IO(error, temp_path.clone()))?;
        temp.flush()
            .map_err(|error| Error::IO(error, temp_path.clone()))?;
        temp.sync_all()
            .map_err(|error| Error::IO(error, temp_path.clone()))?;
        let opened_after_write = temp
            .metadata()
            .map_err(|error| Error::IO(error, temp_path.clone()))?;
        let path_after_write = std::fs::symlink_metadata(&temp_path)
            .map_err(|error| Error::IO(error, temp_path.clone()))?;
        if !opened_after_write.is_file()
            || path_after_write.file_type().is_symlink()
            || !path_after_write.file_type().is_file()
            || !Self::sidecar_is_single_link(&opened_after_write)
            || !Self::sidecar_is_single_link(&path_after_write)
            || !Self::sidecar_metadata_same_object(&opened_after_write, &path_after_write)
            || opened_after_write.len() != u64::try_from(bytes.len())?
        {
            return Err(Self::invalid_pending_merge_entry_error(
                temp_path,
                "pending merge temporary changed while writing",
            ));
        }
        sync_dir(&directory).map_err(|error| Error::IO(error, directory.clone()))?;
        if let Err(error) = std::fs::hard_link(&temp_path, &path) {
            let remove_result = std::fs::remove_file(&temp_path);
            let sync_result = sync_dir(&directory);
            if let Err(remove_error) = remove_result {
                return Err(Error::IO(remove_error, temp_path));
            }
            if let Err(sync_error) = sync_result {
                return Err(Error::IO(sync_error, directory));
            }
            return Err(Error::IO(error, path));
        }
        let target_metadata =
            std::fs::symlink_metadata(&path).map_err(|error| Error::IO(error, path.clone()))?;
        if target_metadata.file_type().is_symlink()
            || !target_metadata.file_type().is_file()
            || !Self::sidecar_metadata_same_object(&opened_after_write, &target_metadata)
            || !Self::sidecar_has_link_count(&target_metadata, 2)
        {
            return Err(Self::invalid_pending_merge_entry_error(
                path,
                "published pending merge target does not bind its durable temporary",
            ));
        }
        let target = std::fs::File::open(&path).map_err(|error| Error::IO(error, path.clone()))?;
        let opened_target = target
            .metadata()
            .map_err(|error| Error::IO(error, path.clone()))?;
        if !Self::sidecar_metadata_same_object(&target_metadata, &opened_target)
            || !Self::sidecar_has_link_count(&opened_target, 2)
        {
            return Err(Self::invalid_pending_merge_entry_error(
                path,
                "published pending merge target changed while opening",
            ));
        }
        target
            .sync_all()
            .map_err(|error| Error::IO(error, path.clone()))?;
        sync_dir(&directory).map_err(|error| Error::IO(error, directory.clone()))?;
        std::fs::remove_file(&temp_path).map_err(|error| Error::IO(error, temp_path.clone()))?;
        sync_dir(&directory).map_err(|error| Error::IO(error, directory.clone()))?;
        let persisted = self
            .read_pending_merge_entry_path(&path, Some(hash))?
            .ok_or_else(|| {
                Self::invalid_pending_merge_entry_error(
                    path.clone(),
                    "published pending merge entry disappeared",
                )
            })?;
        if persisted != *entry {
            return Err(Self::invalid_pending_merge_entry_error(
                path,
                "published pending merge entry differs from its durable input",
            ));
        }
        self.add_disk_usage_bytes(u64::try_from(bytes.len())?);
        accounting_mutation.finish();
        Ok(hash)
    }

    /// Persist exact canonical QueuePlan admission certificate bytes before
    /// they become eligible for a global carrier.
    ///
    /// Kura deliberately treats the versioned certificate as opaque bytes: the
    /// admission layer owns Norito decoding and semantic validation, while this
    /// store preserves those exact bytes under their content hash. Empty,
    /// oversized, aliased, or non-canonical filesystem identities fail closed.
    ///
    /// # Errors
    /// Returns an error when the certificate or pending-control store exceeds
    /// its bounds, or when durable no-clobber publication cannot complete.
    pub fn persist_pending_queue_plan_admission_certificate(
        &self,
        canonical_certificate_bytes: &[u8],
    ) -> Result<Hash> {
        self.ensure_prune_recovery_not_required()?;
        self.durable_mutation_authorized()?;
        if canonical_certificate_bytes.is_empty()
            || canonical_certificate_bytes.len()
                > MAX_PENDING_QUEUE_PLAN_ADMISSION_CERTIFICATE_BYTES
        {
            return Err(Self::invalid_pending_queue_plan_admission_error(
                self.pending_queue_plan_admission_dir(),
                "pending QueuePlan admission certificate violates its hard byte limit",
            ));
        }
        let hash = Hash::new(canonical_certificate_bytes);
        let path = self.pending_queue_plan_admission_path(hash);
        let temp_path = path.with_extension("norito.tmp");
        let directory = self.pending_queue_plan_admission_dir();
        let _guard = self.sidecar_lock.lock();
        self.ensure_pending_queue_plan_admission_dir_unlocked()?;
        let accounting_mutation = self.begin_total_disk_usage_mutation();
        self.reconcile_pending_merge_temp_files_unlocked()?;
        self.reconcile_pending_queue_plan_admission_temp_files_unlocked()?;

        if let Some((_, existing)) =
            self.read_pending_queue_plan_admission_path(&path, Some(hash))?
        {
            if existing == canonical_certificate_bytes {
                accounting_mutation.finish();
                return Ok(hash);
            }
            return Err(Self::invalid_pending_queue_plan_admission_error(
                path,
                "hash-addressed QueuePlan admission sidecar conflicts with existing bytes",
            ));
        }
        let (paths, admission_bytes) = self.pending_queue_plan_admission_paths_unlocked()?;
        if paths.len() == self.pending_control_sidecar_limits.queue_plan_admissions {
            return Err(Self::invalid_pending_queue_plan_admission_error(
                directory,
                "pending QueuePlan admission certificate count exceeds the hard limit",
            ));
        }
        let (_, merge_bytes) = self.pending_merge_entry_paths_unlocked()?;
        if admission_bytes
            .checked_add(canonical_certificate_bytes.len())
            .is_none_or(|total| {
                !self
                    .pending_control_sidecar_limits
                    .combined_bytes_within_limit(merge_bytes, total)
            })
        {
            return Err(Self::invalid_pending_queue_plan_admission_error(
                directory,
                "pending merge and QueuePlan admission bytes exceed their shared hard limit",
            ));
        }

        let mut temp = self.create_exclusive_pending_queue_plan_admission_temp(&temp_path)?;
        temp.write_all(canonical_certificate_bytes)
            .map_err(|error| Error::IO(error, temp_path.clone()))?;
        temp.flush()
            .map_err(|error| Error::IO(error, temp_path.clone()))?;
        temp.sync_all()
            .map_err(|error| Error::IO(error, temp_path.clone()))?;
        let opened_after_write = temp
            .metadata()
            .map_err(|error| Error::IO(error, temp_path.clone()))?;
        let path_after_write = std::fs::symlink_metadata(&temp_path)
            .map_err(|error| Error::IO(error, temp_path.clone()))?;
        if !opened_after_write.is_file()
            || path_after_write.file_type().is_symlink()
            || !path_after_write.file_type().is_file()
            || !Self::sidecar_is_single_link(&opened_after_write)
            || !Self::sidecar_is_single_link(&path_after_write)
            || !Self::sidecar_metadata_same_object(&opened_after_write, &path_after_write)
            || opened_after_write.len() != u64::try_from(canonical_certificate_bytes.len())?
        {
            return Err(Self::invalid_pending_queue_plan_admission_error(
                temp_path,
                "pending QueuePlan admission temporary changed while writing",
            ));
        }
        sync_dir(&directory).map_err(|error| Error::IO(error, directory.clone()))?;
        if let Err(error) = std::fs::hard_link(&temp_path, &path) {
            let remove_result = std::fs::remove_file(&temp_path);
            let sync_result = sync_dir(&directory);
            if let Err(remove_error) = remove_result {
                return Err(Error::IO(remove_error, temp_path));
            }
            if let Err(sync_error) = sync_result {
                return Err(Error::IO(sync_error, directory));
            }
            return Err(Error::IO(error, path));
        }
        let target_metadata =
            std::fs::symlink_metadata(&path).map_err(|error| Error::IO(error, path.clone()))?;
        if target_metadata.file_type().is_symlink()
            || !target_metadata.file_type().is_file()
            || !Self::sidecar_metadata_same_object(&opened_after_write, &target_metadata)
            || !Self::sidecar_has_link_count(&target_metadata, 2)
        {
            return Err(Self::invalid_pending_queue_plan_admission_error(
                path,
                "published QueuePlan admission target does not bind its durable temporary",
            ));
        }
        let target = std::fs::File::open(&path).map_err(|error| Error::IO(error, path.clone()))?;
        let opened_target = target
            .metadata()
            .map_err(|error| Error::IO(error, path.clone()))?;
        if !Self::sidecar_metadata_same_object(&target_metadata, &opened_target)
            || !Self::sidecar_has_link_count(&opened_target, 2)
        {
            return Err(Self::invalid_pending_queue_plan_admission_error(
                path,
                "published QueuePlan admission target changed while opening",
            ));
        }
        target
            .sync_all()
            .map_err(|error| Error::IO(error, path.clone()))?;
        sync_dir(&directory).map_err(|error| Error::IO(error, directory.clone()))?;
        std::fs::remove_file(&temp_path).map_err(|error| Error::IO(error, temp_path.clone()))?;
        sync_dir(&directory).map_err(|error| Error::IO(error, directory.clone()))?;
        let (_, persisted) = self
            .read_pending_queue_plan_admission_path(&path, Some(hash))?
            .ok_or_else(|| {
                Self::invalid_pending_queue_plan_admission_error(
                    path.clone(),
                    "published QueuePlan admission certificate disappeared",
                )
            })?;
        if persisted != canonical_certificate_bytes {
            return Err(Self::invalid_pending_queue_plan_admission_error(
                path,
                "published QueuePlan admission certificate differs from its durable input",
            ));
        }
        self.add_disk_usage_bytes(u64::try_from(canonical_certificate_bytes.len())?);
        accounting_mutation.finish();
        Ok(hash)
    }

    /// Resolve one exact pending QueuePlan admission certificate by its byte hash.
    #[cfg(test)]
    pub(crate) fn pending_queue_plan_admission_certificate(
        &self,
        hash: Hash,
    ) -> Result<Option<Vec<u8>>> {
        self.ensure_prune_recovery_not_required()?;
        let certificate = {
            let _guard = self.sidecar_lock.lock();
            self.ensure_prune_recovery_not_required()?;
            let (_, merge_bytes) = self.pending_merge_entry_paths_unlocked()?;
            let (_, admission_bytes) = self.pending_queue_plan_admission_paths_unlocked()?;
            if !self
                .pending_control_sidecar_limits
                .combined_bytes_within_limit(merge_bytes, admission_bytes)
            {
                return Err(Self::invalid_pending_queue_plan_admission_error(
                    self.store_root.clone(),
                    "pending merge and QueuePlan admission sidecars exceed their shared hard byte limit",
                ));
            }
            self.read_pending_queue_plan_admission_path(
                &self.pending_queue_plan_admission_path(hash),
                Some(hash),
            )?
            .map(|(_, bytes)| bytes)
        };
        self.ensure_prune_recovery_not_required()?;
        Ok(certificate)
    }

    /// Return every pending QueuePlan admission certificate in byte-hash order.
    #[cfg(test)]
    pub(crate) fn pending_queue_plan_admission_certificates(&self) -> Result<Vec<(Hash, Vec<u8>)>> {
        self.pending_queue_plan_admission_certificates_bounded(
            self.pending_control_sidecar_limits.queue_plan_admissions,
        )
    }

    /// Return at most `limit` pending QueuePlan admission certificates in
    /// deterministic byte-hash order.
    pub(crate) fn pending_queue_plan_admission_certificates_bounded(
        &self,
        limit: usize,
    ) -> Result<Vec<(Hash, Vec<u8>)>> {
        if limit == 0 {
            return Ok(Vec::new());
        }
        self.ensure_prune_recovery_not_required()?;
        let certificates = {
            let _guard = self.sidecar_lock.lock();
            self.ensure_prune_recovery_not_required()?;
            let (_, merge_bytes) = self.pending_merge_entry_paths_unlocked()?;
            let (paths, admission_bytes) = self.pending_queue_plan_admission_paths_unlocked()?;
            if !self
                .pending_control_sidecar_limits
                .combined_bytes_within_limit(merge_bytes, admission_bytes)
            {
                return Err(Self::invalid_pending_queue_plan_admission_error(
                    self.store_root.clone(),
                    "pending merge and QueuePlan admission sidecars exceed their shared hard byte limit",
                ));
            }
            let bounded = limit.min(self.pending_control_sidecar_limits.queue_plan_admissions);
            let mut certificates = Vec::with_capacity(paths.len().min(bounded));
            for path in paths.into_iter().take(bounded) {
                let Some(certificate) = self.read_pending_queue_plan_admission_path(&path, None)?
                else {
                    continue;
                };
                certificates.push(certificate);
            }
            certificates
        };
        self.ensure_prune_recovery_not_required()?;
        Ok(certificates)
    }

    /// Fingerprint-bound QueuePlan admission capacity used by bounded callers.
    #[must_use]
    pub(crate) const fn pending_queue_plan_admission_capacity(&self) -> usize {
        self.pending_control_sidecar_limits.queue_plan_admissions
    }

    /// Remove pending QueuePlan admission certificates rejected by `retain`.
    ///
    /// This is the byte-oriented cleanup hook used by the admission layer for
    /// stale round/incarnation evidence; Kura does not interpret the payload.
    #[cfg(test)]
    pub(crate) fn retain_pending_queue_plan_admission_certificates(
        &self,
        mut retain: impl FnMut(Hash, &[u8]) -> bool,
    ) -> Result<usize> {
        self.ensure_prune_recovery_not_required()?;
        self.durable_mutation_authorized()?;
        let _guard = self.sidecar_lock.lock();
        let accounting_mutation = self.begin_total_disk_usage_mutation();
        self.reconcile_pending_queue_plan_admission_temp_files_unlocked()?;
        let directory = self.pending_queue_plan_admission_dir();
        let (paths, _) = self.pending_queue_plan_admission_paths_unlocked()?;
        let mut removed = 0usize;
        let mut removed_bytes = 0u64;
        for path in paths {
            let Some((hash, bytes)) = self.read_pending_queue_plan_admission_path(&path, None)?
            else {
                continue;
            };
            if retain(hash, &bytes) {
                continue;
            }
            removed_bytes = removed_bytes.saturating_add(u64::try_from(bytes.len())?);
            std::fs::remove_file(&path).map_err(|error| Error::IO(error, path))?;
            removed = removed.saturating_add(1);
        }
        if removed > 0 {
            sync_dir(&directory).map_err(|error| Error::IO(error, directory))?;
            self.sub_disk_usage_bytes(removed_bytes);
        }
        accounting_mutation.finish();
        Ok(removed)
    }

    /// Remove one pending QueuePlan admission certificate after canonical
    /// carrier commitment or explicit stale-certificate rejection.
    pub(crate) fn remove_pending_queue_plan_admission_certificate(&self, hash: Hash) -> Result<()> {
        self.ensure_prune_recovery_not_required()?;
        self.durable_mutation_authorized()?;
        let path = self.pending_queue_plan_admission_path(hash);
        let directory = self.pending_queue_plan_admission_dir();
        let _guard = self.sidecar_lock.lock();
        let Some((_, bytes)) = self.read_pending_queue_plan_admission_path(&path, Some(hash))?
        else {
            return Ok(());
        };
        let accounting_mutation = self.begin_total_disk_usage_mutation();
        std::fs::remove_file(&path).map_err(|error| Error::IO(error, path))?;
        sync_dir(&directory).map_err(|error| Error::IO(error, directory))?;
        self.sub_disk_usage_bytes(u64::try_from(bytes.len())?);
        accounting_mutation.finish();
        Ok(())
    }

    /// Resolve an exact merge entry from the pending sidecar store or the
    /// globally committed merge log.
    ///
    /// # Errors
    /// Returns an error if a matching pending sidecar is corrupt or committed
    /// merge-log recovery fails.
    pub(crate) fn merge_entry_by_hash(
        &self,
        hash: HashOf<MergeLedgerEntry>,
    ) -> Result<Option<MergeLedgerEntry>> {
        self.ensure_prune_recovery_not_required()?;
        self.ensure_canonical_storage_not_poisoned()?;
        let path = self.pending_merge_entry_path(hash);
        let pending = {
            let _guard = self.sidecar_lock.lock();
            self.ensure_prune_recovery_not_required()?;
            self.read_pending_merge_entry_path(&path, Some(hash))?
        };
        self.ensure_prune_recovery_not_required()?;
        if pending.is_some() {
            return Ok(pending);
        }
        let mut merge_log = self.merge_log.lock();
        self.ensure_prune_recovery_not_required()?;
        let entry = merge_log.entry_by_hash(hash)?;
        self.ensure_prune_recovery_not_required()?;
        Ok(entry)
    }

    /// Return canonical, uncommitted certified merge sidecars in deterministic order.
    ///
    /// The pending store is bounded at admission, and entries already present in the committed
    /// merge log are excluded.
    pub(crate) fn pending_certified_merge_entries(
        &self,
    ) -> Result<Vec<(HashOf<MergeLedgerEntry>, MergeLedgerEntry)>> {
        self.pending_certified_merge_entries_bounded(
            self.pending_control_sidecar_limits.certified_merge_entries,
        )
    }

    /// Return at most `limit` deterministic pending merge sidecars.
    ///
    /// Directory shape and aggregate metadata remain fail-closed under the
    /// protocol hard limits. Files are decoded one at a time until `limit`
    /// uncommitted entries have been selected, and only those selected entries
    /// are retained. This prevents committed sidecars that sort first from
    /// under-filling the bounded result.
    pub(crate) fn pending_certified_merge_entries_bounded(
        &self,
        limit: usize,
    ) -> Result<Vec<(HashOf<MergeLedgerEntry>, MergeLedgerEntry)>> {
        if limit == 0 {
            return Ok(Vec::new());
        }
        let bounded = limit.min(self.pending_control_sidecar_limits.certified_merge_entries);
        let mut entries = Vec::with_capacity(bounded);
        let _ = self.visit_pending_certified_merge_entries(
            self.pending_control_sidecar_limits.certified_merge_entries,
            |hash, entry| {
                entries.push((hash, entry.clone()));
                entries.len() == bounded
            },
        )?;
        entries.sort_by_key(|(hash, entry)| (entry.epoch_id, *hash));
        self.ensure_prune_recovery_not_required()?;
        Ok(entries)
    }

    /// Return deterministic hashes for matching uncommitted pending merge evidence.
    ///
    /// At most `evidence_scan_limit` sidecars are decoded, one at a time. The
    /// predicate runs without a Kura lock, and selected entries are represented
    /// only by their hashes so callers can resolve, validate, and discard each
    /// large entry independently. [`PendingCertifiedMergeEvidenceScan::LimitExceeded`]
    /// is returned when the stable pending inventory exceeds the scan limit; no
    /// entry bytes are decoded in that case.
    pub(crate) fn pending_certified_merge_entry_hashes_matching_bounded(
        &self,
        evidence_scan_limit: usize,
        mut selected: impl FnMut(&MergeLedgerEntry) -> bool,
    ) -> Result<PendingCertifiedMergeEvidenceScan> {
        let mut matches = Vec::new();
        let outcome =
            self.visit_pending_certified_merge_entries(evidence_scan_limit, |hash, entry| {
                if selected(entry) {
                    matches.push((entry.epoch_id, hash));
                }
                false
            })?;
        if outcome == PendingCertifiedMergeVisitOutcome::ScanLimitExceeded {
            return Ok(PendingCertifiedMergeEvidenceScan::LimitExceeded);
        }
        matches.sort_unstable_by_key(|(epoch_id, hash)| (*epoch_id, *hash));
        Ok(PendingCertifiedMergeEvidenceScan::Complete(
            matches.into_iter().map(|(_, hash)| hash).collect(),
        ))
    }

    fn visit_pending_certified_merge_entries(
        &self,
        evidence_scan_limit: usize,
        mut visitor: impl FnMut(HashOf<MergeLedgerEntry>, &MergeLedgerEntry) -> bool,
    ) -> Result<PendingCertifiedMergeVisitOutcome> {
        self.ensure_prune_recovery_not_required()?;
        let paths = {
            let _guard = self.sidecar_lock.lock();
            self.ensure_prune_recovery_not_required()?;
            let (paths, _) = self.pending_merge_entry_paths_unlocked()?;
            paths
        };
        let evidence_scan_limit =
            evidence_scan_limit.min(self.pending_control_sidecar_limits.certified_merge_entries);
        if paths.len() > evidence_scan_limit {
            return Ok(PendingCertifiedMergeVisitOutcome::ScanLimitExceeded);
        }

        for path in paths {
            let entry = {
                let _guard = self.sidecar_lock.lock();
                self.ensure_prune_recovery_not_required()?;
                self.read_pending_merge_entry_path(&path, None)?
            };
            let Some(entry) = entry else {
                continue;
            };
            let hash = entry.canonical_hash();
            self.ensure_prune_recovery_not_required()?;
            let committed = {
                let mut merge_log = self.merge_log.lock();
                self.ensure_prune_recovery_not_required()?;
                merge_log.contains_hash(hash)
            };
            if committed {
                continue;
            }
            if visitor(hash, &entry) {
                self.ensure_prune_recovery_not_required()?;
                return Ok(PendingCertifiedMergeVisitOutcome::VisitorStopped);
            }
        }
        self.ensure_prune_recovery_not_required()?;
        Ok(PendingCertifiedMergeVisitOutcome::Complete)
    }

    /// Return whether an uncommitted certified merge sidecar still carries
    /// work for one exact active lane incarnation.
    ///
    /// The underlying scan is bounded by the pending-entry count and byte
    /// limits, decodes one entry at a time, and stops at the first blocker.
    /// Malformed autonomous routing bytes, misaligned Native receipts, or a
    /// matching route without one unique historical active-lane binding
    /// conservatively count as work, so drain certification never treats
    /// unverifiable evidence as empty. A certificate-only entry is the closure
    /// carrier itself and owns no lane work; counting it here would make its own
    /// admission impossible.
    pub(crate) fn pending_certified_merge_work_for_lane(
        &self,
        lane_id: LaneId,
        dataspace_id: DataSpaceId,
        lane_incarnation: Hash,
    ) -> Result<bool> {
        let outcome = self.visit_pending_certified_merge_entries(
            self.pending_control_sidecar_limits.certified_merge_entries,
            |_, entry| {
                entry.lane_snapshots.iter().any(|snapshot| {
                    snapshot.lane_id == lane_id
                        && snapshot.dataspace_id == dataspace_id
                        && snapshot.lane_incarnation == lane_incarnation
                }) || entry.execution_batch.as_ref().is_some_and(|batch| {
                    batch.lanes.iter().any(|execution| {
                        let descriptor = &execution.proposal.descriptor;
                        let origin = &execution.origin_proposal.descriptor;
                        let entry_count = execution.entrypoints.len();
                        (descriptor.lane_id == lane_id
                            && descriptor.dataspace_id == dataspace_id
                            && descriptor.lane_incarnation == lane_incarnation)
                            || (origin.lane_id == lane_id
                                && origin.dataspace_id == dataspace_id
                                && origin.lane_incarnation == lane_incarnation)
                            || descriptor.lane_id != origin.lane_id
                            || descriptor.dataspace_id != origin.dataspace_id
                            || descriptor.lane_incarnation != origin.lane_incarnation
                            || execution.entrypoint_hashes.len() != entry_count
                            || execution.reservation_keys.len() != entry_count
                            || execution.routing_plans.len() != entry_count
                            || execution.native_amx_receipts.len() != entry_count
                            || execution.result_hashes.len() != entry_count
                            || execution.results.len() != entry_count
                            || execution
                                .routing_plans
                                .iter()
                                .zip(&execution.native_amx_receipts)
                                .any(|(encoded, receipt)| {
                                    let Ok(plan) = norito::decode_canonical::<
                                        crate::queue::RoutingPlan,
                                    >(encoded)
                                    else {
                                        return true;
                                    };
                                    let coordinator = plan.coordinator_leg().route;
                                    if coordinator.lane_id != origin.lane_id
                                        || coordinator.dataspace_id != origin.dataspace_id
                                    {
                                        return true;
                                    }
                                    let route_carries_incarnation =
                                        plan.legs().into_iter().any(|leg| {
                                            if leg.route.lane_id != lane_id
                                                || leg.route.dataspace_id != dataspace_id
                                            {
                                                return false;
                                            }
                                            let mut bindings =
                                                entry.active_lanes.iter().filter(|binding| {
                                                    binding.lane_id == leg.route.lane_id
                                                        && binding.dataspace_id
                                                            == leg.route.dataspace_id
                                                });
                                            let Some(binding) = bindings.next() else {
                                                return true;
                                            };
                                            if bindings.next().is_some() {
                                                return true;
                                            }
                                            binding.incarnation == lane_incarnation
                                        });
                                    let participant_carries_incarnation = match (&plan, receipt) {
                                        (crate::queue::RoutingPlan::Single(_), None) => false,
                                        (
                                            crate::queue::RoutingPlan::NativeAmx(native_plan),
                                            Some(receipt),
                                        ) => {
                                            if receipt.plan_digest != plan.digest()
                                                || receipt.lane_id != origin.lane_id
                                                || receipt.dataspace_id != origin.dataspace_id
                                                || receipt.lane_incarnation
                                                    != origin.lane_incarnation
                                                || receipt.authority_context_height
                                                    != origin.proposal_height
                                                || receipt.lane_block_height
                                                    != origin.lane_block_height
                                                || receipt.lane_block_view
                                                    != origin.lane_block_view
                                                || receipt.coordinator_proposal_hash
                                                    != execution.origin_proposal.proposal_hash
                                                || receipt.legs.len()
                                                    != native_plan.participants.len()
                                                || receipt.legs.iter().zip(&native_plan.participants).any(
                                                    |(leg, planned)| {
                                                        leg.lane_id
                                                            != planned.route.lane_id
                                                            || leg.dataspace_id
                                                                != planned.route.dataspace_id
                                                    },
                                                )
                                            {
                                                true
                                            } else {
                                                crate::native_amx::native_amx_receipt_requires_separate_participant_application_for(
                                                    receipt,
                                                    lane_id,
                                                    dataspace_id,
                                                    lane_incarnation,
                                                )
                                                .unwrap_or(true)
                                            }
                                        }
                                        _ => true,
                                    };
                                    route_carries_incarnation
                                        || participant_carries_incarnation
                                })
                    })
                })
            },
        )?;
        Ok(outcome != PendingCertifiedMergeVisitOutcome::Complete)
    }

    /// Select the next pending certified entry deterministically by
    /// `(epoch_id, entry_hash)`, excluding entries already in the committed log.
    ///
    /// # Errors
    /// Returns an error when the pending directory is unreadable, exceeds its
    /// hard entry-count/byte caps, or contains a malformed sidecar.
    #[cfg(test)]
    pub(crate) fn select_pending_certified_merge_entry(
        &self,
    ) -> Result<Option<(HashOf<MergeLedgerEntry>, MergeLedgerEntry)>> {
        Ok(self.pending_certified_merge_entries()?.into_iter().next())
    }

    /// Select the first canonical pending entry accepted by `eligible`.
    ///
    /// The predicate runs without the sidecar lock, allowing callers to perform
    /// full state/QC validation. Rejected stale entries remain durable and do
    /// not poison selection of a later eligible candidate.
    pub(crate) fn select_pending_certified_merge_entry_matching(
        &self,
        mut eligible: impl FnMut(HashOf<MergeLedgerEntry>, &MergeLedgerEntry) -> bool,
    ) -> Result<Option<(HashOf<MergeLedgerEntry>, MergeLedgerEntry)>> {
        Ok(self
            .pending_certified_merge_entries()?
            .into_iter()
            .find(|(hash, entry)| eligible(*hash, entry)))
    }

    /// Remove a pending sidecar after the same entry is globally committed.
    ///
    /// # Errors
    /// Returns an error when the sidecar cannot be removed or its parent cannot
    /// be synchronized.
    pub(crate) fn remove_pending_certified_merge_entry(
        &self,
        hash: HashOf<MergeLedgerEntry>,
    ) -> Result<()> {
        self.ensure_prune_recovery_not_required()?;
        self.durable_mutation_authorized()?;
        self.remove_pending_certified_merge_entry_after_authorization(hash)
    }

    fn remove_pending_certified_merge_entry_after_authorization(
        &self,
        hash: HashOf<MergeLedgerEntry>,
    ) -> Result<()> {
        #[cfg(test)]
        if self
            .fail_next_pending_merge_cleanup
            .swap(false, Ordering::Relaxed)
        {
            return Err(Error::IO(
                std::io::Error::other("injected committed-pending cleanup failure"),
                self.pending_merge_entry_path(hash),
            ));
        }
        let path = self.pending_merge_entry_path(hash);
        let directory = self.pending_merge_entry_dir();
        let _guard = self.sidecar_lock.lock();
        let accounting_mutation = self.begin_total_disk_usage_mutation();
        let bytes = std::fs::metadata(&path).map_or(0, |metadata| metadata.len());
        let result = match std::fs::remove_file(&path) {
            Ok(()) => {
                sync_dir(&directory).map_err(|err| Error::IO(err, directory))?;
                self.sub_disk_usage_bytes(bytes);
                Ok(())
            }
            Err(err) if err.kind() == ErrorKind::NotFound => Ok(()),
            Err(err) => Err(Error::IO(err, path)),
        };
        if result.is_ok() {
            accounting_mutation.finish();
        }
        result
    }

    fn preflight_committed_merge_entry_for_block(
        &self,
        block: &SignedBlock,
        entry: &MergeLedgerEntry,
    ) -> Result<()> {
        let record = Self::carrier_record_for_block_entry(block, entry)?;
        self.merge_log.lock().preflight_append(entry)?;
        let _guard = self.merge_carrier_lock.lock();
        self.preflight_merge_carrier_record_unlocked(record)?;
        Ok(())
    }

    fn associated_merge_entry_for_block(
        &self,
        block: &SignedBlock,
    ) -> Result<Option<MergeLedgerEntry>> {
        let Some(reference) = Self::block_merge_reference(block) else {
            return Ok(None);
        };
        let Some(entry) = self.merge_log.lock().entry_by_hash(reference.entry_hash)? else {
            return Ok(None);
        };
        if !reference.matches_entry(&entry) {
            return Err(Error::MergeReferenceMismatch(
                "canonical block compact reference differs from its committed merge entry"
                    .to_owned(),
            ));
        }
        let record = Self::carrier_record_for_block_entry(block, &entry)?;
        let _guard = self.merge_carrier_lock.lock();
        if self.preflight_merge_carrier_record_unlocked(record)? {
            return Ok(None);
        }
        Ok(Some(entry))
    }

    fn remove_committed_pending_merge_entry_best_effort(&self, hash: HashOf<MergeLedgerEntry>) {
        if let Err(error) = self.remove_pending_certified_merge_entry(hash) {
            warn!(
                ?error,
                %hash,
                "committed merge entry remains in the redundant pending sidecar store"
            );
        }
    }

    fn append_committed_merge_entry_for_block_if_missing(
        &self,
        block: &SignedBlock,
        entry: &MergeLedgerEntry,
    ) -> Result<(usize, bool)> {
        let record = Self::carrier_record_for_block_entry(block, entry)?;
        let entry_hash = record.entry_hash;
        let _carrier_guard = self.merge_carrier_lock.lock();
        let mut merge_log = self.merge_log.lock();
        let merge_log_len_before = merge_log.total_entries;
        let existing = merge_log.entry_by_hash(entry_hash)?;
        let mut appended = false;
        let mut merge_accounting_mutation = None;
        if let Some(existing) = existing.as_ref() {
            if existing != entry {
                return Err(Error::MergeCarrierConflict(
                    "committed merge log contains different bytes for the same entry hash"
                        .to_owned(),
                ));
            }
        } else {
            merge_accounting_mutation = Some(self.begin_total_disk_usage_mutation());
            merge_log.append(entry)?;
            appended = true;
        }

        let carrier_written = match self.write_merge_carrier_record_unlocked(record) {
            Ok(written) => written,
            Err(err) => {
                if appended
                    && let Err(rollback_err) = merge_log.truncate_to_len(merge_log_len_before)
                {
                    let combined = Error::MergeCarrierConflict(format!(
                        "merge carrier publication failed ({err}) and merge-log rollback failed ({rollback_err})"
                    ));
                    drop(merge_log);
                    drop(_carrier_guard);
                    return Err(self.committed_recovery_failure(
                        "merge carrier publication rollback",
                        &combined,
                    ));
                }
                return Err(err);
            }
        };
        drop(merge_log);
        if appended && !self.store_root.as_os_str().is_empty() {
            let bytes = Self::merge_entry_bytes(entry)?;
            self.add_disk_usage_bytes(bytes);
        }
        if let Some(accounting_mutation) = merge_accounting_mutation {
            accounting_mutation.finish();
        }
        Ok((merge_log_len_before, carrier_written))
    }

    /// Snapshot merge-ledger entries retained in the in-memory cache.
    pub fn merge_ledger_snapshot(&self) -> Vec<MergeLedgerEntry> {
        if self.prune_recovery_is_required()
            || self.canonical_storage_poisoned.load(Ordering::Acquire)
        {
            return Vec::new();
        }
        let merge_log = self.merge_log.lock();
        if self.prune_recovery_is_required()
            || self.canonical_storage_poisoned.load(Ordering::Acquire)
        {
            return Vec::new();
        }
        let entries = merge_log.snapshot();
        if self.prune_recovery_is_required()
            || self.canonical_storage_poisoned.load(Ordering::Acquire)
        {
            return Vec::new();
        }
        entries
    }

    /// Snapshot at most `limit` newest cached merge-ledger entries, newest first.
    ///
    /// Unlike [`Self::merge_ledger_snapshot`], diagnostic callers can use this
    /// accessor without cloning an operator-configured cache of arbitrary size.
    #[must_use]
    pub fn merge_ledger_latest_snapshot(&self, limit: usize) -> Vec<MergeLedgerEntry> {
        if limit == 0
            || self.prune_recovery_is_required()
            || self.canonical_storage_poisoned.load(Ordering::Acquire)
        {
            return Vec::new();
        }
        let merge_log = self.merge_log.lock();
        if self.prune_recovery_is_required()
            || self.canonical_storage_poisoned.load(Ordering::Acquire)
        {
            return Vec::new();
        }
        let entries = merge_log.latest_snapshot(limit);
        if self.prune_recovery_is_required()
            || self.canonical_storage_poisoned.load(Ordering::Acquire)
        {
            return Vec::new();
        }
        entries
    }

    /// Read every durable merge-ledger entry in chronological order.
    ///
    /// # Errors
    /// Returns an error when an indexed frame cannot be decoded or the file no
    /// longer has the exact length validated by startup/append recovery.
    pub(crate) fn merge_ledger_all_entries(&self) -> Result<Vec<MergeLedgerEntry>> {
        self.ensure_prune_recovery_not_required()?;
        self.ensure_canonical_storage_not_poisoned()?;
        let mut merge_log = self.merge_log.lock();
        self.ensure_prune_recovery_not_required()?;
        self.ensure_canonical_storage_not_poisoned()?;
        let entries = merge_log.all_entries()?;
        self.ensure_prune_recovery_not_required()?;
        self.ensure_canonical_storage_not_poisoned()?;
        Ok(entries)
    }

    /// Resolve exact queue reservations for a bounded set of committed transaction hashes.
    ///
    /// The lookup reuses Kura's canonical transaction-to-block index, requires one unique carrier
    /// height per requested hash, and authenticates that carrier's exact merge sidecar through the
    /// existing carrier and merge-frame indexes. Work and temporary memory are therefore
    /// proportional to `requested`, never to complete merge history.
    ///
    /// # Errors
    /// Returns an error when the durable log changed after index construction, an indexed frame is
    /// malformed, or one transaction has ambiguous committed reservation evidence.
    pub(crate) fn committed_merge_queue_reservations(
        &self,
        requested: &BTreeSet<HashOf<SignedTransaction>>,
    ) -> Result<BTreeMap<HashOf<SignedTransaction>, LaneQueueReservationKeyV2>> {
        self.ensure_prune_recovery_not_required()?;
        self.ensure_canonical_storage_not_poisoned()?;
        self.merge_log.lock().validate_indexed_file_length()?;
        let mut requested_by_height =
            BTreeMap::<NonZeroUsize, BTreeSet<HashOf<SignedTransaction>>>::new();
        {
            let transaction_index = self.transaction_entrypoint_index.lock();
            self.ensure_prune_recovery_not_required()?;
            self.ensure_canonical_storage_not_poisoned()?;
            if !transaction_index.complete {
                return Err(Error::MergeCarrierConflict(
                    "canonical transaction index is incomplete during reservation recovery"
                        .to_owned(),
                ));
            }
            for transaction_hash in requested {
                let mut heights = transaction_index
                    .heights_by_transaction
                    .get(transaction_hash)
                    .into_iter()
                    .flatten()
                    .copied();
                let Some(height) = heights.next() else {
                    continue;
                };
                if heights.next().is_some() {
                    return Err(Error::MergeCarrierConflict(format!(
                        "committed transaction {transaction_hash} has multiple canonical carrier heights"
                    )));
                }
                requested_by_height
                    .entry(height)
                    .or_default()
                    .insert(*transaction_hash);
            }
        }

        let mut reservations = BTreeMap::new();
        for (height, hashes) in requested_by_height {
            let Some(entry) = self.get_merge_entry_by_carrier_height(height)? else {
                continue;
            };
            for (transaction_hash, reservation) in
                crate::state::certified_merge_queue_reservations(&entry).map_err(|error| {
                    Error::MergeCarrierConflict(format!(
                        "indexed committed merge reservations are invalid: {error}"
                    ))
                })?
            {
                if !hashes.contains(&transaction_hash) {
                    continue;
                }
                if let Some(existing) = reservations.insert(transaction_hash, reservation)
                    && existing != reservation
                {
                    return Err(Error::MergeCarrierConflict(format!(
                        "committed merge history binds transaction {transaction_hash} to conflicting reservations"
                    )));
                }
            }
        }
        self.ensure_prune_recovery_not_required()?;
        self.ensure_canonical_storage_not_poisoned()?;
        Ok(reservations)
    }

    /// Return the latest committed lane-local execution height for every active
    /// `(lane, dataspace, incarnation)` identity.
    ///
    /// The map is maintained while the merge log is streamed at startup and on
    /// each append/truncation, so consensus validation does not rescan or decode
    /// the complete durable history for every candidate.
    #[cfg(test)]
    pub(crate) fn latest_merge_execution_heights(
        &self,
    ) -> Result<BTreeMap<(LaneId, DataSpaceId, Hash), u64>> {
        self.ensure_prune_recovery_not_required()?;
        self.ensure_canonical_storage_not_poisoned()?;
        let merge_log = self.merge_log.lock();
        self.ensure_prune_recovery_not_required()?;
        self.ensure_canonical_storage_not_poisoned()?;
        let heights = merge_log.latest_execution_heights();
        self.ensure_prune_recovery_not_required()?;
        self.ensure_canonical_storage_not_poisoned()?;
        Ok(heights)
    }

    #[cfg(test)]
    pub(crate) fn fail_next_merge_append_for_test(&self) {
        self.merge_log.lock().fail_next_append = true;
    }

    /// Reset merge-history read counters used by transaction-query complexity tests.
    #[cfg(test)]
    pub(crate) fn reset_merge_query_read_counters_for_test(&self) {
        let mut merge_log = self.merge_log.lock();
        merge_log.full_history_scans = 0;
        merge_log.indexed_lookups = 0;
        merge_log.complete_execution_scans = 0;
    }

    /// Return `(full_log_scans, complete_execution_scans, indexed_lookups)` for tests.
    #[cfg(test)]
    pub(crate) fn merge_query_read_counters_for_test(&self) -> (usize, usize, usize) {
        let merge_log = self.merge_log.lock();
        (
            merge_log.full_history_scans,
            merge_log.complete_execution_scans,
            merge_log.indexed_lookups,
        )
    }

    /// Corrupt a sidecar payload while retaining its frame index for fail-closed tests.
    #[cfg(test)]
    pub(crate) fn remove_merge_entry_payload_for_test(&self, hash: HashOf<MergeLedgerEntry>) {
        let mut merge_log = self.merge_log.lock();
        merge_log.in_memory_entries.remove(&hash);
        let Some(frame) = merge_log.frames_by_hash.get(&hash).copied() else {
            return;
        };
        let Some(path) = merge_log.file.as_ref().map(|file| file.path.clone()) else {
            return;
        };
        let payload_len =
            usize::try_from(frame.payload_len).expect("merge frame payload length fits usize");
        let mut file = FileWrap::open_with(path, |options| {
            options.write(true);
        })
        .expect("open indexed merge sidecar without append mode for test corruption");
        file.try_io(|inner| {
            inner.seek(SeekFrom::Start(frame.frame_offset.saturating_add(4)))?;
            inner.write_all(&vec![0; payload_len])?;
            inner.sync_data()?;
            Ok(())
        })
        .expect("corrupt indexed merge sidecar payload for test");
    }

    #[cfg(test)]
    fn fail_next_merge_append_after_for_test(&self, point: MergeLedgerAppendFailurePoint) {
        self.merge_log.lock().fail_next_append_after = Some(point);
    }

    pub(crate) fn truncate_merge_log_to_len(&self, keep: usize) -> Result<()> {
        self.durable_mutation_authorized()?;
        self.truncate_merge_log_to_len_after_authorization(keep)
    }

    fn truncate_merge_log_to_len_after_authorization(&self, keep: usize) -> Result<()> {
        let before = self.merge_log_tracked_bytes()?;
        let accounting_mutation = self.begin_total_disk_usage_mutation();
        self.merge_log.lock().truncate_to_len(keep)?;
        let after = self.merge_log_tracked_bytes()?;
        self.update_disk_usage_delta(before, after);
        accounting_mutation.finish();
        Ok(())
    }

    /// Start a thread that receives and stores new blocks
    /// Start the background block writer after all provisional startup authority is finalized.
    ///
    /// # Errors
    /// Returns an error while signed snapshot authentication is pending or canonical storage is
    /// fail-stop poisoned.
    pub fn start(kura: Arc<Self>, shutdown_signal: ShutdownSignal) -> Result<Child> {
        kura.ensure_snapshot_bootstrap_authenticated()?;
        kura.ensure_canonical_storage_not_poisoned()?;
        let shutdown_notify_tx = kura.block_notify_tx.clone();
        let shutdown_signal_clone = shutdown_signal.clone();
        tokio::spawn(async move {
            shutdown_signal_clone.receive().await;
            Self::notify_block_writer_sender(
                &shutdown_notify_tx,
                BlockNotify::Shutdown,
                "shutdown",
            );
        });

        Ok(Child::new(
            tokio::task::spawn(spawn_os_thread_as_future(
                std::thread::Builder::new().name("kura".to_owned()),
                move || {
                    kura.receive_blocks_loop(&shutdown_signal);
                },
            )),
            OnShutdown::Wait(Duration::from_secs(5)),
        ))
    }

    /// Initialize [`Kura`] after its construction to be able to work with it.
    ///
    /// # Errors
    /// Fails if:
    /// - file storage is unavailable
    /// - data in file storage is invalid or corrupted
    #[iroha_logger::log(skip_all, name = "kura_init")]
    fn init(
        block_store: &mut BlockStore,
        mode: InitMode,
        v2_finality_floor: Option<u64>,
        provisional_hash_only_prefix: Option<usize>,
    ) -> Result<(BlockData, ChainValidation)> {
        let block_index_count: usize = block_store
            .read_durable_index_count()?
            .try_into()
            .expect("INTERNAL BUG: block index count exceeds usize::MAX");

        let chain_validation = if let Some(audited_height) = provisional_hash_only_prefix {
            Kura::init_provisional_snapshot_bootstrap(
                block_store,
                block_index_count,
                audited_height,
                v2_finality_floor,
            )?
        } else {
            match mode {
                InitMode::Fast => Kura::init_fast_mode(
                    block_store,
                    block_index_count,
                    v2_finality_floor,
                )
                .or_else(|error| {
                    warn!(%error, "Hashes file is broken. Falling back to strict init mode.");
                    Kura::init_strict_mode(block_store, block_index_count, v2_finality_floor)
                }),
                InitMode::Strict => {
                    Kura::init_strict_mode(block_store, block_index_count, v2_finality_floor)
                }
            }?
        };

        if chain_validation.truncated {
            warn!(
                validated_blocks = chain_validation.hashes.len(),
                "Kura detected corrupted storage during init and pruned to the last valid block"
            );
        }
        if chain_validation.hash_mismatch {
            warn!("Kura rewrote hashes file after detecting mismatches with on-disk blocks");
        }

        // The none value is set in order to indicate that the blocks exist on disk but are not yet loaded.
        let block_data = chain_validation
            .hashes
            .iter()
            .copied()
            .map(|hash| (hash, None))
            .collect();
        Ok((block_data, chain_validation))
    }

    fn init_provisional_snapshot_bootstrap(
        block_store: &mut BlockStore,
        block_index_count: usize,
        audited_height: usize,
        _v2_finality_floor: Option<u64>,
    ) -> Result<ChainValidation, Error> {
        let hashes_count = usize::try_from(block_store.read_hashes_count()?)?;
        if hashes_count != block_index_count || block_index_count < audited_height {
            return Err(Error::HashesFileHeightMismatch);
        }
        let hashes = block_store.read_block_hashes(0, hashes_count)?;
        let mut block_indices = vec![BlockIndex::default(); block_index_count];
        block_store.read_block_indices(0, &mut block_indices)?;
        let data_file_len = block_store.data_file_len()?;
        let mut buffer = Vec::new();
        let mut previous_hash = audited_height
            .checked_sub(1)
            .and_then(|index| hashes.get(index))
            .copied();

        for (index, block_index) in block_indices.iter().enumerate().skip(audited_height) {
            let height = u64::try_from(index)?.saturating_add(1);
            if block_index.length == 0 || block_index.length > STRICT_INIT_MAX_BLOCK_BYTES {
                return Err(Error::InvalidProvisionalSnapshotSuffix {
                    height,
                    reason: format!(
                        "block length {} is zero or exceeds the strict limit",
                        block_index.length
                    ),
                });
            }
            let header = if block_index.is_evicted() {
                block_store.verified_evicted_block_header(height, hashes[index])?
            } else {
                let end = block_index.start.checked_add(block_index.length).ok_or(
                    Error::CorruptedBlockRange {
                        start: block_index.start,
                        length: block_index.length,
                        data_len: data_file_len,
                    },
                )?;
                if end > data_file_len {
                    return Err(Error::CorruptedBlockRange {
                        start: block_index.start,
                        length: block_index.length,
                        data_len: data_file_len,
                    });
                }
                buffer.resize(usize::try_from(block_index.length)?, 0);
                block_store.read_block_data(block_index.start, &mut buffer)?;
                decode_framed_signed_block(&buffer)
                    .map_err(|error| Error::InvalidProvisionalSnapshotSuffix {
                        height,
                        reason: format!("canonical block body is not decodable: {error}"),
                    })?
                    .header()
            };
            if header.height().get() != height
                || header.prev_block_hash() != previous_hash
                || header.hash() != hashes[index]
            {
                return Err(Error::InvalidProvisionalSnapshotSuffix {
                    height,
                    reason: "block height, parent hash, or canonical header hash mismatches the durable journal"
                        .to_owned(),
                });
            }
            previous_hash = Some(hashes[index]);
        }
        Ok(ChainValidation {
            hashes,
            truncated: false,
            hash_mismatch: false,
            hard_fork_hash_only_block_count: audited_height,
        })
    }

    fn ensure_startup_rewrite_respects_v2_finality(
        v2_finality_floor: Option<u64>,
        rewrite_from_height: u64,
    ) -> Result<()> {
        if let Some(finalized_height) = v2_finality_floor
            && finalized_height >= rewrite_from_height
        {
            return Err(Error::FinalizedV2BlockMutation {
                rewrite_from_height,
                finalized_height,
            });
        }
        Ok(())
    }

    fn rewrite_validated_block_hashes(
        block_store: &mut BlockStore,
        hashes: &[HashOf<BlockHeader>],
        v2_finality_floor: Option<u64>,
    ) -> Result<()> {
        let Some(finalized_height) = v2_finality_floor else {
            return block_store.overwrite_block_hashes(hashes);
        };
        let suffix_start = usize::try_from(finalized_height)?;
        let Some(suffix) = hashes.get(suffix_start..) else {
            return Err(Error::HashesFileHeightMismatch);
        };
        block_store.overwrite_block_hash_suffix(finalized_height, suffix)
    }

    #[cfg(test)]
    fn init_hash_only_hard_fork_mode(
        block_store: &mut BlockStore,
        mut block_index_count: usize,
        hard_fork_hash_only_block_count: usize,
        v2_finality_floor: Option<u64>,
    ) -> Result<ChainValidation, Error> {
        let mut block_hashes_count: usize = block_store
            .read_hashes_count()?
            .try_into()
            .expect("INTERNAL BUG: block hashes count exceeds usize::MAX");
        let mut repaired_height_mismatch = false;
        if block_hashes_count > block_index_count {
            Self::ensure_startup_rewrite_respects_v2_finality(
                v2_finality_floor,
                u64::try_from(block_index_count)?.saturating_add(1),
            )?;
            warn!(
                hashes_count = block_hashes_count,
                index_count = block_index_count,
                "hard-fork snapshot bootstrap: hashes journal exceeds durable index; truncating hashes to durable height"
            );
            block_store.truncate_hashes_to_count(block_index_count as u64)?;
            block_store.truncate_data_to_index(block_index_count as u64)?;
            block_hashes_count = block_index_count;
            repaired_height_mismatch = true;
        } else if block_hashes_count < block_index_count {
            Self::ensure_startup_rewrite_respects_v2_finality(
                v2_finality_floor,
                u64::try_from(block_hashes_count)?.saturating_add(1),
            )?;
            warn!(
                hashes_count = block_hashes_count,
                index_count = block_index_count,
                "hard-fork snapshot bootstrap: durable index exceeds hashes journal; truncating index and data to hashes height"
            );
            block_store.write_index_count(block_hashes_count as u64)?;
            block_store.truncate_data_to_index(block_hashes_count as u64)?;
            block_index_count = block_hashes_count;
            repaired_height_mismatch = true;
        }

        let expected_hashes = block_store.read_block_hashes(0, block_hashes_count)?;
        if hard_fork_hash_only_block_count >= block_index_count {
            info!(
                block_count = expected_hashes.len(),
                "hard-fork snapshot bootstrap: trusting existing Kura hash journal without decoding legacy block bodies"
            );
            return Ok(ChainValidation {
                hashes: expected_hashes,
                truncated: repaired_height_mismatch,
                hash_mismatch: false,
                hard_fork_hash_only_block_count: block_index_count,
            });
        }

        let mut block_indices = vec![BlockIndex::default(); block_index_count];
        block_store.read_block_indices(0, &mut block_indices)?;
        let mut validation = Self::validate_block_chain(
            block_store,
            &block_indices,
            Some(&expected_hashes),
            hard_fork_hash_only_block_count,
            v2_finality_floor,
        )?;
        validation.hard_fork_hash_only_block_count = validation
            .hard_fork_hash_only_block_count
            .min(validation.hashes.len());
        if validation.truncated || validation.hash_mismatch {
            Self::rewrite_validated_block_hashes(
                block_store,
                &validation.hashes,
                v2_finality_floor,
            )?;
        }
        validation.truncated |= repaired_height_mismatch;
        info!(
            legacy_blocks = validation.hard_fork_hash_only_block_count,
            validated_blocks = validation
                .hashes
                .len()
                .saturating_sub(validation.hard_fork_hash_only_block_count),
            "hard-fork snapshot bootstrap: trusted legacy prefix and validated post-fork block bodies"
        );
        Ok(validation)
    }

    fn init_fast_mode(
        block_store: &mut BlockStore,
        block_index_count: usize,
        v2_finality_floor: Option<u64>,
    ) -> Result<ChainValidation, Error> {
        let mut block_hashes_count: usize = block_store
            .read_hashes_count()?
            .try_into()
            .expect("INTERNAL BUG: block hashes count exceeds usize::MAX");
        if block_hashes_count > block_index_count {
            Self::ensure_startup_rewrite_respects_v2_finality(
                v2_finality_floor,
                u64::try_from(block_index_count)?.saturating_add(1),
            )?;
            warn!(
                hashes_count = block_hashes_count,
                index_count = block_index_count,
                "hashes file longer than index; truncating to durable count"
            );
            block_store.truncate_hashes_to_count(block_index_count as u64)?;
            block_hashes_count = block_index_count;
        }
        if block_hashes_count == block_index_count {
            let mut block_indices = vec![BlockIndex::default(); block_index_count];
            block_store.read_block_indices(0, &mut block_indices)?;
            let expected_hashes = block_store.read_block_hashes(0, block_hashes_count)?;
            let validation = Self::validate_block_chain(
                block_store,
                &block_indices,
                Some(&expected_hashes),
                0,
                v2_finality_floor,
            )?;
            if validation.truncated || validation.hash_mismatch {
                Self::rewrite_validated_block_hashes(
                    block_store,
                    &validation.hashes,
                    v2_finality_floor,
                )?;
            }
            Ok(validation)
        } else {
            Err(Error::HashesFileHeightMismatch)
        }
    }

    fn init_strict_mode(
        block_store: &mut BlockStore,
        block_index_count: usize,
        v2_finality_floor: Option<u64>,
    ) -> Result<ChainValidation, Error> {
        let mut block_indices = vec![BlockIndex::default(); block_index_count];
        block_store.read_block_indices(0, &mut block_indices)?;
        let hashes_count = block_store.read_hashes_count()?;
        if let Some(finalized_height) = v2_finality_floor {
            if u64::try_from(block_index_count)? < finalized_height {
                return Err(Error::FinalizedV2BlockMutation {
                    rewrite_from_height: u64::try_from(block_index_count)?.saturating_add(1),
                    finalized_height,
                });
            }
            if hashes_count < finalized_height {
                return Err(Error::FinalizedV2BlockMutation {
                    rewrite_from_height: hashes_count.saturating_add(1),
                    finalized_height,
                });
            }
        }
        let hash_journal_is_exact = hashes_count == block_index_count as u64;
        let expected_hashes = if hash_journal_is_exact {
            Some(block_store.read_block_hashes(0, block_index_count)?)
        } else if let Some(finalized_height) = v2_finality_floor {
            let finalized_count = usize::try_from(finalized_height)?;
            warn!(
                hashes_count,
                index_count = block_index_count,
                finalized_height,
                "strict Kura init is retaining the finalized hash prefix and rebuilding only its mutable suffix"
            );
            Some(block_store.read_block_hashes(0, finalized_count)?)
        } else {
            if hashes_count > 0 {
                warn!(
                    hashes_count,
                    index_count = block_index_count,
                    "strict Kura init cannot use hashes file for remote-only block metadata"
                );
            }
            None
        };

        let validation = Self::validate_block_chain(
            block_store,
            &block_indices,
            expected_hashes.as_deref(),
            0,
            v2_finality_floor,
        )?;
        if !hash_journal_is_exact || validation.truncated || validation.hash_mismatch {
            Self::rewrite_validated_block_hashes(
                block_store,
                &validation.hashes,
                v2_finality_floor,
            )?;
        }

        Ok(validation)
    }

    #[allow(clippy::too_many_lines)]
    fn validate_block_chain(
        block_store: &mut BlockStore,
        block_indices: &[BlockIndex],
        expected_hashes: Option<&[HashOf<BlockHeader>]>,
        mut hash_only_prefix: usize,
        v2_finality_floor: Option<u64>,
    ) -> Result<ChainValidation, Error> {
        let hashes_count = block_store.read_hashes_count()?;
        let verified_snapshot_tail = block_store
            .validated_verified_snapshot_tail(u64::try_from(block_indices.len())?, hashes_count)?;
        if let Some(marker) = verified_snapshot_tail.as_ref()
            && marker.body_prefix_count == marker.snapshot_height
        {
            hash_only_prefix = hash_only_prefix.max(usize::try_from(marker.snapshot_height)?);
        }
        if let Some(expected) = expected_hashes {
            if expected.len() > block_indices.len() || expected.len() < hash_only_prefix {
                return Err(Error::HashesFileHeightMismatch);
            }
        } else if hash_only_prefix > 0 {
            return Err(Error::HashesFileHeightMismatch);
        }
        let mut block_hashes = Vec::with_capacity(block_indices.len());
        let mut block_data_buffer = Vec::new();
        let mut prev_block_hash = None;
        let data_file_len = block_store.data_file_len()?;
        let mut truncated = None;
        let mut hash_mismatch = false;

        for (idx, block) in block_indices.iter().enumerate() {
            let height = idx.saturating_add(1) as u64;
            if idx < hash_only_prefix {
                let expected = expected_hashes
                    .and_then(|hashes| hashes.get(idx))
                    .copied()
                    .ok_or(Error::HashesFileHeightMismatch)?;
                prev_block_hash = Some(expected);
                block_hashes.push(expected);
                continue;
            }

            if block.length == 0
                && block.is_evicted()
                && expected_hashes.is_some_and(|hashes| hashes.get(idx).is_some())
                && verified_snapshot_tail.as_ref().is_some_and(|marker| {
                    let position = u64::try_from(idx).unwrap_or(u64::MAX);
                    let marker_start = if marker.body_prefix_count == marker.snapshot_height {
                        0
                    } else {
                        marker.body_prefix_count
                    };
                    position >= marker_start && position < marker.snapshot_height
                })
            {
                let expected = expected_hashes
                    .and_then(|hashes| hashes.get(idx))
                    .copied()
                    .ok_or(Error::HashesFileHeightMismatch)?;
                debug!(
                    block_index = idx,
                    height,
                    block = %expected,
                    "preserving verified snapshot hash-only block metadata from hashes file"
                );
                prev_block_hash = Some(expected);
                block_hashes.push(expected);
                continue;
            }
            if block.length == 0 {
                truncated = Some(true);
                error!(
                    length = block.length,
                    limit = STRICT_INIT_MAX_BLOCK_BYTES,
                    "Encountered zero-length block entry; pruning to last valid block"
                );
                break;
            }
            if block.length > STRICT_INIT_MAX_BLOCK_BYTES {
                truncated = Some(true);
                error!(
                    length = block.length,
                    limit = STRICT_INIT_MAX_BLOCK_BYTES,
                    "Encountered oversized block entry; pruning to last valid block"
                );
                break;
            }
            let decoded_block = if block.is_evicted() {
                let expected_evicted_hash =
                    expected_hashes.and_then(|hashes| hashes.get(idx)).copied();
                let expected_evicted_hash =
                    expected_evicted_hash.ok_or(Error::HashesFileHeightMismatch)?;
                let signed_wire_hash =
                    block_store.verified_v2_finality_wire_hash(height, expected_evicted_hash)?;
                let payload = match block_store.read_optional_da_cache(height) {
                    Ok(payload) => payload,
                    Err(error) => {
                        return Err(error);
                    }
                };
                let Some(payload) = payload else {
                    debug!(
                        block_index = idx,
                        height,
                        block = %expected_evicted_hash,
                        "preserving signed remote-only evicted block metadata from hashes file"
                    );
                    prev_block_hash = Some(expected_evicted_hash);
                    block_hashes.push(expected_evicted_hash);
                    continue;
                };
                {
                    let expected = expected_evicted_hash;
                    let retained_wire_hash = signed_wire_hash;
                    if u64::try_from(payload.len())? != block.length
                        || Hash::new(&payload) != retained_wire_hash
                    {
                        warn!(
                            block_index = idx,
                            height,
                            block = %expected,
                            "removing noncanonical DA cache and preserving remote-only metadata"
                        );
                        if let Err(remove_error) = block_store.remove_da_block_file(height) {
                            warn!(
                                ?remove_error,
                                height, "failed to remove complete-wire-mismatched DA block cache"
                            );
                        }
                        prev_block_hash = Some(expected);
                        block_hashes.push(expected);
                        continue;
                    }
                }
                match decode_framed_signed_block(&payload) {
                    Ok(decoded_block) => {
                        {
                            let expected = expected_evicted_hash;
                            let actual = decoded_block.hash();
                            if actual != expected {
                                warn!(
                                    expected = %expected,
                                    actual = %actual,
                                    block_index = idx,
                                    height,
                                    "removing local sidecar with mismatched block hash and preserving remote-only metadata"
                                );
                                if let Err(remove_error) = block_store.remove_da_block_file(height)
                                {
                                    warn!(
                                        ?remove_error,
                                        height, "failed to remove hash-mismatched DA block sidecar"
                                    );
                                }
                                prev_block_hash = Some(expected);
                                block_hashes.push(expected);
                                continue;
                            }
                        }
                        decoded_block
                    }
                    Err(error) => {
                        let expected = expected_evicted_hash;
                        warn!(
                            ?error,
                            block_index = idx,
                            height,
                            block = %expected,
                            "removing malformed local sidecar and preserving remote-only block metadata"
                        );
                        if let Err(remove_error) = block_store.remove_da_block_file(height) {
                            warn!(
                                ?remove_error,
                                height, "failed to remove malformed DA block sidecar"
                            );
                        }
                        prev_block_hash = Some(expected);
                        block_hashes.push(expected);
                        continue;
                    }
                }
            } else {
                let end =
                    block
                        .start
                        .checked_add(block.length)
                        .ok_or(Error::CorruptedBlockRange {
                            start: block.start,
                            length: block.length,
                            data_len: data_file_len,
                        })?;
                if end > data_file_len {
                    truncated = Some(true);
                    error!(
                        start = block.start,
                        length = block.length,
                        data_len = data_file_len,
                        "Block index points past data file; pruning to last valid block"
                    );
                    break;
                }
                let length: usize = block.length.try_into()?;
                let additional = length.saturating_sub(block_data_buffer.len());
                if additional > 0 {
                    block_data_buffer.try_reserve(additional)?;
                }
                block_data_buffer.resize(length, 0);

                match block_store.read_block_data(block.start, &mut block_data_buffer) {
                    Ok(()) => match decode_framed_signed_block(&block_data_buffer) {
                        Ok(decoded_block) => decoded_block,
                        Err(error) => {
                            truncated = Some(true);
                            error!(
                                ?error,
                                block_index = idx,
                                "Malformed block payload; pruning to last valid block"
                            );
                            break;
                        }
                    },
                    Err(error) => {
                        truncated = Some(true);
                        error!(
                            ?error,
                            block_index = idx,
                            "Failed to read block payload; pruning to last valid block"
                        );
                        break;
                    }
                }
            };

            if prev_block_hash != decoded_block.header().prev_block_hash() {
                truncated = Some(true);
                error!(
                    expected = ?prev_block_hash,
                    actual = ?decoded_block.header().prev_block_hash(),
                    block_index = idx,
                    "Previous block hash mismatch; pruning to last valid block"
                );
                break;
            }

            let decoded_block_hash = decoded_block.hash();
            if let Some(expected) = expected_hashes.and_then(|hashes| hashes.get(idx)).copied() {
                if expected != decoded_block_hash {
                    Self::ensure_startup_rewrite_respects_v2_finality(v2_finality_floor, height)?;
                    hash_mismatch = true;
                    warn!(
                        expected = ?expected,
                        actual = ?decoded_block_hash,
                        block_index = idx,
                        "Block hash file entry mismatched decoded block; rewriting hashes file"
                    );
                }
            }

            prev_block_hash = Some(decoded_block_hash);
            block_hashes.push(decoded_block_hash);
        }

        let truncated = truncated.unwrap_or(false);
        let validated_height = block_hashes.len() as u64;
        if truncated {
            Self::ensure_startup_rewrite_respects_v2_finality(
                v2_finality_floor,
                validated_height.saturating_add(1),
            )?;
            block_store.prune(validated_height)?;
            info!(
                validated_height,
                "Pruned Kura storage to last validated block after detecting corruption"
            );
        }

        let authenticated_hash_only_block_count = verified_snapshot_tail
            .as_ref()
            .filter(|marker| marker.body_prefix_count == marker.snapshot_height)
            .and_then(|marker| usize::try_from(marker.snapshot_height).ok())
            .unwrap_or(hash_only_prefix)
            .min(block_hashes.len());
        Ok(ChainValidation {
            hashes: block_hashes,
            truncated,
            hash_mismatch,
            hard_fork_hash_only_block_count: authenticated_hash_only_block_count,
        })
    }

    #[iroha_logger::log(skip_all)]
    fn receive_blocks_loop(&self, shutdown_signal: &ShutdownSignal) {
        let kura = self;
        let block_rx = kura
            .block_notify_rx
            .lock()
            .take()
            .expect("Kura writer thread already started");

        let mut should_exit = false;
        loop {
            if shutdown_signal.is_sent() {
                info!("Kura block thread is being shut down. Flushing sidecars and fsync state.");
                should_exit = true;
            }

            let prune_guard = kura.prune_lock.lock();
            if kura.prune_recovery_is_required() {
                error!("Kura writer stopped because canonical prune recovery requires restart");
                return;
            }
            kura.flush_pipeline_sidecars();
            kura.flush_fastpq_proof_snapshots();
            kura.flush_pending_budget_eviction();
            drop(prune_guard);

            if should_exit {
                let _prune_guard = kura.prune_lock.lock();
                if kura.prune_recovery_is_required() {
                    error!("Kura writer stopped because canonical prune recovery requires restart");
                    return;
                }
                let flush_result = {
                    let mut store = kura.block_store.lock();
                    store.flush_pending_fsync(true)
                };
                if let Err(error) = flush_result {
                    error!(?error, "Failed to fsync pending blocks on shutdown");
                    kura.record_or_poison_fsync_fault("shutdown fsync", &error);
                    return;
                }
                info!("Kura has flushed sidecars and pending fsync state and is shutting down.");
                return;
            }

            let wait_for_fsync = {
                let guard = kura.block_store.lock();
                guard.next_fsync_wait()
            };
            match wait_for_fsync {
                Some(wait) => match block_rx.recv_timeout(wait) {
                    Ok(BlockNotify::NewBlock) => {
                        debug!("kura writer received sidecar flush signal");
                    }
                    Ok(BlockNotify::StorageBudgetEviction) => {
                        debug!("kura writer received storage-budget eviction signal");
                    }
                    Ok(BlockNotify::Shutdown) => {
                        should_exit = true;
                        debug!("kura writer received shutdown signal");
                    }
                    Err(RecvTimeoutError::Timeout) => {
                        let _prune_guard = kura.prune_lock.lock();
                        if kura.prune_recovery_is_required() {
                            error!(
                                "Kura writer stopped because canonical prune recovery requires restart"
                            );
                            return;
                        }
                        let mut store = kura.block_store.lock();
                        if let Err(error) = store.flush_pending_fsync(false) {
                            error!(?error, "Failed to fsync pending batch");
                            drop(store);
                            kura.record_or_poison_fsync_fault("periodic fsync", &error);
                            return;
                        }
                    }
                    Err(RecvTimeoutError::Disconnected) => {
                        info!("Block writer channel closed; exiting thread.");
                        return;
                    }
                },
                None => match block_rx.recv() {
                    Ok(BlockNotify::NewBlock) => {
                        debug!("kura writer received sidecar flush signal");
                    }
                    Ok(BlockNotify::StorageBudgetEviction) => {
                        debug!("kura writer received storage-budget eviction signal");
                    }
                    Ok(BlockNotify::Shutdown) => {
                        should_exit = true;
                        debug!("kura writer received shutdown signal");
                    }
                    Err(error) => {
                        info!(?error, "Block writer channel closed; exiting thread.");
                        return;
                    }
                },
            }
        }
    }

    /// Get the hash of the block at the provided height.
    pub fn get_block_hash(&self, block_height: NonZeroUsize) -> Option<HashOf<BlockHeader>> {
        if self.prune_recovery_is_required()
            || self.canonical_storage_poisoned.load(Ordering::Acquire)
        {
            return None;
        }
        #[cfg(test)]
        self.observe_canonical_read_after_prune_check_for_tests(CANONICAL_HASH_READER_OBSERVED);
        let hash_data_guard = self.block_data.lock();
        if self.prune_recovery_is_required() {
            return None;
        }

        let block_height = block_height.get();
        if hash_data_guard.len() < block_height {
            return None;
        }

        let block_index = block_height - 1;
        Some(hash_data_guard[block_index].0)
    }

    /// Get the committed hash at the provided height from Kura's durable hash journal.
    pub fn get_durable_block_hash(
        &self,
        block_height: NonZeroUsize,
    ) -> Option<HashOf<BlockHeader>> {
        if self.prune_recovery_is_required()
            || self.canonical_storage_poisoned.load(Ordering::Acquire)
        {
            return None;
        }
        let height = u64::try_from(block_height.get()).ok()?;
        let mut block_store = self.block_store.lock();
        if self.prune_recovery_is_required() {
            return None;
        }
        let hash = Self::read_durable_hash_at_height(&mut block_store, height)
            .ok()
            .flatten();
        if self.prune_recovery_is_required() {
            return None;
        }
        hash
    }

    /// Resolve the height of the block with the given hash.
    pub fn get_block_height_by_hash(&self, hash: HashOf<BlockHeader>) -> Option<NonZeroUsize> {
        if self.prune_recovery_is_required()
            || self.canonical_storage_poisoned.load(Ordering::Acquire)
        {
            return None;
        }
        let index = self.block_height_index.lock();
        if self.prune_recovery_is_required() {
            return None;
        }
        let height = index.get(&hash).copied();
        if self.prune_recovery_is_required() {
            return None;
        }
        height
    }

    /// Resolve block heights containing the given transaction entrypoint hash.
    ///
    /// Returns `None` when the in-memory index is known to be partial, so callers can fall back to
    /// scanning blocks without risking incomplete query results.
    pub fn get_block_heights_by_entrypoint_hash(
        &self,
        hash: HashOf<TransactionEntrypoint>,
    ) -> Option<BTreeSet<NonZeroUsize>> {
        if self.prune_recovery_is_required()
            || self.canonical_storage_poisoned.load(Ordering::Acquire)
        {
            return None;
        }
        let index = self.transaction_entrypoint_index.lock();
        if self.prune_recovery_is_required() {
            return None;
        }
        let heights = index.complete.then(|| {
            index
                .heights_by_entrypoint
                .get(&hash)
                .cloned()
                .unwrap_or_default()
        });
        if self.prune_recovery_is_required() {
            return None;
        }
        heights
    }

    /// Resolve block heights containing the given committed transaction hash.
    ///
    /// Merge-sidecar transactions are indexed at their exact sparse global
    /// carrier height. Returns `None` when the in-memory index is partial.
    pub fn get_block_heights_by_transaction_hash(
        &self,
        hash: HashOf<SignedTransaction>,
    ) -> Option<BTreeSet<NonZeroUsize>> {
        if self.prune_recovery_is_required()
            || self.canonical_storage_poisoned.load(Ordering::Acquire)
        {
            return None;
        }
        let index = self.transaction_entrypoint_index.lock();
        if self.prune_recovery_is_required() {
            return None;
        }
        let heights = index.complete.then(|| {
            index
                .heights_by_transaction
                .get(&hash)
                .cloned()
                .unwrap_or_default()
        });
        if self.prune_recovery_is_required() {
            return None;
        }
        heights
    }

    /// Resolve the earliest block height containing an issuer-bound offline operation.
    ///
    /// The outer `None` means the in-memory transaction index is partial. An inner `None`
    /// means the complete index contains no operation with both the requested outer transaction
    /// authority and signed operation identifier. Binding the lookup to the outer authority keeps
    /// a rejected transaction from another authority from shadowing a Torii-issued operation.
    /// Returning only the earliest height bounds request-time work even if invalid historical data
    /// reused an identifier within one issuer namespace.
    pub fn get_earliest_block_height_by_offline_operation_id(
        &self,
        issuer: &AccountId,
        operation_id: [u8; 32],
    ) -> Option<Option<NonZeroUsize>> {
        if self.prune_recovery_is_required()
            || self.canonical_storage_poisoned.load(Ordering::Acquire)
        {
            return None;
        }
        #[cfg(test)]
        self.observe_canonical_read_after_prune_check_for_tests(OFFLINE_OPERATION_READER_OBSERVED);
        let index = self.transaction_entrypoint_index.lock();
        if self.prune_recovery_is_required() {
            return None;
        }
        let height = index.complete.then(|| {
            index
                .heights_by_offline_operation_id
                .get(&(issuer.clone(), operation_id))
                .and_then(|heights| heights.first().copied())
        });
        if self.prune_recovery_is_required() {
            return None;
        }
        height
    }

    /// Resolve block heights containing committed transactions with the given authority.
    ///
    /// Returns `None` when the in-memory transaction index is known to be partial.
    pub fn get_block_heights_by_transaction_authority(
        &self,
        authority: &AccountId,
    ) -> Option<BTreeSet<NonZeroUsize>> {
        if self.prune_recovery_is_required()
            || self.canonical_storage_poisoned.load(Ordering::Acquire)
        {
            return None;
        }
        let index = self.transaction_entrypoint_index.lock();
        if self.prune_recovery_is_required() {
            return None;
        }
        let heights = index.complete.then(|| {
            index
                .heights_by_authority
                .get(authority)
                .cloned()
                .unwrap_or_default()
        });
        if self.prune_recovery_is_required() {
            return None;
        }
        heights
    }

    /// Resolve block heights containing committed transactions with the given timestamp.
    ///
    /// Returns `None` when the in-memory transaction index is known to be partial.
    pub fn get_block_heights_by_transaction_timestamp_ms(
        &self,
        timestamp_ms: u64,
    ) -> Option<BTreeSet<NonZeroUsize>> {
        if self.prune_recovery_is_required()
            || self.canonical_storage_poisoned.load(Ordering::Acquire)
        {
            return None;
        }
        let index = self.transaction_entrypoint_index.lock();
        if self.prune_recovery_is_required() {
            return None;
        }
        let heights = index.complete.then(|| {
            index
                .heights_by_timestamp_ms
                .get(&timestamp_ms)
                .cloned()
                .unwrap_or_default()
        });
        if self.prune_recovery_is_required() {
            return None;
        }
        heights
    }

    /// Resolve block heights containing committed transactions in the timestamp range.
    ///
    /// Returns `None` when the in-memory transaction index is known to be partial.
    pub fn get_block_heights_by_transaction_timestamp_range(
        &self,
        lower_bound: Option<u64>,
        upper_bound: Option<u64>,
    ) -> Option<BTreeSet<NonZeroUsize>> {
        if self.prune_recovery_is_required()
            || self.canonical_storage_poisoned.load(Ordering::Acquire)
        {
            return None;
        }
        if let (Some(lower), Some(upper)) = (lower_bound, upper_bound)
            && lower > upper
        {
            return Some(BTreeSet::new());
        }

        let index = self.transaction_entrypoint_index.lock();
        if self.prune_recovery_is_required() {
            return None;
        }
        let heights = index.complete.then(|| {
            let lower = lower_bound.map_or(Bound::Unbounded, Bound::Included);
            let upper = upper_bound.map_or(Bound::Unbounded, Bound::Included);
            index
                .heights_by_timestamp_ms
                .range((lower, upper))
                .flat_map(|(_, heights)| heights.iter().copied())
                .collect()
        });
        if self.prune_recovery_is_required() {
            return None;
        }
        heights
    }

    /// Resolve block heights containing committed transactions with the given result status.
    ///
    /// Returns `None` when the in-memory transaction index is known to be partial.
    pub fn get_block_heights_by_transaction_result_status(
        &self,
        is_ok: bool,
    ) -> Option<BTreeSet<NonZeroUsize>> {
        if self.prune_recovery_is_required()
            || self.canonical_storage_poisoned.load(Ordering::Acquire)
        {
            return None;
        }
        let index = self.transaction_entrypoint_index.lock();
        if self.prune_recovery_is_required() {
            return None;
        }
        let heights = index.complete.then(|| {
            index
                .heights_by_result_status
                .get(&is_ok)
                .cloned()
                .unwrap_or_default()
        });
        if self.prune_recovery_is_required() {
            return None;
        }
        heights
    }

    /// Return the durable height and encoded payload length for a known canonical block hash.
    #[cfg(test)]
    pub(crate) fn durable_block_payload_len_by_hash(
        &self,
        hash: HashOf<BlockHeader>,
    ) -> Option<(u64, u64)> {
        if self.canonical_storage_poisoned.load(Ordering::Acquire) {
            return None;
        }
        let height = self.get_block_height_by_hash(hash)?;
        let height_u64 = u64::try_from(height.get()).ok()?;
        let mut store = self.block_store.lock();
        if self.prune_recovery_is_required() {
            return None;
        }
        let durable_hash = Self::read_durable_hash_at_height(&mut store, height_u64).ok()??;
        if durable_hash != hash {
            return None;
        }
        let index = store.read_block_index(height_u64.saturating_sub(1)).ok()?;
        if self.prune_recovery_is_required() {
            return None;
        }
        (index.length > 0).then_some((height_u64, index.length))
    }

    /// Cache a canonical block body in the local sidecar store after remote rehydration.
    ///
    /// The body must match Kura's durable height/hash metadata. Inline blocks are already local and
    /// are left untouched.
    pub(crate) fn cache_block_body(&self, block: &SignedBlock) -> Result<()> {
        let _prune_guard = self.prune_lock.lock();
        self.ensure_prune_recovery_not_required()?;
        let _canonical_chain_guard = self.canonical_chain_lock.lock();
        self.resolve_canonical_storage_before_mutation()?;
        let _write_guard = self.block_store_write_lock.lock();
        self.ensure_no_pending_rollback()?;
        let height = block.header().height().get();
        let hash = block.hash();
        self.ensure_durable_block_at_height(height, hash)?;
        let index = self
            .block_store
            .lock()
            .read_block_index(height.saturating_sub(1))?;
        if !index.is_evicted() {
            return Ok(());
        }
        let wire = block.canonical_wire()?;
        let (frame, _versioned) = wire.into_parts();
        let expected_len = u64::try_from(frame.len())?;
        if index.length != expected_len {
            return Err(Error::CorruptedBlockRange {
                start: index.start,
                length: expected_len,
                data_len: index.length,
            });
        }
        self.ensure_existing_block_wire_matches(block, height, hash)?;
        let blocks_dir = self.active_blocks_dir.lock().clone();
        let finality_wire_hash = self
            .verified_v2_finality_wire_hash_for_eviction(&blocks_dir, height, hash)?
            .ok_or_else(|| {
                Error::IO(
                    std::io::Error::new(
                        ErrorKind::InvalidData,
                        "evicted canonical block has no signed complete-wire finality",
                    ),
                    self.v2_finality_artifact_path(height),
                )
            })?;
        if Hash::new(&frame) != finality_wire_hash {
            return Err(Error::IO(
                std::io::Error::new(
                    ErrorKind::InvalidData,
                    "rehydrated block wire differs from the signed complete-wire finality",
                ),
                self.v2_finality_artifact_path(height),
            ));
        }
        let store = self.block_store.lock();
        let path = store.da_block_path(height);
        let before = Self::file_len_or_zero(&path)?;
        let accounting_mutation = self.begin_total_disk_usage_mutation();
        store.write_da_block_bytes(height, &frame)?;
        let after = Self::file_len_or_zero(&path)?;
        drop(store);
        self.update_total_disk_usage_delta(before, after);
        accounting_mutation.finish();
        Ok(())
    }

    /// Get a reference to block by height, loading it from disk if needed.
    pub fn get_block(&self, block_height: NonZeroUsize) -> Option<Arc<SignedBlock>> {
        self.get_block_inner(block_height, true)
    }

    /// Load a canonical block without resolving its compact merge sidecar.
    ///
    /// Transaction-query budget admission uses this narrow path to inspect the
    /// compact reference and precharge its declared entrypoint count before any
    /// potentially large merge sidecar is read or decoded. A disk-loaded block
    /// is not cached until the normal sidecar-validating path succeeds.
    pub(crate) fn get_block_without_merge_sidecar(
        &self,
        block_height: NonZeroUsize,
    ) -> Option<Arc<SignedBlock>> {
        self.get_block_inner(block_height, false)
    }

    fn get_block_inner(
        &self,
        block_height: NonZeroUsize,
        validate_merge_sidecar: bool,
    ) -> Option<Arc<SignedBlock>> {
        if self.prune_recovery_is_required()
            || self.canonical_storage_poisoned.load(Ordering::Acquire)
        {
            if self.canonical_storage_poisoned.load(Ordering::Relaxed) {
                error!(
                    height = block_height.get(),
                    "refusing canonical block read while Kura storage is fail-stop poisoned"
                );
            }
            return None;
        }
        #[cfg(test)]
        self.observe_canonical_read_after_prune_check_for_tests(CANONICAL_BLOCK_READER_OBSERVED);
        let (block_index, expected_hash, cached_block, should_cache, chain_len) = {
            let data = self.block_data.lock();
            if self.prune_recovery_is_required() {
                return None;
            }
            if data.len() < block_height.get() {
                return None;
            }

            let idx = block_height.get() - 1;
            if self.is_hard_fork_hash_only_block(idx) {
                debug!(
                    block_index = idx,
                    "hard-fork snapshot bootstrap: hash-only block body is unavailable"
                );
                return None;
            }

            let expected_hash = data[idx].0;
            let cached_block = data[idx].1.as_ref().map(Arc::clone);
            let should_cache = idx + self.blocks_in_memory.get() >= data.len();
            (idx, expected_hash, cached_block, should_cache, data.len())
        };

        let (block, is_evicted) = {
            let mut block_store = self.block_store.lock();
            if self.prune_recovery_is_required() {
                return None;
            }
            let index = match block_store.read_block_index(block_index as u64) {
                Ok(index) => index,
                Err(error) => {
                    error!(?error, block_index, "Failed to read block index from disk");
                    return None;
                }
            };
            let is_evicted = index.is_evicted();
            let BlockIndex { start, length } = index;

            if length == 0 {
                debug!(
                    block_index,
                    height = block_index.saturating_add(1),
                    evicted = is_evicted,
                    "Kura block body is unavailable for hash-only metadata"
                );
                return None;
            }

            if let Some(telemetry) = self.telemetry.get() {
                let outcome = if is_evicted { "miss" } else { "hit" };
                telemetry.inc_storage_da_cache("kura", outcome);
            }

            let block = if is_evicted {
                let height = block_index.saturating_add(1) as u64;
                let finality_wire_hash = match self.verified_v2_finality_wire_hash_for_eviction(
                    &block_store.path_to_blockchain,
                    height,
                    expected_hash,
                ) {
                    Ok(Some(hash)) => hash,
                    Ok(None) => {
                        error!(
                            block_index,
                            height, "Evicted block has no signed complete-wire finality"
                        );
                        return None;
                    }
                    Err(error) => {
                        error!(
                            ?error,
                            block_index,
                            height,
                            "Failed to authenticate signed complete-wire finality"
                        );
                        return None;
                    }
                };
                let bytes = match block_store.read_optional_da_cache(height) {
                    Ok(Some(bytes)) => bytes,
                    Ok(None) => return None,
                    Err(error) => {
                        error!(
                            ?error,
                            block_index, height, "Failed to read evicted block cache"
                        );
                        return None;
                    }
                };
                if u64::try_from(bytes.len()).ok() != Some(length)
                    || Hash::new(&bytes) != finality_wire_hash
                {
                    error!(
                        block_index,
                        height, "Evicted block cache differs from its signed complete-wire binding"
                    );
                    return None;
                }
                if let Some(telemetry) = self.telemetry.get() {
                    let actual_len = u64::try_from(bytes.len()).unwrap_or(u64::MAX);
                    telemetry.add_storage_da_churn_bytes("kura", "rehydrated", actual_len);
                }
                match decode_framed_signed_block(&bytes) {
                    Ok(decoded) => decoded,
                    Err(error) => {
                        if self.is_hard_fork_hash_only_block(block_index) {
                            debug!(
                                ?error,
                                block_index,
                                height,
                                "hard-fork snapshot bootstrap: legacy block body is unavailable"
                            );
                            return None;
                        }
                        error!(
                            ?error,
                            block_index, height, "Failed to decode evicted block payload"
                        );
                        return None;
                    }
                }
            } else {
                if let Some(block) = cached_block {
                    return Some(block);
                }
                let bytes = match block_store.block_bytes(start, length) {
                    Ok(slice) => slice,
                    Err(error) => {
                        error!(?error, block_index, "Failed to borrow block data slice");
                        return None;
                    }
                };

                match decode_framed_signed_block(bytes) {
                    Ok(decoded) => decoded,
                    Err(error) => {
                        if self.is_hard_fork_hash_only_block(block_index) {
                            debug!(
                                ?error,
                                block_index,
                                "hard-fork snapshot bootstrap: legacy block body is unavailable"
                            );
                            return None;
                        }
                        error!(?error, block_index, "Failed to decode block from disk");
                        return None;
                    }
                }
            };
            (block, is_evicted)
        };
        if self.prune_recovery_is_required() {
            return None;
        }

        if block.hash() != expected_hash {
            error!(
                expected = ?expected_hash,
                actual = ?block.hash(),
                block_index,
                "Loaded block hash mismatched the index entry"
            );
            return None;
        }

        if self.prune_recovery_is_required() {
            return None;
        }
        let block_arc = Arc::new(block);
        let merge_reference_present = Self::block_merge_reference(&block_arc).is_some();
        let associated_merge_entry = if validate_merge_sidecar && merge_reference_present {
            match self.merge_entry_for_loaded_carrier(block_arc.as_ref()) {
                Ok(Some(entry)) => Some(entry),
                Ok(None) => {
                    error!(
                        carrier_height = block_index.saturating_add(1),
                        ?expected_hash,
                        "Loaded merge carrier block has no committed merge entry; marking its transaction index incomplete"
                    );
                    None
                }
                Err(error) => {
                    error!(
                        ?error,
                        carrier_height = block_index.saturating_add(1),
                        ?expected_hash,
                        "Failed to authenticate merge association while indexing loaded block"
                    );
                    return None;
                }
            }
        } else {
            None
        };
        if validate_merge_sidecar {
            self.set_transaction_entrypoint_index_entry_with_merge(
                block_index.saturating_add(1),
                block_arc.as_ref(),
                associated_merge_entry.as_ref(),
                chain_len,
                !merge_reference_present || associated_merge_entry.is_some(),
            );
        }

        if should_cache && validate_merge_sidecar && !is_evicted {
            #[cfg(test)]
            self.maybe_pause_block_read_before_cache_recheck_for_tests();

            // Cache publication is opportunistic, but it must be ordered after the durable index
            // observation. Eviction publishes its new index and clears this slot while retaining
            // `block_store`; re-read both durable identity fields before acquiring the cache so a
            // reader that decoded the old inline body cannot reinsert it after that publication.
            // Some canonical writers already own `block_data` before taking `block_store`, so use
            // a non-blocking cache acquisition while the store guard is held to avoid introducing
            // a reverse-order deadlock. A missed cache fill is harmless.
            let mut block_store = self.block_store.lock();
            let current_index = block_store.read_block_index(block_index as u64);
            let current_hash = block_store
                .read_block_hashes(block_index as u64, 1)
                .map(|hashes| hashes.first().copied());
            match (current_index, current_hash) {
                (Ok(index), Ok(Some(hash)))
                    if !index.is_evicted() && index.length > 0 && hash == expected_hash =>
                {
                    if let Some(mut data) = self.block_data.try_lock()
                        && data.get(block_index).is_some_and(|(hash, cached)| {
                            *hash == expected_hash && cached.is_none()
                        })
                    {
                        data[block_index].1 = Some(Arc::clone(&block_arc));
                    }
                }
                (Err(error), _) | (_, Err(error)) => {
                    debug!(
                        ?error,
                        block_index, "Skipping block cache fill after durable recheck failed"
                    );
                }
                _ => {}
            }
            drop(block_store);
        }

        if self.prune_recovery_is_required() {
            return None;
        }
        Some(block_arc)
    }

    fn is_hard_fork_hash_only_block(&self, block_index: usize) -> bool {
        block_index < self.hard_fork_hash_only_block_count.load(Ordering::Relaxed)
    }

    /// Return the provisional imported-prefix boundary and lineage digest.
    ///
    /// This is classification metadata only. Presence does not authenticate
    /// either the Kura hashes or the snapshot lineage.
    pub(crate) fn provisional_snapshot_bootstrap_metadata(&self) -> Option<(usize, Option<Hash>)> {
        self.provisional_snapshot_bootstrap
            .lock()
            .pending_metadata()
            .map(|pending| {
                (
                    pending.hash_only_prefix_height,
                    pending.bootstrap_lineage_hash,
                )
            })
    }

    /// Return whether Kura is open only for provisional signed-snapshot authentication.
    #[must_use]
    pub fn provisional_snapshot_bootstrap_pending(&self) -> bool {
        !self
            .provisional_snapshot_bootstrap
            .lock()
            .is_authenticated()
    }

    /// Return whether this height belongs to the imported snapshot prefix.
    ///
    /// The result deliberately includes a provisional prefix so startup
    /// planning can classify unavailable bodies before authentication. No
    /// mutation or output may use that classification until finalization.
    pub(crate) fn is_audited_snapshot_import_height(&self, block_height: NonZeroUsize) -> bool {
        self.is_hard_fork_hash_only_block(block_height.get().saturating_sub(1))
    }

    fn ensure_snapshot_bootstrap_authenticated(&self) -> Result<()> {
        if !self
            .provisional_snapshot_bootstrap
            .lock()
            .is_authenticated()
        {
            return Err(Error::SnapshotBootstrapAuthenticationPending);
        }
        Ok(())
    }

    /// Authorize a durable sidecar or journal mutation which does not require
    /// canonical block-stage recovery.
    fn durable_mutation_authorized(&self) -> Result<()> {
        self.ensure_snapshot_bootstrap_authenticated()?;
        self.ensure_canonical_storage_not_poisoned()
    }

    /// Finalize a provisional imported prefix against an authenticated typed lineage.
    ///
    /// The authorization proves that the outer snapshot signature (or exact
    /// one-time audited policy), Merkle metadata, complete hash vector, and
    /// first executable v2 artifact were verified. This method consumes that
    /// authorization and independently rechecks every durable marker binding
    /// before enabling Kura mutation.
    ///
    /// # Errors
    ///
    /// Returns an error if Kura is not awaiting authentication, the token
    /// differs from the durable provisional prefix, or deferred recovery
    /// fails. A deferred-recovery failure poisons canonical storage and leaves
    /// finalization fail-closed.
    pub fn finalize_authenticated_snapshot_bootstrap(
        &self,
        authorization: crate::sumeragi::AuthenticatedV2SnapshotStartup,
    ) -> Result<()> {
        let (record, snapshot_hashes, first_height_context) = authorization.into_parts();
        let pending = {
            let state = self.provisional_snapshot_bootstrap.lock();
            state
                .pending_metadata()
                .cloned()
                .ok_or(Error::SnapshotBootstrapAuthenticationPending)?
        };
        record
            .validate()
            .map_err(|error| Error::InvalidSnapshotBootstrapMarker {
                path: self
                    .active_blocks_dir
                    .lock()
                    .join(VERIFIED_SNAPSHOT_TAIL_FILE_NAME),
                reason: format!("typed bootstrap lineage is invalid: {error}"),
            })?;
        let anchor = record
            .context
            .snapshot_bootstrap
            .as_ref()
            .expect("validated bootstrap lineage contains an anchor");
        if usize::try_from(anchor.snapshot_height)? != pending.hash_only_prefix_height
            || snapshot_hashes.len() < pending.hash_only_prefix_height
            || snapshot_hashes
                .get(pending.hash_only_prefix_height.saturating_sub(1))
                .copied()
                != Some(anchor.snapshot_block_hash)
        {
            return Err(Error::InvalidSnapshotBootstrapMarker {
                path: self
                    .active_blocks_dir
                    .lock()
                    .join(VERIFIED_SNAPSHOT_TAIL_FILE_NAME),
                reason: "typed lineage anchor differs from the provisional Kura prefix".to_owned(),
            });
        }
        let lineage_hash = snapshot_bootstrap_lineage_digest(&record);
        if first_height_context.context() != &record.context
            || first_height_context.proofs_of_possession() != record.validator_set_pops
        {
            return Err(Error::InvalidSnapshotBootstrapMarker {
                path: self.sumeragi_v2_storage_root().join("contexts"),
                reason: "authenticated first-height context differs from typed snapshot lineage"
                    .to_owned(),
            });
        }
        if pending
            .bootstrap_lineage_hash
            .is_some_and(|expected| expected != lineage_hash)
        {
            return Err(Error::InvalidSnapshotBootstrapMarker {
                path: self
                    .active_blocks_dir
                    .lock()
                    .join(VERIFIED_SNAPSHOT_TAIL_FILE_NAME),
                reason: "signed snapshot lineage differs from the durable marker binding"
                    .to_owned(),
            });
        }

        {
            let mut store = self.block_store.lock();
            let logical_count = store.read_index_count()?;
            let hashes_count = store.read_hashes_count()?;
            let durable_hashes = store.read_block_hashes(0, usize::try_from(hashes_count)?)?;
            if logical_count != hashes_count
                || snapshot_hashes.len() > durable_hashes.len()
                || durable_hashes[..snapshot_hashes.len()] != snapshot_hashes[..]
            {
                return Err(Error::InvalidSnapshotBootstrapMarker {
                    path: store.path_to_blockchain.join(HASHES_FILE_NAME),
                    reason: "signed snapshot hash vector is not an exact prefix of durable Kura"
                        .to_owned(),
                });
            }
            let marker = store
                .validated_verified_snapshot_tail_read_only(logical_count, hashes_count)?
                .ok_or_else(|| Error::InvalidSnapshotBootstrapMarker {
                    path: store.verified_snapshot_tail_marker_path(),
                    reason: "authenticated snapshot did not publish a durable lineage marker"
                        .to_owned(),
                })?;
            if marker.body_prefix_count != marker.snapshot_height
                || usize::try_from(marker.snapshot_height)? != pending.hash_only_prefix_height
                || marker.bootstrap_lineage_hash != Some(lineage_hash)
                || pending
                    .hash_journal_digest
                    .is_some_and(|expected| expected != marker.hash_journal_digest)
            {
                return Err(Error::InvalidSnapshotBootstrapMarker {
                    path: store.verified_snapshot_tail_marker_path(),
                    reason: "durable marker differs from authenticated prefix lineage".to_owned(),
                });
            }
        }

        // The read-only authentication preflight is complete. Claim the one
        // finalization transition immediately before deferred recovery. Any
        // competing or repeated finalizer observes `Finalizing` (or the later
        // `Authenticated`) and cannot run recovery a second time.
        if !self
            .provisional_snapshot_bootstrap
            .lock()
            .begin_finalization(&pending)
        {
            return Err(Error::SnapshotBootstrapAuthenticationPending);
        }

        // Deferred recovery is now authorized. Any failure poisons canonical
        // storage and deliberately leaves the runtime in `Finalizing`, so no
        // canonical operation can observe partially recovered state.
        let finalize_result = (|| -> Result<()> {
            let finalization_authority = SnapshotFinalizationMutationAuthority::new(self)?;
            let roster_path = Self::roster_log_path(&self.store_root);
            let roster = CommitRosterJournal::load(roster_path, self.block_sync_roster_retention)?;
            *self.roster_log.write() = roster;

            let merge_path = self.active_merge_path.lock().clone();
            let merge_capacity = self.merge_log.lock().cache_capacity;
            let mut merge_log = MergeLedgerLog::open_at(&merge_path, merge_capacity)?;
            let block_count = self.exact_durable_blocks_count()?;
            if merge_log.total_entries > block_count {
                merge_log.truncate_to_len(block_count)?;
            }
            *self.merge_log.lock() = merge_log;

            let blocks_root = self.active_blocks_dir.lock().clone();
            let mut durable_hashes = self
                .block_data
                .lock()
                .iter()
                .take(block_count)
                .map(|(hash, _)| *hash)
                .collect::<Vec<_>>();
            {
                let mut store = self.block_store.lock();
                Self::reconcile_commit_manifests(&mut store, &blocks_root, &mut durable_hashes)?;
            }
            self.recover_retained_block_rewrite_stage_during_snapshot_finalization(
                &blocks_root,
                &finalization_authority,
            )?;
            let verified_finality = self.validate_v2_finality_inventory_on_startup()?;
            self.install_v2_startup_finality_verification_inventory(verified_finality);
            self.prune_retained_block_records_from_during_snapshot_finalization(
                &blocks_root,
                u64::try_from(block_count)?.saturating_add(1),
                &finalization_authority,
            )?;
            self.validate_retained_block_inventory_on_startup()?;
            self.recover_canonical_association_stage_during_snapshot_finalization(
                &finalization_authority,
            )?;
            self.reconcile_merge_carriers_during_snapshot_finalization(&finalization_authority)?;
            if block_count > 0 {
                let _ = self.commit_manifest(u64::try_from(block_count)?)?;
            }
            self.refresh_disk_usage_bytes()?;
            self.refresh_total_disk_usage_bytes()?;
            // Publish the immutable first-height context last. After this
            // point the same state-machine lock performs the infallible
            // Finalizing -> Authenticated assignment, so no fallible operation
            // can leave a successfully published context in a live pending
            // process.
            let mut runtime_state = self.provisional_snapshot_bootstrap.lock();
            if !matches!(*runtime_state, SnapshotBootstrapRuntimeState::Finalizing) {
                return Err(Error::SnapshotBootstrapAuthenticationPending);
            }
            let context_store = crate::sumeragi::v2_context_store::V2ContextStore::open(
                self.sumeragi_v2_storage_root(),
            )
            .map_err(|error| Error::SnapshotBootstrapFinalization {
                reason: error.to_string(),
            })?;
            context_store
                .persist(&first_height_context)
                .map_err(|error| Error::SnapshotBootstrapFinalization {
                    reason: error.to_string(),
                })?;
            *runtime_state = SnapshotBootstrapRuntimeState::Authenticated;
            Ok(())
        })();
        if let Err(error) = finalize_result {
            self.poison_canonical_storage(
                "authenticated snapshot deferred startup recovery",
                &error,
            );
            return Err(error);
        }

        Ok(())
    }

    /// Returns `true` when the canonical block is represented only by its
    /// hash from a hard-fork snapshot bootstrap and the local body is
    /// intentionally unavailable.
    pub(crate) fn is_hash_only_block_height(&self, block_height: NonZeroUsize) -> bool {
        if self.prune_recovery_is_required() {
            return false;
        }
        let idx = block_height.get().saturating_sub(1);
        if self.is_hard_fork_hash_only_block(idx) {
            return true;
        }
        let data = self.block_data.lock();
        if self.prune_recovery_is_required() {
            return false;
        }
        if data.len() <= idx || data[idx].1.is_some() {
            return false;
        }
        drop(data);
        let mut store = self.block_store.lock();
        if self.prune_recovery_is_required() {
            return false;
        }
        let is_hash_only = matches!(
            store.read_block_index(idx as u64),
            Ok(index) if index.length == 0
        );
        !self.prune_recovery_is_required() && is_hash_only
    }

    /// Force a stored block height into hash-only form when constructing snapshot tests.
    #[doc(hidden)]
    #[cfg(any(test, feature = "iroha-core-tests"))]
    #[allow(dead_code)]
    pub fn force_hash_only_block_for_testing(&self, block_height: NonZeroUsize) -> Result<()> {
        let idx = block_height.get().saturating_sub(1);
        let (block_hash, block_count) = {
            let mut data = self.block_data.lock();
            let block_count = data.len();
            let Some((block_hash, block_body)) = data.get_mut(idx) else {
                return Err(Error::OutOfBoundsBlockRead {
                    start_block_height: u64::try_from(block_height.get())?,
                    block_count,
                });
            };
            *block_body = None;
            (*block_hash, block_count)
        };

        let _write_guard = self.block_store_write_lock.lock();
        let mut store = self.block_store.lock();
        store.create_files_if_they_do_not_exist()?;
        store.write_block_hash(u64::try_from(idx)?, block_hash)?;
        store.write_block_index(u64::try_from(idx)?, EVICTED_BLOCK_START, 0)?;
        store.publish_commit_marker(u64::try_from(block_count)?)?;
        self.hard_fork_hash_only_block_count
            .fetch_max(block_height.get(), Ordering::Relaxed);
        Ok(())
    }

    pub(crate) fn hash_only_unavailable_prefix_len(&self, limit: usize) -> usize {
        if self.prune_recovery_is_required() {
            return 0;
        }
        let hash_only_count = self.hard_fork_hash_only_block_count.load(Ordering::Relaxed);
        if hash_only_count == 0 || limit == 0 {
            return 0;
        }
        hash_only_count.min(limit).min(self.block_data.lock().len())
    }

