    fn validate_v2_startup_replay_storage_binding_unlocked(
        &self,
        binding: &V2StartupReplayStorageBinding,
    ) -> Result<()> {
        let blocks_dir = self.active_blocks_dir.lock().clone();
        let current_boundary = self.exact_replay_boundary()?;
        let current_storage = self.canonical_block_store_metadata(&blocks_dir)?;
        let current_finality_directory =
            self.stable_sidecar_directory_metadata(&binding.finality_directory.expected_path)?;
        let current_retained_directory =
            self.stable_sidecar_directory_metadata(&binding.retained_directory.expected_path)?;
        if current_boundary != binding.boundary
            || !Self::canonical_block_store_metadata_unchanged(
                &binding.canonical_storage,
                &current_storage,
            )
            || !Self::stable_sidecar_directory_metadata_unchanged(
                &binding.finality_directory,
                &current_finality_directory,
            )
            || !Self::stable_sidecar_directory_metadata_unchanged(
                &binding.retained_directory,
                &current_retained_directory,
            )
        {
            return Err(Error::IO(
                std::io::Error::new(
                    ErrorKind::InvalidData,
                    "Kura startup replay storage identity changed after validation",
                ),
                blocks_dir,
            ));
        }
        let current_auxiliary = self.capture_v2_startup_replay_auxiliary_sidecars()?;
        if current_auxiliary.len() != binding.auxiliary_sidecars.len()
            || binding
                .auxiliary_sidecars
                .iter()
                .any(|(directory, expected)| {
                    current_auxiliary.get(directory).is_none_or(|current| {
                        !Self::stable_sidecar_directory_inventory_unchanged(expected, current)
                    })
                })
        {
            return Err(Error::IO(
                std::io::Error::new(
                    ErrorKind::InvalidData,
                    "startup replay checkpoint, manifest, or lane sidecar identity changed",
                ),
                blocks_dir,
            ));
        }
        let finality_directory = Self::v2_finality_artifact_dir_for(&blocks_dir);
        let retained_directory = Self::retained_block_record_dir_for(&blocks_dir);
        for (&height, entry) in &binding.entries {
            let finality_path = Self::v2_finality_artifact_path_for(&blocks_dir, height);
            let current_finality = self
                .regular_sidecar_metadata(&finality_path, &finality_directory)?
                .ok_or_else(|| {
                    Error::IO(
                        std::io::Error::new(
                            ErrorKind::NotFound,
                            "validated v2 finality sidecar disappeared before recovery",
                        ),
                        finality_path.clone(),
                    )
                })?;
            if !Self::stable_sidecar_metadata_unchanged(&entry.finality.metadata, &current_finality)
            {
                return Err(Error::IO(
                    std::io::Error::new(
                        ErrorKind::InvalidData,
                        "validated v2 finality sidecar changed before recovery",
                    ),
                    finality_path,
                ));
            }
            let retained_path = Self::retained_block_record_path_for(&blocks_dir, height);
            let current_retained = self
                .regular_sidecar_metadata(&retained_path, &retained_directory)?
                .ok_or_else(|| {
                    Error::IO(
                        std::io::Error::new(
                            ErrorKind::NotFound,
                            "validated retained block sidecar disappeared before recovery",
                        ),
                        retained_path.clone(),
                    )
                })?;
            if !Self::stable_sidecar_metadata_unchanged(
                &entry.retained_block.metadata,
                &current_retained,
            ) {
                return Err(Error::IO(
                    std::io::Error::new(
                        ErrorKind::InvalidData,
                        "validated retained block sidecar changed before recovery",
                    ),
                    retained_path,
                ));
            }
        }
        Ok(())
    }

    /// Revalidate the metadata-only storage authorization carried by a replay
    /// plan immediately before active-height recovery.
    pub(crate) fn validate_v2_startup_replay_storage_binding(
        &self,
        binding: &V2StartupReplayStorageBinding,
    ) -> Result<()> {
        let _prune_guard = self.prune_lock.lock();
        self.ensure_prune_recovery_not_required()?;
        let _canonical_chain_guard = self.canonical_chain_lock.lock();
        self.ensure_canonical_storage_not_poisoned()?;
        self.validate_v2_startup_replay_storage_binding_unlocked(binding)
    }

    /// Bind one replay-planning pass to the exact canonical storage image
    /// covered by the startup finality audit.
    ///
    /// `Ok(None)` means no reusable inventory is available; callers must use
    /// the ordinary fully validating finality reader.
    pub(crate) fn begin_v2_startup_finality_verification(
        &self,
    ) -> Result<Option<V2StartupFinalityVerificationSession<'_>>> {
        let prune_guard = self.prune_lock.lock();
        self.ensure_prune_recovery_not_required()?;
        let canonical_chain_guard = self.canonical_chain_lock.lock();
        self.ensure_canonical_storage_not_poisoned()?;
        let (
            boundary,
            canonical_storage,
            finality_directory,
            retained_directory,
            evicted_heights,
            entries,
        ) = {
            let inventory = self.v2_startup_finality_verification_inventory.lock();
            let Some(boundary) = inventory.boundary.clone() else {
                return Ok(None);
            };
            let Some(canonical_storage) = inventory.canonical_storage.clone() else {
                return Ok(None);
            };
            let Some(finality_directory) = inventory.finality_directory.clone() else {
                return Ok(None);
            };
            let Some(retained_directory) = inventory.retained_directory.clone() else {
                return Ok(None);
            };
            (
                boundary,
                canonical_storage,
                finality_directory,
                retained_directory,
                inventory.evicted_heights.clone(),
                inventory.entries.clone(),
            )
        };
        let auxiliary_sidecars = self.capture_v2_startup_replay_auxiliary_sidecars()?;
        let binding = V2StartupReplayStorageBinding {
            boundary: boundary.clone(),
            canonical_storage: canonical_storage.clone(),
            finality_directory: finality_directory.clone(),
            retained_directory: retained_directory.clone(),
            auxiliary_sidecars: auxiliary_sidecars.clone(),
            entries: entries.clone(),
        };
        if self
            .validate_v2_startup_replay_storage_binding_unlocked(&binding)
            .is_err()
        {
            self.finish_v2_startup_finality_verification();
            return Ok(None);
        }
        Ok(Some(V2StartupFinalityVerificationSession {
            kura: self,
            _prune_guard: prune_guard,
            _canonical_chain_guard: canonical_chain_guard,
            boundary,
            canonical_storage,
            finality_directory,
            retained_directory,
            auxiliary_sidecars,
            evicted_heights,
            entries,
        }))
    }

    fn v2_startup_finality_entry_matches(
        &self,
        height: u64,
        finality_identity: &StableSidecarRead,
        retained_identity: &StableSidecarRead,
    ) -> bool {
        self.v2_startup_finality_verification_inventory
            .lock()
            .entries
            .get(&height)
            .is_some_and(|entry| {
                entry.finality.bytes_hash == finality_identity.bytes_hash
                    && Self::stable_sidecar_metadata_unchanged(
                        &entry.finality.metadata,
                        &finality_identity.metadata,
                    )
                    && entry.retained_block.bytes_hash == retained_identity.bytes_hash
                    && Self::stable_sidecar_metadata_unchanged(
                        &entry.retained_block.metadata,
                        &retained_identity.metadata,
                    )
            })
    }

    fn v2_startup_retained_entry_matches(
        &self,
        height: u64,
        retained_identity: &StableSidecarRead,
    ) -> bool {
        self.v2_startup_finality_verification_inventory
            .lock()
            .entries
            .get(&height)
            .is_some_and(|entry| {
                entry.retained_block.bytes_hash == retained_identity.bytes_hash
                    && Self::stable_sidecar_metadata_unchanged(
                        &entry.retained_block.metadata,
                        &retained_identity.metadata,
                    )
            })
    }

    fn remember_verified_v2_finality_entry(&self, entry: VerifiedV2FinalityCacheEntry) {
        let mut cache = self.v2_finality_verification_cache.lock();
        cache.retain(|cached| cached.height != entry.height);
        while cache.len() >= V2_FINALITY_VERIFICATION_CACHE_CAPACITY {
            cache.pop_front();
        }
        cache.push_back(entry);
    }

    fn remember_verified_v2_finality(
        &self,
        height: u64,
        artifact_hash: HashOf<V2FinalityArtifact>,
        bytes_hash: Hash,
        metadata: StableSidecarMetadata,
    ) {
        self.remember_verified_v2_finality_entry(VerifiedV2FinalityCacheEntry {
            height,
            artifact_hash,
            bytes_hash,
            metadata,
        });
    }

    fn verify_v2_finality_crypto(&self, artifact: &V2FinalityArtifact) -> Result<()> {
        #[cfg(test)]
        self.v2_finality_crypto_verifications
            .fetch_add(1, Ordering::Relaxed);
        artifact.verify()?;
        Ok(())
    }

    fn verify_v2_finality_artifact_uncached_at(
        &self,
        path: &Path,
        directory: &Path,
        artifact: &V2FinalityArtifact,
        read_identity: &StableSidecarRead,
    ) -> Result<VerifiedV2FinalityCacheEntry> {
        let current_metadata =
            self.regular_sidecar_metadata(path, directory)?
                .ok_or_else(|| {
                    Error::IO(
                        std::io::Error::new(
                            ErrorKind::NotFound,
                            "v2 finality sidecar disappeared before verification",
                        ),
                        path.to_path_buf(),
                    )
                })?;
        if !Self::stable_sidecar_metadata_unchanged(&read_identity.metadata, &current_metadata) {
            return Err(Error::IO(
                std::io::Error::new(
                    ErrorKind::InvalidData,
                    "v2 finality sidecar changed between decoding and verification",
                ),
                path.to_path_buf(),
            ));
        }

        let artifact_hash = HashOf::new(artifact);
        self.verify_v2_finality_crypto(artifact)?;
        let after = self
            .regular_sidecar_metadata(path, directory)?
            .ok_or_else(|| {
                Error::IO(
                    std::io::Error::new(
                        ErrorKind::NotFound,
                        "v2 finality sidecar disappeared after verification",
                    ),
                    path.to_path_buf(),
                )
            })?;
        if !Self::stable_sidecar_metadata_unchanged(&current_metadata, &after) {
            return Err(Error::IO(
                std::io::Error::new(
                    ErrorKind::InvalidData,
                    "v2 finality sidecar changed during cryptographic verification",
                ),
                path.to_path_buf(),
            ));
        }
        Ok(VerifiedV2FinalityCacheEntry {
            height: artifact.height,
            artifact_hash,
            bytes_hash: read_identity.bytes_hash,
            metadata: after,
        })
    }

    fn verify_v2_finality_artifact_at(
        &self,
        path: &Path,
        directory: &Path,
        artifact: &V2FinalityArtifact,
        read_identity: &StableSidecarRead,
    ) -> Result<()> {
        let current_metadata =
            self.regular_sidecar_metadata(path, directory)?
                .ok_or_else(|| {
                    Error::IO(
                        std::io::Error::new(
                            ErrorKind::NotFound,
                            "v2 finality sidecar disappeared before verification",
                        ),
                        path.to_path_buf(),
                    )
                })?;
        if !Self::stable_sidecar_metadata_unchanged(&read_identity.metadata, &current_metadata) {
            return Err(Error::IO(
                std::io::Error::new(
                    ErrorKind::InvalidData,
                    "v2 finality sidecar changed between decoding and verification",
                ),
                path.to_path_buf(),
            ));
        }
        let artifact_hash = HashOf::new(artifact);
        if self.v2_finality_cache_hit(
            artifact.height,
            artifact_hash,
            read_identity.bytes_hash,
            &current_metadata,
        ) {
            return Ok(());
        }
        if self.v2_startup_finality_verification_hit(
            artifact.height,
            artifact_hash,
            read_identity.bytes_hash,
            &current_metadata,
        ) {
            self.remember_verified_v2_finality(
                artifact.height,
                artifact_hash,
                read_identity.bytes_hash,
                current_metadata,
            );
            return Ok(());
        }

        let entry =
            self.verify_v2_finality_artifact_uncached_at(path, directory, artifact, read_identity)?;
        self.remember_verified_v2_finality_entry(entry);
        Ok(())
    }

    fn cache_newly_verified_v2_finality(
        &self,
        path: &Path,
        directory: &Path,
        record: &KuraV2FinalityRecord,
    ) -> Result<()> {
        let snapshot = self
            .read_regular_sidecar_snapshot(path, directory, MAX_KURA_V2_FINALITY_RECORD_BYTES)?
            .ok_or_else(|| {
                Error::IO(
                    std::io::Error::new(
                        ErrorKind::NotFound,
                        "new v2 finality sidecar is missing after durable rename",
                    ),
                    path.to_path_buf(),
                )
            })?;
        let expected_bytes = record.encode();
        let bytes_hash = Hash::new(&expected_bytes);
        if snapshot.bytes != expected_bytes || snapshot.bytes_hash != bytes_hash {
            return Err(Error::IO(
                std::io::Error::new(
                    ErrorKind::InvalidData,
                    "new v2 finality sidecar bytes changed after durable rename",
                ),
                path.to_path_buf(),
            ));
        }
        self.remember_verified_v2_finality(
            record.artifact.height,
            HashOf::new(&record.artifact),
            bytes_hash,
            snapshot.metadata,
        );
        Ok(())
    }

    /// Return the chain-scoped root for consensus-v2 journals and transport stores.
    ///
    /// The directory is rooted directly below the immutable Kura store root, not
    /// below the relabelable primary-lane block directory. Live consensus stores
    /// therefore keep a stable pathname while a lane alias changes. A configured
    /// chain still never shares a safety WAL or body store with another Kura
    /// instance. Callers create and synchronise their own children; Kura
    /// deliberately does not create this path as a side effect of lookup.
    pub(crate) fn sumeragi_v2_storage_root(&self) -> PathBuf {
        self.store_root.join("sumeragi_v2")
    }

    fn canonical_header_for_v2_finality(
        &self,
        block_height: NonZeroUsize,
        canonical_hash: HashOf<BlockHeader>,
        retained_header: Option<BlockHeader>,
    ) -> Result<BlockHeader> {
        let height = u64::try_from(block_height.get())?;
        let body_header = self.get_block(block_height).map(|block| block.header());
        if let Some(header) = body_header {
            let actual_hash = header.hash();
            if header.height().get() != height || actual_hash != canonical_hash {
                return Err(Error::BlockHeightConflict {
                    height,
                    expected: canonical_hash,
                    actual: actual_hash,
                });
            }
        }
        if let (Some(body), Some(retained)) = (body_header, retained_header)
            && body != retained
        {
            return Err(Error::ConflictingRetainedBlockRecord { height });
        }
        body_header
            .or(retained_header)
            .ok_or(Error::V2FinalityCanonicalHeaderUnavailable { height })
    }

    /// Persist a cryptographically valid v2 finality artifact for an already durable block.
    ///
    /// The returned [`KuraV2CommitReceipt`] is created only after the artifact
    /// contents, canonical header, separately retained complete-block wire
    /// hash, atomic rename, artifact directory, and a newly created artifact
    /// directory entry have been synchronously persisted.
    ///
    /// # Errors
    ///
    /// Returns an error if the artifact is malformed, its height or block hash
    /// or signed payload hash differs from Kura's canonical durable block, or
    /// persistence fails.
    pub fn store_v2_finality_artifact(
        &self,
        artifact: &V2FinalityArtifact,
    ) -> Result<KuraV2CommitReceipt> {
        let _prune_guard = self.prune_lock.lock();
        self.ensure_prune_recovery_not_required()?;
        self.ensure_canonical_storage_not_poisoned()?;
        artifact.validate()?;
        let height = artifact.height;
        let block_hash = artifact.block_hash;
        let artifact_bytes = artifact.encode();
        if artifact_bytes.len() > MAX_V2_FINALITY_ARTIFACT_BYTES {
            return Err(Error::V2FinalityArtifactTooLarge {
                actual: artifact_bytes.len(),
                max: MAX_V2_FINALITY_ARTIFACT_BYTES,
            });
        }

        // Finality association and destructive canonical-chain operations share
        // one serialization lock beneath the prune gate. Appends cannot change
        // an existing height, so the block-store writer lock is deliberately not
        // retained across BLS work or sidecar I/O.
        let _canonical_chain_guard = self.canonical_chain_lock.lock();
        // `canonical_chain_lock` excludes live canonical publication. Any
        // ambiguous publication has already latched canonical poison in the
        // writer, while startup resolves durable stages before constructing
        // this Kura. Finality therefore needs the ordinary mutation
        // authorization check, not `block_store_write_lock`; waiting for that
        // lock here would invert a block-data owner and deadlock finality.
        self.durable_mutation_authorized()?;
        let block_height = NonZeroUsize::new(usize::try_from(height)?)
            .ok_or(Error::V2FinalityCanonicalHeaderUnavailable { height })?;
        let blocks_dir = self.active_blocks_dir.lock().clone();
        let dir = Self::v2_finality_artifact_dir_for(&blocks_dir);
        let path = Self::v2_finality_artifact_path_for(&blocks_dir, height);
        self.ensure_durable_block_at_height(height, block_hash)?;
        let canonical_hash = self
            .get_durable_block_hash(block_height)
            .ok_or(Error::V2FinalityCanonicalHeaderUnavailable { height })?;
        let (retained_header, prepared_retained_record) =
            match self.retained_block_record_at(&blocks_dir, height, canonical_hash)? {
                Some((header, proposal_wire_hash, executed_block_wire_hash, _)) => {
                    Self::validate_v2_finality_wire_bindings(
                        height,
                        artifact,
                        proposal_wire_hash,
                        executed_block_wire_hash,
                    )?;
                    (header, None)
                }
                None => {
                    let canonical_block = self
                        .get_block(block_height)
                        .ok_or(Error::V2FinalityCanonicalHeaderUnavailable { height })?;
                    let header = canonical_block.header();
                    if header.hash() != canonical_hash {
                        return Err(Error::BlockHeightConflict {
                            height,
                            expected: canonical_hash,
                            actual: header.hash(),
                        });
                    }
                    let prepared = Self::prepare_retained_block_record(
                        &blocks_dir,
                        canonical_hash,
                        canonical_block.as_ref(),
                    )?;
                    if prepared.block_header != header {
                        return Err(Error::ConflictingRetainedBlockRecord { height });
                    }
                    Self::validate_v2_finality_wire_bindings(
                        height,
                        artifact,
                        prepared.proposal_wire_hash,
                        prepared.executed_block_wire_hash,
                    )?;
                    (header, Some(prepared))
                }
            };
        let canonical_header = self.canonical_header_for_v2_finality(
            block_height,
            canonical_hash,
            Some(retained_header),
        )?;
        artifact.validate_for_header(&canonical_header)?;

        if let Some((existing, read_identity)) = self.decode_v2_finality_record_at(&path, &dir)? {
            Self::validate_v2_finality_record_at(&path, height, canonical_hash, &existing)?;
            if retained_header != existing.block_header {
                return Err(Error::ConflictingRetainedBlockRecord { height });
            }
            if existing.artifact != *artifact {
                return Err(Error::ConflictingV2FinalityArtifact { height });
            }
            self.verify_v2_finality_artifact_at(&path, &dir, &existing.artifact, &read_identity)?;
            if let Some(prepared) = prepared_retained_record.as_ref() {
                self.persist_prepared_retained_block_record(&blocks_dir, canonical_hash, prepared)?;
            }
            return Ok(v2_commit_receipt(&existing.artifact));
        }

        let record = KuraV2FinalityRecord::new(canonical_header, artifact.clone());
        Self::validate_v2_finality_record_at(&path, height, canonical_hash, &record)?;
        let bytes = record.encode();
        if bytes.len() > MAX_KURA_V2_FINALITY_RECORD_BYTES {
            return Err(Error::V2FinalityRecordTooLarge {
                actual: bytes.len(),
                max: MAX_KURA_V2_FINALITY_RECORD_BYTES,
            });
        }
        // A structurally coherent but forged certificate must not create even
        // ancillary retained evidence. Complete all cryptographic validation
        // before the first durable mutation in the new-artifact path.
        self.verify_v2_finality_crypto(artifact)?;
        if self.canonical_sidecar_directory(&dir)?.is_none() {
            create_dir_all_with_context(&dir)?;
            self.canonical_sidecar_directory(&dir)?.ok_or_else(|| {
                Error::IO(
                    std::io::Error::new(
                        ErrorKind::NotFound,
                        "Kura v2 finality directory disappeared after creation",
                    ),
                    dir.clone(),
                )
            })?;
        }
        if let Some(parent) = dir.parent() {
            sync_dir(parent).map_err(|error| Error::IO(error, parent.to_path_buf()))?;
        }
        if let Some(prepared) = prepared_retained_record.as_ref() {
            self.persist_prepared_retained_block_record(&blocks_dir, canonical_hash, prepared)?;
        }
        #[cfg(test)]
        if self
            .fail_next_v2_finality_write
            .swap(false, Ordering::Relaxed)
        {
            return Err(Error::IO(
                std::io::Error::other("Kura Sumeragi v2 finality injected failure"),
                PathBuf::from("v2_finality_test_fail"),
            ));
        }

        let accounting_mutation = self.begin_total_disk_usage_mutation();
        if !self.write_atomic_synced_noclobber(&path, &bytes)? {
            let Some((existing, read_identity)) = self.decode_v2_finality_record_at(&path, &dir)?
            else {
                return Err(Error::ConflictingV2FinalityArtifact { height });
            };
            Self::validate_v2_finality_record_at(&path, height, canonical_hash, &existing)?;
            if existing.artifact != *artifact {
                return Err(Error::ConflictingV2FinalityArtifact { height });
            }
            self.verify_v2_finality_artifact_at(&path, &dir, &existing.artifact, &read_identity)?;
            return Ok(v2_commit_receipt(&existing.artifact));
        }
        self.add_total_disk_usage_bytes(u64::try_from(bytes.len())?);
        self.cache_newly_verified_v2_finality(&path, &dir, &record)?;
        accounting_mutation.finish();
        Ok(v2_commit_receipt(artifact))
    }

    fn decode_v2_finality_record_at(
        &self,
        path: &Path,
        directory: &Path,
    ) -> Result<Option<(KuraV2FinalityRecord, StableSidecarRead)>> {
        let Some(snapshot) =
            self.read_regular_sidecar_snapshot(path, directory, MAX_KURA_V2_FINALITY_RECORD_BYTES)?
        else {
            return Ok(None);
        };
        let mut cursor = snapshot.bytes.as_slice();
        let record = KuraV2FinalityRecord::decode_all(&mut cursor).map_err(Error::NoritoFrame)?;
        if record.encode() != snapshot.bytes {
            return Err(Error::IO(
                std::io::Error::new(
                    ErrorKind::InvalidData,
                    "Kura v2 finality record is not canonically encoded",
                ),
                path.to_path_buf(),
            ));
        }
        Ok(Some((record, snapshot)))
    }

    fn validate_v2_finality_record_at(
        path: &Path,
        expected_height: u64,
        canonical_hash: HashOf<BlockHeader>,
        record: &KuraV2FinalityRecord,
    ) -> Result<()> {
        if record.format_version != KURA_V2_FINALITY_RECORD_VERSION {
            return Err(Error::IO(
                std::io::Error::new(
                    ErrorKind::InvalidData,
                    "unsupported Kura v2 finality record version",
                ),
                path.to_path_buf(),
            ));
        }
        if record.artifact.height != expected_height {
            return Err(Error::IO(
                std::io::Error::new(
                    ErrorKind::InvalidData,
                    "v2 finality artifact height does not match its canonical file name",
                ),
                path.to_path_buf(),
            ));
        }
        let artifact_len = record.artifact.encode().len();
        if artifact_len > MAX_V2_FINALITY_ARTIFACT_BYTES {
            return Err(Error::V2FinalityArtifactTooLarge {
                actual: artifact_len,
                max: MAX_V2_FINALITY_ARTIFACT_BYTES,
            });
        }
        let recorded_hash = record.block_header.hash();
        if recorded_hash != canonical_hash {
            return Err(Error::BlockHeightConflict {
                height: expected_height,
                expected: canonical_hash,
                actual: recorded_hash,
            });
        }
        record
            .artifact
            .validate_for_header(&record.block_header)
            .map_err(Error::from)
    }

    /// Read and cryptographically validate a v2 finality artifact for a durable block.
    ///
    /// A missing final path returns `Ok(None)`. Incomplete temporary files left
    /// before the atomic rename are ignored. A malformed final path or an
    /// artifact that does not match Kura's canonical header and separately
    /// retained complete-block wire hash fails closed.
    ///
    /// # Errors
    ///
    /// Returns an error if decoding, header association, proof-of-possession,
    /// or CommitQC verification fails, the height is zero or absent from the
    /// durable chain, or the canonical header/wire association differs.
    pub fn v2_finality_artifact(&self, height: u64) -> Result<Option<V2FinalityArtifact>> {
        Ok(self
            .v2_finality_artifact_with_header(height)?
            .map(|(_, artifact)| artifact))
    }

    /// Read a verified finality artifact together with its retained canonical header.
    ///
    /// The signed payload is also matched to the separately retained canonical
    /// `SignedBlock` wire hash. This remains available after the block body is
    /// evicted to remote-only storage.
    ///
    /// # Errors
    ///
    /// Returns an error if the durable record, canonical header/wire binding,
    /// artifact structure, or finality cryptography is invalid.
    pub(crate) fn v2_finality_artifact_with_header(
        &self,
        height: u64,
    ) -> Result<Option<(BlockHeader, V2FinalityArtifact)>> {
        Ok(self
            .v2_finality_artifact_with_archive(height)?
            .map(|(header, artifact, _)| (header, artifact)))
    }

    /// Read verified finality and the root-authenticated SCCP archive in one bounded pass.
    ///
    /// Rootless finalized blocks return an empty archive. Combining these reads prevents
    /// proof-serving callers from decoding and validating the retained record twice. The
    /// finality subject must equal that record's canonical complete-block wire hash.
    ///
    /// # Errors
    ///
    /// Returns an error if the finality record, retained block record, canonical header/wire
    /// binding, SCCP archive, or finality cryptography is invalid.
    pub(crate) fn v2_finality_artifact_with_archive(
        &self,
        height: u64,
    ) -> Result<
        Option<(
            BlockHeader,
            V2FinalityArtifact,
            Vec<crate::bridge::ValidatedSccpOutboundMessageProjectionV1>,
        )>,
    > {
        let _prune_guard = self.prune_lock.lock();
        self.v2_finality_artifact_with_archive_under_prune_guard(height)
    }

    /// Inner finality reader for callers that already hold `prune_lock`.
    ///
    /// Keeping the complete canonical-header, retained-wire, and cryptographic
    /// validation here lets multi-artifact publication revalidate finality in
    /// the same prune critical section without recursively locking.
    fn v2_finality_artifact_with_archive_under_prune_guard(
        &self,
        height: u64,
    ) -> Result<
        Option<(
            BlockHeader,
            V2FinalityArtifact,
            Vec<crate::bridge::ValidatedSccpOutboundMessageProjectionV1>,
        )>,
    > {
        self.ensure_prune_recovery_not_required()?;
        self.ensure_canonical_storage_not_poisoned()?;
        let _canonical_chain_guard = self.canonical_chain_lock.lock();
        self.v2_finality_artifact_with_archive_under_prune_and_canonical_guards(height)
    }

    /// Inner finality reader for callers that already hold `prune_lock` and
    /// `canonical_chain_lock`, in that order.
    ///
    /// Geometry retirement and archive validation also hold
    /// `lane_geometry_lock` and `sidecar_lock`. Keeping this reader free of
    /// lock acquisition lets those paths authenticate retained Native AMX
    /// evidence without recursively acquiring the canonical-chain mutex.
    fn v2_finality_artifact_with_archive_under_prune_and_canonical_guards(
        &self,
        height: u64,
    ) -> Result<
        Option<(
            BlockHeader,
            V2FinalityArtifact,
            Vec<crate::bridge::ValidatedSccpOutboundMessageProjectionV1>,
        )>,
    > {
        self.ensure_prune_recovery_not_required()?;
        self.ensure_canonical_storage_not_poisoned()?;
        let blocks_dir = self.active_blocks_dir.lock().clone();
        let directory = Self::v2_finality_artifact_dir_for(&blocks_dir);
        let path = Self::v2_finality_artifact_path_for(&blocks_dir, height);
        let Some((record, read_identity)) = self.decode_v2_finality_record_at(&path, &directory)?
        else {
            return Ok(None);
        };

        let Some(block_height) = NonZeroUsize::new(usize::try_from(height)?) else {
            return Err(Error::NoritoFrame(norito::core::Error::Message(
                "v2 finality artifact height must be non-zero".into(),
            )));
        };
        let block_hash = self.get_durable_block_hash(block_height);
        self.ensure_prune_recovery_not_required()?;
        let Some(block_hash) = block_hash else {
            return Err(Error::BlockHeightGap {
                expected_next_height: u64::try_from(self.exact_durable_blocks_count()?)?
                    .saturating_add(1),
                actual_height: height,
            });
        };
        Self::validate_v2_finality_record_at(&path, height, block_hash, &record)?;
        let (retained_header, proposal_wire_hash, executed_block_wire_hash, archive) = self
            .retained_block_record_at(&blocks_dir, height, block_hash)?
            .ok_or(Error::MissingRetainedBlockRecord { height })?;
        if retained_header != record.block_header {
            return Err(Error::ConflictingRetainedBlockRecord { height });
        }
        Self::validate_v2_finality_wire_bindings(
            height,
            &record.artifact,
            proposal_wire_hash,
            executed_block_wire_hash,
        )?;
        self.verify_v2_finality_artifact_at(&path, &directory, &record.artifact, &read_identity)?;
        Ok(Some((record.block_header, record.artifact, archive)))
    }

    /// Recover a validated durable v2 finality artifact together with the
    /// same non-forgeable receipt minted by the write path.
    ///
    /// Final artifact paths are immutable: an idempotent repeat is accepted,
    /// while a conflicting rewrite is rejected by
    /// [`Self::store_v2_finality_artifact`]. Therefore a successfully read and
    /// canonical-block-checked artifact is sufficient to reconstruct its
    /// receipt during startup replay.
    pub fn v2_finality_artifact_with_receipt(
        &self,
        height: u64,
    ) -> Result<Option<(V2FinalityArtifact, KuraV2CommitReceipt)>> {
        let Some(artifact) = self.v2_finality_artifact(height)? else {
            return Ok(None);
        };
        let receipt = v2_commit_receipt(&artifact);
        Ok(Some((artifact, receipt)))
    }

    /// Recover finality during startup replay while reusing the exact
    /// live-body and BLS validation performed by Kura initialization.
    ///
    /// The session holds prune/canonical mutation guards and binds the full
    /// block journals. Bodyless retained-record validation is used only when
    /// both finality and retained sidecars still match their audited bytes,
    /// path, file, and directory identities. Any mismatch falls back to the
    /// ordinary live-body and cryptographic validation path.
    pub(crate) fn v2_finality_artifact_with_receipt_for_startup(
        &self,
        session: &V2StartupFinalityVerificationSession<'_>,
        height: u64,
    ) -> Result<Option<(V2FinalityArtifact, KuraV2CommitReceipt)>> {
        if !std::ptr::eq(self, session.kura) {
            return Err(Error::NoritoFrame(norito::core::Error::Message(
                "startup finality verification session belongs to another Kura".to_owned(),
            )));
        }
        self.ensure_prune_recovery_not_required()?;
        self.ensure_canonical_storage_not_poisoned()?;
        let canonical_hash = session
            .canonical_hash(height)
            .ok_or(Error::V2FinalityCanonicalHeaderUnavailable { height })?;
        let blocks_dir = self.active_blocks_dir.lock().clone();
        let directory = Self::v2_finality_artifact_dir_for(&blocks_dir);
        let path = Self::v2_finality_artifact_path_for(&blocks_dir, height);
        let Some((record, finality_identity)) =
            self.decode_v2_finality_record_at(&path, &directory)?
        else {
            return Ok(None);
        };
        Self::validate_v2_finality_record_at(&path, height, canonical_hash, &record)?;

        let Some((bodyless_retained, retained_identity)) = self
            .retained_block_record_at_with_identity(&blocks_dir, height, canonical_hash, false)?
        else {
            return Err(Error::MissingRetainedBlockRecord { height });
        };
        let retained = if !session.evicted_heights.contains(&height)
            && self.v2_startup_finality_entry_matches(
                height,
                &finality_identity,
                &retained_identity,
            ) {
            bodyless_retained
        } else {
            self.retained_block_record_at(&blocks_dir, height, canonical_hash)?
                .ok_or(Error::MissingRetainedBlockRecord { height })?
        };
        let (retained_header, proposal_wire_hash, executed_block_wire_hash, _) = retained;
        if retained_header != record.block_header {
            return Err(Error::ConflictingRetainedBlockRecord { height });
        }
        Self::validate_v2_finality_wire_bindings(
            height,
            &record.artifact,
            proposal_wire_hash,
            executed_block_wire_hash,
        )?;
        self.verify_v2_finality_artifact_at(
            &path,
            &directory,
            &record.artifact,
            &finality_identity,
        )?;
        let receipt = v2_commit_receipt(&record.artifact);
        Ok(Some((record.artifact, receipt)))
    }

    fn staged_kagemusha_topup_finality_from_witness(
        height: u64,
        block_hash: HashOf<BlockHeader>,
        witness: &ExecWitness,
        expected: ExecutionCommitment,
    ) -> Result<Option<StagedKagemushaTopUpFinalitySidecar>> {
        let writes = witness
            .writes
            .iter()
            .map(|entry| crate::sumeragi::smt::KvPair::new(entry.key.clone(), entry.value.clone()))
            .collect::<Vec<_>>();
        let commitment = crate::sumeragi::smt::build_kagemusha_topup_block_commitment(&writes)
            .map_err(|error| Error::KagemushaTopUpFinalitySidecar(error.to_owned()))?;
        let Some(commitment) = commitment else {
            if expected.topup_anchor_count != 0 || expected.topup_anchor_root.is_some() {
                return Err(Error::KagemushaTopUpFinalitySidecar(
                    "signed execution commitment advertises top-ups absent from the witness"
                        .to_owned(),
                ));
            }
            return Ok(None);
        };
        if expected.ordinary_writes_root != commitment.ordinary_writes_root
            || expected.topup_anchor_root != Some(commitment.topup_anchor_root)
            || expected.post_state_root != commitment.post_state_root
            || usize::try_from(expected.topup_anchor_count).ok() != Some(commitment.leaves.len())
            || commitment.leaves.len() != commitment.proofs.len()
        {
            return Err(Error::KagemushaTopUpFinalitySidecar(
                "witness-derived top-up subtree differs from the signed execution commitment"
                    .to_owned(),
            ));
        }

        let leaves = commitment
            .leaves
            .iter()
            .zip(&commitment.proofs)
            .map(|(leaf, path)| {
                let operation_id = leaf
                    .key
                    .get(1..)
                    .and_then(|bytes| <[u8; 32]>::try_from(bytes).ok())
                    .ok_or_else(|| {
                        Error::KagemushaTopUpFinalitySidecar(
                            "witness top-up operation id has the wrong width".to_owned(),
                        )
                    })?;
                let anchor_digest = <[u8; 32]>::try_from(leaf.value.as_slice()).map_err(|_| {
                    Error::KagemushaTopUpFinalitySidecar(
                        "witness top-up anchor digest has the wrong width".to_owned(),
                    )
                })?;
                Ok(KagemushaTopUpFinalityLeaf {
                    operation_id,
                    anchor_digest,
                    leaf_index: path.leaf_index,
                    leaf_count: path.leaf_count,
                    siblings: path.siblings.clone(),
                })
            })
            .collect::<Result<Vec<_>>>()?;
        Ok(Some(StagedKagemushaTopUpFinalitySidecar {
            format: KagemushaTopUpFinalitySidecarFormat::Current,
            version: KagemushaTopUpFinalitySidecar::VERSION,
            height,
            block_hash,
            ordinary_writes_root: commitment.ordinary_writes_root,
            topup_anchor_root: commitment.topup_anchor_root,
            post_state_root: commitment.post_state_root,
            leaves,
        }))
    }

    fn validate_staged_kagemusha_topup_finality(
        staged: &StagedKagemushaTopUpFinalitySidecar,
        artifact: &V2FinalityArtifact,
    ) -> Result<()> {
        let commitment = artifact.commit_qc.execution_commitment;
        if staged.format != KagemushaTopUpFinalitySidecarFormat::Current
            || staged.version != KagemushaTopUpFinalitySidecar::VERSION
            || staged.height != artifact.height
            || staged.block_hash != artifact.block_hash
            || staged.ordinary_writes_root != commitment.ordinary_writes_root
            || Some(staged.topup_anchor_root) != commitment.topup_anchor_root
            || staged.post_state_root != commitment.post_state_root
            || usize::try_from(commitment.topup_anchor_count).ok() != Some(staged.leaves.len())
            || staged.leaves.is_empty()
            || staged
                .leaves
                .windows(2)
                .any(|pair| pair[0].operation_id >= pair[1].operation_id)
        {
            return Err(Error::KagemushaTopUpFinalitySidecar(
                "staged top-up sidecar differs from the exact finality artifact".to_owned(),
            ));
        }
        for (index, leaf) in staged.leaves.iter().enumerate() {
            if leaf.operation_id == [0; 32]
                || leaf.anchor_digest == [0; 32]
                || usize::try_from(leaf.leaf_index).ok() != Some(index)
                || usize::try_from(leaf.leaf_count).ok() != Some(staged.leaves.len())
            {
                return Err(Error::KagemushaTopUpFinalitySidecar(
                    "staged top-up leaf identity or position is non-canonical".to_owned(),
                ));
            }
            let mut key = Vec::with_capacity(33);
            key.push(crate::sumeragi::smt::KAGEMUSHA_V4_TOPUP_ANCHOR_WITNESS_KEY_TAG);
            key.extend_from_slice(&leaf.operation_id);
            let pair = crate::sumeragi::smt::KvPair::new(key, leaf.anchor_digest);
            let path = crate::sumeragi::smt::KagemushaTopUpMerkleProof {
                leaf_index: leaf.leaf_index,
                leaf_count: leaf.leaf_count,
                siblings: leaf.siblings.clone(),
            };
            if !crate::sumeragi::smt::verify_kagemusha_topup_write_inclusion(
                &pair,
                &path,
                staged.ordinary_writes_root,
                staged.post_state_root,
            ) {
                return Err(Error::KagemushaTopUpFinalitySidecar(
                    "staged top-up Merkle path does not match the signed post-state root"
                        .to_owned(),
                ));
            }
        }
        Ok(())
    }

    fn validate_kagemusha_topup_finality_sidecar(
        sidecar: &KagemushaTopUpFinalitySidecar,
        artifact: &V2FinalityArtifact,
    ) -> Result<()> {
        let staged = StagedKagemushaTopUpFinalitySidecar {
            format: sidecar.format,
            version: sidecar.version,
            height: sidecar.height,
            block_hash: sidecar.block_hash,
            ordinary_writes_root: sidecar.ordinary_writes_root,
            topup_anchor_root: sidecar.topup_anchor_root,
            post_state_root: sidecar.post_state_root,
            leaves: sidecar.leaves.clone(),
        };
        Self::validate_staged_kagemusha_topup_finality(&staged, artifact)?;
        if sidecar.finality_artifact_hash != HashOf::new(artifact) {
            return Err(Error::KagemushaTopUpFinalitySidecar(
                "top-up sidecar is bound to another finality artifact".to_owned(),
            ));
        }
        Ok(())
    }

    fn decode_staged_kagemusha_topup_finality(
        &self,
        path: &Path,
    ) -> Result<Option<(StagedKagemushaTopUpFinalitySidecar, StableSidecarRead)>> {
        let directory = self.kagemusha_topup_finality_staging_dir();
        let Some(snapshot) = self.read_regular_sidecar_snapshot(
            path,
            &directory,
            MAX_KAGEMUSHA_TOPUP_FINALITY_SIDECAR_BYTES,
        )?
        else {
            return Ok(None);
        };
        let mut cursor = snapshot.bytes.as_slice();
        let sidecar = StagedKagemushaTopUpFinalitySidecar::decode_all(&mut cursor)
            .map_err(Error::NoritoFrame)?;
        if sidecar.encode() != snapshot.bytes {
            return Err(Error::IO(
                std::io::Error::new(
                    ErrorKind::InvalidData,
                    "staged top-up sidecar is not the canonical Norito encoding",
                ),
                path.to_path_buf(),
            ));
        }
        Ok(Some((sidecar, snapshot)))
    }

    fn decode_kagemusha_topup_finality_sidecar(
        &self,
        path: &Path,
    ) -> Result<Option<(KagemushaTopUpFinalitySidecar, StableSidecarRead)>> {
        let directory = self.kagemusha_topup_finality_sidecar_dir();
        let Some(snapshot) = self.read_regular_sidecar_snapshot(
            path,
            &directory,
            MAX_KAGEMUSHA_TOPUP_FINALITY_SIDECAR_BYTES,
        )?
        else {
            return Ok(None);
        };
        let mut cursor = snapshot.bytes.as_slice();
        let sidecar =
            KagemushaTopUpFinalitySidecar::decode_all(&mut cursor).map_err(Error::NoritoFrame)?;
        if sidecar.encode() != snapshot.bytes {
            return Err(Error::IO(
                std::io::Error::new(
                    ErrorKind::InvalidData,
                    "final top-up sidecar is not the canonical Norito encoding",
                ),
                path.to_path_buf(),
            ));
        }
        Ok(Some((sidecar, snapshot)))
    }

    fn validate_staged_kagemusha_active_receiver_finality(
        staged: &StagedKagemushaActiveReceiverFinalitySidecarV1,
        artifact: &V2FinalityArtifact,
    ) -> Result<()> {
        let commitment = artifact.commit_qc.execution_commitment;
        let snapshot = staged
            .witness_proof
            .commitment()
            .map_err(|error| Error::KagemushaActiveReceiverFinalitySidecar(error.to_owned()))?;
        let validation_fee_snapshot = staged
            .validation_fee_policy_witness
            .commitment()
            .map_err(|error| Error::KagemushaActiveReceiverFinalitySidecar(error.to_owned()))?;
        if staged.version != KagemushaActiveReceiverFinalitySidecarV1::VERSION
            || staged.height != artifact.height
            || staged.block_hash != artifact.block_hash
            || staged.ordinary_writes_root != commitment.ordinary_writes_root
            || staged.post_state_root != commitment.post_state_root
            || snapshot.evaluated_height != staged.height
            || !staged.witness_proof.verify(commitment.ordinary_writes_root)
            || validation_fee_snapshot.evaluated_height != staged.height
            || !staged
                .validation_fee_policy_witness
                .verify(commitment.ordinary_writes_root)
        {
            return Err(Error::KagemushaActiveReceiverFinalitySidecar(
                "active-receiver witness stage differs from the exact finality artifact".to_owned(),
            ));
        }
        commitment.validate().map_err(|error| {
            Error::KagemushaActiveReceiverFinalitySidecar(format!(
                "active-receiver finality execution commitment is invalid: {error}"
            ))
        })?;
        Ok(())
    }

    fn validate_kagemusha_active_receiver_finality_sidecar(
        sidecar: &KagemushaActiveReceiverFinalitySidecarV1,
        artifact: &V2FinalityArtifact,
    ) -> Result<()> {
        Self::validate_staged_kagemusha_active_receiver_finality(
            &StagedKagemushaActiveReceiverFinalitySidecarV1 {
                version: sidecar.version,
                height: sidecar.height,
                block_hash: sidecar.block_hash,
                ordinary_writes_root: sidecar.ordinary_writes_root,
                post_state_root: sidecar.post_state_root,
                witness_proof: sidecar.witness_proof.clone(),
                validation_fee_policy_witness: sidecar.validation_fee_policy_witness.clone(),
            },
            artifact,
        )?;
        if sidecar.finality_artifact_hash != HashOf::new(artifact) {
            return Err(Error::KagemushaActiveReceiverFinalitySidecar(
                "active-receiver sidecar is bound to another finality artifact".to_owned(),
            ));
        }
        Ok(())
    }

    fn decode_staged_kagemusha_active_receiver_finality(
        &self,
        path: &Path,
    ) -> Result<
        Option<(
            StagedKagemushaActiveReceiverFinalitySidecarV1,
            StableSidecarRead,
        )>,
    > {
        let directory = self.kagemusha_active_receiver_staging_dir();
        let Some(snapshot) = self.read_regular_sidecar_snapshot(
            path,
            &directory,
            MAX_KAGEMUSHA_ACTIVE_RECEIVER_SIDECAR_BYTES,
        )?
        else {
            return Ok(None);
        };
        let mut cursor = snapshot.bytes.as_slice();
        let sidecar = StagedKagemushaActiveReceiverFinalitySidecarV1::decode_all(&mut cursor)
            .map_err(Error::NoritoFrame)?;
        if sidecar.encode() != snapshot.bytes {
            return Err(Error::IO(
                std::io::Error::new(
                    ErrorKind::InvalidData,
                    "staged active-receiver sidecar is not canonical Norito",
                ),
                path.to_path_buf(),
            ));
        }
        Ok(Some((sidecar, snapshot)))
    }

    fn decode_kagemusha_active_receiver_finality_sidecar(
        &self,
        path: &Path,
    ) -> Result<Option<(KagemushaActiveReceiverFinalitySidecarV1, StableSidecarRead)>> {
        let directory = self.kagemusha_active_receiver_sidecar_dir();
        let Some(snapshot) = self.read_regular_sidecar_snapshot(
            path,
            &directory,
            MAX_KAGEMUSHA_ACTIVE_RECEIVER_SIDECAR_BYTES,
        )?
        else {
            return Ok(None);
        };
        let mut cursor = snapshot.bytes.as_slice();
        let sidecar = KagemushaActiveReceiverFinalitySidecarV1::decode_all(&mut cursor)
            .map_err(Error::NoritoFrame)?;
        if sidecar.encode() != snapshot.bytes {
            return Err(Error::IO(
                std::io::Error::new(
                    ErrorKind::InvalidData,
                    "final active-receiver sidecar is not canonical Norito",
                ),
                path.to_path_buf(),
            ));
        }
        Ok(Some((sidecar, snapshot)))
    }

    fn stage_kagemusha_active_receiver_finality_sidecar(
        &self,
        height: u64,
        block_hash: HashOf<BlockHeader>,
        witness: &ExecWitness,
        expected: ExecutionCommitment,
    ) -> Result<()> {
        self.durable_mutation_authorized()?;
        let (witness_proof, ordinary_writes_root) =
            crate::receiver_snapshot::active_receiver_witness_proof_v1(witness)
                .map_err(Error::KagemushaActiveReceiverFinalitySidecar)?;
        let (validation_fee_policy_witness, validation_fee_root) =
            crate::receiver_snapshot::validation_fee_policy_witness_proof_v1(witness)
                .map_err(Error::KagemushaActiveReceiverFinalitySidecar)?;
        if ordinary_writes_root != expected.ordinary_writes_root
            || validation_fee_root != ordinary_writes_root
            || !witness_proof.verify(expected.ordinary_writes_root)
            || !validation_fee_policy_witness.verify(expected.ordinary_writes_root)
        {
            return Err(Error::KagemushaActiveReceiverFinalitySidecar(
                "witness-derived active-receiver proof differs from the signed ordinary-write root"
                    .to_owned(),
            ));
        }
        let snapshot = witness_proof
            .commitment()
            .map_err(|error| Error::KagemushaActiveReceiverFinalitySidecar(error.to_owned()))?;
        if snapshot.evaluated_height != height {
            return Err(Error::KagemushaActiveReceiverFinalitySidecar(
                "active-receiver snapshot height differs from its block".to_owned(),
            ));
        }
        let validation_fee_snapshot = validation_fee_policy_witness
            .commitment()
            .map_err(|error| Error::KagemushaActiveReceiverFinalitySidecar(error.to_owned()))?;
        if validation_fee_snapshot.evaluated_height != height {
            return Err(Error::KagemushaActiveReceiverFinalitySidecar(
                "validation-fee snapshot height differs from its block".to_owned(),
            ));
        }
        let staged = StagedKagemushaActiveReceiverFinalitySidecarV1 {
            version: KagemushaActiveReceiverFinalitySidecarV1::VERSION,
            height,
            block_hash,
            ordinary_writes_root,
            post_state_root: expected.post_state_root,
            witness_proof,
            validation_fee_policy_witness,
        };
        let bytes = staged.encode();
        if bytes.len() > MAX_KAGEMUSHA_ACTIVE_RECEIVER_SIDECAR_BYTES {
            return Err(Error::KagemushaActiveReceiverFinalitySidecarTooLarge {
                actual: bytes.len(),
                max: MAX_KAGEMUSHA_ACTIVE_RECEIVER_SIDECAR_BYTES,
            });
        }
        let _guard = self.sidecar_lock.lock();
        let directory = self.kagemusha_active_receiver_staging_dir();
        create_dir_all_with_context(&directory)?;
        if let Some(parent) = directory.parent() {
            sync_dir(parent).map_err(|error| Error::IO(error, parent.to_path_buf()))?;
        }
        let path = self.kagemusha_active_receiver_staging_path(height);
        if let Some((existing, identity)) =
            self.decode_staged_kagemusha_active_receiver_finality(&path)?
        {
            if existing == staged
                && identity.bytes == bytes
                && identity.bytes_hash == Hash::new(&bytes)
            {
                return Ok(());
            }
            return Err(Error::KagemushaActiveReceiverFinalitySidecar(
                "conflicting staged active-receiver sidecar at one height".to_owned(),
            ));
        }
        if !self.write_atomic_synced_noclobber(&path, &bytes)? {
            let Some((existing, _)) =
                self.decode_staged_kagemusha_active_receiver_finality(&path)?
            else {
                return Err(Error::KagemushaActiveReceiverFinalitySidecar(
                    "staged active-receiver sidecar disappeared during publication".to_owned(),
                ));
            };
            if existing != staged {
                return Err(Error::KagemushaActiveReceiverFinalitySidecar(
                    "no-clobber race published a conflicting active-receiver stage".to_owned(),
                ));
            }
        }
        let Some((persisted, identity)) =
            self.decode_staged_kagemusha_active_receiver_finality(&path)?
        else {
            return Err(Error::KagemushaActiveReceiverFinalitySidecar(
                "staged active-receiver sidecar disappeared after publication".to_owned(),
            ));
        };
        if persisted != staged
            || identity.bytes != bytes
            || identity.bytes_hash != Hash::new(&bytes)
        {
            return Err(Error::KagemushaActiveReceiverFinalitySidecar(
                "staged active-receiver sidecar changed during readback".to_owned(),
            ));
        }
        Ok(())
    }

    fn remove_exact_staged_kagemusha_active_receiver_finality(
        &self,
        path: &Path,
        read_identity: &StableSidecarRead,
    ) -> Result<()> {
        let directory = self.kagemusha_active_receiver_staging_dir();
        let Some(current) = self.regular_sidecar_metadata(path, &directory)? else {
            return Ok(());
        };
        if !Self::stable_sidecar_metadata_unchanged(&read_identity.metadata, &current) {
            return Err(Error::KagemushaActiveReceiverFinalitySidecar(
                "staged active-receiver sidecar changed before cleanup".to_owned(),
            ));
        }
        std::fs::remove_file(path).map_err(|error| Error::IO(error, path.to_path_buf()))?;
        sync_dir(&directory).map_err(|error| Error::IO(error, directory))?;
        Ok(())
    }

    fn promote_kagemusha_active_receiver_finality_sidecar(
        &self,
        artifact: &V2FinalityArtifact,
        receipt: &KuraV2CommitReceipt,
    ) -> Result<()> {
        self.durable_mutation_authorized()?;
        if receipt.height != artifact.height
            || receipt.block_hash != artifact.block_hash
            || receipt.context_id != artifact.context_id()
            || receipt.subject != artifact.subject
            || receipt.certificate != artifact.commit_qc.as_ref()
            || receipt.artifact_hash != HashOf::new(artifact)
        {
            return Err(Error::KagemushaActiveReceiverFinalitySidecar(
                "finality receipt does not identify the active-receiver artifact".to_owned(),
            ));
        }
        let durable = self.v2_finality_artifact(artifact.height)?.ok_or_else(|| {
            Error::KagemushaActiveReceiverFinalitySidecar(
                "active-receiver promotion has no durable finality artifact".to_owned(),
            )
        })?;
        if durable != *artifact || HashOf::new(&durable) != receipt.artifact_hash {
            return Err(Error::KagemushaActiveReceiverFinalitySidecar(
                "durable finality differs from active-receiver promotion receipt".to_owned(),
            ));
        }

        let _guard = self.sidecar_lock.lock();
        let final_path = self.kagemusha_active_receiver_sidecar_path(artifact.height);
        let staged_path = self.kagemusha_active_receiver_staging_path(artifact.height);
        if let Some((existing, _)) =
            self.decode_kagemusha_active_receiver_finality_sidecar(&final_path)?
        {
            Self::validate_kagemusha_active_receiver_finality_sidecar(&existing, artifact)?;
            if let Some((staged, identity)) =
                self.decode_staged_kagemusha_active_receiver_finality(&staged_path)?
            {
                Self::validate_staged_kagemusha_active_receiver_finality(&staged, artifact)?;
                self.remove_exact_staged_kagemusha_active_receiver_finality(
                    &staged_path,
                    &identity,
                )?;
            }
            return Ok(());
        }
        let Some((staged, staged_identity)) =
            self.decode_staged_kagemusha_active_receiver_finality(&staged_path)?
        else {
            return Err(Error::KagemushaActiveReceiverFinalitySidecar(
                "finality is durable but its active-receiver witness stage is missing".to_owned(),
            ));
        };
        Self::validate_staged_kagemusha_active_receiver_finality(&staged, artifact)?;
        let final_sidecar = KagemushaActiveReceiverFinalitySidecarV1 {
            version: staged.version,
            height: staged.height,
            block_hash: staged.block_hash,
            ordinary_writes_root: staged.ordinary_writes_root,
            post_state_root: staged.post_state_root,
            finality_artifact_hash: receipt.artifact_hash,
            witness_proof: staged.witness_proof,
            validation_fee_policy_witness: staged.validation_fee_policy_witness,
        };
        Self::validate_kagemusha_active_receiver_finality_sidecar(&final_sidecar, artifact)?;
        let bytes = final_sidecar.encode();
        if bytes.len() > MAX_KAGEMUSHA_ACTIVE_RECEIVER_SIDECAR_BYTES {
            return Err(Error::KagemushaActiveReceiverFinalitySidecarTooLarge {
                actual: bytes.len(),
                max: MAX_KAGEMUSHA_ACTIVE_RECEIVER_SIDECAR_BYTES,
            });
        }
        let directory = self.kagemusha_active_receiver_sidecar_dir();
        create_dir_all_with_context(&directory)?;
        if let Some(parent) = directory.parent() {
            sync_dir(parent).map_err(|error| Error::IO(error, parent.to_path_buf()))?;
        }
        if !self.write_atomic_synced_noclobber(&final_path, &bytes)? {
            let Some((existing, _)) =
                self.decode_kagemusha_active_receiver_finality_sidecar(&final_path)?
            else {
                return Err(Error::KagemushaActiveReceiverFinalitySidecar(
                    "final active-receiver sidecar disappeared during publication".to_owned(),
                ));
            };
            if existing != final_sidecar {
                return Err(Error::KagemushaActiveReceiverFinalitySidecar(
                    "no-clobber race published a conflicting active-receiver sidecar".to_owned(),
                ));
            }
        }
        let Some((persisted, identity)) =
            self.decode_kagemusha_active_receiver_finality_sidecar(&final_path)?
        else {
            return Err(Error::KagemushaActiveReceiverFinalitySidecar(
                "final active-receiver sidecar disappeared after publication".to_owned(),
            ));
        };
        if persisted != final_sidecar
            || identity.bytes != bytes
            || identity.bytes_hash != Hash::new(&bytes)
        {
            return Err(Error::KagemushaActiveReceiverFinalitySidecar(
                "final active-receiver sidecar changed during readback".to_owned(),
            ));
        }
        self.remove_exact_staged_kagemusha_active_receiver_finality(
            &staged_path,
            &staged_identity,
        )?;
        Ok(())
    }

    /// Return the finalized fixed-key receiver snapshot witness proof for one block.
    pub fn kagemusha_active_receiver_witness_proof_v1(
        &self,
        height: u64,
    ) -> Result<Option<KagemushaActiveReceiverWitnessProofV1>> {
        let Some(artifact) = self.v2_finality_artifact(height)? else {
            return Ok(None);
        };
        let _guard = self.sidecar_lock.lock();
        let path = self.kagemusha_active_receiver_sidecar_path(height);
        let Some((sidecar, _)) = self.decode_kagemusha_active_receiver_finality_sidecar(&path)?
        else {
            return Err(Error::KagemushaActiveReceiverFinalitySidecar(
                "finality artifact has no active-receiver witness sidecar".to_owned(),
            ));
        };
        Self::validate_kagemusha_active_receiver_finality_sidecar(&sidecar, &artifact)?;
        Ok(Some(sidecar.witness_proof))
    }

    /// Return the finalized fixed-key validation-fee registry witness proof for one block.
    pub fn validation_fee_policy_witness_proof_v1(
        &self,
        height: u64,
    ) -> Result<Option<ValidationFeePolicyWitnessProofV1>> {
        let Some(artifact) = self.v2_finality_artifact(height)? else {
            return Ok(None);
        };
        let _guard = self.sidecar_lock.lock();
        let path = self.kagemusha_active_receiver_sidecar_path(height);
        let Some((sidecar, _)) = self.decode_kagemusha_active_receiver_finality_sidecar(&path)?
        else {
            return Err(Error::KagemushaActiveReceiverFinalitySidecar(
                "finality artifact has no validation-fee witness sidecar".to_owned(),
            ));
        };
        Self::validate_kagemusha_active_receiver_finality_sidecar(&sidecar, &artifact)?;
        Ok(Some(sidecar.validation_fee_policy_witness))
    }

    /// Durably stage the bounded top-up leaf/path projection before WSV commit.
    ///
    /// A block without top-ups creates no file. An existing exact stage is an
    /// idempotent retry; a conflicting stage at the same height fails closed.
    pub(crate) fn stage_kagemusha_topup_finality_sidecar(
        &self,
        height: u64,
        block_hash: HashOf<BlockHeader>,
        witness: &ExecWitness,
        expected: ExecutionCommitment,
    ) -> Result<()> {
        self.stage_kagemusha_active_receiver_finality_sidecar(
            height, block_hash, witness, expected,
        )?;
        self.durable_mutation_authorized()?;
        let Some(staged) = Self::staged_kagemusha_topup_finality_from_witness(
            height, block_hash, witness, expected,
        )?
        else {
            return Ok(());
        };
        let bytes = staged.encode();
        if bytes.len() > MAX_KAGEMUSHA_TOPUP_FINALITY_SIDECAR_BYTES {
            return Err(Error::KagemushaTopUpFinalitySidecarTooLarge {
                actual: bytes.len(),
                max: MAX_KAGEMUSHA_TOPUP_FINALITY_SIDECAR_BYTES,
            });
        }
        let _guard = self.sidecar_lock.lock();
        let directory = self.kagemusha_topup_finality_staging_dir();
        create_dir_all_with_context(&directory)?;
        if let Some(parent) = directory.parent() {
            sync_dir(parent).map_err(|error| Error::IO(error, parent.to_path_buf()))?;
        }
        let path = self.kagemusha_topup_finality_staging_path(height);
        if let Some((existing, identity)) = self.decode_staged_kagemusha_topup_finality(&path)? {
            if existing == staged
                && identity.bytes == bytes
                && identity.bytes_hash == Hash::new(&bytes)
            {
                return Ok(());
            }
            return Err(Error::KagemushaTopUpFinalitySidecar(
                "conflicting staged top-up sidecar at one height".to_owned(),
            ));
        }
        if !self.write_atomic_synced_noclobber(&path, &bytes)? {
            let Some((existing, _)) = self.decode_staged_kagemusha_topup_finality(&path)? else {
                return Err(Error::KagemushaTopUpFinalitySidecar(
                    "staged top-up sidecar appeared and disappeared during no-clobber publication"
                        .to_owned(),
                ));
            };
            if existing != staged {
                return Err(Error::KagemushaTopUpFinalitySidecar(
                    "no-clobber race published a conflicting staged top-up sidecar".to_owned(),
                ));
            }
        }
        let Some((persisted, persisted_identity)) =
            self.decode_staged_kagemusha_topup_finality(&path)?
        else {
            return Err(Error::KagemushaTopUpFinalitySidecar(
                "staged top-up sidecar disappeared after publication".to_owned(),
            ));
        };
        if persisted != staged
            || persisted_identity.bytes != bytes
            || persisted_identity.bytes_hash != Hash::new(&bytes)
        {
            return Err(Error::KagemushaTopUpFinalitySidecar(
                "staged top-up sidecar changed during publication readback".to_owned(),
            ));
        }
        Ok(())
    }

    fn remove_exact_staged_kagemusha_topup_finality(
        &self,
        path: &Path,
        read_identity: &StableSidecarRead,
    ) -> Result<()> {
        let directory = self.kagemusha_topup_finality_staging_dir();
        let Some(current) = self.regular_sidecar_metadata(path, &directory)? else {
            return Ok(());
        };
        if !Self::stable_sidecar_metadata_unchanged(&read_identity.metadata, &current) {
            return Err(Error::KagemushaTopUpFinalitySidecar(
                "staged top-up sidecar changed before cleanup".to_owned(),
            ));
        }
        std::fs::remove_file(path).map_err(|error| Error::IO(error, path.to_path_buf()))?;
        sync_dir(&directory).map_err(|error| Error::IO(error, directory))?;
        Ok(())
    }

    /// Promote a witness-derived stage only after the exact finality artifact is durable.
    pub(crate) fn promote_kagemusha_topup_finality_sidecar(
        &self,
        artifact: &V2FinalityArtifact,
        receipt: &KuraV2CommitReceipt,
    ) -> Result<()> {
        self.promote_kagemusha_active_receiver_finality_sidecar(artifact, receipt)?;
        self.durable_mutation_authorized()?;
        if receipt.height != artifact.height
            || receipt.block_hash != artifact.block_hash
            || receipt.context_id != artifact.context_id()
            || receipt.subject != artifact.subject
            || receipt.certificate != artifact.commit_qc.as_ref()
            || receipt.artifact_hash != HashOf::new(artifact)
        {
            return Err(Error::KagemushaTopUpFinalitySidecar(
                "finality receipt does not identify the supplied artifact".to_owned(),
            ));
        }
        let _guard = self.sidecar_lock.lock();
        let finality_path = self.v2_finality_artifact_path(artifact.height);
        let finality_directory = self.v2_finality_artifact_dir();
        let Some((durable_record, finality_identity)) =
            self.decode_v2_finality_record_at(&finality_path, &finality_directory)?
        else {
            return Err(Error::KagemushaTopUpFinalitySidecar(
                "finality receipt has no matching durable artifact".to_owned(),
            ));
        };
        let durable_artifact = &durable_record.artifact;
        if durable_artifact != artifact || HashOf::new(durable_artifact) != receipt.artifact_hash {
            return Err(Error::KagemushaTopUpFinalitySidecar(
                "durable finality artifact differs from the promotion receipt".to_owned(),
            ));
        }
        let block_height = NonZeroUsize::new(usize::try_from(artifact.height)?).ok_or(
            Error::V2FinalityCanonicalHeaderUnavailable {
                height: artifact.height,
            },
        )?;
        let canonical_hash = self.get_durable_block_hash(block_height).ok_or(
            Error::V2FinalityCanonicalHeaderUnavailable {
                height: artifact.height,
            },
        )?;
        Self::validate_v2_finality_record_at(
            &finality_path,
            artifact.height,
            canonical_hash,
            &durable_record,
        )?;
        self.verify_v2_finality_artifact_at(
            &finality_path,
            &finality_directory,
            durable_artifact,
            &finality_identity,
        )?;
        if artifact.commit_qc.execution_commitment.topup_anchor_count == 0 {
            for (path, directory, kind) in [
                (
                    self.kagemusha_topup_finality_staging_path(artifact.height),
                    self.kagemusha_topup_finality_staging_dir(),
                    "staged",
                ),
                (
                    self.kagemusha_topup_finality_sidecar_path(artifact.height),
                    self.kagemusha_topup_finality_sidecar_dir(),
                    "finalized",
                ),
            ] {
                if self.regular_sidecar_metadata(&path, &directory)?.is_some() {
                    return Err(Error::KagemushaTopUpFinalitySidecar(format!(
                        "non-top-up finality artifact has a conflicting {kind} top-up sidecar"
                    )));
                }
            }
            return Ok(());
        }

        let final_path = self.kagemusha_topup_finality_sidecar_path(artifact.height);
        let staged_path = self.kagemusha_topup_finality_staging_path(artifact.height);
        if let Some((existing, _)) = self.decode_kagemusha_topup_finality_sidecar(&final_path)? {
            Self::validate_kagemusha_topup_finality_sidecar(&existing, artifact)?;
            if let Some((staged, identity)) =
                self.decode_staged_kagemusha_topup_finality(&staged_path)?
            {
                Self::validate_staged_kagemusha_topup_finality(&staged, artifact)?;
                self.remove_exact_staged_kagemusha_topup_finality(&staged_path, &identity)?;
            }
            return Ok(());
        }

        let Some((staged, staged_identity)) =
            self.decode_staged_kagemusha_topup_finality(&staged_path)?
        else {
            return Err(Error::KagemushaTopUpFinalitySidecar(
                "top-up finality artifact is durable but its pre-commit witness stage is missing"
                    .to_owned(),
            ));
        };
        Self::validate_staged_kagemusha_topup_finality(&staged, artifact)?;
        let final_sidecar = KagemushaTopUpFinalitySidecar {
            format: staged.format,
            version: staged.version,
            height: staged.height,
            block_hash: staged.block_hash,
            ordinary_writes_root: staged.ordinary_writes_root,
            topup_anchor_root: staged.topup_anchor_root,
            post_state_root: staged.post_state_root,
            finality_artifact_hash: receipt.artifact_hash,
            leaves: staged.leaves,
        };
        Self::validate_kagemusha_topup_finality_sidecar(&final_sidecar, artifact)?;
        let bytes = final_sidecar.encode();
        if bytes.len() > MAX_KAGEMUSHA_TOPUP_FINALITY_SIDECAR_BYTES {
            return Err(Error::KagemushaTopUpFinalitySidecarTooLarge {
                actual: bytes.len(),
                max: MAX_KAGEMUSHA_TOPUP_FINALITY_SIDECAR_BYTES,
            });
        }
        let directory = self.kagemusha_topup_finality_sidecar_dir();
        create_dir_all_with_context(&directory)?;
        if let Some(parent) = directory.parent() {
            sync_dir(parent).map_err(|error| Error::IO(error, parent.to_path_buf()))?;
        }
        if !self.write_atomic_synced_noclobber(&final_path, &bytes)? {
            let Some((existing, _)) = self.decode_kagemusha_topup_finality_sidecar(&final_path)?
            else {
                return Err(Error::KagemushaTopUpFinalitySidecar(
                    "final top-up sidecar appeared and disappeared during no-clobber publication"
                        .to_owned(),
                ));
            };
            if existing != final_sidecar {
                return Err(Error::KagemushaTopUpFinalitySidecar(
                    "no-clobber race published a conflicting final top-up sidecar".to_owned(),
                ));
            }
        }
        let Some((persisted, persisted_identity)) =
            self.decode_kagemusha_topup_finality_sidecar(&final_path)?
        else {
            return Err(Error::KagemushaTopUpFinalitySidecar(
                "final top-up sidecar disappeared after publication".to_owned(),
            ));
        };
        Self::validate_kagemusha_topup_finality_sidecar(&persisted, artifact)?;
        if persisted != final_sidecar
            || persisted_identity.bytes != bytes
            || persisted_identity.bytes_hash != Hash::new(&bytes)
        {
            return Err(Error::KagemushaTopUpFinalitySidecar(
                "final top-up sidecar changed during publication readback".to_owned(),
            ));
        }
        self.remove_exact_staged_kagemusha_topup_finality(&staged_path, &staged_identity)?;
        Ok(())
    }

    /// Build a compact peer proof from an exact verified finality artifact and
    /// its independently durable witness-derived leaf/path sidecar.
    pub fn kagemusha_topup_finality_proof_v2(
        &self,
        height: u64,
        operation_id: [u8; 32],
    ) -> Result<Option<KagemushaTopUpFinalityProofV2>> {
        let Some(artifact) = self.v2_finality_artifact(height)? else {
            return Ok(None);
        };
        if artifact.commit_qc.execution_commitment.topup_anchor_count == 0 {
            return Ok(None);
        }
        let _guard = self.sidecar_lock.lock();
        let path = self.kagemusha_topup_finality_sidecar_path(height);
        let Some((sidecar, _)) = self.decode_kagemusha_topup_finality_sidecar(&path)? else {
            return Err(Error::KagemushaTopUpFinalitySidecar(
                "finality artifact advertises top-ups but its durable leaf/path sidecar is missing"
                    .to_owned(),
            ));
        };
        Self::validate_kagemusha_topup_finality_sidecar(&sidecar, &artifact)?;
        let Some(leaf) = sidecar.leaf_for_operation(&operation_id) else {
            return Ok(None);
        };
        let context = &artifact.height_context;
        let proof = KagemushaTopUpFinalityProofV2 {
            version: KAGEMUSHA_TOPUP_FINALITY_PROOF_VERSION_V2,
            anchor: iroha_data_model::offline::KagemushaRecursiveSpendTopUpAnchorRefV2 {
                topup_operation_id: leaf.operation_id,
                anchor_digest: leaf.anchor_digest,
            },
            commit_qc: KagemushaTopUpFinalityCompactQcV2 {
                height_context: KagemushaTopUpFinalityHeightContextV2 {
                    context_id: context.id(),
                    chain_id: context.chain_id.clone(),
                    protocol_version: context.protocol_version,
                    height: context.height,
                    epoch: context.epoch,
                    epoch_end_height: context.epoch_end_height,
                    next_epoch_snapshot: context.next_epoch_snapshot.clone(),
                    mode: context.mode,
                    parent_commit_qc: context.parent_commit_qc.clone(),
                    snapshot_bootstrap: context.snapshot_bootstrap,
                    nexus_amx_context_hash: context.nexus_amx_context_hash,
                    da_layout: context.da_layout,
                    leader_seed: context.leader_seed,
                },
                certificate: artifact.commit_qc.clone(),
            },
            anchor_path: KagemushaTopUpAnchorMerkleProofV2 {
                leaf_index: leaf.leaf_index,
                leaf_count: leaf.leaf_count,
                siblings: leaf.siblings.iter().copied().map(Into::into).collect(),
            },
        };
        proof.validate_structure().map_err(|error| {
            Error::KagemushaTopUpFinalitySidecar(format!(
                "durable top-up proof projection is invalid: {error}"
            ))
        })?;
        Ok(Some(proof))
    }

    /// Persist the immutable canonical WSV checkpoint for a durable block.
    ///
    /// The checkpoint is staged from the validated `StateBlock` after the block
    /// body is durable but before live WSV publication, then bound to the
    /// complete commit manifest after publication succeeds. It is mandatory
    /// replay-integrity metadata for every durable full-body commit, allowing
    /// Kura to verify either the replayed overlay or reconstructed committed
    /// state surface byte-for-byte by hash. Authenticated hash-only snapshot
    /// prefixes are exempt because their block bodies are unavailable locally.
    ///
    /// Once a checkpoint exists, its height, block, and state identity are
    /// immutable even before manifest binding. This makes a pre-commit crash
    /// fail closed if deterministic replay produces a different state.
    ///
    /// # Errors
    /// Returns an error if the target block is not durable or the checkpoint cannot be written.
    pub(crate) fn store_wsv_checkpoint(
        &self,
        height: u64,
        block_hash: HashOf<BlockHeader>,
        state_hash: Hash,
    ) -> Result<()> {
        let _prune_guard = self.prune_lock.lock();
        self.ensure_prune_recovery_not_required()?;
        self.durable_mutation_authorized()?;
        self.ensure_durable_block_at_height(height, block_hash)?;
        #[cfg(test)]
        if self
            .fail_next_wsv_checkpoint_write
            .swap(false, Ordering::Relaxed)
        {
            return Err(Error::IO(
                std::io::Error::other("kura WSV checkpoint injected failure"),
                PathBuf::from("wsv_checkpoint_test_fail"),
            ));
        }
        let _guard = self.sidecar_lock.lock();
        // Close the preflight-to-publication race with top-block replacement. A writer can pass
        // the first durable-hash check and then wait behind replacement's metadata fence.
        self.ensure_durable_block_at_height(height, block_hash)?;
        let dir = self.wsv_checkpoint_dir();
        create_dir_all_with_context(&dir)?;
        let path = dir.join(format!("{height:020}.norito"));
        let mut checkpoint = WsvCheckpoint::new(height, block_hash, state_hash);
        if let Some(existing) = Self::decode_wsv_checkpoint_at(&path)? {
            if existing.height != height
                || existing.block_hash != block_hash
                || existing.state_hash != state_hash
            {
                return Err(Error::NoritoFrame(norito::core::Error::Message(format!(
                    "refusing to replace immutable WSV checkpoint #{height}"
                ))));
            }
            // Re-persisting an identical checkpoint must never erase the
            // durable proof that a complete manifest was already published.
            checkpoint.commit_manifest_hash = existing.commit_manifest_hash;
        }
        let tmp_path = path.with_extension("norito.tmp");
        let bytes = checkpoint.encode();
        let mut tmp_file = FileWrap::open_with(tmp_path.clone(), |opts| {
            opts.write(true).create(true).truncate(true);
        })?;
        tmp_file.try_io(|file| {
            file.write_all(&bytes)?;
            file.flush()?;
            file.sync_data()
        })?;
        std::fs::rename(&tmp_path, &path).map_err(|err| Error::IO(err, path.clone()))?;
        sync_dir(&dir).map_err(|err| Error::IO(err, dir))?;
        Ok(())
    }

    fn bind_wsv_checkpoint_to_manifest(&self, manifest: &CommitManifest) -> Result<()> {
        let path = self.wsv_checkpoint_path(manifest.height);
        let Some(mut checkpoint) = Self::decode_wsv_checkpoint_at(&path)? else {
            return Ok(());
        };
        Self::ensure_checkpoint_matches_manifest(&checkpoint, manifest)?;
        let manifest_hash = manifest.encoded_hash();
        if checkpoint
            .commit_manifest_hash
            .is_some_and(|published| published != manifest_hash)
        {
            return Err(Error::NoritoFrame(norito::core::Error::Message(format!(
                "refusing to replace published commit manifest digest at height {}",
                manifest.height
            ))));
        }
        checkpoint.commit_manifest_hash = Some(manifest_hash);
        let dir = self.wsv_checkpoint_dir();
        let tmp_path = path.with_extension("norito.tmp");
        let bytes = checkpoint.encode();
        let mut tmp_file = FileWrap::open_with(tmp_path.clone(), |opts| {
            opts.write(true).create(true).truncate(true);
        })?;
        tmp_file.try_io(|file| {
            file.write_all(&bytes)?;
            file.flush()?;
            file.sync_data()
        })?;
        std::fs::rename(&tmp_path, &path).map_err(|err| Error::IO(err, path.clone()))?;
        sync_dir(&dir).map_err(|err| Error::IO(err, dir))?;
        Ok(())
    }

    /// Persist the durable commit manifest for a committed block height.
    ///
    /// Manifests are written after the block body is durable and WSV commit succeeds. They are the
    /// mandatory replay-integrity join point between Kura's canonical block log, the memory-only
    /// WSV surface, and authenticated v2 finality. Only the sole interrupted pending tip may lack
    /// one until startup completes it; authenticated hash-only snapshot prefixes are exempt.
    ///
    /// # Errors
    /// Returns an error if the target block is not durable or the manifest cannot be written.
    pub(crate) fn store_commit_manifest(&self, manifest: CommitManifest) -> Result<()> {
        let _prune_guard = self.prune_lock.lock();
        self.ensure_prune_recovery_not_required()?;
        self.durable_mutation_authorized()?;
        self.ensure_durable_block_at_height(manifest.height, manifest.block_hash)?;
        #[cfg(test)]
        if self
            .fail_next_commit_manifest_write
            .swap(false, Ordering::Relaxed)
        {
            return Err(Error::IO(
                std::io::Error::other("kura commit manifest injected failure"),
                PathBuf::from("commit_manifest_test_fail"),
            ));
        }
        let _guard = self.sidecar_lock.lock();
        // Close the preflight-to-publication race with top-block replacement. A writer can pass
        // the first durable-hash check and then wait behind replacement's metadata fence.
        self.ensure_durable_block_at_height(manifest.height, manifest.block_hash)?;
        // Keep the replacement fence in the same critical section as publication. Otherwise two
        // concurrent writers could both pass a pre-lock check and the loser could overwrite the
        // manifest before discovering that the checkpoint already published the winner's digest.
        self.ensure_checkpoint_accepts_manifest_write(&manifest)?;
        let dir = self.commit_manifest_dir();
        create_dir_all_with_context(&dir)?;
        let path = self.commit_manifest_path(manifest.height);
        let tmp_path = path.with_extension("norito.tmp");
        let bytes = manifest.encode();
        let mut tmp_file = FileWrap::open_with(tmp_path.clone(), |opts| {
            opts.write(true).create(true).truncate(true);
        })?;
        tmp_file.try_io(|file| {
            file.write_all(&bytes)?;
            file.flush()?;
            file.sync_data()
        })?;
        std::fs::rename(&tmp_path, &path).map_err(|err| Error::IO(err, path.clone()))?;
        sync_dir(&dir).map_err(|err| Error::IO(err, dir.clone()))?;
        // Publish the external checkpoint binding only after the complete manifest is durable.
        // Recovery can therefore trust a matching digest without ever observing a checkpoint that
        // points at absent or partially promoted manifest bytes.
        self.bind_wsv_checkpoint_to_manifest(&manifest)?;
        Ok(())
    }

    fn decode_commit_manifest_at(path: &Path) -> Result<Option<CommitManifest>> {
        let bytes = match std::fs::read(path) {
            Ok(bytes) => bytes,
            Err(err) if err.kind() == ErrorKind::NotFound => return Ok(None),
            Err(err) => return Err(Error::IO(err, path.to_path_buf())),
        };
        let mut cursor = bytes.as_slice();
        CommitManifest::decode_all(&mut cursor)
            .map(Some)
            .map_err(Error::NoritoFrame)
    }

    /// Read and validate the durable commit manifest for a committed block height.
    ///
    /// # Errors
    /// Returns an error if the manifest exists but does not match the durable block hash or a
    /// present WSV checkpoint sidecar, or if the checkpoint proves a manifest was already
    /// published but its bytes are missing.
    pub(crate) fn commit_manifest(&self, height: u64) -> Result<Option<CommitManifest>> {
        self.ensure_prune_recovery_not_required()?;
        let _guard = self.sidecar_lock.lock();
        self.commit_manifest_under_sidecar_guard(height)
    }

    /// Read a commit manifest while the caller holds `sidecar_lock`.
    ///
    /// This no-relock variant is used by geometry evidence validation, whose
    /// outer critical section already owns prune, canonical, geometry, and
    /// sidecar locks in the global order.
    fn commit_manifest_under_sidecar_guard(&self, height: u64) -> Result<Option<CommitManifest>> {
        self.ensure_prune_recovery_not_required()?;
        let path = self.commit_manifest_path(height);
        let manifest = Self::decode_commit_manifest_at(&path)?;
        let Some(manifest) = manifest else {
            self.ensure_prune_recovery_not_required()?;
            if self
                .wsv_checkpoint_under_sidecar_guard(height)?
                .is_some_and(|checkpoint| checkpoint.commit_manifest_hash.is_some())
            {
                return Err(Error::NoritoFrame(norito::core::Error::Message(format!(
                    "WSV checkpoint #{height} proves a commit manifest was published, but the manifest is missing"
                ))));
            }
            self.ensure_prune_recovery_not_required()?;
            return Ok(None);
        };
        if manifest.height != height {
            return Err(Error::NoritoFrame(norito::core::Error::Message(format!(
                "commit manifest height mismatch: expected {height}, got {}",
                manifest.height
            ))));
        }
        let Some(block_height) = NonZeroUsize::new(usize::try_from(height)?) else {
            return Err(Error::NoritoFrame(norito::core::Error::Message(
                "commit manifest height must be non-zero".into(),
            )));
        };
        let durable_hash = self.get_durable_block_hash(block_height);
        self.ensure_prune_recovery_not_required()?;
        let Some(durable_hash) = durable_hash else {
            return Err(Error::BlockHeightGap {
                expected_next_height: u64::try_from(self.exact_durable_blocks_count()?)?
                    .saturating_add(1),
                actual_height: height,
            });
        };
        if manifest.block_hash != durable_hash {
            return Err(Error::BlockHeightConflict {
                height,
                expected: durable_hash,
                actual: manifest.block_hash,
            });
        }
        self.ensure_checkpoint_matches_commit_manifest_under_sidecar_guard(&manifest)?;
        self.ensure_prune_recovery_not_required()?;
        Ok(Some(manifest))
    }

    /// Return whether the WSV checkpoint independently binds every byte of `manifest`.
    #[cfg(test)]
    pub(crate) fn commit_manifest_has_wsv_binding(
        &self,
        manifest: &CommitManifest,
    ) -> Result<bool> {
        Ok(self.commit_manifest_binding_state(manifest)? == CommitManifestBindingState::Bound)
    }

    /// Classify the checkpoint-to-manifest digest without conflating an interrupted publication
    /// (`None`) with an already published, different digest.
    pub(crate) fn commit_manifest_binding_state(
        &self,
        manifest: &CommitManifest,
    ) -> Result<CommitManifestBindingState> {
        let Some(checkpoint) = self.wsv_checkpoint(manifest.height)? else {
            return Ok(CommitManifestBindingState::Unbound);
        };
        Self::ensure_checkpoint_matches_manifest(&checkpoint, manifest)?;
        Ok(match checkpoint.commit_manifest_hash {
            None => CommitManifestBindingState::Unbound,
            Some(hash) if hash == manifest.encoded_hash() => CommitManifestBindingState::Bound,
            Some(_) => CommitManifestBindingState::Mismatched,
        })
    }

    fn ensure_checkpoint_matches_commit_manifest_under_sidecar_guard(
        &self,
        manifest: &CommitManifest,
    ) -> Result<()> {
        if let Some(checkpoint) = self.wsv_checkpoint_under_sidecar_guard(manifest.height)? {
            Self::ensure_checkpoint_matches_manifest(&checkpoint, manifest)?;
        }
        Ok(())
    }

    fn ensure_checkpoint_accepts_manifest_write(&self, manifest: &CommitManifest) -> Result<()> {
        let checkpoint_path = self.wsv_checkpoint_path(manifest.height);
        let Some(checkpoint) = Self::decode_wsv_checkpoint_at(&checkpoint_path)? else {
            return Ok(());
        };
        Self::ensure_checkpoint_matches_manifest(&checkpoint, manifest)?;
        if checkpoint
            .commit_manifest_hash
            .is_some_and(|published| published != manifest.encoded_hash())
        {
            return Err(Error::NoritoFrame(norito::core::Error::Message(format!(
                "commit manifest at height {} would replace an already published digest",
                manifest.height
            ))));
        }
        Ok(())
    }

    fn ensure_checkpoint_matches_manifest(
        checkpoint: &WsvCheckpoint,
        manifest: &CommitManifest,
    ) -> Result<()> {
        if checkpoint.height != manifest.height {
            return Err(Error::NoritoFrame(norito::core::Error::Message(format!(
                "commit manifest checkpoint height mismatch: manifest height {}, checkpoint height {}",
                manifest.height, checkpoint.height
            ))));
        }
        if checkpoint.block_hash != manifest.block_hash {
            return Err(Error::BlockHeightConflict {
                height: manifest.height,
                expected: manifest.block_hash,
                actual: checkpoint.block_hash,
            });
        }
        if checkpoint.state_hash != manifest.wsv_checkpoint_hash {
            return Err(Error::NoritoFrame(norito::core::Error::Message(format!(
                "commit manifest WSV checkpoint hash mismatch at height {}",
                manifest.height
            ))));
        }
        Ok(())
    }

    fn reconcile_commit_manifests(
        _block_store: &mut BlockStore,
        blocks_dir: &Path,
        block_hashes: &mut Vec<HashOf<BlockHeader>>,
    ) -> Result<CommitManifestReconciliation> {
        let dir = Self::commit_manifest_dir_for(blocks_dir);
        // Validate checkpoints first. A checkpoint with a published manifest digest turns an
        // absent, unreadable, or altered manifest into fail-closed corruption rather than a
        // repairable post-commit crash window.
        let pruned_checkpoints =
            Self::reconcile_wsv_checkpoints_against_blocks(blocks_dir, block_hashes)?;
        let entries = match std::fs::read_dir(&dir) {
            Ok(entries) => entries,
            Err(err) if err.kind() == ErrorKind::NotFound => {
                return Ok(CommitManifestReconciliation {
                    manifests_present: false,
                    pruned_manifests: false,
                    pruned_checkpoints,
                    retained_height: block_hashes.len(),
                });
            }
            Err(err) => return Err(Error::IO(err, dir)),
        };
        let mut manifests_present = false;
        let mut pruned_manifests = false;
        for entry in entries {
            let entry = entry.map_err(|err| Error::IO(err, dir.clone()))?;
            let file_type = entry
                .file_type()
                .map_err(|err| Error::IO(err, entry.path()))?;
            if !file_type.is_file() {
                continue;
            }
            let path = entry.path();
            if path.extension().and_then(|ext| ext.to_str()) != Some("norito") {
                continue;
            }
            let Some(stem) = path.file_stem().and_then(|stem| stem.to_str()) else {
                continue;
            };
            let Ok(height) = stem.parse::<u64>() else {
                continue;
            };
            let addresses_retained_block = usize::try_from(height)
                .ok()
                .is_some_and(|height| height != 0 && height <= block_hashes.len());
            let manifest = match Self::decode_commit_manifest_at(&path) {
                Ok(Some(manifest)) => manifest,
                Ok(None) => continue,
                Err(Error::NoritoFrame(err)) if addresses_retained_block => {
                    return Err(Error::NoritoFrame(err));
                }
                Err(Error::NoritoFrame(err)) => {
                    warn!(
                        ?err,
                        path = %path.display(),
                        "pruning unreadable Kura commit manifest sidecar"
                    );
                    std::fs::remove_file(&path).map_err(|err| Error::IO(err, path.clone()))?;
                    pruned_manifests = true;
                    continue;
                }
                Err(err) => return Err(err),
            };
            manifests_present = true;
            if manifest.height != height {
                if addresses_retained_block {
                    return Err(Error::NoritoFrame(norito::core::Error::Message(format!(
                        "retained commit manifest filename height {height} does not match payload height {}",
                        manifest.height
                    ))));
                }
                warn!(
                    path = %path.display(),
                    filename_height = height,
                    payload_height = manifest.height,
                    "pruning Kura commit manifest sidecar with mismatched height"
                );
                std::fs::remove_file(&path).map_err(|err| Error::IO(err, path.clone()))?;
                pruned_manifests = true;
                continue;
            }
            let Some(index) = height
                .checked_sub(1)
                .and_then(|value| usize::try_from(value).ok())
            else {
                warn!(
                    path = %path.display(),
                    "pruning Kura commit manifest sidecar with zero height"
                );
                std::fs::remove_file(&path).map_err(|err| Error::IO(err, path.clone()))?;
                pruned_manifests = true;
                continue;
            };
            let Some(expected) = block_hashes.get(index).copied() else {
                std::fs::remove_file(&path).map_err(|err| Error::IO(err, path.clone()))?;
                pruned_manifests = true;
                continue;
            };
            if manifest.block_hash != expected {
                return Err(Error::BlockHeightConflict {
                    height,
                    expected,
                    actual: manifest.block_hash,
                });
            }
            let checkpoint_path = Self::wsv_checkpoint_path_for(blocks_dir, height);
            match Self::decode_wsv_checkpoint_at(&checkpoint_path) {
                Ok(Some(checkpoint)) => {
                    Self::ensure_checkpoint_matches_manifest(&checkpoint, &manifest)?;
                }
                Ok(None) => {}
                Err(Error::NoritoFrame(err)) => {
                    return Err(Error::NoritoFrame(err));
                }
                Err(err) => return Err(err),
            }
        }

        sync_dir(&dir).map_err(|err| Error::IO(err, dir))?;
        Ok(CommitManifestReconciliation {
            manifests_present,
            pruned_manifests,
            pruned_checkpoints,
            retained_height: block_hashes.len(),
        })
    }

    fn reconcile_wsv_checkpoints_against_blocks(
        blocks_dir: &Path,
        block_hashes: &[HashOf<BlockHeader>],
    ) -> Result<bool> {
        let dir = Self::wsv_checkpoint_dir_for(blocks_dir);
        if !dir.exists() {
            return Ok(false);
        }
        let mut pruned = false;
        for entry in std::fs::read_dir(&dir).map_err(|err| Error::IO(err, dir.clone()))? {
            let entry = entry.map_err(|err| Error::IO(err, dir.clone()))?;
            let file_type = entry
                .file_type()
                .map_err(|err| Error::IO(err, entry.path()))?;
            if !file_type.is_file() {
                continue;
            }
            let path = entry.path();
            if path.extension().and_then(|ext| ext.to_str()) != Some("norito") {
                continue;
            }
            let Some(stem) = path.file_stem().and_then(|stem| stem.to_str()) else {
                continue;
            };
            let Ok(height) = stem.parse::<u64>() else {
                continue;
            };
            let addresses_retained_block = usize::try_from(height)
                .ok()
                .is_some_and(|height| height != 0 && height <= block_hashes.len());
            let checkpoint = match Self::decode_wsv_checkpoint_at(&path) {
                Ok(Some(checkpoint)) => checkpoint,
                Ok(None) => continue,
                Err(Error::NoritoFrame(err)) if addresses_retained_block => {
                    return Err(Error::NoritoFrame(err));
                }
                Err(Error::NoritoFrame(err)) => {
                    warn!(
                        ?err,
                        path = %path.display(),
                        "pruning unreadable Kura WSV checkpoint sidecar"
                    );
                    std::fs::remove_file(&path).map_err(|err| Error::IO(err, path.clone()))?;
                    pruned = true;
                    continue;
                }
                Err(err) => return Err(err),
            };
            let Some(index) = height
                .checked_sub(1)
                .and_then(|value| usize::try_from(value).ok())
            else {
                warn!(
                    path = %path.display(),
                    "pruning Kura WSV checkpoint sidecar with zero height"
                );
                std::fs::remove_file(&path).map_err(|err| Error::IO(err, path.clone()))?;
                pruned = true;
                continue;
            };
            let Some(expected) = block_hashes.get(index).copied() else {
                warn!(
                    path = %path.display(),
                    height,
                    "pruning Kura WSV checkpoint sidecar above durable block log"
                );
                std::fs::remove_file(&path).map_err(|err| Error::IO(err, path.clone()))?;
                pruned = true;
                continue;
            };
            if checkpoint.height != height || checkpoint.block_hash != expected {
                if checkpoint.height != height {
                    return Err(Error::NoritoFrame(norito::core::Error::Message(format!(
                        "retained WSV checkpoint filename height {height} does not match payload height {}",
                        checkpoint.height
                    ))));
                }
                return Err(Error::BlockHeightConflict {
                    height,
                    expected,
                    actual: checkpoint.block_hash,
                });
            }
            Self::ensure_published_manifest_claim_resolves(blocks_dir, &checkpoint)?;
        }
        if pruned {
            sync_dir(&dir).map_err(|err| Error::IO(err, dir))?;
        }
        Ok(pruned)
    }

    fn ensure_published_manifest_claim_resolves(
        blocks_dir: &Path,
        checkpoint: &WsvCheckpoint,
    ) -> Result<()> {
        let Some(expected_manifest_hash) = checkpoint.commit_manifest_hash else {
            return Ok(());
        };
        let path = Self::commit_manifest_path_for(blocks_dir, checkpoint.height);
        let Some(manifest) = Self::decode_commit_manifest_at(&path)? else {
            return Err(Error::NoritoFrame(norito::core::Error::Message(format!(
                "WSV checkpoint #{} proves a commit manifest was published, but the manifest is missing",
                checkpoint.height
            ))));
        };
        Self::ensure_checkpoint_matches_manifest(checkpoint, &manifest)?;
        if manifest.encoded_hash() != expected_manifest_hash {
            return Err(Error::NoritoFrame(norito::core::Error::Message(format!(
                "WSV checkpoint #{} commit manifest digest does not match the published manifest",
                checkpoint.height
            ))));
        }
        Ok(())
    }

    /// Read the canonical WSV checkpoint for a committed block height, if one exists.
    ///
    /// # Errors
    /// Returns an error if the checkpoint file exists but cannot be read, decoded, or matched to
    /// the canonical block hash stored at the same height.
    pub(crate) fn wsv_checkpoint(&self, height: u64) -> Result<Option<WsvCheckpoint>> {
        self.ensure_prune_recovery_not_required()?;
        let _guard = self.sidecar_lock.lock();
        self.wsv_checkpoint_under_sidecar_guard(height)
    }

    /// Read a WSV checkpoint while the caller holds `sidecar_lock`.
    fn wsv_checkpoint_under_sidecar_guard(&self, height: u64) -> Result<Option<WsvCheckpoint>> {
        self.ensure_prune_recovery_not_required()?;
        let path = self.wsv_checkpoint_path(height);
        let checkpoint = Self::decode_wsv_checkpoint_at(&path)?;
        let Some(checkpoint) = checkpoint else {
            self.ensure_prune_recovery_not_required()?;
            return Ok(None);
        };
        if checkpoint.height != height {
            return Err(Error::NoritoFrame(norito::core::Error::Message(format!(
                "WSV checkpoint height mismatch: expected {height}, got {}",
                checkpoint.height
            ))));
        }
        let Some(block_height) = NonZeroUsize::new(usize::try_from(height)?) else {
            return Err(Error::NoritoFrame(norito::core::Error::Message(
                "WSV checkpoint height must be non-zero".into(),
            )));
        };
        let durable_hash = self.get_durable_block_hash(block_height);
        self.ensure_prune_recovery_not_required()?;
        let Some(durable_hash) = durable_hash else {
            return Err(Error::BlockHeightGap {
                expected_next_height: u64::try_from(self.exact_durable_blocks_count()?)?
                    .saturating_add(1),
                actual_height: height,
            });
        };
        if checkpoint.block_hash != durable_hash {
            return Err(Error::BlockHeightConflict {
                height,
                expected: durable_hash,
                actual: checkpoint.block_hash,
            });
        }
        self.ensure_prune_recovery_not_required()?;
        Ok(Some(checkpoint))
    }

    fn decode_wsv_checkpoint_at(path: &Path) -> Result<Option<WsvCheckpoint>> {
        let bytes = match std::fs::read(&path) {
            Ok(bytes) => bytes,
            Err(err) if err.kind() == ErrorKind::NotFound => return Ok(None),
            Err(err) => return Err(Error::IO(err, path.to_path_buf())),
        };
        let mut cursor = bytes.as_slice();
        WsvCheckpoint::decode_all(&mut cursor)
            .map(Some)
            .map_err(Error::NoritoFrame)
    }

    /// Return the latest canonical WSV checkpoint height at or below `height`.
    pub fn latest_wsv_checkpoint_height_at_or_before(&self, height: u64) -> Result<Option<u64>> {
        self.ensure_prune_recovery_not_required()?;
        if height == 0 {
            return Ok(None);
        }
        let _guard = self.sidecar_lock.lock();
        self.ensure_prune_recovery_not_required()?;
        let dir = self.wsv_checkpoint_dir();
        let entries = match std::fs::read_dir(&dir) {
            Ok(entries) => entries,
            Err(err) if err.kind() == ErrorKind::NotFound => return Ok(None),
            Err(err) => return Err(Error::IO(err, dir)),
        };
        let mut latest: Option<u64> = None;
        for entry in entries {
            let entry = entry.map_err(|err| Error::IO(err, dir.clone()))?;
            let file_type = entry
                .file_type()
                .map_err(|err| Error::IO(err, entry.path()))?;
            if !file_type.is_file() {
                continue;
            }
            let path = entry.path();
            if path.extension().and_then(|ext| ext.to_str()) != Some("norito") {
                continue;
            }
            let Some(stem) = path.file_stem().and_then(|stem| stem.to_str()) else {
                continue;
            };
            let Ok(checkpoint_height) = stem.parse::<u64>() else {
                continue;
            };
            if checkpoint_height <= height {
                latest = Some(match latest {
                    Some(current) => current.max(checkpoint_height),
                    None => checkpoint_height,
                });
            }
        }
        self.ensure_prune_recovery_not_required()?;
        Ok(latest)
    }

    /// Return whether any canonical WSV checkpoint file exists at or below `height`.
    #[cfg(test)]
    pub(crate) fn has_wsv_checkpoint_at_or_before(&self, height: u64) -> Result<bool> {
        self.ensure_prune_recovery_not_required()?;
        self.latest_wsv_checkpoint_height_at_or_before(height)
            .map(|height| height.is_some())
    }

    fn prune_wsv_checkpoints_above_in_dir(dir: &Path, height: u64) -> Result<bool> {
        if !dir.exists() {
            return Ok(false);
        }
        let mut pruned = false;
        for entry in std::fs::read_dir(dir).map_err(|err| Error::IO(err, dir.to_path_buf()))? {
            let entry = entry.map_err(|err| Error::IO(err, dir.to_path_buf()))?;
            let path = entry.path();
            let Some(checkpoint_height) = numbered_norito_sidecar_height(&path) else {
                continue;
            };
            if checkpoint_height > height {
                let file_type = entry
                    .file_type()
                    .map_err(|err| Error::IO(err, path.clone()))?;
                if !file_type.is_file() && !file_type.is_symlink() {
                    return Err(Error::PruneIntentConflict(format!(
                        "WSV-checkpoint suffix entry {} is not removable as a file",
                        path.display()
                    )));
                }
                std::fs::remove_file(&path).map_err(|err| Error::IO(err, path))?;
                pruned = true;
            }
        }
        sync_dir(dir).map_err(|err| Error::IO(err, dir.to_path_buf()))?;
        Ok(pruned)
    }

    fn prune_commit_manifests_above_in_dir(dir: &Path, height: u64) -> Result<()> {
        if !dir.exists() {
            return Ok(());
        }
        for entry in std::fs::read_dir(dir).map_err(|err| Error::IO(err, dir.to_path_buf()))? {
            let entry = entry.map_err(|err| Error::IO(err, dir.to_path_buf()))?;
            let path = entry.path();
            let Some(manifest_height) = numbered_norito_sidecar_height(&path) else {
                continue;
            };
            if manifest_height > height {
                let file_type = entry
                    .file_type()
                    .map_err(|err| Error::IO(err, path.clone()))?;
                if !file_type.is_file() && !file_type.is_symlink() {
                    return Err(Error::PruneIntentConflict(format!(
                        "commit-manifest suffix entry {} is not removable as a file",
                        path.display()
                    )));
                }
                std::fs::remove_file(&path).map_err(|err| Error::IO(err, path))?;
            }
        }
        sync_dir(dir).map_err(|err| Error::IO(err, dir.to_path_buf()))?;
        Ok(())
    }

    fn prune_v2_finality_artifacts_above(&self, height: u64) -> Result<()> {
        let _guard = self.sidecar_lock.lock();
        let dir = self.v2_finality_artifact_dir();
        Self::prune_v2_finality_artifacts_above_in_dir(&dir, height)
    }

    fn prune_v2_finality_artifacts_above_in_dir(dir: &Path, height: u64) -> Result<()> {
        if !dir.exists() {
            return Ok(());
        }
        for entry in std::fs::read_dir(dir).map_err(|err| Error::IO(err, dir.to_path_buf()))? {
            let entry = entry.map_err(|err| Error::IO(err, dir.to_path_buf()))?;
            let path = entry.path();
            let Some(artifact_height) = numbered_norito_sidecar_height(&path) else {
                continue;
            };
            if artifact_height > height {
                let file_type = entry
                    .file_type()
                    .map_err(|err| Error::IO(err, path.clone()))?;
                if !file_type.is_file() && !file_type.is_symlink() {
                    return Err(Error::PruneIntentConflict(format!(
                        "Sumeragi v2 finality suffix entry {} is not removable as a file",
                        path.display()
                    )));
                }
                std::fs::remove_file(&path).map_err(|err| Error::IO(err, path))?;
            }
        }
        sync_dir(dir).map_err(|err| Error::IO(err, dir.to_path_buf()))?;
        Ok(())
    }

    fn read_durable_hash_at_height(
        block_store: &mut BlockStore,
        height: u64,
    ) -> Result<Option<HashOf<BlockHeader>>> {
        let durable_count = block_store.read_durable_index_count()?;
        if durable_count < height {
            return Ok(None);
        }
        Ok(block_store
            .read_block_hashes(height.saturating_sub(1), 1)?
            .first()
            .copied())
    }

    fn ensure_durable_block_at_height(&self, height: u64, hash: HashOf<BlockHeader>) -> Result<()> {
        let mut block_store = self.block_store.lock();
        match Self::read_durable_hash_at_height(&mut block_store, height)? {
            Some(existing) if existing == hash => Ok(()),
            Some(expected) => Err(Error::BlockHeightConflict {
                height,
                expected,
                actual: hash,
            }),
            None => {
                let expected_next_height =
                    block_store.read_durable_index_count()?.saturating_add(1);
                Err(Error::BlockHeightGap {
                    expected_next_height,
                    actual_height: height,
                })
            }
        }
    }

    fn append_debug_block_dump(&self, block: &Arc<SignedBlock>) {
        let Some(path) = self.block_plain_text_path.lock().clone() else {
            return;
        };
        let accounting_mutation = self.begin_total_disk_usage_mutation();
        let debug_before = match Self::file_len_or_zero(&path) {
            Ok(bytes) => Some(bytes),
            Err(err) => {
                warn!(
                    ?err,
                    path = %path.display(),
                    "failed to measure debug block dump before append"
                );
                None
            }
        };
        if let Err(error) = Self::append_blocks_jsonl(&path, std::slice::from_ref(block)) {
            warn!(
                ?error,
                path = %path.display(),
                "Failed to append debug block dump"
            );
        }
        if let Some(debug_before) = debug_before {
            match Self::file_len_or_zero(&path) {
                Ok(debug_after) => {
                    self.update_disk_usage_delta(debug_before, debug_after);
                    accounting_mutation.finish();
                }
                Err(err) => warn!(
                    ?err,
                    path = %path.display(),
                    "failed to measure debug block dump after append"
                ),
            }
        }
    }

    #[cfg(test)]
    fn persist_block_at_height(&self, block: &Arc<SignedBlock>, height: u64) -> Result<()> {
        let write_guard = self.lock_block_store_for_write();
        self.persist_block_at_height_while_locked(block, height, &write_guard)
    }

    fn persist_block_at_height_while_locked(
        &self,
        block: &Arc<SignedBlock>,
        height: u64,
        _write_guard: &parking_lot::MutexGuard<'_, ()>,
    ) -> Result<()> {
        self.ensure_canonical_storage_not_poisoned()?;
        #[cfg(test)]
        if self.fail_next_block_write.swap(false, Ordering::Relaxed) {
            return Err(Error::IO(
                std::io::Error::other("kura store_block injected failure"),
                PathBuf::from("block_store_test_fail"),
            ));
        }

        let start_height = height.saturating_sub(1);
        self.ensure_no_pending_rollback()?;
        let mut block_store = self.block_store.lock();
        let block_store_before = match Self::block_store_tracked_bytes(&mut block_store) {
            Ok(bytes) => Some(bytes),
            Err(err) => {
                warn!(?err, "failed to measure block store bytes before append");
                None
            }
        };
        let total_initialized = self.disk_usage_total_initialized.load(Ordering::Relaxed);
        let da_before = if total_initialized {
            match Self::da_payload_bytes_for_range(&block_store, start_height, 1) {
                Ok(bytes) => Some(bytes),
                Err(err) => {
                    warn!(?err, "failed to measure DA payload bytes before append");
                    None
                }
            }
        } else {
            None
        };
        let accounting_mutation = self.begin_total_disk_usage_mutation();
        let mut accounting_complete =
            block_store_before.is_some() && (!total_initialized || da_before.is_some());
        if let Err(error) = block_store.append_block_batch_at(
            start_height,
            std::slice::from_ref(block),
            self.max_disk_usage_bytes,
        ) {
            if matches!(error, Error::DaBlockRewriteCommitStateUnknown { .. }) {
                self.poison_canonical_storage("ambiguous DA block rewrite publication", &error);
            }
            return Err(error);
        }
        if let Some(message) = block_store.take_deferred_da_recovery_fault() {
            let recovery_error = Error::IO(
                std::io::Error::other(message),
                block_store.da_block_rewrite_stage_path(),
            );
            self.poison_canonical_storage("committed DA block rewrite recovery", &recovery_error);
            return Err(Error::CanonicalBlockCommittedRecoveryRequired {
                detail: format!(
                    "DA rewrite marker committed but body promotion could not complete: {recovery_error}"
                ),
            });
        }
        if let Err(error) = block_store.flush_pending_fsync(true) {
            let publication_is_ambiguous =
                matches!(error, Error::DaBlockRewriteCommitStateUnknown { .. });
            drop(block_store);
            if publication_is_ambiguous {
                self.poison_canonical_storage("ambiguous block append publication", &error);
            }
            return Err(error);
        }
        let rewritten_index = block_store.read_block_index(start_height)?;
        if !rewritten_index.is_evicted()
            && let Err(error) = block_store.remove_da_block_file(height)
        {
            warn!(
                ?error,
                height, "canonical inline rewrite is durable but stale DA-sidecar cleanup failed"
            );
            self.record_writer_fault("stale DA-sidecar cleanup", &error);
        }

        if let Some(block_store_before) = block_store_before {
            match Self::block_store_tracked_bytes(&mut block_store) {
                Ok(after_bytes) => self.update_disk_usage_delta(block_store_before, after_bytes),
                Err(err) => {
                    accounting_complete = false;
                    warn!(?err, "failed to measure block store bytes after append");
                }
            }
        }
        if let Some(da_before) = da_before {
            match Self::da_payload_bytes_for_range(&block_store, start_height, 1) {
                Ok(da_after) => self.update_total_disk_usage_delta(da_before, da_after),
                Err(err) => {
                    accounting_complete = false;
                    warn!(?err, "failed to measure DA payload bytes after append");
                }
            }
        }
        match usize::try_from(height) {
            Ok(persisted_count) => self.publish_durable_budget_snapshot(persisted_count, 0),
            Err(err) => {
                warn!(?err, height, "failed to cache Kura durable budget metadata");
                self.invalidate_durable_budget_snapshot();
            }
        }
        if accounting_complete {
            accounting_mutation.finish();
        }
        Ok(())
    }

    fn store_block_durable(
        &self,
        block: &Arc<SignedBlock>,
        merge_entry: Option<&MergeLedgerEntry>,
    ) -> Result<()> {
        let _prune_guard = self.prune_lock.lock();
        self.ensure_prune_recovery_not_required()?;
        let _canonical_chain_guard = self.canonical_chain_lock.lock();
        self.resolve_canonical_storage_before_mutation()?;
        let blocks_dir = self.active_blocks_dir.lock().clone();
        self.resolve_retained_block_rewrite_stage_before_canonical_mutation(&blocks_dir)?;
        let block_hash = block.hash();
        let actual_height = block.header().height().get();
        let actual_height_usize = usize::try_from(actual_height)?;
        match (Self::block_merge_reference(block), merge_entry) {
            (Some(reference), Some(entry)) if reference.matches_entry(entry) => {}
            (Some(reference), None) => {
                return Err(Error::MissingCertifiedMergeSidecar {
                    entry_hash: reference.entry_hash,
                });
            }
            (Some(_), Some(_)) => {
                return Err(Error::MergeReferenceMismatch(
                    "block compact reference does not match supplied merge entry".to_owned(),
                ));
            }
            (None, Some(_)) => {
                return Err(Error::MergeReferenceMismatch(
                    "merge entry supplied for a block without a compact reference".to_owned(),
                ));
            }
            (None, None) => {}
        }
        if let Some(entry) = merge_entry {
            Self::validate_merge_transaction_uniqueness(block, entry)?;
        }

        {
            let block_data = self.block_data.lock();
            self.ensure_prune_recovery_not_required()?;
            Self::validate_next_or_existing_block(
                block_data.as_slice(),
                actual_height,
                actual_height_usize,
                block_hash,
            )?;
            if actual_height <= u64::try_from(block_data.len())? {
                let chain_len = block_data.len();
                drop(block_data);
                self.ensure_existing_block_wire_matches(block, actual_height, block_hash)?;
                if let Some(entry) = merge_entry {
                    self.preflight_committed_merge_entry_for_block(block, entry)?;
                    let associated = self.associated_merge_entry_for_block(block)?;
                    if associated.as_ref() != Some(entry) {
                        self.persist_pending_certified_merge_entry(entry)?;
                    }
                }
                self.persist_lane_payload_ownership_artifacts_for_block(block)?;
                self.set_block_height_index_entry(actual_height_usize, block_hash);
                if let Some(entry) = merge_entry {
                    self.set_transaction_entrypoint_index_entry_with_merge(
                        actual_height_usize,
                        block,
                        None,
                        chain_len,
                        false,
                    );
                    self.append_committed_merge_entry_for_block_if_missing(block, entry)?;
                    self.set_transaction_entrypoint_index_entry_with_merge(
                        actual_height_usize,
                        block,
                        Some(entry),
                        chain_len,
                        true,
                    );
                    self.remove_committed_pending_merge_entry_best_effort(entry.canonical_hash());
                } else {
                    self.set_transaction_entrypoint_index_entry(
                        actual_height_usize,
                        block,
                        chain_len,
                        None,
                    );
                }
                debug!(
                    height = actual_height,
                    ?block_hash,
                    "block already durably stored in Kura"
                );
                return Ok(());
            }
        }

        if let Some(entry) = merge_entry {
            self.preflight_committed_merge_entry_for_block(block, entry)?;
        }
        self.check_storage_budget(block, merge_entry)?;
        if let Some(entry) = merge_entry {
            // The exact full entry is the recovery source for every crash after
            // the canonical block commit point, including direct callers that
            // did not arrive through the pending sidecar transport.
            self.persist_pending_certified_merge_entry(entry)?;
            #[cfg(test)]
            self.maybe_pause_store_after_pending_merge_stage_for_tests();
        }
        let mut lane_artifacts = self.stage_lane_payload_ownership_artifacts_for_block(
            block,
            LaneBlockArtifactConflictPolicy::PreserveCanonical,
        )?;

        // Lane-artifact staging, when present, already owns `sidecar_lock`. Canonical mutation
        // therefore follows one global order: sidecar -> block-store write -> block_data.
        let write_guard = self.lock_block_store_for_write();
        let mut block_data = self.block_data.lock();
        self.ensure_prune_recovery_not_required()?;
        Self::validate_next_or_existing_block(
            block_data.as_slice(),
            actual_height,
            actual_height_usize,
            block_hash,
        )?;
        if actual_height <= u64::try_from(block_data.len())? {
            let chain_len = block_data.len();
            drop(block_data);
            self.ensure_existing_block_wire_matches(block, actual_height, block_hash)?;
            if let Some(entry) = merge_entry {
                self.preflight_committed_merge_entry_for_block(block, entry)?;
            }
            if let Some(batch) = lane_artifacts.take() {
                batch.commit();
            }
            self.set_block_height_index_entry(actual_height_usize, block_hash);
            if let Some(entry) = merge_entry {
                self.set_transaction_entrypoint_index_entry_with_merge(
                    actual_height_usize,
                    block,
                    None,
                    chain_len,
                    false,
                );
                self.append_committed_merge_entry_for_block_if_missing(block, entry)?;
                self.set_transaction_entrypoint_index_entry_with_merge(
                    actual_height_usize,
                    block,
                    Some(entry),
                    chain_len,
                    true,
                );
                self.remove_committed_pending_merge_entry_best_effort(entry.canonical_hash());
            } else {
                self.set_transaction_entrypoint_index_entry(
                    actual_height_usize,
                    block,
                    chain_len,
                    None,
                );
            }
            debug!(
                height = actual_height,
                ?block_hash,
                "block was durably stored in Kura while waiting to append"
            );
            return Ok(());
        }

        if let Some(entry) = merge_entry {
            // Recheck after all fallible staging and while the canonical height
            // is still exclusively reserved. Deterministic binding conflicts
            // must fail before the block becomes irrevocable.
            self.preflight_committed_merge_entry_for_block(block, entry)?;
        }

        self.write_canonical_association_stage(block, merge_entry)?;
        if let Err(err) =
            self.persist_block_at_height_while_locked(block, actual_height, &write_guard)
        {
            if matches!(
                err,
                Error::DaBlockRewriteCommitStateUnknown { .. }
                    | Error::CanonicalBlockCommittedRecoveryRequired { .. }
                    | Error::CanonicalStoragePoisoned
            ) {
                // Startup resolves the marker first, then applies or discards the durable
                // association stage against the selected canonical block hash.
                return Err(err);
            }
            if let Some(mut batch) = lane_artifacts.take()
                && let Err(rollback_err) = batch.rollback()
            {
                error!(
                    ?rollback_err,
                    ?block_hash,
                    "Failed to rollback lane artifacts after block write failure"
                );
            }
            self.remove_canonical_association_stage()?;
            return Err(err);
        }

        if let Some(batch) = lane_artifacts.take() {
            batch.commit();
        }
        block_data.push((block_hash, Some(Arc::clone(block))));
        Self::drop_persisted_blocks(
            &mut block_data,
            actual_height_usize,
            self.blocks_in_memory.get(),
        );
        let new_len = block_data.len();
        self.set_block_height_index_entry(actual_height_usize, block_hash);
        // The canonical block is now durable, but its compact merge reference
        // is not query-complete until the full entry and sparse carrier record
        // are both durable. Passing no entry records that partial frontier.
        self.set_transaction_entrypoint_index_entry(actual_height_usize, block, new_len, None);
        drop(block_data);
        // Apply associations only after block_data and the durable marker agree. The durable
        // stage remains authoritative across any post-commit association failure.
        if let Err(association_error) = self.recover_canonical_association_stage() {
            return Err(self.committed_recovery_failure(
                "committed canonical association recovery",
                &association_error,
            ));
        }
        self.append_debug_block_dump(block);

        if let Some(entry) = merge_entry {
            // The block fsync above is the Kura commit point. From here on all
            // repair is monotonic: never truncate the block, lane artifacts, or
            // a successfully appended merge frame when a later write fails.
            if let Err(err) = self.append_committed_merge_entry_for_block_if_missing(block, entry) {
                error!(
                    ?err,
                    ?block_hash,
                    entry_epoch = entry.epoch_id,
                    "Failed to publish merge-ledger association after canonical block commit"
                );
                return Err(self.committed_recovery_failure(
                    "committed merge-ledger association publication",
                    &err,
                ));
            }
            self.set_transaction_entrypoint_index_entry_with_merge(
                actual_height_usize,
                block,
                Some(entry),
                new_len,
                true,
            );
            // Canonical-association recovery already attempted the
            // post-commit cleanup. Preserve its redundant repair sidecar when
            // that best-effort removal failed; an idempotent store retry uses
            // the existing-block branch above to remove it.
        }

        debug!(
            height = actual_height,
            new_len,
            ?block_hash,
            "stored block durably in Kura"
        );

        Ok(())
    }

    fn validate_next_or_existing_block(
        block_data: &[(HashOf<BlockHeader>, Option<Arc<SignedBlock>>)],
        actual_height: u64,
        actual_height_usize: usize,
        block_hash: HashOf<BlockHeader>,
    ) -> Result<()> {
        let expected_next_height = u64::try_from(block_data.len())?.saturating_add(1);

        if actual_height < expected_next_height {
            let index = actual_height_usize.saturating_sub(1);
            if let Some((expected, _)) = block_data.get(index) {
                if *expected == block_hash {
                    return Ok(());
                }
                return Err(Error::BlockHeightConflict {
                    height: actual_height,
                    expected: *expected,
                    actual: block_hash,
                });
            }
        }

        if actual_height > expected_next_height {
            return Err(Error::BlockHeightGap {
                expected_next_height,
                actual_height,
            });
        }

        Ok(())
    }

    fn file_len_or_zero(path: &Path) -> Result<u64> {
        if path.as_os_str().is_empty() {
            return Ok(0);
        }
        match std::fs::metadata(path) {
            Ok(meta) => Ok(meta.len()),
            Err(err) if err.kind() == ErrorKind::NotFound => Ok(0),
            Err(err) => Err(Error::IO(err, path.to_path_buf())),
        }
    }

    fn read_block_data_from_file(
        file: &mut FileWrap,
        start_location_in_data_file: u64,
        dest_buffer: &mut [u8],
    ) -> Result<()> {
        file.try_io(|file| {
            file.seek(SeekFrom::Start(start_location_in_data_file))?;
            file.read_exact(dest_buffer)
        })
    }

    fn write_atomic_synced_replace(&self, path: &Path, bytes: &[u8]) -> Result<()> {
        self.write_atomic_synced_impl(path, bytes, true).map(|_| ())
    }

    fn write_atomic_synced_noclobber(&self, path: &Path, bytes: &[u8]) -> Result<bool> {
        self.write_atomic_synced_impl(path, bytes, false)
    }

    fn write_atomic_synced_impl(
        &self,
        path: &Path,
        bytes: &[u8],
        allow_replace: bool,
    ) -> Result<bool> {
        self.durable_mutation_authorized()?;
        let parent = path.parent().ok_or_else(|| {
            Error::IO(
                std::io::Error::new(
                    ErrorKind::InvalidInput,
                    "atomic sidecar path has no parent directory",
                ),
                path.to_path_buf(),
            )
        })?;
        let (_, directory_before) = self.canonical_sidecar_directory(parent)?.ok_or_else(|| {
            Error::IO(
                std::io::Error::new(
                    ErrorKind::NotFound,
                    "atomic sidecar directory does not exist",
                ),
                parent.to_path_buf(),
            )
        })?;
        let mut temporary = tempfile::Builder::new()
            .prefix(".kura-sidecar-")
            .tempfile_in(parent)
            .map_err(|error| Error::IO(error, parent.to_path_buf()))?;
        let (_, directory_after_create) =
            self.canonical_sidecar_directory(parent)?.ok_or_else(|| {
                Error::IO(
                    std::io::Error::new(
                        ErrorKind::NotFound,
                        "atomic sidecar directory disappeared",
                    ),
                    parent.to_path_buf(),
                )
            })?;
        if !Self::sidecar_metadata_same_object(&directory_before, &directory_after_create) {
            return Err(Error::IO(
                std::io::Error::new(
                    ErrorKind::InvalidData,
                    "atomic sidecar directory changed while creating the temporary file",
                ),
                parent.to_path_buf(),
            ));
        }
        let temporary_metadata = temporary
            .as_file()
            .metadata()
            .map_err(|error| Error::IO(error, path.to_path_buf()))?;
        if !temporary_metadata.is_file() || !Self::sidecar_is_single_link(&temporary_metadata) {
            return Err(Error::IO(
                std::io::Error::new(
                    ErrorKind::InvalidData,
                    "atomic sidecar temporary path is not a single-link regular file",
                ),
                path.to_path_buf(),
            ));
        }
        temporary
            .as_file_mut()
            .write_all(bytes)
            .map_err(|error| Error::IO(error, path.to_path_buf()))?;
        temporary
            .as_file_mut()
            .flush()
            .map_err(|error| Error::IO(error, path.to_path_buf()))?;
        temporary
            .as_file()
            .sync_all()
            .map_err(|error| Error::IO(error, path.to_path_buf()))?;
        let (_, directory_before_persist) =
            self.canonical_sidecar_directory(parent)?.ok_or_else(|| {
                Error::IO(
                    std::io::Error::new(
                        ErrorKind::NotFound,
                        "atomic sidecar directory disappeared before rename",
                    ),
                    parent.to_path_buf(),
                )
            })?;
        if !Self::sidecar_metadata_same_object(&directory_before, &directory_before_persist) {
            return Err(Error::IO(
                std::io::Error::new(
                    ErrorKind::InvalidData,
                    "atomic sidecar directory changed before rename",
                ),
                parent.to_path_buf(),
            ));
        }
        let persisted = if allow_replace {
            temporary
                .persist(path)
                .map_err(|error| Error::IO(error.error, path.to_path_buf()))?
        } else {
            match temporary.persist_noclobber(path) {
                Ok(file) => file,
                Err(error) if error.error.kind() == ErrorKind::AlreadyExists => return Ok(false),
                Err(error) => return Err(Error::IO(error.error, path.to_path_buf())),
            }
        };
        persisted
            .sync_all()
            .map_err(|error| Error::IO(error, path.to_path_buf()))?;
        let persisted_metadata = persisted
            .metadata()
            .map_err(|error| Error::IO(error, path.to_path_buf()))?;
        let path_metadata = std::fs::symlink_metadata(path)
            .map_err(|error| Error::IO(error, path.to_path_buf()))?;
        let (_, directory_after_persist) =
            self.canonical_sidecar_directory(parent)?.ok_or_else(|| {
                Error::IO(
                    std::io::Error::new(
                        ErrorKind::NotFound,
                        "atomic sidecar directory disappeared after rename",
                    ),
                    parent.to_path_buf(),
                )
            })?;
        if !Self::sidecar_metadata_same_object(&directory_before, &directory_after_persist)
            || path_metadata.file_type().is_symlink()
            || !path_metadata.is_file()
            || !Self::sidecar_file_metadata_unchanged(&persisted_metadata, &path_metadata)
            || persisted_metadata.len() != u64::try_from(bytes.len())?
        {
            return Err(Error::IO(
                std::io::Error::new(
                    ErrorKind::InvalidData,
                    "atomic sidecar changed during durable rename",
                ),
                path.to_path_buf(),
            ));
        }
        sync_dir(parent).map_err(|err| Error::IO(err, parent.to_path_buf()))?;
        Ok(true)
    }

    fn prune_intent_path_for(store_root: &Path) -> PathBuf {
        store_root.join(PRUNE_INTENT_FILE_NAME)
    }

    fn decode_prune_intent(path: &Path, bytes: &[u8]) -> Result<KuraPruneIntentV1> {
        if bytes.is_empty() || bytes.len() > PRUNE_INTENT_MAX_BYTES {
            return Err(Error::PruneIntentConflict(format!(
                "intent {} has invalid byte length {}",
                path.display(),
                bytes.len()
            )));
        }
        let intent = norito::decode_canonical::<KuraPruneIntentV1>(bytes).map_err(|err| {
            Error::PruneIntentConflict(format!(
                "intent {} failed exact Norito decode: {err}",
                path.display()
            ))
        })?;
        if intent.version != 1
            || intent.target_height >= intent.source_height
            || (intent.source_height == 0) != intent.source_tip_hash.is_none()
            || (intent.target_height == 0) != intent.target_tip_hash.is_none()
            || (intent.retained_merge_entries == 0) != intent.retained_merge_tip_hash.is_none()
        {
            return Err(Error::PruneIntentConflict(format!(
                "intent {} has a non-canonical identity",
                path.display()
            )));
        }
        Ok(intent)
    }

    fn read_prune_intent_path(path: &Path) -> Result<Option<KuraPruneIntentV1>> {
        let metadata = match std::fs::symlink_metadata(path) {
            Ok(metadata) => metadata,
            Err(err) if err.kind() == ErrorKind::NotFound => return Ok(None),
            Err(err) => return Err(Error::IO(err, path.to_path_buf())),
        };
        if metadata.file_type().is_symlink() || !metadata.file_type().is_file() {
            return Err(Error::PruneIntentConflict(format!(
                "intent {} is not a regular no-follow file",
                path.display()
            )));
        }
        if usize::try_from(metadata.len()).unwrap_or(usize::MAX) > PRUNE_INTENT_MAX_BYTES {
            return Err(Error::PruneIntentConflict(format!(
                "intent {} exceeds its hard byte limit",
                path.display()
            )));
        }
        let bytes = std::fs::read(path).map_err(|err| Error::IO(err, path.to_path_buf()))?;
        Self::decode_prune_intent(path, &bytes).map(Some)
    }

    fn read_prune_intent(store_root: &Path) -> Result<Option<KuraPruneIntentV1>> {
        let path = Self::prune_intent_path_for(store_root);
        let temp_path = path.with_extension("norito.tmp");
        let intent = Self::read_prune_intent_path(&path)?;
        let temporary = Self::read_prune_intent_path(&temp_path)?;
        match (intent, temporary) {
            (Some(intent), Some(temporary)) if intent != temporary => {
                Err(Error::PruneIntentConflict(
                    "canonical and temporary prune intents disagree".to_owned(),
                ))
            }
            (Some(intent), temporary) => {
                if temporary.is_some() {
                    std::fs::remove_file(&temp_path)
                        .map_err(|err| Error::IO(err, temp_path.clone()))?;
                    sync_dir(store_root).map_err(|err| Error::IO(err, store_root.to_path_buf()))?;
                }
                Ok(Some(intent))
            }
            (None, Some(_)) => {
                // Publication did not reach the atomic rename, so no destructive
                // prune stage was allowed to begin.
                std::fs::remove_file(&temp_path)
                    .map_err(|err| Error::IO(err, temp_path.clone()))?;
                sync_dir(store_root).map_err(|err| Error::IO(err, store_root.to_path_buf()))?;
                Ok(None)
            }
            (None, None) => Ok(None),
        }
    }

    fn persist_prune_intent(&self, intent: &KuraPruneIntentV1) -> Result<()> {
        let path = Self::prune_intent_path_for(&self.store_root);
        if Self::read_prune_intent(&self.store_root)?.is_some() {
            return Err(Error::PruneIntentConflict(
                "another prune intent is already active".to_owned(),
            ));
        }
        let bytes = norito::encode_canonical(intent).map_err(Error::NoritoFrame)?;
        if bytes.len() > PRUNE_INTENT_MAX_BYTES {
            return Err(Error::PruneIntentConflict(
                "encoded prune intent exceeds its hard byte limit".to_owned(),
            ));
        }
        if !self.write_atomic_synced_noclobber(&path, &bytes)? {
            return Err(Error::PruneIntentConflict(
                "another prune intent became active during publication".to_owned(),
            ));
        }
        Ok(())
    }

    fn rollback_intent_path(blocks_root: &Path) -> PathBuf {
        blocks_root.join(ROLLBACK_INTENT_FILE_NAME)
    }

    fn decode_rollback_intent(path: &Path) -> Result<KuraRollbackIntent> {
        let bytes = std::fs::read(path).map_err(|err| Error::IO(err, path.to_path_buf()))?;
        let intent = norito::decode_canonical::<KuraRollbackIntent>(&bytes).map_err(|err| {
            Error::RollbackIntentInvalid {
                path: path.to_path_buf(),
                reason: format!("failed to decode rollback intent: {err}"),
            }
        })?;
        intent.validate(path)?;
        Ok(intent)
    }

    fn load_rollback_intent(blocks_root: &Path) -> Result<Option<KuraRollbackIntent>> {
        if blocks_root.as_os_str().is_empty() {
            return Err(Error::EmptyStoreRoot);
        }
        let path = Self::rollback_intent_path(blocks_root);
        let tmp_path = path.with_extension("norito.tmp");
        let main = if path.exists() {
            Some(Self::decode_rollback_intent(&path))
        } else {
            None
        };
        let temp = if tmp_path.exists() {
            Some(Self::decode_rollback_intent(&tmp_path))
        } else {
            None
        };
        match (main, temp) {
            (None, None) => Ok(None),
            (Some(Err(err)), _) | (_, Some(Err(err))) => Err(err),
            (Some(Ok(main)), None) => Ok(Some(main)),
            (None, Some(Ok(temp))) => {
                std::fs::rename(&tmp_path, &path).map_err(|err| Error::IO(err, path.clone()))?;
                sync_dir(blocks_root).map_err(|err| Error::IO(err, blocks_root.to_path_buf()))?;
                Ok(Some(temp))
            }
            (Some(Ok(main)), Some(Ok(temp))) if main == temp => {
                std::fs::remove_file(&tmp_path).map_err(|err| Error::IO(err, tmp_path.clone()))?;
                sync_dir(blocks_root).map_err(|err| Error::IO(err, blocks_root.to_path_buf()))?;
                Ok(Some(main))
            }
            (Some(Ok(_)), Some(Ok(_))) => Err(Error::RollbackIntentInvalid {
                path,
                reason: "main and temporary rollback intents diverge".to_owned(),
            }),
        }
    }

    fn clear_prune_intent(&self) -> Result<()> {
        let path = Self::prune_intent_path_for(&self.store_root);
        let temp_path = path.with_extension("norito.tmp");
        for candidate in [&path, &temp_path] {
            if let Err(err) = std::fs::remove_file(candidate)
                && err.kind() != ErrorKind::NotFound
            {
                return Err(Error::IO(err, candidate.to_path_buf()));
            }
        }
        sync_dir(&self.store_root).map_err(|err| Error::IO(err, self.store_root.clone()))
    }

    fn finish_prune_intent(&self) -> Result<()> {
        self.clear_prune_intent()?;
        self.prune_recovery_required.store(false, Ordering::Release);
        Ok(())
    }

    fn block_hash_from_store(
        block_store: &mut BlockStore,
        height: u64,
    ) -> Result<Option<HashOf<BlockHeader>>> {
        if height == 0 || block_store.read_durable_index_count()? < height {
            return Ok(None);
        }
        Ok(block_store
            .read_block_hashes(height.saturating_sub(1), 1)?
            .into_iter()
            .next())
    }

    fn apply_prune_intent_to_block_store(
        block_store: &mut BlockStore,
        intent: &KuraPruneIntentV1,
    ) -> Result<()> {
        let current = block_store.read_durable_index_count()?;
        if current != intent.source_height && current != intent.target_height {
            return Err(Error::PruneIntentConflict(format!(
                "durable block height {current} matches neither prune source {} nor target {}",
                intent.source_height, intent.target_height
            )));
        }
        let expected_tip = if current == intent.source_height {
            intent.source_tip_hash
        } else {
            intent.target_tip_hash
        };
        if Self::block_hash_from_store(block_store, current)? != expected_tip {
            return Err(Error::PruneIntentConflict(format!(
                "durable block tip at height {current} differs from the prune intent"
            )));
        }
        if intent.target_height > 0
            && Self::block_hash_from_store(block_store, intent.target_height)?
                != intent.target_tip_hash
        {
            return Err(Error::PruneIntentConflict(
                "durable target hash differs from the prune intent".to_owned(),
            ));
        }
        // Re-run the idempotent block-store prune even when the target marker
        // was already published. A crash immediately after that marker can
        // leave the index/data/hash or DA-sidecar stages incomplete; the
        // marker alone must not cause forward recovery to skip those stages.
        block_store.prune(intent.target_height)?;
        Ok(())
    }

    fn validate_prune_intent_merge_prefix(
        merge_log: &mut MergeLedgerLog,
        intent: &KuraPruneIntentV1,
    ) -> Result<()> {
        let retained = usize::try_from(intent.retained_merge_entries)?;
        if retained > merge_log.total_entries {
            return Err(Error::PruneIntentConflict(format!(
                "intent retains {retained} merge entries but the log has only {}",
                merge_log.total_entries
            )));
        }
        let entries = merge_log.all_entries()?;
        let retained_tip = retained
            .checked_sub(1)
            .and_then(|index| entries.get(index))
            .map(MergeLedgerEntry::canonical_hash);
        if retained_tip != intent.retained_merge_tip_hash {
            return Err(Error::PruneIntentConflict(
                "merge-log retained prefix differs from the prune intent".to_owned(),
            ));
        }
        if entries[retained..]
            .iter()
            .any(|entry| entry.merge_qc.carrier_height <= intent.target_height)
        {
            return Err(Error::PruneIntentConflict(
                "merge-log prune suffix contains an entry at or below the target height".to_owned(),
            ));
        }
        Ok(())
    }

    fn remove_rollback_intent(blocks_root: &Path) -> Result<()> {
        let path = Self::rollback_intent_path(blocks_root);
        let tmp_path = path.with_extension("norito.tmp");
        for artifact in [&path, &tmp_path] {
            match std::fs::remove_file(artifact) {
                Ok(()) => {}
                Err(err) if err.kind() == ErrorKind::NotFound => {}
                Err(err) => return Err(Error::IO(err, artifact.to_path_buf())),
            }
        }
        sync_dir(blocks_root).map_err(|err| Error::IO(err, blocks_root.to_path_buf()))?;
        Ok(())
    }

    fn ensure_no_pending_rollback(&self) -> Result<()> {
        let blocks_root = self.active_blocks_dir.lock().clone();
        if let Some(intent) = Self::load_rollback_intent(&blocks_root)? {
            return Err(Error::RollbackIntentInvalid {
                path: Self::rollback_intent_path(&blocks_root),
                reason: format!(
                    "rollback {} -> {} is incomplete; canonical writes are disabled",
                    intent.from_height, intent.target_height
                ),
            });
        }
        Ok(())
    }

    fn block_store_tracked_bytes(block_store: &mut BlockStore) -> Result<u64> {
        if block_store.path_to_blockchain.as_os_str().is_empty() {
            return Ok(0);
        }
        let data_len = block_store.data_file_len()?;
        let index_len = block_store.index_file_len()?;
        let hashes_len = block_store.hashes_file_len()?;
        let marker_path = block_store.commit_marker_path();
        let marker_len = Self::file_len_or_zero(&marker_path)?;
        let marker_tmp_len = Self::file_len_or_zero(&marker_path.with_extension("norito.tmp"))?;
        let data_tmp_len = Self::file_len_or_zero(
            &block_store
                .path_to_blockchain
                .join(format!("{DATA_FILE_NAME}.tmp")),
        )?;
        let index_tmp_len = Self::file_len_or_zero(
            &block_store
                .path_to_blockchain
                .join(format!("{INDEX_FILE_NAME}.tmp")),
        )?;
        let hashes_tmp_len = Self::file_len_or_zero(
            &block_store
                .path_to_blockchain
                .join(format!("{HASHES_FILE_NAME}.tmp")),
        )?;
        Ok(data_len
            .saturating_add(index_len)
            .saturating_add(hashes_len)
            .saturating_add(marker_len)
            .saturating_add(marker_tmp_len)
            .saturating_add(data_tmp_len)
            .saturating_add(index_tmp_len)
            .saturating_add(hashes_tmp_len))
    }

    fn da_payload_bytes_for_range(
        block_store: &BlockStore,
        start_height: u64,
        count: usize,
    ) -> Result<u64> {
        if block_store.da_blocks_dir.as_os_str().is_empty() || count == 0 {
            return Ok(0);
        }
        let mut total = 0u64;
        for offset in 0..count {
            let height = start_height.saturating_add(offset as u64).saturating_add(1);
            let path = block_store.da_block_path(height);
            total = total.saturating_add(Self::file_len_or_zero(&path)?);
        }
        Ok(total)
    }

    fn merge_log_tracked_bytes(&self) -> Result<u64> {
        if self.store_root.as_os_str().is_empty() {
            return Ok(0);
        }
        let path = self.active_merge_path.lock().clone();
        Self::file_len_or_zero(&path)
    }

    fn roster_journal_tracked_bytes(&self) -> Result<u64> {
        if self.store_root.as_os_str().is_empty() {
            return Ok(0);
        }
        let path = CommitRosterJournal::journal_path(&self.store_root);
        Self::directory_tree_file_bytes(&path)
    }

    fn sidecar_tracked_bytes(
        data_path: &Path,
        index_path: &Path,
        json_path: Option<&Path>,
    ) -> Result<u64> {
        let data_tmp = data_path.with_extension("norito.tmp");
        let index_tmp = index_path.with_extension("index.tmp");
        let mut total = Self::file_len_or_zero(data_path)?
            .saturating_add(Self::file_len_or_zero(index_path)?)
            .saturating_add(Self::file_len_or_zero(&data_tmp)?)
            .saturating_add(Self::file_len_or_zero(&index_tmp)?);
        if let Some(path) = json_path {
            total = total.saturating_add(Self::file_len_or_zero(path)?);
        }
        Ok(total)
    }

    fn block_required_bytes(block: &SignedBlock) -> Result<u64> {
        let wire = block.canonical_wire()?;
        let (frame, _) = wire.into_parts();
        let frame_len = u64::try_from(frame.len())?;
        Ok(frame_len
            .saturating_add(BlockIndex::SIZE)
            .saturating_add(SIZE_OF_BLOCK_HASH))
    }

    fn merge_entry_bytes(entry: &MergeLedgerEntry) -> Result<u64> {
        let encoded = Encode::encode(entry);
        let encoded_len = u64::try_from(encoded.len())?;
        Ok(encoded_len.saturating_add(std::mem::size_of::<u32>() as u64))
    }

    fn merge_commit_required_bytes(
        &self,
        block: &SignedBlock,
        entry: &MergeLedgerEntry,
    ) -> Result<u64> {
        let entry_hash = entry.canonical_hash();
        let pending_bytes = {
            let _guard = self.sidecar_lock.lock();
            self.reconcile_pending_merge_temp_files_unlocked()?;
            let path = self.pending_merge_entry_path(entry_hash);
            match self.read_pending_merge_entry_path(&path, Some(entry_hash))? {
                Some(existing) if existing == *entry => 0,
                Some(_) => {
                    return Err(Self::invalid_pending_merge_entry_error(
                        path,
                        "hash-addressed pending merge sidecar conflicts with existing bytes",
                    ));
                }
                None => u64::try_from(entry.canonical_bytes().len())?,
            }
        };
        let log_bytes = if self.merge_log.lock().preflight_append(entry)? {
            Self::merge_entry_bytes(entry)?
        } else {
            0
        };
        let record = Self::carrier_record_for_block_entry(block, entry)?;
        let carrier_bytes = {
            let _guard = self.merge_carrier_lock.lock();
            if self.preflight_merge_carrier_record_unlocked(record)? {
                u64::try_from(
                    norito::encode_canonical(&record)
                        .map_err(Error::NoritoFrame)?
                        .len(),
                )?
            } else {
                0
            }
        };
        Ok(pending_bytes
            .saturating_add(log_bytes)
            .saturating_add(carrier_bytes))
    }

    fn block_required_bytes_for_budget(&self, block: &SignedBlock, _limit: u64) -> Result<u64> {
        let required = Self::block_required_bytes(block)?;
        Ok(required.saturating_add(self.lane_artifact_required_bytes_for_block(block)?))
    }

    fn sidecar_bytes(store_dir: &Path) -> Result<u64> {
        if store_dir.as_os_str().is_empty() {
            return Ok(0);
        }
        let mut total = 0u64;
        for dir_name in [PIPELINE_DIR_NAME, LANE_ARTIFACTS_DIR_NAME] {
            let dir = store_dir.join(dir_name);
            let entries = match std::fs::read_dir(&dir) {
                Ok(entries) => entries,
                Err(err) if err.kind() == ErrorKind::NotFound => continue,
                Err(err) => return Err(Error::IO(err, dir)),
            };
            for entry in entries {
                let entry = entry.map_err(|err| Error::IO(err, dir.clone()))?;
                let path = entry.path();
                let file_type = entry
                    .file_type()
                    .map_err(|err| Error::IO(err, path.clone()))?;
                if file_type.is_file() {
                    let len = entry
                        .metadata()
                        .map_err(|err| Error::IO(err, path.clone()))?
                        .len();
                    total = total.saturating_add(len);
                }
            }
        }
        Ok(total)
    }

    fn block_store_bytes(blocks_dir: &Path) -> Result<u64> {
        if blocks_dir.as_os_str().is_empty() {
            return Ok(0);
        }
        let entries = match std::fs::read_dir(blocks_dir) {
            Ok(entries) => entries,
            Err(err) if err.kind() == ErrorKind::NotFound => return Ok(0),
            Err(err) => return Err(Error::IO(err, blocks_dir.to_path_buf())),
        };
        let mut files = 0u64;
        for entry in entries {
            let entry = entry.map_err(|err| Error::IO(err, blocks_dir.to_path_buf()))?;
            let path = entry.path();
            let file_type = entry
                .file_type()
                .map_err(|err| Error::IO(err, path.clone()))?;
            if file_type.is_file() {
                let len = entry
                    .metadata()
                    .map_err(|err| Error::IO(err, path.clone()))?
                    .len();
                files = files.saturating_add(len);
            }
        }
        let sidecars = Self::sidecar_bytes(blocks_dir)?;
        Ok(files.saturating_add(sidecars))
    }

